INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('forrestthewoods/anubis/kanban-management', 'community', 'forrestthewoods', 'anubis', 'forrestthewoods/anubis', 'kanban-management', 0, 0, 60, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:48.996Z', '73da49bc4690a268ac839e9426e2d08d1dbf7f0c4f9e4f041974e790fb9188f9', '{"id":"forrestthewoods/anubis/kanban-management","name":"kanban-management","description":{"en":"The kanban-management skill utilizes the Anubis Issue Tracker project board for streamlined project management. This skill benefits developers and project managers by providing a pre-configured board with a 7-status column workflow.","zh":"Kanban管理是一种使用项目板进行项目管理的方法，Anubis Issue Tracker项目板已配置好七个状态列","ja":"Kanbanマネージメントは、プロジェクトボードを使用したプロジェクト管理方法であり、Anubis Issue Trackerプロジェクトボードには7つのステータス列が設定されています","ko":"칸반 관리는 프로젝트 보드를 사용하여 프로젝트를 관리하는 방법으로, Anubis Issue Tracker 프로젝트 보드에는 7개의 상태 열이 구성되어 있습니다","es":"La gestión Kanban es una técnica de gestión de proyectos que utiliza un tablero de proyecto para visualizar y gestionar el trabajo","fr":"La gestion Kanban est une technique de gestion de projets qui utilise un tableau de projet pour visualiser et gérer les tâches","de":"Die Kanban-Verwaltung ist eine Projektmanagement-Technik, die ein Projektboard verwendet, um die Arbeit zu visualisieren und zu verwalten","pt":"O kanban management é uma técnica de gerenciamento de projetos que visa melhorar a produtividade e a eficiência do time de desenvolvimento","ru":"Канбан управление - это техника управления проектами, направленная на повышение производительности и эффективности команды разработчиков","ar":"إدارة كانبان هي تقنية لإدارة المشاريع تهدف إلى تحسين الإنتاجية والكفاءة لفريق التطوير"},"seo":{"title":{"en":"Kanban-Management: Setup Guide for AI Agents | AI Agent S...","zh":"Kanban管理设置指南","ja":"Kanbanマネージメントベストプラクティス - AIエージェント","ko":"칸반 관리 설정 가이드 - AI 도구","es":"Guía de configuración de Kanban Management para proyectos...","fr":"Guide de mise en place de la gestion Kanban pour les proj...","de":"Einrichtungsleitfaden für Kanban-Management in Entwicklun...","pt":"Guia de Configuração do Kanban Management para Desenvolve...","ru":"Настройка Канбан Управления: Лучшие Практики для Разработ...","ar":"دليل إعداد إدارة كانبان للطورين مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to leverage the Anubis Issue Tracker project board for efficient kanban-management. Learn to navigate the 7-status column workflow and get start...","zh":"了解Kanban管理的技术细节，并学习如何使用Anubis Issue Tracker项目板进行项目管理","ja":"Kanbanマネージメントの技術的な詳細を学び、Anubis Issue Trackerプロジェクトボードを使用したプロジェクト管理方法を確認する","ko":"칸반 관리의 기술적 세부 사항을 알아보고 Anubis Issue Tracker 프로젝트 보드를 사용하여 프로젝트를 관리하는 방법을 배우세요","es":"Aprende a configurar y utilizar la gestión Kanban para tus proyectos de desarrollo con nuestra guía paso a paso","fr":"Découvrez comment configurer et utiliser la gestion Kanban pour vos projets de développement avec notre guide étape par étape","de":"Erfahren Sie, wie Sie die Kanban-Verwaltung für Ihre Entwicklungsprojekte konfigurieren und nutzen können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o kanban management para melhorar a produtividade do seu time de desenvolvimento com o Anubis Issue Tracker","ru":"Узнайте, как настроить канбан управление для повышения производительности вашей команды разработчиков с помощью Anubis Issue Tracker и ИИ Агентов","ar":"تعرف على كيفية إعداد إدارة كانبان لتحسين إنتاجية فريق التطوير الخاص بك مع تتبع قضايا أنوبيس وادوات الذكاء الاصطناعي"},"definition":{"en":"Kanban-management is a project management approach using a pre-configured board with status columns like Backlog, to track and visualize work progress.","zh":"Kanban管理是一种使用可视化项目板进行工作项管理的方法","ja":"Kanbanマネージメントは、可視化されたプロジェクトボードを使用した作業項目の管理方法","ko":"칸반 관리는 가시적인 프로젝트 보드를 사용하여 작업 항목을 관리하는 방법입니다","es":"Kanban es una técnica de gestión de proyectos que se centra en la visualización del trabajo y la limitación del trabajo en curso","fr":"Kanban est une technique de gestion de projets qui se concentre sur la visualisation des tâches et la limitation du travail en cours","de":"Kanban ist eine Projektmanagement-Technik, die sich auf die Visualisierung der Arbeit und die Begrenzung der laufenden Arbeit konzentriert","pt":"O que é kanban management? É uma técnica de gerenciamento de projetos que utiliza um quadro de projeto para visualizar e gerenciar tarefas","ru":"Что такое канбан управление? Это техника управления проектами, которая использует доску проекта для визуализации и управления задачами","ar":"ما هي إدارة كانبان؟ هي تقنية لإدارة المشاريع التي تستخدم لوحة المشروع لتصور وإدارة المهام"},"features":{"en":["Utilizes the Anubis Issue Tracker project board with a pre-configured 7-status column workflow","Supports project management via the GitHub projects interface","Includes a specific project URL (https://github.com/users/forrestthewoods/projects/8) for easy access","Features a project board with a unique project number (#8) for organization","Employs a board status workflow with columns like Backlog for future ideas or deferred work","Requires use of project #8, eliminating the need to create a new project board"],"zh":["使用Anubis Issue Tracker项目板进行项目管理","七个状态列：Backlog、进行中、已完成等","项目板URL：https://github.com/users/forrestthewoods/projects/8","支持GitHub项目管理"],"ja":["Anubis Issue Trackerプロジェクトボードを使用したプロジェクト管理","7つのステータス列：バックログ、進行中、完了など","プロジェクトボードURL：https://github.com/users/forrestthewoods/projects/8","GitHubプロジェクト管理に対応"],"ko":["Anubis Issue Tracker 프로젝트 보드를 사용하여 프로젝트를 관리","7개의 상태 열：백로그, 진행 중, 완료 등","프로젝트 보드 URL：https://github.com/users/forrestthewoods/projects/8","GitHub 프로젝트 관리 지원"],"es":["Tablero de proyecto configurado con columnas de estado personalizadas","Gestión de tareas y seguimiento del progreso","Limitación del trabajo en curso para mejorar la eficiencia","Integración con GitHub para un seguimiento más preciso","Siete columnas de estado preconfiguradas: Backlog, TODO, etc."],"fr":["Tableau de projet configuré avec des colonnes d''état personnalisées","Gestion des tâches et suivi de la progression","Limitation du travail en cours pour améliorer l''efficacité","Intégration avec GitHub pour un suivi plus précis","Sept colonnes d''état préconfigurées : Backlog, TODO, etc."],"de":["Projektboard mit benutzerdefinierten Statusspalten","Aufgabenverwaltung und Fortschrittsüberwachung","Begrenzung der laufenden Arbeit für verbesserte Effizienz","Integration mit GitHub für präzisere Nachverfolgung","Sieben vorkonfigurierte Statusspalten: Backlog, TODO usw."],"pt":["Utiliza o Anubis Issue Tracker para gerenciar tarefas","Configuração pré-definida do quadro de projeto","Sete colunas de status para gerenciar o workflow do projeto","Integração com GitHub para gerenciar projetos","Melhoria da produtividade e eficiência do time de desenvolvimento"],"ru":["Использует Anubis Issue Tracker для управления задачами","Предварительно настроенная конфигурация доски проекта","Семь столбцов статуса для управления рабочим процессом проекта","Интеграция с GitHub для управления проектами","Повышение производительности и эффективности команды разработчиков с помощью ИИ Агентов"],"ar":["استخدام تتبع قضايا أنوبيس لإدارة المهام","إعداد مسبق للوحة المشروع","سبعة أعمدة للحالة لإدارة تدفق العمل للمشروع","التكامل مع جيثب لإدارة المشاريع","تحسين الإنتاجية والكفاءة لفريق التطوير مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use kanban-management","what is kanban-management","kanban-management alternative","kanban-management vs trello","kanban-management install","kanban-management setup guide","anubis issue tracker tutorial","github projects kanban-management"],"zh":["Kanban管理","项目管理","Anubis Issue Tracker","GitHub项目管理","项目板","状态列","工作项管理"],"ja":["Kanbanマネージメント","プロジェクト管理","Anubis Issue Tracker","GitHubプロジェクト管理","プロジェクトボード","ステータス列","作業項目管理","AIエージェント"],"ko":["칸반 관리","프로젝트 관리","Anubis Issue Tracker","GitHub 프로젝트 관리","프로젝트 보드","상태 열","작업 항목 관리","AI 도구"],"es":["Kanban management","gestión de proyectos","tablero de proyecto","gestión de tareas","limitación del trabajo en curso","integración con GitHub","desarrollo de software","metodologías ágiles"],"fr":["Gestion Kanban","gestion de projets","tableau de projet","gestion des tâches","limitation du travail en cours","intégration avec GitHub","développement de logiciels","méthodologies agiles"],"de":["Kanban-Verwaltung","Projektmanagement","Projektboard","Aufgabenverwaltung","Begrenzung der laufenden Arbeit","Integration mit GitHub","Softwareentwicklung","Agile Methoden"],"pt":["kanban management","Anubis Issue Tracker","gerenciamento de projetos","produtividade do time de desenvolvimento","técnica de gerenciamento de projetos","quadro de projeto","GitHub","desenvolvedores"],"ru":["канбан управление","Anubis Issue Tracker","управление проектами","производительность команды разработчиков","техника управления проектами","доска проекта","GitHub","ИИ Агенты","разработчики"],"ar":["إدارة كانبان","تتبع قضايا أنوبيس","إدارة المشاريع","إنتاجية فريق التطوير","تقنية إدارة المشاريع","لوحة المشروع","جيثب","أدوات الذكاء الاصطناعي","مطورين"]}},"owner":"forrestthewoods","repo":"anubis","repoPath":"forrestthewoods/anubis","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.350Z","topics":[],"category":"community","skillMd":{"name":"kanban-management","description":"Manages the Anubis Issue Tracker GitHub project board. Use when you need to organize issues by difficulty/status, move issues through workflow stages, or generate board status reports.","bodyPreview":"# Kanban Project Management\n\n## Project Board\n\nThe **Anubis Issue Tracker** project board is already created and configured:\n- **Project URL:** https://github.com/users/forrestthewoods/projects/8\n- **Project Number:** 8\n- **Owner:** forrestthewoods\n\n**Important:** Do NOT create a new project board. Always use project #8.\n\n## Board Status Workflow\n\nThe project board uses these seven status columns:\n\n| Status | Description |\n|--------|-------------|\n| **Backlog** | Future ideas or deferred work; n","body":"# Kanban Project Management\n\n## Project Board\n\nThe **Anubis Issue Tracker** project board is already created and configured:\n- **Project URL:** https://github.com/users/forrestthewoods/projects/8\n- **Project Number:** 8\n- **Owner:** forrestthewoods\n\n**Important:** Do NOT create a new project board. Always use project #8.\n\n## Board Status Workflow\n\nThe project board uses these seven status columns:\n\n| Status | Description |\n|--------|-------------|\n| **Backlog** | Future ideas or deferred work; not ready for action yet |\n| **Triage** | New issues not yet added to the project board |\n| **Needs Agent Review** | Issues ready for agent to review and categorize |\n| **Needs Human Review** | Agent has questions; waiting for human clarification |\n| **Ready to Implement** | Agent reviewed, wrote plan, no questions remaining |\n| **Needs Code Review** | Implementation in progress (has active branch) |\n| **Done** | Closed and completed (automatic via GitHub) |\n\n**Important:** Issues in **Backlog** should be **completely ignored** by all skills. These are tasks that have been captured so they won''t be forgotten, but are not ready for action. They will be moved to Triage or Needs Agent Review when they are ready to be worked on.\n\n## Workflow Overview\n\n1. **New issues** are created in GitHub Issues\n2. Issues not in the project are placed in **Triage**\n3. Issues move to **Needs Agent Review** for agent processing\n4. Agent reviews each issue:\n   - Labels the issue as `difficulty: easy`, `difficulty: medium`, or `difficulty: hard`\n   - If clarification needed → post questions as comment → move to **Needs Human Review**\n   - If no questions → write detailed implementation plan as comment → move to **Ready to Implement**\n5. When implementation begins, agent creates branch using the branch naming convention\n6. Issues with active branches are detected and moved to **Needs Code Review**\n7. When issue is closed, GitHub automatically moves it to **Done**\n\n## Purpose\n\nThis skill helps manage the existing project board by:\n1. Adding new issues to the board\n2. Moving issues through workflow stages\n3. Organizing issues by difficulty labels\n4. Generating board status reports\n5. Maintaining board hygiene\n\n## Instructions\n\n### Step 1: View Current Board State\n\n```bash\n# List all items on the project board\ngh project item-list 8 --owner forrestthewoods --format json\n\n# View project details\ngh project view 8 --owner forrestthewoods --format json\n```\n\n### Step 2: Add New Issues to Board\n\nWhen new issues are created, add them to the board:\n\n```bash\n# Add a single issue\ngh project item-add 8 --owner forrestthewoods --url https://github.com/forrestthewoods/anubis/issues/<number>\n\n# Add all open issues not yet on board\ngh issue list --state open --json url -q ''.[].url'' | while read url; do\n  gh project item-add 8 --owner forrestthewoods --url \"$url\" 2>/dev/null\ndone\n```\n\n### Step 3: Move Issues Through Stages\n\nUpdate issue status based on progress:\n\n```bash\n# Get project and field IDs\ngh project view 8 --owner forrestthewoods --format json\n\n# Get item ID for specific issue\ngh project item-list 8 --owner forrestthewoods --format json | jq ''.items[] | select(.content.number == <issue-number>)''\n\n# Update status\ngh project item-edit --project-id <project-id> --id <item-id> --field-id <status-field-id> --single-select-option-id <option-id>\n```\n\n**Status Transition Rules:**\n\n| From | To | Trigger |\n|------|-----|---------|\n| Triage | Needs Agent Review | Issue added to project board |\n| Needs Agent Review | Needs Human Review | Agent posts clarifying questions |\n| Needs Agent Review | Ready to Implement | Agent writes implementation plan |\n| Needs Human Review | Needs Agent Review | Human responds to questions |\n| Ready to Implement | Needs Code Review | Agent creates implementation branch |\n| Needs Code Review | Done | PR merged and issue closed |\n\n### Step 4: Manage Difficulty Labels\n\nEnsure issues have appropriate difficulty labels:\n\n```bash\n# Create difficulty labels (if not exist)\ngh label create \"difficulty: easy\" --color \"0E8A16\" --description \"Simple change, good first issue\" --force\ngh label create \"difficulty: medium\" --color \"FBCA04\" --description \"Moderate complexity\" --force\ngh label create \"difficulty: hard\" --color \"D93F0B\" --description \"Complex, requires significant effort\" --force\n\n# Add label to issue\ngh issue edit <number> --add-label \"difficulty: easy|medium|hard\"\n```\n\n### Step 5: Generate Board Status Report\n\n```markdown\n## Anubis Issue Tracker - Board Status\n\n**Project:** https://github.com/users/forrestthewoods/projects/8\n\n### Summary\n- **Total Issues:** 22\n- **Triage:** 2\n- **Needs Agent Review:** 5\n- **Needs Human Review:** 3\n- **Ready to Implement:** 8\n- **Needs Code Review:** 2\n- **Done:** 2\n\n### By Difficulty\n\n| Difficulty | Triage | Agent Review | Human Review | Ready to Impl | Code Review | Done |\n|------------|--------|--------------|--------------|---------------|-------------|------|\n| Easy       | 0      | 1            | 1            | 3             | 1           | 1    |\n| Medium     | 1      | 2            | 1            | 3             | 1           | 1    |\n| Hard       | 0      | 2            | 1            | 2             | 0           | 0    |\n| Unlabeled  | 1      | 0            | 0            | 0             | 0           | 0    |\n\n### Ready to Implement (Prioritized)\nThese issues have plans and are ready for work:\n\n**Easy (Quick Wins):**\n1. #10 - Fix typo in README\n2. #11 - Add --help examples\n\n**Medium:**\n1. #18 - Add user preferences\n\n**Hard:**\n1. #22 - Refactor build system\n\n### Needs Human Review\nThese need human responses before agent can continue:\n- #4 - Asked about reproduction steps (3 days ago)\n- #9 - Asked about expected behavior (1 day ago)\n\n### Needs Code Review\nImplementation in progress (has active branch):\n- #25 - Parallel builds (branch: claude/issue-25-parallel-builds)\n- #30 - Add caching (branch: claude/issue-30-add-caching)\n\n### Stale Items\nItems that haven''t been updated in 14+ days:\n- #8 - In \"Ready to Implement\" since Dec 1\n- #12 - In \"Needs Human Review\" since Nov 28 (may need follow-up)\n```\n\n### Step 6: Board Hygiene Tasks\n\n**Weekly cleanup checklist:**\n\n1. **Check for orphaned issues:**\n   ```bash\n   # Find open issues not on board\n   gh issue list --state open --json number,title | jq -r ''.[] | \"#\\(.number) - \\(.title)\"''\n   ```\n\n2. **Archive completed items older than 30 days:**\n   - Items in \"Done\" status can be archived to keep board clean\n\n3. **Flag stale \"Needs Code Review\" items:**\n   - Issues in \"Needs Code Review\" for more than 14 days may have stalled PRs\n\n4. **Verify labels match board status:**\n   - All issues should have a difficulty label once they leave \"Triage\"\n\n5. **Check for issues needing triage:**\n   - New issues should be moved from \"Triage\" to \"Needs Agent Review\" promptly\n\n6. **Check for stale \"Needs Human Review\":**\n   - Issues waiting for human response for more than 7 days may need follow-up\n\n7. **Detect issues with active branches:**\n   ```bash\n   # List all remote branches that may correspond to issues\n   git ls-remote --heads origin | grep -E ''claude/issue-|issue-''\n   ```\n   - Issues with active branches should be in \"Needs Code Review\"\n\n## Automation Notes\n\nThe project board has automated workflows that handle:\n- Moving items to \"Done\" when issues are closed\n- Moving items when issues are reopened\n\nThese automations run automatically. Manual/agent status updates are needed for:\n- Moving from \"Triage\" to \"Needs Agent Review\"\n- Agent review decisions (to \"Needs Human Review\" or \"Ready to Implement\")\n- Detecting active branches and moving to \"Needs Code Review\"\n\n## Guidelines\n\n- Keep the board focused on actionable items\n- Update status when actual progress changes\n- Don''t let items sit in \"In-progress\" indefinitely\n- Review stale items weekly\n- Use consistent labeling between issues and board\n- Prioritize items in \"Triage\" status quickly\n- Ensure all open issues are on the board\n\n## Quick Reference Commands\n\n```bash\n# View board\ngh project view 8 --owner forrestthewoods --web\n\n# List all items\ngh project item-list 8 --owner forrestthewoods\n\n# Add issue to board\ngh project item-add 8 --owner forrestthewoods --url <issue-url>\n\n# List open issues\ngh issue list --state open\n\n# View specific issue\ngh issue view <number>\n\n# Edit issue labels\ngh issue edit <number> --add-label \"difficulty: easy\"\n```\n"},"lastSynced":"2026-03-08T02:03:48.996Z","agentAnalysis":{"suitability":{"en":"Perfect for Project Management Agents requiring streamlined workflow and issue tracking capabilities.","zh":"非常适合需要简化工作流程和问题跟踪功能的项目管理代理。","ja":"プロジェクト管理エージェントが効率的なワークフローと問題追跡機能を必要とする場合に最適です。","ko":"프로젝트 관리 에이전트가 효율적인 워크플로우와 이슈 추적 기능을 필요로 하는 경우에 적합합니다.","es":"Perfecto para agentes de gestión de proyectos que requieren un flujo de trabajo optimizado y capacidades de seguimiento de problemas.","fr":"Parfait pour les agents de gestion de projet nécessitant un flux de travail rationalisé et des capacités de suivi de problèmes.","de":"Perfekt für Projektmanagement-Agenten, die ein optimiertes Workflow- und Problemmelde-Management benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos que exigem fluxo de trabalho simplificado e capacidades de rastreamento de problemas.","ru":"Идеально подходит для агентов по управлению проектами, требующих упрощенного рабочего процесса и возможностей отслеживания проблем.","ar":"مثالي للوكلاء لإدارة المشاريع الذين يتطلبون تدفق عمل مبسط وقدرات تتبع المشكلات."},"recommendation":{"en":"Empowers agents to manage projects efficiently using the Anubis Issue Tracker project board with a pre-configured 7-status column workflow, including backlog, and GitHub project integration.","zh":"使得代理能够使用预配置的7状态列工作流的Anubis问题跟踪器项目板，实现项目的高效管理，并与GitHub项目集成。","ja":"エージェントがAnubis Issue Trackerプロジェクトボードの事前に設定された7状態列ワークフローを使用してプロジェクトを効率的に管理し、GitHubプロジェクトと統合できるようにします。","ko":"에이전트가 Anubis 이슈 트래커 프로젝트 보드의 사전 구성된 7 상태 열 워크플로를 사용하여 프로젝트를 효율적으로 관리하고 GitHub 프로젝트와 통합할 수 있도록 합니다.","es":"Habilita a los agentes a gestionar proyectos de manera eficiente utilizando la pizarra de seguimiento de problemas Anubis con un flujo de trabajo de 7 columnas preconfigurado, incluyendo lista de pendientes y integración con GitHub.","fr":"Permet aux agents de gérer les projets de manière efficace en utilisant le tableau de suivi de problèmes Anubis avec un flux de travail de 7 colonnes préconfiguré, y compris la liste de tâches et l''intégration à GitHub.","de":"Ermöglicht es den Agenten, Projekte effizient zu verwalten, indem sie das Anubis Issue Tracker-Projektboard mit einem vorkonfigurierten 7-Status-Spalten-Workflow verwenden, einschließlich Backlog und GitHub-Projektintegration.","pt":"Habilita os agentes a gerenciar projetos de forma eficiente usando o quadro de projeto do Anubis Issue Tracker com um fluxo de trabalho de 7 colunas pré-configurado, incluindo backlog e integração com o projeto do GitHub.","ru":"Позволяет агентам эффективно управлять проектами, используя доску проекта Anubis Issue Tracker с предварительно настроенным рабочим процессом из 7 статусов, включая бэклог и интеграцию с проектом GitHub.","ar":"يُمكن للوكلاء من خلاله إدارة المشاريع بفعالية باستخدام لوحة مشروع Anubis Issue Tracker مع تدفق عمل مسبق التهيئة ذي 7 أعمدة ، بما في ذلك المخزون ودمج مشروع GitHub."},"useCases":{"en":["Streamlining project workflows","Tracking issues with a 7-status column board","Managing projects on GitHub using the Anubis Issue Tracker"],"zh":["简化项目工作流程","使用7状态列板跟踪问题","使用Anubis问题跟踪器在GitHub上管理项目"],"ja":["プロジェクトワークフローの簡素化","7状態列ボードを使用した問題の追跡","Anubis Issue Trackerを使用したGitHubでのプロジェクト管理"],"ko":["프로젝트 워크플로우의 간소화","7 상태 열 보드를 사용한 이슈 추적","Anubis 이슈 트래커를 사용한 GitHub에서의 프로젝트 관리"],"es":["Optimizar flujos de trabajo de proyectos","Seguimiento de problemas con una pizarra de 7 columnas","Gestión de proyectos en GitHub utilizando el Anubis Issue Tracker"],"fr":["Rationaliser les flux de travail de projet","Suivi de problèmes avec un tableau de 7 colonnes","Gestion de projets sur GitHub à l''aide de l''Anubis Issue Tracker"],"de":["Optimieren von Projekt-Workflows","Verfolgen von Problemen mit einer 7-Status-Spalten-Tafel","Verwalten von Projekten auf GitHub mit dem Anubis Issue Tracker"],"pt":["Simplificar fluxos de trabalho de projeto","Rastrear problemas com uma placa de 7 colunas","Gerenciar projetos no GitHub usando o Anubis Issue Tracker"],"ru":["Упрощение рабочих процессов проекта","Отслеживание проблем с помощью доски из 7 столбцов","Управление проектами на GitHub с помощью Anubis Issue Tracker"],"ar":["تبسيط تدفقات عمل المشروع","تتبع المشكلات باستخدام لوحة 7 أعمدة","إدارة المشاريع على منصة GitHub باستخدام Anubis Issue Tracker"]},"limitations":{"en":["Requires access to the Anubis Issue Tracker project board","Limited to project #8 on GitHub","Must use the pre-configured 7-status column workflow"],"zh":["需要访问Anubis问题跟踪器项目板","仅限于GitHub上的项目#8","必须使用预配置的7状态列工作流"],"ja":["Anubis Issue Trackerプロジェクトボードへのアクセスが必要","GitHub上のプロジェクト#8に限定","事前に設定された7状態列ワークフローを使用する必要がある"],"ko":["Anubis 이슈 트래커 프로젝트 보드에 대한 액세스가 필요합니다","GitHub의 프로젝트 #8에만 제한됨","사전 구성된 7 상태 열 워크플로를 사용해야 함"],"es":["Requiere acceso a la pizarra de seguimiento de problemas Anubis","Limitado al proyecto #8 en GitHub","Debe utilizar el flujo de trabajo de 7 columnas preconfigurado"],"fr":["Nécessite un accès au tableau de suivi de problèmes Anubis","Limité au projet #8 sur GitHub","Doit utiliser le flux de travail de 7 colonnes préconfiguré"],"de":["Erfordert Zugriff auf das Anubis Issue Tracker-Projektboard","Begrenzt auf Projekt #8 auf GitHub","Muss den vorkonfigurierten 7-Status-Spalten-Workflow verwenden"],"pt":["Exige acesso à placa de projeto do Anubis Issue Tracker","Limitado ao projeto #8 no GitHub","Deve usar o fluxo de trabalho de 7 colunas pré-configurado"],"ru":["Требует доступа к доске проекта Anubis Issue Tracker","Ограничен проектом #8 на GitHub","Должен использовать предварительно настроенный рабочий процесс из 7 статусов"],"ar":["يتطلب الوصول إلى لوحة مشروع Anubis Issue Tracker","محدود بمشروع #8 على منصة GitHub","يجب استخدامه مع تدفق العمل المسبق التهيئة ذي 7 أعمدة"]},"version":4},"contentHash":"73da49bc4690a268ac839e9426e2d08d1dbf7f0c4f9e4f041974e790fb9188f9","qualityScore":60}');
