INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('forrestthewoods/anubis/kanban-management', 'kanban-management', 'forrestthewoods', 'anubis', 'community', 'kanban-management forrestthewoods anubis community The kanban-management skill utilizes the Anubis Issue Tracker project board for streamlined project management. This skill benefits developers and project managers by providing a pre-configured board with a 7-status column workflow. Kanban管理是一种使用项目板进行项目管理的方法，Anubis Issue Tracker项目板已配置好七个状态列 Kanbanマネージメントは、プロジェクトボードを使用したプロジェクト管理方法であり、Anubis Issue Trackerプロジェクトボードには7つのステータス列が設定されています 칸반 관리는 프로젝트 보드를 사용하여 프로젝트를 관리하는 방법으로, Anubis Issue Tracker 프로젝트 보드에는 7개의 상태 열이 구성되어 있습니다 La gestión Kanban es una técnica de gestión de proyectos que utiliza un tablero de proyecto para visualizar y gestionar el trabajo La gestion Kanban est une technique de gestion de projets qui utilise un tableau de projet pour visualiser et gérer les tâches Die Kanban-Verwaltung ist eine Projektmanagement-Technik, die ein Projektboard verwendet, um die Arbeit zu visualisieren und zu verwalten O kanban management é uma técnica de gerenciamento de projetos que visa melhorar a produtividade e a eficiência do time de desenvolvimento Канбан управление - это техника управления проектами, направленная на повышение производительности и эффективности команды разработчиков إدارة كانبان هي تقنية لإدارة المشاريع تهدف إلى تحسين الإنتاجية والكفاءة لفريق التطوير how to use kanban-management what is kanban-management kanban-management alternative kanban-management vs trello kanban-management install kanban-management setup guide anubis issue tracker tutorial github projects kanban-management Kanban管理 项目管理 Anubis Issue Tracker GitHub项目管理 项目板 状态列 工作项管理 Utilizes the Anubis Issue Tracker project board with a pre-configured 7-status column workflow Supports project management via the GitHub projects interface Includes a specific project URL (https://github.com/users/forrestthewoods/projects/8) for easy access Features a project board with a unique project number (#8) for organization Employs a board status workflow with columns like Backlog for future ideas or deferred work Requires use of project #8, eliminating the need to create a new project board Kanban-management is a project management approach using a pre-configured board with status columns like Backlog, to track and visualize work progress.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ADLenehan/battery/cli-patterns', 'community', 'ADLenehan', 'battery', 'ADLenehan/battery', 'cli-patterns', 0, 0, 60, '2026-03-08T01:57:15.352Z', '2026-03-08T02:03:52.572Z', 'fdc3424fa0a45dc2c320bc2894ae384c51794b3a26189b7bf2b28a1bb6987d08', '{"id":"ADLenehan/battery/cli-patterns","name":"cli-patterns","description":{"en":"cli-patterns provides safe hosting for non-technical users by utilizing Commander.js for command structure. It benefits developers and non-technical users alike by simplifying application deployment.","zh":"CLI Patterns 提供安全托管解决方案，使用 Commander.js 创建命令","ja":"CLI パターンは安全なホスティングの解決策を提供し、Commander.js を使用してコマンドを作成します","ko":"CLI 패턴은 안전한 호스팅 솔루션을 제공하며 Commander.js를 사용하여 명령을 생성합니다","es":"CLI Patterns proporciona una forma segura de hospedaje para proyectos de AI no técnicos, utilizando Commander.js para comandos CLI","fr":"CLI Patterns offre un hébergement sécurisé pour les projets d''IA non techniques, en utilisant Commander.js pour les commandes CLI","de":"CLI Patterns bietet sichere Hosting-Möglichkeiten für nicht-technische KI-Projekte, indem Commander.js für CLI-Befehle verwendet wird","pt":"Padrões de CLI para hospedagem segura de aplicações. Use Commander.js para criar comandos personalizados.","ru":"Шаблоны CLI для безопасного хостинга приложений. Используйте Commander.js для создания пользовательских команд.","ar":"أنماط CLI لاستضافة تطبيقات آمنة. استخدم Commander.js لإنشاء أوامر مخصصة."},"seo":{"title":{"en":"cli-patterns: Commander.js Setup Guide | AI Agent Skill","zh":"CLI Patterns 安全托管指南","ja":"CLI パターンを使用した安全なホスティングの設定方法","ko":"CLI 패턴을 사용한 안전한 호스팅 설정 가이드","es":"Guía de configuración de CLI Patterns para herramientas d...","fr":"Guide de configuration de CLI Patterns pour les outils d''IA","de":"Konfigurationsleitfaden für CLI Patterns in KI-Tools","pt":"Guia de Configuração de Padrões de CLI para Ferramentas d...","ru":"Настройка шаблонов CLI для ИИ Агентов","ar":"دليل إعداد أنماط CLI لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how cli-patterns simplifies safe hosting for non-technical users with Commander.js. Learn to deploy applications with ease and explore its features.","zh":"了解如何使用 Commander.js 创建安全的 CLI 命令，实现应用程序的安全托管","ja":"Commander.js を使用して安全な CLI コマンドを作成し、アプリケーションの安全なホスティングを実現する方法","ko":"Commander.js를 사용하여 안전한 CLI 명령을 생성하고 애플리케이션의 안전한 호스팅을 구현하는 방법","es":"Aprende a utilizar Commander.js para crear comandos CLI seguros y fáciles de usar en tus proyectos de AI","fr":"Découvrez comment utiliser Commander.js pour créer des commandes CLI sûres et faciles à utiliser dans vos projets d''IA","de":"Erfahren Sie, wie Sie Commander.js verwenden können, um sichere und benutzerfreundliche CLI-Befehle in Ihren KI-Projekten zu erstellen","pt":"Aprenda a configurar padrões de CLI para hospedagem segura de aplicações com Commander.js","ru":"Узнайте, как настроить шаблоны CLI для безопасного хостинга приложений с помощью Commander.js","ar":"تعرف على كيفية تعيين أنماط CLI لاستضافة تطبيقات آمنة باستخدام Commander.js"},"definition":{"en":"cli-patterns is a skill that utilizes Commander.js to provide a structured command line interface for safe hosting, specifically designed for non-technical users.","zh":"CLI Patterns 是一种使用 Commander.js 创建安全 CLI 命令的方法","ja":"CLI パターンは、Commander.js を使用して安全な CLI コマンドを作成する方法です","ko":"CLI 패턴은 Commander.js를 사용하여 안전한 CLI 명령을 생성하는 방법입니다","es":"CLI Patterns es un conjunto de patrones de diseño para crear comandos CLI seguros y fáciles de usar en proyectos de AI","fr":"CLI Patterns est un ensemble de modèles de conception pour créer des commandes CLI sûres et faciles à utiliser dans les projets d''IA","de":"CLI Patterns ist eine Sammlung von Designmustern für die Erstellung sicherer und benutzerfreundlicher CLI-Befehle in KI-Projekten","pt":"Padrões de CLI são estruturas de comandos personalizados para hospedagem segura de aplicações","ru":"Шаблоны CLI - это структуры пользовательских команд для безопасного хостинга приложений","ar":"أنماط CLI هي هياكل أوامر مخصصة لاستضافة تطبيقات آمنة"},"features":{"en":["Utilizes Commander.js for command structure","Supports basic commands like deploy with options for environment and dry-run","Commands are stored in packages/cli/src/commands/","Allows for argument specification, such as path to application directory","Includes options for targeting specific environments, like production"],"zh":["使用 Commander.js 创建安全的 CLI 命令","支持自定义命令参数和选项","提供应用程序部署和环境管理功能","支持 dry-run 模式进行部署前验证","使用 TypeScript 编写命令"],"ja":["Commander.js を使用して安全な CLI コマンドを作成","カスタムコマンドパラメータとオプションをサポート","アプリケーションのデプロイと環境管理機能を提供","dry-run モードをサポートしてデプロイ前の検証を行う","TypeScript を使用してコマンドを記述"],"ko":["Commander.js를 사용하여 안전한 CLI 명령을 생성","사용자 정의 명령 매개 변수 및 옵션 지원","애플리케이션 배포 및 환경 관리 기능 제공","dry-run 모드를 지원하여 배포 전 검증","TypeScript를 사용하여 명령을 작성"],"es":["Utiliza Commander.js para crear comandos CLI","Comandos personalizados con opciones y argumentos","Soporte para entornos de ejecución diferentes","Opción de simulación para probar comandos sin ejecutarlos","Estructura de comandos organizada en paquetes"],"fr":["Utilise Commander.js pour créer des commandes CLI","Commandes personnalisées avec options et arguments","Prise en charge de différents environnements d''exécution","Option de simulation pour tester les commandes sans les exécuter","Structure de commandes organisée en paquets"],"de":["Verwenden von Commander.js für die Erstellung von CLI-Befehlen","Benutzerdefinierte Befehle mit Optionen und Argumenten","Unterstützung für verschiedene Ausführungsumgebungen","Simulationsfunktion zum Testen von Befehlen ohne Ausführung","Organisierte Befehlsstruktur in Paketen"],"pt":["Criação de comandos personalizados com Commander.js","Estrutura de comandos em `packages/cli/src/commands/`","Opções de linha de comando com `.option()`","Argumentos de linha de comando com `.argument()`","Comandos básicos com `.description()`","Suporte a deploy em ambientes de produção"],"ru":["Создание пользовательских команд с помощью Commander.js","Структура команд в `packages/cli/src/commands/`","Опции командной строки с `.option()`","Аргументы командной строки с `.argument()`","Базовые команды с `.description()`","Поддержка деплоя в продакшн-окружении"],"ar":["إنشاء أوامر مخصصة باستخدام Commander.js","هيكل الأوامر في `packages/cli/src/commands/`","خيارات سطر الأوامر مع `.option()`","معاملات سطر الأوامر مع `.argument()`","أوامر أساسية مع `.description()`","دعم النشر في بيئات الإنتاج"]},"keywords":{"en":["how to use cli-patterns","cli-patterns setup guide","what is cli-patterns","cli-patterns alternative","cli-patterns vs Commander.js","cli-patterns install","Commander.js tutorial","safe hosting solutions","non-technical user deployment"],"zh":["CLI Patterns","Commander.js","安全托管","CLI 命令","TypeScript","应用程序部署","环境管理","AIエージェント"],"ja":["CLI パターン","Commander.js","安全なホスティング","CLI コマンド","TypeScript","アプリケーションのデプロイ","環境管理","AIエージェント"],"ko":["CLI 패턴","Commander.js","안전한 호스팅","CLI 명령","TypeScript","애플리케이션 배포","환경 관리","AI 도구"],"es":["CLI Patterns","Comandos CLI","Commander.js","Herramientas de AI","Proyectos de AI","Seguridad en CLI","Diseño de comandos CLI","Entornos de ejecución","Simulación de comandos"],"fr":["CLI Patterns","Commandes CLI","Commander.js","Outils d''IA","Projets d''IA","Sécurité CLI","Conception de commandes CLI","Environnements d''exécution","Simulation de commandes"],"de":["CLI Patterns","CLI-Befehle","Commander.js","KI-Tools","KI-Projekte","Sicherheit in CLI","Entwurf von CLI-Befehlen","Ausführungsumgebungen","Befehlssimulation"],"pt":["padrões de CLI","Commander.js","hospedagem segura","comandos personalizados","deploy em produção","desenvolvimento de aplicações","ferramentas de IA","segurança de aplicações"],"ru":["шаблоны CLI","Commander.js","безопасный хостинг","пользовательские команды","деплой в продакшн","разработка приложений","ИИ Агенты","безопасность приложений"],"ar":["أنماط CLI","Commander.js","استضافة آمنة","أوامر مخصصة","نشر في الإنتاج","تطوير التطبيقات","أدوات الذكاء الاصطناعي","أمان التطبيقات"]}},"owner":"ADLenehan","repo":"battery","repoPath":"ADLenehan/battery","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.352Z","topics":[],"category":"community","skillMd":{"name":"cli-patterns","description":"Patterns for building Battery CLI commands with Commander.js. Use this skill when creating new CLI commands, adding options/flags, formatting output, handling errors, or implementing interactive prompts.","bodyPreview":"# CLI Patterns\n\n## Command Structure\n\nUse Commander.js for all CLI commands. Commands live in `packages/cli/src/commands/`.\n\n### Basic Command\n\n```typescript\nimport { Command } from ''commander''\n\nexport const deployCommand = new Command(''deploy'')\n  .description(''Deploy an application to Battery'')\n  .argument(''<path>'', ''Path to the application directory'')\n  .option(''-e, --env <environment>'', ''Target environment'', ''production'')\n  .option(''--dry-run'', ''Show what would be deployed without deploying'')","body":"# CLI Patterns\n\n## Command Structure\n\nUse Commander.js for all CLI commands. Commands live in `packages/cli/src/commands/`.\n\n### Basic Command\n\n```typescript\nimport { Command } from ''commander''\n\nexport const deployCommand = new Command(''deploy'')\n  .description(''Deploy an application to Battery'')\n  .argument(''<path>'', ''Path to the application directory'')\n  .option(''-e, --env <environment>'', ''Target environment'', ''production'')\n  .option(''--dry-run'', ''Show what would be deployed without deploying'')\n  .action(async (path, options) => {\n    // Implementation\n  })\n```\n\n### Command with Subcommands\n\n```typescript\nexport const configCommand = new Command(''config'')\n  .description(''Manage Battery configuration'')\n\nconfigCommand\n  .command(''set <key> <value>'')\n  .description(''Set a configuration value'')\n  .action(async (key, value) => {})\n\nconfigCommand\n  .command(''get <key>'')\n  .description(''Get a configuration value'')\n  .action(async (key) => {})\n```\n\n## Output Formatting\n\n### Chalk for Colors\n\n```typescript\nimport chalk from ''chalk''\n\n// Status messages\nconsole.log(chalk.green(''✓''), ''Deployment successful'')\nconsole.log(chalk.yellow(''!''), ''Warning: No auth detected'')\nconsole.log(chalk.red(''✗''), ''Error: Invalid credentials'')\n\n// Emphasis\nconsole.log(chalk.bold(''Scanning...''))\nconsole.log(chalk.dim(''Press Ctrl+C to cancel''))\n\n// URLs and paths\nconsole.log(chalk.cyan(''https://app.battery.dev''))\nconsole.log(chalk.gray(''./src/config.ts''))\n```\n\n### Ora for Spinners\n\n```typescript\nimport ora from ''ora''\n\nconst spinner = ora(''Scanning for credentials...'').start()\n\ntry {\n  const results = await scan(path)\n  spinner.succeed(''Scan complete'')\n} catch (error) {\n  spinner.fail(''Scan failed'')\n  throw error\n}\n```\n\n### Tree Output\n\n```typescript\nfunction printTree(items: string[], indent = 0): void {\n  const prefix = ''  ''.repeat(indent)\n  items.forEach((item, i) => {\n    const isLast = i === items.length - 1\n    const branch = isLast ? ''└──'' : ''├──''\n    console.log(`${prefix}${branch} ${item}`)\n  })\n}\n\n// Output:\n// ├── Detected: Next.js\n// ├── Found credentials:\n// │   ├── SNOWFLAKE_PASSWORD in .env\n// │   └── SALESFORCE_TOKEN in lib/api.ts\n// └── Deploying...\n```\n\n## Error Handling\n\n### Exit Codes\n\n```typescript\nexport const ExitCode = {\n  Success: 0,\n  GeneralError: 1,\n  InvalidArgument: 2,\n  ConfigError: 3,\n  NetworkError: 4,\n  AuthError: 5,\n} as const\n\nprocess.exit(ExitCode.InvalidArgument)\n```\n\n### Error Display\n\n```typescript\nimport chalk from ''chalk''\n\nfunction handleError(error: Error): never {\n  console.error()\n  console.error(chalk.red(''Error:''), error.message)\n\n  if (error.cause) {\n    console.error(chalk.dim(''Cause:''), String(error.cause))\n  }\n\n  if (process.env.DEBUG) {\n    console.error(chalk.dim(error.stack))\n  }\n\n  process.exit(ExitCode.GeneralError)\n}\n```\n\n### Graceful Shutdown\n\n```typescript\nprocess.on(''SIGINT'', () => {\n  console.log()\n  console.log(chalk.dim(''Cancelled''))\n  process.exit(130)\n})\n```\n\n## Interactive Prompts\n\nUse @inquirer/prompts for user input.\n\n### Confirmation\n\n```typescript\nimport { confirm } from ''@inquirer/prompts''\n\nconst proceed = await confirm({\n  message: ''Deploy to production?'',\n  default: false,\n})\n```\n\n### Selection\n\n```typescript\nimport { select } from ''@inquirer/prompts''\n\nconst environment = await select({\n  message: ''Select environment'',\n  choices: [\n    { name: ''Production'', value: ''production'' },\n    { name: ''Staging'', value: ''staging'' },\n    { name: ''Development'', value: ''development'' },\n  ],\n})\n```\n\n### Text Input\n\n```typescript\nimport { input } from ''@inquirer/prompts''\n\nconst projectName = await input({\n  message: ''Project name'',\n  default: path.basename(process.cwd()),\n  validate: (value) => {\n    if (!/^[a-z0-9-]+$/.test(value)) {\n      return ''Must be lowercase alphanumeric with hyphens''\n    }\n    return true\n  },\n})\n```\n\n### Password Input\n\n```typescript\nimport { password } from ''@inquirer/prompts''\n\nconst token = await password({\n  message: ''Enter your API token'',\n  mask: ''*'',\n})\n```\n\n## Configuration Files\n\n### Config Location\n\n```typescript\nimport { homedir } from ''os''\nimport { join } from ''path''\n\nconst CONFIG_DIR = join(homedir(), ''.battery'')\nconst CONFIG_FILE = join(CONFIG_DIR, ''config.json'')\nconst CREDENTIALS_FILE = join(CONFIG_DIR, ''credentials.json'')\n```\n\n### Config Schema\n\n```typescript\ninterface BatteryConfig {\n  defaultOrg?: string\n  defaultEnvironment?: ''production'' | ''staging''\n  telemetry?: boolean\n}\n```\n\n## Patterns to Follow\n\n1. **Always show progress** - Use spinners for operations > 500ms\n2. **Confirm destructive actions** - Prompt before deleting or overwriting\n3. **Support --json flag** - For programmatic output\n4. **Respect NO_COLOR** - Disable colors when env var is set\n5. **Use stderr for errors** - Keep stdout clean for piping\n"},"lastSynced":"2026-03-08T02:03:52.572Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing structured command-line interface patterns with Commander.js","zh":"适合需要结构化命令行接口模式的开发者代理，使用 Commander.js","ja":"Commander.js を使用して構造化されたコマンドラインインターフェイス パターンを必要とする Developer エージェントに適しています","ko":"Commander.js를 사용하여 구조화된 명령줄 인터페이스 패턴이 필요한 개발자 에이전트에게 적합합니다","es":"Perfecto para Agentes de Desarrollador que necesitan patrones de interfaz de línea de comandos estructurados con Commander.js","fr":"Parfait pour les Agents de Développeur ayant besoin de modèles d''interface de ligne de commande structurés avec Commander.js","de":"Perfekt für Developer-Agents, die strukturierte Befehlszeilen-Schnittstellen-Muster mit Commander.js benötigen","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de padrões de interface de linha de comando estruturados com Commander.js","ru":"Идеально для агентов-разработчиков, которым необходимы структурированные шаблоны командной строки с Commander.js","ar":"مثالي لعميل المطور الذي يحتاج إلى أنماط واجهة سطر الأوامر المنظمة مع Commander.js"},"recommendation":{"en":"Empowers agents to simplify application deployment using Commander.js for command structure, allowing safe hosting for non-technical users and streamlining development with features like argument parsing and option handling for environments and dry-run simulations","zh":"赋予代理简化应用程序部署的能力，使用 Commander.js 进行命令结构，允许非技术用户安全托管，并通过诸如参数解析和选项处理等功能简化开发，支持环境和 dry-run 模拟","ja":"Commander.js を使用してコマンド構造を実行することで、アプリケーションの展開を簡素化し、非技術ユーザーが安全にホスティングできるようにし、環境や dry-run シミュレーションなどの機能を使用して開発を簡素化するエージェントの能力を付与します","ko":"Commander.js를 사용하여 명령 구조를 수행함으로써 애플리케이션 배포를 단순화하고 비기술 사용자가 안전하게 호스팅 할 수 있도록 하며, 환경 및 dry-run 시뮬레이션 등의 기능을 사용하여 개발을 단순화하는 에이전트의 능력을 부여합니다","es":"Permite a los agentes simplificar la implementación de aplicaciones utilizando Commander.js para la estructura de comandos, lo que permite un alojamiento seguro para usuarios no técnicos y agiliza el desarrollo con características como el análisis de argumentos y el manejo de opciones para entornos y simulaciones de ejecución en seco","fr":"Permet aux agents de simplifier le déploiement d''applications en utilisant Commander.js pour la structure de commande, ce qui permet un hébergement sécurisé pour les utilisateurs non techniques et rationalise le développement avec des fonctionnalités comme l''analyse des arguments et la gestion des options pour les environnements et les simulations de dry-run","de":"Ermächtigt Agenten, die Anwendungsbereitstellung mithilfe von Commander.js für die Befehlsstruktur zu vereinfachen, was ein sicheres Hosting für nicht-technische Benutzer ermöglicht und die Entwicklung mit Funktionen wie Argumentparsing und Optionenhandhabung für Umgebungen und Dry-Run-Simulationen rationalisiert","pt":"Habilita os agentes a simplificar a implantação de aplicativos usando Commander.js para estrutura de comandos, permitindo hospedagem segura para usuários não técnicos e simplificando o desenvolvimento com recursos como análise de argumentos e manipulação de opções para ambientes e simulações de dry-run","ru":"Наделяет агентов возможностью упростить развертывание приложений с помощью Commander.js для структуры команд, обеспечивая безопасное размещение для нетехнических пользователей и оптимизируя разработку с помощью функций, таких как парсинг аргументов и обработка опций для сред и симуляций dry-run","ar":"يمنح الوكيل القدرة على تبسيط نشر التطبيقات باستخدام Commander.js لهيكلة الأوامر، مما يتيح استضافة آمنة للمستخدمين غير التقنيين وتبسيط التطوير باستخدام ميزات مثل تحليل الحجج ومعالجة الخيارات للبيئات ومحاكاة التشغيل الجاف"},"useCases":{"en":["Deploying applications to specific environments","Simplifying command-line interfaces with structured patterns","Validating command arguments and options"],"zh":["将应用程序部署到特定环境","使用结构化模式简化命令行接口","验证命令参数和选项"],"ja":["特定環境へのアプリケーションの展開","構造化されたパターンを使用してコマンドライン インターフェイスを簡素化する","コマンドの引数とオプションを検証する"],"ko":["특정 환경에 애플리케이션 배포","구조화된 패턴을 사용하여 명령줄 인터페이스를 단순화","명령 인수 및 옵션을 검증"],"es":["Implementar aplicaciones en entornos específicos","Simplificar interfaces de línea de comandos con patrones estructurados","Validar argumentos y opciones de comandos"],"fr":["Déployer des applications dans des environnements spécifiques","Simplifier les interfaces de ligne de commande avec des modèles structurés","Valider les arguments et les options de commande"],"de":["Anwendungen in bestimmten Umgebungen bereitstellen","Befehlszeilen-Schnittstellen mit strukturierten Mustern vereinfachen","Befehlsargumente und -optionen überprüfen"],"pt":["Implantação de aplicativos em ambientes específicos","Simplificação de interfaces de linha de comando com padrões estruturados","Validação de argumentos e opções de comando"],"ru":["Развертывание приложений в конкретные среды","Упрощение интерфейсов командной строки с помощью структурированных шаблонов","Валидация аргументов и опций команд"],"ar":["نشر التطبيقات في بيئات محددة","تبسيط واجهات سطر الأوامر بأنماط منظم","تحقق من حجج وأوامر الأوامر"]},"limitations":{"en":["Requires Commander.js library","Limited to TypeScript-based projects","Dependent on packages/cli/src/commands/ directory structure"],"zh":["需要 Commander.js 库","仅限于 TypeScript 基础项目","依赖于 packages/cli/src/commands/ 目录结构"],"ja":["Commander.js ライブラリが必要","TypeScript ベースのプロジェクトに限定される","packages/cli/src/commands/ ディレクトリ構造に依存する"],"ko":["Commander.js 라이브러리가 필요","TypeScript 기반 프로젝트에만 제한","packages/cli/src/commands/ 디렉토리 구조에 의존"],"es":["Requiere la biblioteca Commander.js","Limitado a proyectos basados en TypeScript","Dependiente de la estructura del directorio packages/cli/src/commands/"],"fr":["Nécessite la bibliothèque Commander.js","Limité aux projets basés sur TypeScript","Dépend de la structure du répertoire packages/cli/src/commands/"],"de":["Erfordert die Commander.js-Bibliothek","Begrenzt auf TypeScript-basierte Projekte","Abhängig von der Verzeichnisstruktur packages/cli/src/commands/"],"pt":["Exige a biblioteca Commander.js","Limitado a projetos baseados em TypeScript","Dependente da estrutura de diretório packages/cli/src/commands/"],"ru":["Требует библиотеки Commander.js","Ограничен проектами на основе TypeScript","Зависит от структуры директории packages/cli/src/commands/"],"ar":["يتطلب مكتبة Commander.js","محدود بمشاريع قائمة على TypeScript","يعتمد على هيكل دليل packages/cli/src/commands/"]},"version":4},"contentHash":"fdc3424fa0a45dc2c320bc2894ae384c51794b3a26189b7bf2b28a1bb6987d08","qualityScore":60}');
