INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dredd-us/seashells/code-testing', 'code-testing', 'dredd-us', 'seashells', 'community', 'code-testing dredd-us seashells community Code-testing generates and runs comprehensive unit and integration tests following TDD principles, benefiting developers in code review validation and coverage verification. 代码测试AI工具帮助开发人员生成和运行全面单元和集成测试，确保代码质量 コードテストAIエージェントは、開発者が包括的なユニットと統合テストを生成して実行するのに役立ち、コード品質を確保します 코드 테스팅 AI 도구는 개발자가 포괄적인 유닛 및 통합 테스트를 생성하여 실행하는 것을 도와줌으로써 코드 품질을 보장합니다 El código de pruebas es una habilidad que permite generar y ejecutar pruebas unitarias e integrales completas siguiendo principios de TDD Le code de test est une compétence qui permet de générer et d''exécuter des tests unitaires et intégraux complets suivant les principes de TDD Der Code-Test ist eine Fähigkeit, die die Erstellung und Ausführung umfassender Einheits- und Integrations-tests nach TDD-Prinzipien ermöglicht O teste de código é uma ferramenta essencial para garantir a qualidade do código, utilizando pytest para testes de unidade e integração Тестирование кода - необходимый инструмент для обеспечения качества кода, использующий pytest для модульного и интеграционного тестирования اختبار الكود هو أداة ضرورية لضمان جودة الكود، باستخدام pytest لاختبارات الوحدة والدمج how to use code-testing code-testing setup guide TDD principles in code-testing code-testing vs Jest code-testing install for Python code-testing for CI/CD pipeline integration 代码测试 TDD 单元测试 集成测试 代码覆盖率 CI/CD AI工具 代码质量 pytest Generates unit tests using pytest Supports test-driven development (TDD) principles Includes fixtures, mocking, and coverage measurement Enables code review validation and regression testing Integrates with CI/CD pipelines for automated testing Code-testing is a web-based SSH session manager with a chat-like interface for generating and running comprehensive unit and integration tests.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('VledicFranco/organon/organon-tools-developer', 'community', 'VledicFranco', 'organon', 'VledicFranco/organon', 'organon-tools-developer', 0, 0, 60, '2026-03-08T01:57:15.352Z', '2026-03-08T02:03:53.046Z', 'd865733a235954ef025ce53b8be753e22adb6d5680d134f3b276d9d34321e9bd', '{"id":"VledicFranco/organon/organon-tools-developer","name":"organon-tools-developer","description":{"en":"The organon-tools-developer skill ensures that tools enforcing methodology are built using methodology, benefiting developers working with organon-tools. It streamlines development by validating CLI commands, verification gates, and MCP tools.","zh":"Organon Tools Developer Skill 是一个 Claude 代理技能，确保开发工具遵循其自身的方法论。它支持 CLI 命令、验证门和 MCP 工具的开发。","ja":"Organon Tools Developer Skill は Claude エージェント スキルであり、開発ツールがその自身の方法論に従っていることを保証します。CLI コマンド、検証ゲート、MCP ツールの開発をサポートします。","ko":"Organon Tools Developer Skill은 Claude 에이전트 스킬로서 개발 도구가 자신의 방법론을 따르는 것을 보장합니다. CLI 명령, 확인 게이트 및 MCP 도구의 개발을 지원합니다.","es":"El skill organon-tools-developer garantiza que las herramientas de metodología se desarrollen utilizando metodología, con soporte para CLI y MCP.","fr":"Le skill organon-tools-developer assure que les outils de méthodologie sont développés en utilisant la méthodologie, avec prise en charge de CLI et MCP.","de":"Der Skill organon-tools-developer stellt sicher, dass Methodik-Tools mithilfe von Methodik entwickelt werden, mit Unterstützung für CLI und MCP.","pt":"O Organon Tools Developer é uma habilidade do Claude para agentes que desenvolvem ferramentas de metodologia, garantindo que as ferramentas sejam desenvolvidas usando metodologia","ru":"Organon Tools Developer — навык Claude для агентов, разрабатывающих инструменты методологии, обеспечивающий разработку инструментов с помощью методологии ИИ Агенты","ar":"أداة Organon Tools Developer هي مهارة من كلود لتعليم الوكلاء تطوير أدوات المنهجية، لضمان تطوير الأدوات باستخدام المنهجية"},"seo":{"title":{"en":"organon-tools-developer: Methodology Enforcement Setup Gu...","zh":"Organon Tools Developer Setup Guide - AIエージェント开发最佳实践","ja":"Organon Tools Developer ベストプラクティス - AIエージェント開発ガイド","ko":"Organon Tools Developer 설정 가이드 - AI 에이전트 개발 모범 사례","es":"Guía de configuración de organon-tools-developer para age...","fr":"Guide de mise en place d''outils pour les agents de dévelo...","de":"Einrichtungsleitfaden für organon-tools-developer für KI-...","pt":"Guia de Configuração do Organon Tools Developer","ru":"Настройка Organon Tools Developer: Лучшие Практики","ar":"دليل إعداد أداة Organon Tools Developer"},"description":{"en":"Unlock efficient organon-tools development with this AI agent skill, ensuring methodology consistency - learn how to get started now!","zh":"了解 Organon Tools Developer Skill 的技术细节，确保开发遵循其自身的方法论，提高 CLI 命令、验证门和 MCP 工具的开发效率。","ja":"Organon Tools Developer Skill の技術的詳細を学び、開発がその自身の方法論に従っていることを確認し、CLI コマンド、検証ゲート、MCP ツールの開発効率を向上させる。","ko":"Organon Tools Developer Skill의 기술 세부 정보를学习하고 개발이 자신의 방법론을 따르는지 확인하여 CLI 명령, 확인 게이트 및 MCP 도구의 개발 효율성을 향상시키십시오.","es":"Aprende a utilizar el skill organon-tools-developer para desarrollar herramientas de metodología con CLI y MCP","fr":"Découvrez comment utiliser le skill organon-tools-developer pour développer des outils de méthodologie avec CLI et MCP","de":"Erfahren Sie, wie Sie den Skill organon-tools-developer verwenden, um Methodik-Tools mit CLI und MCP zu entwickeln","pt":"Aprenda a configurar o Organon Tools Developer para garantir que as ferramentas de metodologia sejam desenvolvidas usando metodologia","ru":"Узнайте, как настроить Organon Tools Developer, чтобы обеспечить разработку инструментов методологии с помощью методологии ИИ Агенты","ar":"تعرف على كيفية إعداد أداة Organon Tools Developer لضمان تطوير أدوات المنهجية باستخدام المنهجية"},"definition":{"en":"organon-tools-developer is a Claude skill for agents developing organon-tools, ensuring that the tools follow the methodology specification.","zh":"Organon Tools Developer Skill 是一种 Claude 代理技能，用于确保开发工具遵循其自身的方法论。","ja":"Organon Tools Developer Skill は、開発ツールがその自身の方法論に従っていることを保証する Claude エージェント スキルです。","ko":"Organon Tools Developer Skill은 개발 도구가 자신의 방법론을 따르는 것을 보장하는 Claude 에이전트 스킬입니다.","es":"El skill organon-tools-developer es una habilidad para agentes de IA que desarrollan herramientas de metodología","fr":"Le skill organon-tools-developer est une compétence pour les agents de développement qui créent des outils de méthodologie","de":"Der Skill organon-tools-developer ist eine Fähigkeit für KI-Agenten, die Methodik-Tools entwickeln","pt":"O que é Organon Tools Developer? É uma habilidade do Claude que garante que as ferramentas de metodologia sejam desenvolvidas usando metodologia","ru":"Что такое Organon Tools Developer? Это навык Claude, обеспечивающий разработку инструментов методологии с помощью методологии ИИ Агенты","ar":"ما هي أداة Organon Tools Developer؟ هي مهارة من كلود لضمان تطوير أدوات المنهجية باستخدام المنهجية"},"features":{"en":["Adds new CLI commands (organon <command>) with methodology consistency","Supports addition of new verification gates for enhanced validation","Enables evolution of methodology specification (book-llms/) with precision","Facilitates bug fixing and refactoring of organon-tools code with adherence to methodology","Ensures development of new MCP tools/prompt/resource aligns with methodology"],"zh":["支持添加新 CLI 命令（organon <command>）","支持添加新验证门","支持添加新 MCP 工具/提示/资源","支持演化方法论规范（book-llms/）","支持修复 bug 和重构 organon-tools 代码"],"ja":["新しい CLI コマンド（organon <command>）の追加をサポート","新しい検証ゲートの追加をサポート","新しい MCP ツール/プロンプト/リソースの追加をサポート","方法論仕様（book-llms/）の進化をサポート","バグの修正と organon-tools コードのリファクタリングをサポート"],"ko":["새로운 CLI 명령（organon <command>）추가를 지원","새로운 확인 게이트 추가를 지원","새로운 MCP 도구/프롬프트/리소스 추가를 지원","방법론 사양（book-llms/）의 진화를 지원","버그 수정 및 organon-tools 코드 리팩토링을 지원"],"es":["Soporte para agregar nuevos comandos de CLI (organon <command>)","Integración con verificación de puertas (verification gate)","Desarrollo de herramientas y recursos de MCP","Evolución de la especificación de metodología (book-llms/)","Depuración y refactorización de código de organon-tools"],"fr":["Prise en charge de l''ajout de nouveaux commandes CLI (organon <command>)","Intégration avec la vérification de portes (verification gate)","Développement d''outils et de ressources MCP","Évolution de la spécification de méthodologie (book-llms/)","Débogage et refactorisation du code d''organon-tools"],"de":["Unterstützung für das Hinzufügen neuer CLI-Befehle (organon <command>)","Integration mit der Überprüfung von Toren (verification gate)","Entwicklung von Tools und Ressourcen für MCP","Weiterentwicklung der Methodik-Spezifikation (book-llms/)","Fehlerbehebung und Refactoring von organon-tools-Code"],"pt":["Adicionar novos comandos CLI (organon <comando>)","Adicionar novas portas de verificação","Adicionar novas ferramentas/prompt/recursos MCP","Evolutionar a especificação de metodologia (book-llms/)","Corrigir bugs ou refatorar código organon-tools"],"ru":["Добавить новые команды CLI (organon <команда>)","Добавить новые ворота проверки","Добавить новые инструменты/предложения/ресурсы MCP","Эволюционировать спецификацию методологии (book-llms/)","Исправить ошибки или рефакторить код organon-tools ИИ Агенты"],"ar":["إضافة أوامر CLI جديدة (organon <الأمر>)","إضافة بوابات التحقق الجديدة","إضافة أدوات/تحفيز/موارد MCP جديدة","تطوير مواصفات المنهجية (book-llms/)","إصلاح الأخطاء أو إعادة هيكلة代码 organon-tools"]},"keywords":{"en":["how to use organon-tools-developer","what is organon-tools-developer","organon-tools-developer setup guide","organon-tools-developer install","organon-tools-developer alternative","organon-tools-developer vs competing tools","methodology enforcement in organon-tools","organon-tools development best practices","organon-tools CLI command development"],"zh":["Organon Tools Developer Skill","AIエージェント开发","CLI 命令开发","验证门开发","MCP 工具开发","方法论规范","organon-tools 开发"],"ja":["Organon Tools Developer Skill","AIエージェント開発","CLI コマンド開発","検証ゲート開発","MCP ツール開発","方法論仕様","organon-tools 開発"],"ko":["Organon Tools Developer Skill","AI 에이전트 개발","CLI 명령 개발","확인 게이트 개발","MCP 도구 개발","방법론 사양","organon-tools 개발"],"es":["organon-tools-developer","agentes de IA","herramientas de metodología","CLI","MCP","desarrollo de software","metodología de desarrollo","IA y desarrollo"],"fr":["organon-tools-developer","agents de développement","outils de méthodologie","CLI","MCP","développement de logiciels","méthodologie de développement","IA et développement"],"de":["organon-tools-developer","KI-Agenten","Methodik-Tools","CLI","MCP","Software-Entwicklung","Methodik-Entwicklung","KI und Entwicklung"],"pt":["Organon Tools Developer","desenvolvimento de ferramentas de metodologia","CLI","MCP","metodologia de desenvolvimento","ferramentas de desenvolvimento","guia de configuração"],"ru":["Organon Tools Developer","разработка инструментов методологии","CLI","MCP","методология разработки","инструменты разработки","настройка ИИ Агенты"],"ar":["أداة Organon Tools Developer","تطوير أدوات المنهجية","CLI","MCP","منهجية التطوير","أدوات التطوير","دليل الإعداد"]}},"owner":"VledicFranco","repo":"organon","repoPath":"VledicFranco/organon","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.352Z","topics":[],"category":"community","skillMd":{"name":"organon-tools-developer","description":"Enforces organon-tools ETHOS.md and PHILOSOPHY.md constraints during development. Use when adding CLI commands, verification gates, MCP tools, or fixing bugs in packages/tools/. Ensures 6 invariants (schema fidelity, test coverage, gates fail not warn, machine-parsable output, idempotency, semver) and 5 design principles (fail-fast, composability, testability, clarity).","bodyPreview":"# Organon Tools Developer Skill\n\n> A Claude skill for agents developing organon-tools — ensures the tools that enforce methodology are built using methodology.\n\n---\n\n## When to Use This Skill\n\nUse this skill when:\n- Adding a new CLI command (`organon <command>`)\n- Adding a new verification gate\n- Adding a new MCP tool/prompt/resource\n- Evolving the methodology specification (book-llms/)\n- Fixing bugs or refactoring organon-tools code\n\n**Purpose:** Ensure organon-tools development follows its own","body":"# Organon Tools Developer Skill\n\n> A Claude skill for agents developing organon-tools — ensures the tools that enforce methodology are built using methodology.\n\n---\n\n## When to Use This Skill\n\nUse this skill when:\n- Adding a new CLI command (`organon <command>`)\n- Adding a new verification gate\n- Adding a new MCP tool/prompt/resource\n- Evolving the methodology specification (book-llms/)\n- Fixing bugs or refactoring organon-tools code\n\n**Purpose:** Ensure organon-tools development follows its own ETHOS.md constraints and PHILOSOPHY.md design decisions.\n\n---\n\n## Identity Check (Always Start Here)\n\nBefore any work, load and internalize:\n\n1. **Read `organon/domains/tools/ETHOS.md`** - 6 invariants, 5 principles, 8 heuristics\n2. **Read `organon/domains/tools/PHILOSOPHY.md`** - 5 design decisions and trade-offs\n3. **Read `book-llms/three-layer-architecture.md`** - If working on verification gates\n\n**Critical constraint:** This tool builds tools that enforce methodology. The builder must follow what it builds.\n\n---\n\n## The 6 Invariants (Never Violate)\n\nFrom `organon/domains/tools/ETHOS.md`:\n\n1. **Schema fidelity** - Frontmatter parser matches `book-llms/frontmatter-system.md` exactly\n2. **Every command has tests** - No untested code ships\n3. **Gates fail builds, not warn** - Verification gates produce pass/fail, never soft warnings\n4. **Machine-parsable output** - All commands support `--format json`\n5. **Idempotent operations** - Same input = same output, no side effects\n6. **Breaking changes require major version bump** - CLI, JSON schema, frontmatter schema\n\n**If your change violates any invariant, STOP and redesign.**\n\n---\n\n## The 5 Design Principles (Prioritized)\n\nFrom `organon/domains/tools/ETHOS.md`:\n\n1. **Schema fidelity over convenience** - When book-llms/ spec conflicts with ease-of-use, spec wins\n2. **Fail-fast over forgiving** - Invalid input blocks execution, errors surface immediately\n3. **Composability over monoliths** - Commands work in Unix pipelines\n4. **Testability over implementation speed** - Pure functions with tests, thin CLI wrappers\n5. **Clarity over brevity** - Error messages explain what failed and how to fix it\n\n---\n\n## Core Architecture Pattern\n\nFrom `organon/domains/tools/PHILOSOPHY.md`:\n\n```\nsrc/\n├── core/                   ← Pure functions (no I/O, no console, no process.exit)\n│   ├── types.ts            ← FileSystem interface, result types\n│   ├── <feature>.ts        ← Pure logic with tests\n│   └── <feature>.test.ts   ← Vitest tests (>90% coverage)\n├── cli/commands/           ← Thin wrappers (yargs handlers)\n│   └── <command>.ts        ← Parse args → call core → format output\n└── mcp/                    ← Thin MCP adapters\n    ├── tools.ts            ← Wrap core functions as MCP tools\n    └── prompts.ts          ← Methodology workflow templates\n```\n\n**Pattern:** Core logic is pure and testable. CLI and MCP are thin adapters.\n\n---\n\n## Workflow 1: Adding a New CLI Command\n\n**Example:** Adding `organon check-links` command\n\n1. **Design phase** (before coding):\n   - [ ] What does it do? (one sentence)\n   - [ ] Is it idempotent? (same input = same output?)\n   - [ ] Does it support `--format json`?\n   - [ ] What exit codes? (0 = success, 1 = failure)\n   - [ ] Does it compose with other commands?\n\n2. **Implementation phase**:\n   ```bash\n   # Create core utility (pure function)\n   touch src/core/check-links.ts\n   touch src/core/check-links.test.ts\n\n   # Create CLI command wrapper\n   touch src/cli/commands/check-links.ts\n   ```\n\n3. **Core utility structure** (`src/core/check-links.ts`):\n   ```typescript\n   import { FileSystem, Result } from ''./types'';\n\n   export interface CheckLinksOptions {\n     projectRoot: string;\n     // ... other options\n   }\n\n   export interface CheckLinksResult {\n     success: boolean;\n     brokenLinks: Array<{ file: string; link: string; reason: string }>;\n   }\n\n   export async function checkLinks(\n     options: CheckLinksOptions,\n     fs: FileSystem\n   ): Promise<CheckLinksResult> {\n     // Pure logic here - no console.log, no process.exit\n     // Return structured results\n   }\n   ```\n\n4. **Write tests first** (`src/core/check-links.test.ts`):\n   ```typescript\n   import { describe, it, expect } from ''vitest'';\n   import { checkLinks } from ''./check-links'';\n   import { MockFileSystem } from ''./test-utils'';\n\n   describe(''checkLinks'', () => {\n     it(''detects broken links'', async () => {\n       const fs = new MockFileSystem({ ... });\n       const result = await checkLinks({ projectRoot: ''.'' }, fs);\n       expect(result.brokenLinks).toHaveLength(1);\n     });\n\n     // ... more tests\n   });\n   ```\n\n5. **CLI wrapper** (`src/cli/commands/check-links.ts`):\n   ```typescript\n   import yargs from ''yargs'';\n   import { checkLinks } from ''../../core/check-links'';\n   import { NodeFileSystem } from ''../../core/node-fs'';\n\n   export const checkLinksCommand: yargs.CommandModule = {\n     command: ''check-links'',\n     describe: ''Check for broken links in organon files'',\n     builder: (yargs) => {\n       return yargs\n         .option(''format'', {\n           choices: [''human'', ''json''] as const,\n           default: ''human'' as const,\n         });\n     },\n     handler: async (args) => {\n       const fs = new NodeFileSystem();\n       const result = await checkLinks({ projectRoot: process.cwd() }, fs);\n\n       if (args.format === ''json'') {\n         console.log(JSON.stringify(result, null, 2));\n       } else {\n         // Human-readable output\n         if (result.brokenLinks.length === 0) {\n           console.log(''✓ No broken links found'');\n         } else {\n           console.error(''✗ Found broken links:'');\n           result.brokenLinks.forEach(l => {\n             console.error(`  ${l.file}: ${l.link} (${l.reason})`);\n           });\n         }\n       }\n\n       process.exit(result.success ? 0 : 1);\n     },\n   };\n   ```\n\n6. **Register command** (in `src/cli/index.ts`):\n   ```typescript\n   import { checkLinksCommand } from ''./commands/check-links'';\n\n   yargs\n     .command(checkLinksCommand)\n     // ... other commands\n   ```\n\n7. **Verification checklist**:\n   - [ ] Core function is pure (no I/O, no console, no process.exit)\n   - [ ] Tests exist and pass (`npm test`)\n   - [ ] Coverage >90% for core logic\n   - [ ] Command supports `--format json`\n   - [ ] Command is idempotent\n   - [ ] Help text exists (`organon check-links --help`)\n   - [ ] Error messages are clear and actionable\n   - [ ] README.md updated with example usage\n   - [ ] No TypeScript compilation errors (`npm run build`)\n\n---\n\n## Workflow 2: Adding a New Verification Gate\n\n**Example:** Adding a \"freshness\" gate that checks last-modified dates\n\n1. **Update specification first**:\n   - [ ] Add gate description to `book-llms/three-layer-architecture.md`\n   - [ ] Define what it checks, when it fails, how to fix\n   - [ ] Commit spec changes before implementation\n\n2. **Implementation** (follow Workflow 1 pattern):\n   ```bash\n   # Core logic\n   touch src/core/verify-freshness.ts\n   touch src/core/verify-freshness.test.ts\n   ```\n\n3. **Gate structure** (`src/core/verify-freshness.ts`):\n   ```typescript\n   import { FileSystem, VerificationResult } from ''./types'';\n\n   export async function verifyFreshness(\n     projectRoot: string,\n     fs: FileSystem\n   ): Promise<VerificationResult> {\n     return {\n       gate: ''freshness'',\n       passed: boolean,\n       errors: Array<{ file: string; message: string; fix: string }>,\n       warnings: [], // Gates never warn, only fail\n     };\n   }\n   ```\n\n4. **Register gate** (in `src/core/verify.ts`):\n   ```typescript\n   import { verifyFreshness } from ''./verify-freshness'';\n\n   const GATES = {\n     ''freshness'': verifyFreshness,\n     // ... other gates\n   };\n   ```\n\n5. **Test coverage requirements**:\n   - [ ] 100% coverage for verification gate logic (stricter than general 90% requirement)\n   - [ ] Test pass cases\n   - [ ] Test all failure modes\n   - [ ] Test fix suggestions are actionable\n\n6. **Update CLI** (`src/cli/commands/verify.ts`):\n   ```typescript\n   .option(''gate'', {\n     type: ''array'',\n     choices: [''frontmatter'', ''references'', ''triplets'', ''coverage'', ''freshness''],\n     description: ''Run specific gates (defaults to all)'',\n   })\n   ```\n\n7. **Verification checklist**:\n   - [ ] Spec updated in `book-llms/three-layer-architecture.md` FIRST\n   - [ ] Gate fails builds (exit 1), never warns\n   - [ ] 100% test coverage for gate logic\n   - [ ] Error messages include file path, line number, and fix suggestion\n   - [ ] Gate registered in verify.ts\n   - [ ] CLI updated with new gate option\n   - [ ] README.md documents the new gate\n   - [ ] `organon verify --gate freshness` works\n\n---\n\n## Workflow 3: Adding a New MCP Tool/Prompt\n\n**Example:** Adding `organon_check_dependencies` MCP tool\n\n1. **Core function exists** (or create it following Workflow 1)\n\n2. **Add MCP tool** (`src/mcp/tools.ts`):\n   ```typescript\n   {\n     name: ''organon_check_dependencies'',\n     description: ''Check if organon file dependencies are satisfied'',\n     inputSchema: {\n       type: ''object'',\n       properties: {\n         file: { type: ''string'', description: ''Path to organon file'' },\n       },\n       required: [''file''],\n     },\n     handler: async (args) => {\n       const result = await checkDependencies(args.file, fs);\n       return {\n         content: [{ type: ''text'', text: JSON.stringify(result, null, 2) }],\n       };\n     },\n   }\n   ```\n\n3. **Add MCP prompt** (`src/mcp/prompts.ts`) - If it''s a workflow:\n   ```typescript\n   {\n     name: ''check-organon-dependencies'',\n     description: ''Workflow for verifying organon dependency chains'',\n     arguments: [\n       { name: ''scope'', description: ''Scope to check (product, domain, feature)'', required: false },\n     ],\n     handler: async (args) => {\n       return {\n         messages: [\n           {\n             role: ''user'',\n             content: {\n               type: ''text'',\n               text: `# Check Organon Dependencies Workflow\\n\\n...`,\n             },\n           },\n         ],\n       };\n     },\n   }\n   ```\n\n4. **Verification checklist**:\n   - [ ] Tool wraps existing core function (don''t duplicate logic)\n   - [ ] Input schema is clear and validates properly\n   - [ ] Output is structured JSON\n   - [ ] Tool registered in `src/mcp/server.ts`\n   - [ ] MCP-SETUP.md updated with usage example\n   - [ ] Test with `organon mcp` and verify tool appears\n\n---\n\n## Workflow 4: Evolving the Methodology (RFC-Aware)\n\n**Example:** Adding a new frontmatter field\n\n**DANGER ZONE:** Changes to `book-llms/` affect ALL projects using Organon.\n\n1. **RFC pattern** (from `book-llms/patterns.md`):\n   - [ ] Create `book-llms/rfcs/RFC-NNN-<title>.md`\n   - [ ] Document: Problem, Proposal, Trade-offs, Migration path\n   - [ ] Get consensus (in this project: ensure it aligns with ETHOS.md)\n   - [ ] Update spec (`book-llms/frontmatter-system.md`)\n   - [ ] Update implementation (`packages/tools/src/core/frontmatter-parser.ts`)\n   - [ ] Update tests\n   - [ ] Document migration in CHANGELOG.md\n   - [ ] Bump version (breaking = major, additive = minor)\n\n2. **Breaking change checklist** (requires major version bump):\n   - [ ] Does it change frontmatter schema? (breaking)\n   - [ ] Does it change CLI interface? (breaking)\n   - [ ] Does it change JSON output schema? (breaking)\n   - [ ] Does it remove/rename a command? (breaking)\n   - [ ] If any YES, bump major version\n\n3. **Invariant check**:\n   - **Schema fidelity:** Implementation must match spec exactly\n   - **Breaking changes require major version bump:** Semver enforced\n\n---\n\n## Common Pitfalls (Don''t Do This)\n\n1. **❌ Adding logic to CLI commands** → ✅ Add to `src/core/`, CLI is thin wrapper\n2. **❌ Using `console.log` in core functions** → ✅ Return structured results, CLI formats\n3. **❌ Using `process.exit` in core functions** → ✅ Return success/failure, CLI exits\n4. **❌ Writing tests after code** → ✅ Write tests first (TDD pattern)\n5. **❌ Making gates warn instead of fail** → ✅ Gates fail builds (INV-TOOLS-3)\n6. **❌ Skipping `--format json` support** → ✅ All commands must support it (INV-TOOLS-4)\n7. **❌ Implementing before spec updated** → ✅ Update book-llms/ spec first\n8. **❌ Auto-fixing invalid frontmatter** → ✅ Fail-fast, force user to fix (principle #2)\n\n---\n\n## Pre-Commit Verification\n\nBefore committing ANY code:\n\n```bash\n# 1. Tests pass\nnpm test\n\n# 2. No TypeScript errors\nnpm run build\n\n# 3. Self-verification (dogfooding)\nnpm run organon verify\n\n# 4. Coverage check (>90% for core, 100% for gates)\nnpm run test:coverage\n```\n\n**If any fail, do not commit.**\n\n---\n\n## When in Doubt\n\n1. **Check ETHOS.md** - Does this violate an invariant?\n2. **Check PHILOSOPHY.md** - Does this align with design decisions?\n3. **Check three-layer-architecture.md** - Is this the right pattern for gates?\n4. **Ask:** Would this tool enforce what I''m about to build?\n\n**Remember:** Organon-tools builds tools that enforce methodology. If you wouldn''t want the tool to allow this pattern, don''t implement it.\n\n---\n\n## Meta-Principle\n\n> The tools that enforce constraints must be built with more discipline than the code they govern.\n\nIf organon-tools has untested code, how can it enforce test coverage on others?\nIf organon-tools has invalid frontmatter, how can it validate others?\nIf organon-tools violates its own ETHOS.md, the methodology loses credibility.\n\n**Build the tools you wish existed when auditing someone else''s work.**\n\n---\n\n## Error Recovery\n\n| Failure | Recovery Action |\n|---------|-----------------|\n| Tests fail | Fix implementation to match test expectations. Do not skip or disable tests. |\n| Coverage below threshold (>90% core, 100% gates) | Add missing test cases for uncovered branches. Use `npm run test:coverage` to identify gaps. |\n| TypeScript compilation errors | Fix type issues. Do not use `any` or `@ts-ignore` as workarounds. |\n| Gate warns instead of failing | Change gate to produce pass/fail exit codes. Invariant INV-TOOLS-3: gates fail builds, never warn. |\n| `--format json` not supported | Add JSON output format. Invariant INV-TOOLS-4: all commands must support `--format json`. |\n| Breaking change detected | Bump major version. Invariant INV-TOOLS-6: breaking changes require major version bump. |\n| Spec not updated before implementation | Stop. Update `book-llms/` specification first, then implement to match. Spec is source of truth. |\n"},"lastSynced":"2026-03-08T02:03:53.046Z","agentAnalysis":{"suitability":{"en":"Perfect for Methodology Enforcement Agents needing to develop and validate organon-tools using CLI commands and verification gates.","zh":"非常适合需要使用CLI命令和验证门开发和验证organon-tools的方法论执行代理","ja":"CLIコマンドおよび検証ゲートを使用してorganon-toolsを開発および検証する必要がある方法論エージェントの実施に最適","ko":"CLI 명령과 검증 게이트를 사용하여 오르가논 툴을 개발 및 검증해야 하는 방법론 강제 에이전트에게 완벽함","es":"Perfecto para Agentes de Aplicación de Metodología que necesitan desarrollar y validar herramientas de organon utilizando comandos de CLI y puertas de verificación.","fr":"Parfait pour les Agents d''Application de Méthodologie ayant besoin de développer et de valider des outils d''organon à l''aide de commandes CLI et de portes de vérification.","de":"Perfekt für Methodik-Durchsetzungsagenten, die Organon-Tools mithilfe von CLI-Befehlen und Überprüfungstoren entwickeln und validieren müssen.","pt":"Perfeito para Agentes de Enriquecimento de Metodologia que precisam desenvolver e validar ferramentas organon usando comandos CLI e portas de verificação.","ru":"Идеально для_AGENTов реализации методологии, которым необходимо разрабатывать и проверять инструменты organon с помощью команд CLI и ворот проверки.","ar":"مثالي لوسائط تنفيذ المنهجية الذين يحتاجون إلى تطوير و التحقق من أدوات أورجانون باستخدام أوامر CLI و بوابات التحقق."},"recommendation":{"en":"Empowers agents to streamline development by validating CLI commands, verification gates, and MCP tools, ensuring organon-tools are built using methodology, with features like evolution of methodology specification and bug fixing.","zh":"赋予代理人流线开发的能力，通过验证CLI命令、验证门和MCP工具，确保organon-tools按照方法论构建，并具有方法论规格演化和错误修复等功能","ja":"CLIコマンド、検証ゲート、MCPツールの検証を通じて、方法論に従ってorganon-toolsを構築することを保証し、方法論仕様の進化やバグ修正などの機能を提供することで、エージェントが開発を効率化できるようにする","ko":"에이전트가 CLI 명령, 검증 게이트 및 MCP 툴을 검증함으로써 방법론에 따라 오르가논 툴을 구축하는 것을 보장하고, 방법론 사양의 진화 및 버그 수정 등의 기능을 통해 개발을 효율화할 수 있도록 하는 것","es":"Permite a los agentes agilizar el desarrollo validando comandos de CLI, puertas de verificación y herramientas de MCP, asegurando que las herramientas de organon se construyan utilizando metodología, con características como la evolución de la especificación de metodología y la corrección de errores.","fr":"Permet aux agents de rationaliser le développement en validant les commandes CLI, les portes de vérification et les outils MCP, en garantissant que les outils d''organon sont construits en utilisant la méthodologie, avec des fonctionnalités telles que l''évolution de la spécification de méthodologie et la correction de bogues.","de":"Ermöglicht es Agenten, die Entwicklung durch Validierung von CLI-Befehlen, Überprüfungstoren und MCP-Tools zu rationalisieren, um sicherzustellen, dass Organon-Tools mithilfe von Methodik erstellt werden, mit Funktionen wie der Weiterentwicklung der Methodikspezifikation und der Fehlerbehebung.","pt":"Habilita os agentes a agilizar o desenvolvimento validando comandos CLI, portas de verificação e ferramentas MCP, garantindo que as ferramentas organon sejam construídas usando metodologia, com recursos como evolução da especificação da metodologia e correção de bugs.","ru":"Наделяет агентов возможностью оптимизировать разработку путем проверки команд CLI, ворот проверки и инструментов MCP, обеспечивая строительство инструментов organon с использованием методологии, с функциями, такими как эволюция спецификации методологии и исправление ошибок.","ar":"تمكّن الوكيل من تسريع التطوير من خلال التحقق من أوامر CLI و بوابات التحقق و أدوات MCP، وضمان بناء أدوات أورجانون باستخدام المنهجية، مع ميزات مثل تطور مواصفات المنهجية و إصلاح الأخطاء."},"useCases":{"en":["Adding new CLI commands for organon-tools","Creating new verification gates for methodology enforcement","Developing and refining MCP tools and resources"],"zh":["为organon-tools添加新的CLI命令","为方法论执行创建新的验证门","开发和完善MCP工具和资源"],"ja":["organon-tools用の新しいCLIコマンドを追加する","方法論エージェントの実施用に新しい検証ゲートを作成する","MCPツールおよびリソースを開発および洗練する"],"ko":["오르가논 툴을 위한 새로운 CLI 명령어 추가","방법론 강제를 위한 새로운 검증 게이트 생성","MCP 툴 및 리소스 개발 및 정련"],"es":["Agregar nuevos comandos de CLI para herramientas de organon","Crear nuevas puertas de verificación para la aplicación de metodología","Desarrollar y perfeccionar herramientas y recursos de MCP"],"fr":["Ajouter de nouvelles commandes CLI pour les outils d''organon","Créer de nouvelles portes de vérification pour l''application de la méthodologie","Développer et affiner les outils et les ressources MCP"],"de":["Hinzufügen neuer CLI-Befehle für Organon-Tools","Erstellen neuer Überprüfungstoren für die Methodenanwendung","Entwickeln und Verfeinern von MCP-Tools und -Ressourcen"],"pt":["Adicionar novos comandos CLI para ferramentas organon","Criar novas portas de verificação para aplicação da metodologia","Desenvolver e aperfeiçoar ferramentas e recursos MCP"],"ru":["Добавление новых команд CLI для инструментов organon","Создание новых ворот проверки для реализации методологии","Разработка и усовершенствование инструментов и ресурсов MCP"],"ar":["إضافة أوامر CLI جديدة لأدوات أورجانون","إنشاء بوابات تحقق جديدة لتنفيذ المنهجية","تطوير وأدوات و موارد MCP"]},"limitations":{"en":["Requires knowledge of organon-tools and methodology","Limited to development and validation of organon-tools"],"zh":["需要了解organon-tools和方法论","仅限于organon-tools的开发和验证"],"ja":["organon-toolsおよび方法論に関する知識が必要","organon-toolsの開発および検証に限定される"],"ko":["오르가논 툴 및 방법론에 대한 지식이 필요","오르가논 툴의 개발 및 검증에만 제한"],"es":["Requiere conocimiento de herramientas de organon y metodología","Limitado al desarrollo y validación de herramientas de organon"],"fr":["Nécessite des connaissances en outils d''organon et en méthodologie","Limité au développement et à la validation des outils d''organon"],"de":["Benötigt Kenntnisse über Organon-Tools und Methodik","Begrenzt auf die Entwicklung und Validierung von Organon-Tools"],"pt":["Exige conhecimento de ferramentas organon e metodologia","Limitado ao desenvolvimento e validação de ferramentas organon"],"ru":["Требует знания инструментов organon и методологии","Ограничен разработкой и проверкой инструментов organon"],"ar":["يتطلب معرفة أدوات أورجانون و المنهجية","محدود بالتطوير و التحقق من أدوات أورجانون"]},"version":4},"contentHash":"d865733a235954ef025ce53b8be753e22adb6d5680d134f3b276d9d34321e9bd","qualityScore":60}');
