INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('VledicFranco/organon/organon-tools-developer', 'organon-tools-developer', 'VledicFranco', 'organon', 'community', 'organon-tools-developer VledicFranco organon community The organon-tools-developer skill ensures that tools enforcing methodology are built using methodology, benefiting developers working with organon-tools. It streamlines development by validating CLI commands, verification gates, and MCP tools. Organon Tools Developer Skill 是一个 Claude 代理技能，确保开发工具遵循其自身的方法论。它支持 CLI 命令、验证门和 MCP 工具的开发。 Organon Tools Developer Skill は Claude エージェント スキルであり、開発ツールがその自身の方法論に従っていることを保証します。CLI コマンド、検証ゲート、MCP ツールの開発をサポートします。 Organon Tools Developer Skill은 Claude 에이전트 스킬로서 개발 도구가 자신의 방법론을 따르는 것을 보장합니다. CLI 명령, 확인 게이트 및 MCP 도구의 개발을 지원합니다. El skill organon-tools-developer garantiza que las herramientas de metodología se desarrollen utilizando metodología, con soporte para CLI y MCP. Le skill organon-tools-developer assure que les outils de méthodologie sont développés en utilisant la méthodologie, avec prise en charge de CLI et MCP. Der Skill organon-tools-developer stellt sicher, dass Methodik-Tools mithilfe von Methodik entwickelt werden, mit Unterstützung für CLI und MCP. O Organon Tools Developer é uma habilidade do Claude para agentes que desenvolvem ferramentas de metodologia, garantindo que as ferramentas sejam desenvolvidas usando metodologia Organon Tools Developer — навык Claude для агентов, разрабатывающих инструменты методологии, обеспечивающий разработку инструментов с помощью методологии ИИ Агенты أداة Organon Tools Developer هي مهارة من كلود لتعليم الوكلاء تطوير أدوات المنهجية، لضمان تطوير الأدوات باستخدام المنهجية how to use organon-tools-developer what is organon-tools-developer organon-tools-developer setup guide organon-tools-developer install organon-tools-developer alternative organon-tools-developer vs competing tools methodology enforcement in organon-tools organon-tools development best practices organon-tools CLI command development Organon Tools Developer Skill AIエージェント开发 CLI 命令开发 验证门开发 MCP 工具开发 方法论规范 organon-tools 开发 Adds new CLI commands (organon <command>) with methodology consistency Supports addition of new verification gates for enhanced validation Enables evolution of methodology specification (book-llms/) with precision Facilitates bug fixing and refactoring of organon-tools code with adherence to methodology Ensures development of new MCP tools/prompt/resource aligns with methodology organon-tools-developer is a Claude skill for agents developing organon-tools, ensuring that the tools follow the methodology specification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PrasadTelasula/EvokeQOne/component-testing', 'community', 'PrasadTelasula', 'EvokeQOne', 'PrasadTelasula/EvokeQOne', 'component-testing', 0, 0, 60, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:55.743Z', '6c5534b6796ea0eb571f70af38907ef1ca483452ddc7b11395a48598f3f9d4a2', '{"id":"PrasadTelasula/EvokeQOne/component-testing","name":"component-testing","description":{"en":"The component-testing skill helps QA teams test React components and pages using React Testing Library and Playwright, enabling efficient unit testing and E2E testing.","zh":"组件测试是使用React Testing Library和Playwright测试React组件和页面的过程。它包括单元测试、集成测试和可访问性测试","ja":"コンポーネントテストは、React Testing LibraryとPlaywrightを使用してReactコンポーネントとページをテストするプロセスです。単体テスト、統合テスト、可達性テストなど","ko":"컴포넌트 테스트는 React Testing Library 및 Playwright를 사용하여 React 컴포넌트와 페이지를 테스트하는 프로세스입니다. 단위 테스트, 통합 테스트, 접근성 테스트 등","es":"Prueba componentes de React con React Testing Library y Playwright para asegurar la calidad de tu código","fr":"Testez des composants React avec React Testing Library et Playwright pour assurer la qualité de votre code","de":"Testen Sie React-Komponenten mit React Testing Library und Playwright, um die Qualität Ihres Codes sicherzustellen","pt":"Teste componentes React com React Testing Library e Playwright. Realize testes unitários e de ponta a ponta para garantir a qualidade do seu código.","ru":"Тестируйте компоненты React с помощью React Testing Library и Playwright. Проводите юнит-тесты и тесты end-to-end, чтобы обеспечить качество вашего кода.","ar":"اختبر مكونات React باستخدام مكتبة React Testing و Playwright. قم باختبارات الوحدة واختبارات النهاية إلى النهاية لضمان جودة кодك"},"seo":{"title":{"en":"Component-Testing: E2E Testing Setup Guide | AI Agent Skill","zh":"组件测试Setup Guide - 使用React Testing Library和Playwright","ja":"コンポーネントテストベストプラクティス - React Testing LibraryとPlaywrightを使用","ko":"컴포넌트 테스트 설정 가이드 - React Testing Library 및 Playwright 사용","es":"Guía de configuración para pruebas de componentes con Rea...","fr":"Configurer les tests de composants avec React Testing Lib...","de":"Einrichten von Komponententests mit React Testing Library...","pt":"Guia de Configuração de Testes de Componentes com React T...","ru":"ИИ Агенты: Руководство по настройке тестирования компонен...","ar":"إعداد اختبارات المكونات مع مكتبة React Testing"},"description":{"en":"Discover how to test React components with confidence using React Testing Library and Playwright - get started with our expert guide today!","zh":"了解如何使用React Testing Library和Playwright进行组件测试，包括单元测试、集成测试和可访问性测试","ja":"React Testing LibraryとPlaywrightを使用したコンポーネントテストの方法を学びましょう。単体テスト、統合テスト、可達性テストなど","ko":"React Testing Library 및 Playwright를 사용하여 컴포넌트 테스트를 수행하는 방법에 대해 알아보세요. 단위 테스트, 통합 테스트, 접근성 테스트 등","es":"Aprende a probar componentes de React con nuestra guía de pruebas de componentes y mejora la calidad de tu código con herramientas como React Testing Library...","fr":"Découvrez comment tester des composants React avec notre guide de tests de composants et améliorez la qualité de votre code avec des outils tels que React Te...","de":"Erfahren Sie, wie Sie React-Komponenten testen können, mit unserer Komponententest-Guide und verbessern Sie die Qualität Ihres Codes mit Tools wie React Test...","pt":"Aprenda a testar componentes React com a biblioteca React Testing Library e Playwright. Melhore a qualidade do seu código com testes unitários e de ponta a p...","ru":"Используйте ИИ Агенты для тестирования компонентов React с помощью React Testing Library и Playwright. Улучшите качество вашего кода с помощью юнит-тестов и ...","ar":"استخدم أداة الإيضاح لاختبار مكونات React باستخدام مكتبة React Testing و Playwright. تحسين جودة кодك باستخدام الاختبارات الموحدة واختبارات النهاية إلى النهاية"},"definition":{"en":"Component-testing is a skill that utilizes React Testing Library and Playwright to test React components and pages for functionality and accessibility.","zh":"组件测试是指使用自动化工具测试软件组件的过程","ja":"コンポーネントテストは、自動化ツールを使用してソフトウェアコンポーネントをテストするプロセス","ko":"컴포넌트 테스트는 자동화 도구를 사용하여 소프트웨어 컴포넌트를 테스트하는 프로세스","es":"Las pruebas de componentes son un proceso para verificar la funcionalidad de los componentes de software","fr":"Les tests de composants sont un processus pour vérifier la fonctionnalité des composants logiciels","de":"Komponententests sind ein Prozess, um die Funktionalität von Softwarekomponenten zu überprüfen","pt":"Teste de componentes é o processo de verificação da funcionalidade de componentes React usando React Testing Library e Playwright.","ru":"Тестирование компонентов - это процесс проверки функциональности компонентов React с помощью React Testing Library и Playwright.","ar":"اختبار المكونات هو عملية التحقق من وظيفة مكونات React باستخدام مكتبة React Testing و Playwright"},"features":{"en":["Writes unit tests for component logic using React Testing Library","Tests user interactions such as clicks, typing, and form submission with Playwright","Performs E2E testing of complete user flows","Conducts accessibility testing for React components","Enables visual regression testing for UI validation"],"zh":["使用React Testing Library进行单元测试","使用Playwright进行集成测试","支持可访问性测试","支持视觉回归测试","支持E2E测试"],"ja":["React Testing Libraryを使用した単体テスト","Playwrightを使用した統合テスト","可達性テストのサポート","視覚的回帰テストのサポート","E2Eテストのサポート"],"ko":["React Testing Library를 사용한 단위 테스트","Playwright를 사용한 통합 테스트","접근성 테스트 지원","시각적 회귀 테스트 지원","E2E 테스트 지원"],"es":["Pruebas unitarias con React Testing Library","Pruebas de interacción de usuario con Playwright","Pruebas de flujo de usuario completo","Pruebas de accesibilidad","Pruebas de regresión visual"],"fr":["Tests unitaires avec React Testing Library","Tests d''interaction utilisateur avec Playwright","Tests de flux d''utilisateur complet","Tests d''accessibilité","Tests de régression visuelle"],"de":["Einheitliche Tests mit React Testing Library","Benutzerschnittstellen-Tests mit Playwright","Vollständige Benutzerfluss-Tests","Barrierefreiheitstests","Visuelle Regressionstests"],"pt":["Testes unitários com React Testing Library","Testes de ponta a ponta com Playwright","Testes de interação do usuário","Testes de acessibilidade","Testes de regressão visual"],"ru":["Юнит-тесты с React Testing Library","Тесты end-to-end с Playwright","Тесты взаимодействия пользователя","Тесты доступности","Тесты визуальной регрессии"],"ar":["اختبارات الوحدة مع مكتبة React Testing","اختبارات النهاية إلى النهاية مع Playwright","اختبارات تفاعل المستخدم","اختبارات الإمكانية","اختبارات الانحدار المرئي"]},"keywords":{"en":["how to use component-testing","component-testing setup guide","React Testing Library tutorial","Playwright E2E testing","component-testing vs Jest","install component-testing","what is component-testing","component-testing best practices","React component testing examples"],"zh":["组件测试","React Testing Library","Playwright","单元测试","集成测试","可访问性测试","视觉回归测试","E2E测试","AIエージェント"],"ja":["コンポーネントテスト","React Testing Library","Playwright","単体テスト","統合テスト","可達性テスト","視覚的回帰テスト","E2Eテスト","AIエージェント"],"ko":["컴포넌트 테스트","React Testing Library","Playwright","단위 테스트","통합 테스트","접근성 테스트","시각적 회귀 테스트","E2E 테스트","인공지능 에이전트"],"es":["pruebas de componentes","React Testing Library","Playwright","pruebas unitarias","pruebas de interacción de usuario","pruebas de accesibilidad","herramientas de pruebas de componentes","mejora de la calidad del código","desarrollo de software"],"fr":["tests de composants","React Testing Library","Playwright","tests unitaires","tests d''interaction utilisateur","tests d''accessibilité","outils de tests de composants","amélioration de la qualité du code","développement de logiciels"],"de":["Komponententests","React Testing Library","Playwright","Einheitliche Tests","Benutzerschnittstellen-Tests","Barrierefreiheitstests","Werkzeuge für Komponententests","Qualitätsverbesserung des Codes","Softwareentwicklung"],"pt":["testes de componentes React","React Testing Library","Playwright","testes unitários","testes de ponta a ponta","testes de interação do usuário","testes de acessibilidade","testes de regressão visual"],"ru":["тестирование компонентов React","React Testing Library","Playwright","юнит-тесты","тесты end-to-end","тесты взаимодействия пользователя","тесты доступности","тесты визуальной регрессии"],"ar":["اختبارات مكونات React","مكتبة React Testing","Playwright","اختبارات الوحدة","اختبارات النهاية إلى النهاية","اختبارات تفاعل المستخدم","اختبارات الإمكانية","اختبارات الانحدار المرئي"]}},"owner":"PrasadTelasula","repo":"EvokeQOne","repoPath":"PrasadTelasula/EvokeQOne","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.353Z","topics":[],"category":"community","skillMd":{"name":"component-testing","description":"Test React components with React Testing Library and Playwright. Use when building UI components or verifying frontend functionality.","bodyPreview":"You help test React components and pages for the QA Team Portal frontend using React Testing Library and Playwright.\n\n## When to Use This Skill\n\n- Testing React components after creation\n- Writing unit tests for component logic\n- Testing user interactions (clicks, typing, form submission)\n- E2E testing of complete user flows\n- Accessibility testing\n- Visual regression testing\n\n## Testing Approaches\n\n### 1. Unit Tests with React Testing Library\n\n#### Basic Component Test\n\n```typescript\n// tests/u","body":"You help test React components and pages for the QA Team Portal frontend using React Testing Library and Playwright.\n\n## When to Use This Skill\n\n- Testing React components after creation\n- Writing unit tests for component logic\n- Testing user interactions (clicks, typing, form submission)\n- E2E testing of complete user flows\n- Accessibility testing\n- Visual regression testing\n\n## Testing Approaches\n\n### 1. Unit Tests with React Testing Library\n\n#### Basic Component Test\n\n```typescript\n// tests/unit/components/TeamMemberCard.test.tsx\nimport { render, screen } from ''@testing-library/react''\nimport { TeamMemberCard } from ''@/components/public/TeamIntro/TeamMemberCard''\n\nconst mockMember = {\n  id: ''123'',\n  name: ''John Doe'',\n  role: ''QA Lead'',\n  email: ''john@example.com'',\n  profilePhotoUrl: ''/path/to/photo.jpg''\n}\n\ndescribe(''TeamMemberCard'', () => {\n  it(''renders member name and role'', () => {\n    render(<TeamMemberCard member={mockMember} />)\n\n    expect(screen.getByText(''John Doe'')).toBeInTheDocument()\n    expect(screen.getByText(''QA Lead'')).toBeInTheDocument()\n  })\n\n  it(''displays profile photo with alt text'', () => {\n    render(<TeamMemberCard member={mockMember} />)\n\n    const img = screen.getByRole(''img'', { name: /john doe/i })\n    expect(img).toHaveAttribute(''src'', mockMember.profilePhotoUrl)\n  })\n\n  it(''shows email link when provided'', () => {\n    render(<TeamMemberCard member={mockMember} />)\n\n    const emailLink = screen.getByRole(''link'', { name: /email/i })\n    expect(emailLink).toHaveAttribute(''href'', ''mailto:john@example.com'')\n  })\n})\n```\n\n#### Testing User Interactions\n\n```typescript\nimport { render, screen, fireEvent } from ''@testing-library/react''\nimport userEvent from ''@testing-library/user-event''\nimport { UpdatesModal } from ''@/components/public/Updates/UpdateModal''\n\ndescribe(''UpdatesModal'', () => {\n  it(''closes modal when close button clicked'', async () => {\n    const onClose = vi.fn()\n    render(<UpdatesModal isOpen={true} onClose={onClose} update={mockUpdate} />)\n\n    const closeButton = screen.getByRole(''button'', { name: /close/i })\n    await userEvent.click(closeButton)\n\n    expect(onClose).toHaveBeenCalledTimes(1)\n  })\n\n  it(''closes modal on escape key press'', async () => {\n    const onClose = vi.fn()\n    render(<UpdatesModal isOpen={true} onClose={onClose} update={mockUpdate} />)\n\n    fireEvent.keyDown(document, { key: ''Escape'' })\n\n    expect(onClose).toHaveBeenCalled()\n  })\n})\n```\n\n#### Testing Forms\n\n```typescript\nimport { render, screen, waitFor } from ''@testing-library/react''\nimport userEvent from ''@testing-library/user-event''\nimport { LoginForm } from ''@/components/admin/auth/LoginForm''\n\ndescribe(''LoginForm'', () => {\n  it(''submits form with valid data'', async () => {\n    const onSubmit = vi.fn()\n    render(<LoginForm onSubmit={onSubmit} />)\n\n    await userEvent.type(\n      screen.getByLabelText(/email/i),\n      ''admin@test.com''\n    )\n    await userEvent.type(\n      screen.getByLabelText(/password/i),\n      ''password123''\n    )\n\n    await userEvent.click(screen.getByRole(''button'', { name: /login/i }))\n\n    await waitFor(() => {\n      expect(onSubmit).toHaveBeenCalledWith({\n        email: ''admin@test.com'',\n        password: ''password123''\n      })\n    })\n  })\n\n  it(''shows validation errors for invalid email'', async () => {\n    render(<LoginForm onSubmit={vi.fn()} />)\n\n    await userEvent.type(\n      screen.getByLabelText(/email/i),\n      ''invalid-email''\n    )\n    await userEvent.click(screen.getByRole(''button'', { name: /login/i }))\n\n    await waitFor(() => {\n      expect(screen.getByText(/invalid email/i)).toBeInTheDocument()\n    })\n  })\n})\n```\n\n#### Testing API Integration\n\n```typescript\nimport { render, screen, waitFor } from ''@testing-library/react''\nimport { TeamList } from ''@/components/public/TeamIntro/TeamList''\nimport { rest } from ''msw''\nimport { setupServer } from ''msw/node''\n\nconst mockTeamMembers = [\n  { id: ''1'', name: ''John Doe'', role: ''QA Lead'' },\n  { id: ''2'', name: ''Jane Smith'', role: ''QA Engineer'' }\n]\n\nconst server = setupServer(\n  rest.get(''/api/v1/team-members'', (req, res, ctx) => {\n    return res(ctx.json(mockTeamMembers))\n  })\n)\n\nbeforeAll(() => server.listen())\nafterEach(() => server.resetHandlers())\nafterAll(() => server.close())\n\ndescribe(''TeamList'', () => {\n  it(''displays loading state initially'', () => {\n    render(<TeamList />)\n    expect(screen.getByRole(''status'')).toBeInTheDocument()\n  })\n\n  it(''displays team members after loading'', async () => {\n    render(<TeamList />)\n\n    await waitFor(() => {\n      expect(screen.getByText(''John Doe'')).toBeInTheDocument()\n      expect(screen.getByText(''Jane Smith'')).toBeInTheDocument()\n    })\n  })\n\n  it(''displays error message on API failure'', async () => {\n    server.use(\n      rest.get(''/api/v1/team-members'', (req, res, ctx) => {\n        return res(ctx.status(500))\n      })\n    )\n\n    render(<TeamList />)\n\n    await waitFor(() => {\n      expect(screen.getByText(/error loading/i)).toBeInTheDocument()\n    })\n  })\n})\n```\n\n### 2. E2E Tests with Playwright\n\n#### Setup Playwright\n\n```typescript\n// playwright.config.ts\nimport { defineConfig } from ''@playwright/test''\n\nexport default defineConfig({\n  testDir: ''./tests/e2e'',\n  use: {\n    baseURL: ''http://localhost:5173'',\n    screenshot: ''only-on-failure'',\n    video: ''retain-on-failure'',\n  },\n  webServer: {\n    command: ''npm run dev'',\n    port: 5173,\n    reuseExistingServer: !process.env.CI,\n  },\n})\n```\n\n#### Basic E2E Test\n\n```typescript\n// tests/e2e/landing-page.spec.ts\nimport { test, expect } from ''@playwright/test''\n\ntest.describe(''Landing Page'', () => {\n  test(''displays all sections'', async ({ page }) => {\n    await page.goto(''/'')\n\n    // Check all sections are visible\n    await expect(page.getByRole(''heading'', { name: /team introduction/i })).toBeVisible()\n    await expect(page.getByRole(''heading'', { name: /latest updates/i })).toBeVisible()\n    await expect(page.getByRole(''heading'', { name: /tools/i })).toBeVisible()\n    await expect(page.getByRole(''heading'', { name: /resources/i })).toBeVisible()\n    await expect(page.getByRole(''heading'', { name: /research/i })).toBeVisible()\n  })\n\n  test(''navigation links scroll to sections'', async ({ page }) => {\n    await page.goto(''/'')\n\n    // Click tools nav link\n    await page.getByRole(''link'', { name: /tools/i }).click()\n\n    // Check tools section is in view\n    const toolsSection = page.getByRole(''heading'', { name: /tools/i })\n    await expect(toolsSection).toBeInViewport()\n  })\n})\n```\n\n#### Testing User Flows\n\n```typescript\n// tests/e2e/admin-login.spec.ts\nimport { test, expect } from ''@playwright/test''\n\ntest.describe(''Admin Login'', () => {\n  test(''admin can login and access dashboard'', async ({ page }) => {\n    // Navigate to login page\n    await page.goto(''/admin/login'')\n\n    // Fill login form\n    await page.getByLabel(/email/i).fill(''admin@test.com'')\n    await page.getByLabel(/password/i).fill(''testpass123'')\n\n    // Submit form\n    await page.getByRole(''button'', { name: /login/i }).click()\n\n    // Wait for redirect to dashboard\n    await expect(page).toHaveURL(''/admin/dashboard'')\n\n    // Check dashboard loads\n    await expect(page.getByRole(''heading'', { name: /dashboard/i })).toBeVisible()\n  })\n\n  test(''shows error for invalid credentials'', async ({ page }) => {\n    await page.goto(''/admin/login'')\n\n    await page.getByLabel(/email/i).fill(''wrong@test.com'')\n    await page.getByLabel(/password/i).fill(''wrongpass'')\n\n    await page.getByRole(''button'', { name: /login/i }).click()\n\n    // Check error message appears\n    await expect(page.getByText(/invalid credentials/i)).toBeVisible()\n  })\n})\n```\n\n#### Testing CRUD Operations\n\n```typescript\n// tests/e2e/team-management.spec.ts\nimport { test, expect } from ''@playwright/test''\n\ntest.describe(''Team Management'', () => {\n  test.beforeEach(async ({ page }) => {\n    // Login as admin\n    await page.goto(''/admin/login'')\n    await page.getByLabel(/email/i).fill(''admin@test.com'')\n    await page.getByLabel(/password/i).fill(''testpass123'')\n    await page.getByRole(''button'', { name: /login/i }).click()\n    await page.waitForURL(''/admin/dashboard'')\n\n    // Navigate to team management\n    await page.getByRole(''link'', { name: /team members/i }).click()\n  })\n\n  test(''can create new team member'', async ({ page }) => {\n    await page.getByRole(''button'', { name: /add member/i }).click()\n\n    // Fill form\n    await page.getByLabel(/name/i).fill(''New Member'')\n    await page.getByLabel(/role/i).fill(''QA Engineer'')\n    await page.getByLabel(/email/i).fill(''new@test.com'')\n\n    // Upload photo\n    await page.getByLabel(/photo/i).setInputFiles(''./tests/fixtures/profile.jpg'')\n\n    // Submit\n    await page.getByRole(''button'', { name: /save/i }).click()\n\n    // Verify success message\n    await expect(page.getByText(/member created successfully/i)).toBeVisible()\n\n    // Verify appears in list\n    await expect(page.getByText(''New Member'')).toBeVisible()\n  })\n\n  test(''can edit existing team member'', async ({ page }) => {\n    // Click edit button for first member\n    await page.getByRole(''row'').first().getByRole(''button'', { name: /edit/i }).click()\n\n    // Update name\n    await page.getByLabel(/name/i).clear()\n    await page.getByLabel(/name/i).fill(''Updated Name'')\n\n    // Save\n    await page.getByRole(''button'', { name: /save/i }).click()\n\n    // Verify updated\n    await expect(page.getByText(''Updated Name'')).toBeVisible()\n  })\n\n  test(''can delete team member'', async ({ page }) => {\n    // Get initial count\n    const initialCount = await page.getByRole(''row'').count()\n\n    // Delete first member\n    await page.getByRole(''row'').first().getByRole(''button'', { name: /delete/i }).click()\n\n    // Confirm deletion\n    await page.getByRole(''button'', { name: /confirm/i }).click()\n\n    // Verify count decreased\n    const newCount = await page.getByRole(''row'').count()\n    expect(newCount).toBe(initialCount - 1)\n  })\n})\n```\n\n### 3. Accessibility Testing\n\n```typescript\n// tests/e2e/accessibility.spec.ts\nimport { test, expect } from ''@playwright/test''\nimport AxeBuilder from ''@axe-core/playwright''\n\ntest.describe(''Accessibility'', () => {\n  test(''landing page has no accessibility violations'', async ({ page }) => {\n    await page.goto(''/'')\n\n    const accessibilityScanResults = await new AxeBuilder({ page }).analyze()\n\n    expect(accessibilityScanResults.violations).toEqual([])\n  })\n\n  test(''admin dashboard has no accessibility violations'', async ({ page }) => {\n    // Login first\n    await page.goto(''/admin/login'')\n    await page.getByLabel(/email/i).fill(''admin@test.com'')\n    await page.getByLabel(/password/i).fill(''testpass123'')\n    await page.getByRole(''button'', { name: /login/i }).click()\n\n    await page.waitForURL(''/admin/dashboard'')\n\n    const accessibilityScanResults = await new AxeBuilder({ page }).analyze()\n\n    expect(accessibilityScanResults.violations).toEqual([])\n  })\n})\n```\n\n## Running Tests\n\n### Vitest (Unit Tests)\n\n```bash\ncd frontend\n\n# Run all unit tests\nnpm run test\n\n# Run in watch mode\nnpm run test:watch\n\n# Run with coverage\nnpm run test:coverage\n\n# Run specific file\nnpm run test -- TeamMemberCard.test.tsx\n\n# Run with UI\nnpm run test:ui\n```\n\n### Playwright (E2E Tests)\n\n```bash\ncd frontend\n\n# Install browsers (first time)\nnpx playwright install\n\n# Run all E2E tests\nnpx playwright test\n\n# Run in UI mode\nnpx playwright test --ui\n\n# Run specific test file\nnpx playwright test tests/e2e/landing-page.spec.ts\n\n# Run in headed mode (see browser)\nnpx playwright test --headed\n\n# Run in debug mode\nnpx playwright test --debug\n\n# Run on specific browser\nnpx playwright test --project=chromium\n\n# Generate test code\nnpx playwright codegen http://localhost:5173\n```\n\n## Test Configuration\n\n### Vitest Setup (vitest.config.ts)\n\n```typescript\nimport { defineConfig } from ''vitest/config''\nimport react from ''@vitejs/plugin-react''\nimport path from ''path''\n\nexport default defineConfig({\n  plugins: [react()],\n  test: {\n    globals: true,\n    environment: ''jsdom'',\n    setupFiles: ''./tests/setup.ts'',\n  },\n  resolve: {\n    alias: {\n      ''@'': path.resolve(__dirname, ''./src''),\n    },\n  },\n})\n```\n\n### Test Setup File (tests/setup.ts)\n\n```typescript\nimport ''@testing-library/jest-dom''\nimport { cleanup } from ''@testing-library/react''\nimport { afterEach, vi } from ''vitest''\n\n// Cleanup after each test\nafterEach(() => {\n  cleanup()\n})\n\n// Mock window.matchMedia\nObject.defineProperty(window, ''matchMedia'', {\n  writable: true,\n  value: vi.fn().mockImplementation(query => ({\n    matches: false,\n    media: query,\n    onchange: null,\n    addListener: vi.fn(),\n    removeListener: vi.fn(),\n    addEventListener: vi.fn(),\n    removeEventListener: vi.fn(),\n    dispatchEvent: vi.fn(),\n  })),\n})\n```\n\n## Test Checklist\n\nFor each component, verify:\n\n- [ ] **Rendering** - Component renders without errors\n- [ ] **Props** - Handles different prop combinations\n- [ ] **User interactions** - Clicks, typing, form submission work\n- [ ] **Loading states** - Shows loading indicators\n- [ ] **Error states** - Shows error messages\n- [ ] **Empty states** - Handles no data gracefully\n- [ ] **Accessibility** - ARIA labels, keyboard navigation, screen readers\n- [ ] **Responsiveness** - Works on mobile/tablet/desktop\n- [ ] **Edge cases** - Null values, long text, special characters\n\n## Common Testing Patterns\n\n### Testing Hooks\n\n```typescript\nimport { renderHook, waitFor } from ''@testing-library/react''\nimport { useTeamMembers } from ''@/hooks/useTeamMembers''\n\ntest(''useTeamMembers fetches data'', async () => {\n  const { result } = renderHook(() => useTeamMembers())\n\n  expect(result.current.loading).toBe(true)\n\n  await waitFor(() => {\n    expect(result.current.loading).toBe(false)\n    expect(result.current.data).toHaveLength(2)\n  })\n})\n```\n\n### Testing Context\n\n```typescript\nimport { render, screen } from ''@testing-library/react''\nimport { AuthProvider } from ''@/contexts/AuthContext''\nimport { ProtectedComponent } from ''@/components/ProtectedComponent''\n\ntest(''shows content when authenticated'', () => {\n  render(\n    <AuthProvider value={{ user: mockUser, isAuthenticated: true }}>\n      <ProtectedComponent />\n    </AuthProvider>\n  )\n\n  expect(screen.getByText(/protected content/i)).toBeInTheDocument()\n})\n```\n\n## Output Format\n\nAfter testing, report:\n\n1. **Tests Run**: X passed, Y failed\n2. **Coverage**: X% of components/lines covered\n3. **Failed Tests**: List with error messages\n4. **Accessibility Issues**: WCAG violations found\n5. **Performance**: Slow-rendering components\n6. **Recommendations**: Suggested improvements\n\n## Best Practices\n\n1. **Test user behavior**, not implementation details\n2. **Use semantic queries** (getByRole, getByLabel, getByText)\n3. **Avoid testing IDs or classes** when possible\n4. **Test accessibility** (keyboard navigation, screen readers)\n5. **Mock external dependencies** (API calls, localStorage)\n6. **Keep tests independent** - no shared state\n7. **Use descriptive test names** - what you''re testing and expected outcome\n8. **Test error scenarios** - not just happy path\n"},"lastSynced":"2026-03-08T02:03:55.743Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced React component testing capabilities with React Testing Library and Playwright.","zh":"非常适合需要高级 React 组件测试功能的前端代理，具有 React Testing Library 和 Playwright 测试能力。","ja":"React コンポーネントの高度なテスト機能が必要なフロントエンドエージェントに最適です。React Testing Library と Playwright を使用したテストが可能です。","ko":"고급 React 컴포넌트 테스트 기능이 필요한 프론트엔드 에이전트에게 적합합니다. React Testing Library와 Playwright를 사용한 테스트가 가능합니다.","es":"Perfecto para Agentes Frontend que necesitan capacidades avanzadas de prueba de componentes React con React Testing Library y Playwright.","fr":"Parfait pour les agents Frontend ayant besoin de capacités avancées de test de composants React avec React Testing Library et Playwright.","de":"Perfekt für Frontend-Agents, die erweiterte React-Komponententestfunktionen mit React Testing Library und Playwright benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de teste de componentes React com React Testing Library e Playwright.","ru":"Идеально подходит для агентов Frontend, которым необходимы продвинутые возможности тестирования компонентов React с помощью React Testing Library и Playwright.","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى إمكانيات متقدمة لاختبار مكونات React مع مكتبة React Testing و Playwright."},"recommendation":{"en":"Empowers agents to efficiently test React components and pages, enabling unit testing and E2E testing with libraries like React Testing Library and Playwright, supporting user interaction simulations and accessibility testing.","zh":"赋予代理高效测试 React 组件和页面的能力，实现单元测试和端到端测试，支持用户交互模拟和无障碍测试，使用诸如 React Testing Library 和 Playwright 之类的库。","ja":"エージェントが React コンポーネントとページを効率的にテストできるようにし、ユニットテストとエンドツーエンドテストを実現することで、ユーザーのインタラクションシミュレーションとアクセシビリティテストをサポートします。React Testing Library や Playwright などのライブラリを使用します。","ko":"에이전트가 React 컴포넌트와 페이지를 효율적으로 테스트할 수 있도록 해줌으로써, 단위 테스트와 종단간 테스트를 가능하게 하며, 사용자 상호작용 시뮬레이션 및 접근성 테스트를 지원합니다. React Testing Library와 Playwright 같은 라이브러리를 사용합니다.","es":"Habilita a los agentes a probar de forma eficiente los componentes y páginas de React, permitiendo pruebas unitarias y pruebas E2E con bibliotecas como React Testing Library y Playwright, y admitiendo simulaciones de interacción del usuario y pruebas de accesibilidad.","fr":"Permet aux agents de tester efficacement les composants et les pages React, permettant les tests unitaires et les tests E2E avec des bibliothèques comme React Testing Library et Playwright, et prenant en charge les simulations d''interaction utilisateur et les tests d''accessibilité.","de":"Ermächtigt die Agenten, React-Komponenten und -Seiten effizient zu testen, ermöglicht Einheitstests und E2E-Tests mit Bibliotheken wie React Testing Library und Playwright und unterstützt Benutzerschnittstellen-Simulierungen und Zugriffstests.","pt":"Habilita os agentes a testar eficientemente componentes e páginas React, permitindo testes unitários e testes E2E com bibliotecas como React Testing Library e Playwright, suportando simulações de interações do usuário e testes de acessibilidade.","ru":"Наделяет агентов возможностью эффективно тестировать компоненты и страницы React, обеспечивая проведение модульных тестов и тестирования E2E с помощью библиотек zoals React Testing Library и Playwright, поддерживая симуляцию взаимодействия пользователя и тестирование доступности.","ar":"تمكين الوكلاء من اختبار مكونات وصفحات React بشكل فعال، مما يسمح باختبار الوحدات واختبار E2E باستخدام مكتبات مثل مكتبة React Testing و Playwright، ودعم محاكاة تفاعل المستخدم واختبار إمكانية الوصول."},"useCases":{"en":["Automating unit tests for component logic","Testing user interactions with React components","Performing E2E testing of complete user flows with Playwright"],"zh":["为组件逻辑自动化单元测试","使用 React 组件测试用户交互","使用 Playwright 进行完整用户流的端到端测试"],"ja":["コンポーネントロジックのユニットテストの自動化","React コンポーネントを使用したユーザーインタラクションのテスト","Playwright を使用した完了したユーザーフローのエンドツーエンドテスト"],"ko":["컴포넌트 논리의 단위 테스트 자동화","React 컴포넌트를 사용한 사용자 상호작용 테스트","Playwright를 사용한 완료된 사용자 흐름의 종단간 테스트"],"es":["Automatizar pruebas unitarias para la lógica de componentes","Probar interacciones de usuario con componentes de React","Realizar pruebas E2E de flujos de usuario completos con Playwright"],"fr":["Automatiser les tests unitaires pour la logique de composants","Tester les interactions utilisateur avec les composants React","Effectuer des tests E2E de flux d''utilisateur complets avec Playwright"],"de":["Automatisieren von Einheitstests für die Komponentenlogik","Testen von Benutzerinteraktionen mit React-Komponenten","Durchführen von E2E-Tests von vollständigen Benutzerflüssen mit Playwright"],"pt":["Automatizar testes unitários para lógica de componentes","Testar interações do usuário com componentes React","Realizar testes E2E de fluxos de usuário completos com Playwright"],"ru":["Автоматизировать модульные тесты для логики компонентов","Тестировать взаимодействие пользователя с компонентами React","Проводить тестирование E2E полных потоков пользователя с помощью Playwright"],"ar":["أتمتة اختبار الوحدات لمنطق المكونات","اختبار تفاعل المستخدم مع مكونات React","إجراء اختبار E2E للتدفقات المستخدمة الكاملة مع Playwright"]},"limitations":{"en":["Requires React and React Testing Library setup","Limited to React components and pages testing"],"zh":["需要 React 和 React Testing Library 设置","仅限于 React 组件和页面测试"],"ja":["React と React Testing Library の設定が必要","React コンポーネントとページのテストのみ"],"ko":["React와 React Testing Library 설정이 필요","React 컴포넌트와 페이지 테스트만 가능"],"es":["Requiere configuración de React y React Testing Library","Limitado a las pruebas de componentes y páginas de React"],"fr":["Nécessite une configuration de React et de React Testing Library","Limité aux tests de composants et de pages React"],"de":["Benötigt eine Konfiguration von React und React Testing Library","Begrenzt auf die Tests von React-Komponenten und -Seiten"],"pt":["Exige configuração do React e da React Testing Library","Limitado a testes de componentes e páginas React"],"ru":["Требует настройки React и React Testing Library","Ограничен тестированием компонентов и страниц React"],"ar":["يتطلب إعداد React ومكتبة React Testing","محدود باختبار مكونات وصفحات React"]},"version":4},"contentHash":"6c5534b6796ea0eb571f70af38907ef1ca483452ddc7b11395a48598f3f9d4a2","qualityScore":60}');
