INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PrasadTelasula/EvokeQOne/component-testing', 'component-testing', 'PrasadTelasula', 'EvokeQOne', 'community', 'component-testing PrasadTelasula EvokeQOne community The component-testing skill helps QA teams test React components and pages using React Testing Library and Playwright, enabling efficient unit testing and E2E testing. 组件测试是使用React Testing Library和Playwright测试React组件和页面的过程。它包括单元测试、集成测试和可访问性测试 コンポーネントテストは、React Testing LibraryとPlaywrightを使用してReactコンポーネントとページをテストするプロセスです。単体テスト、統合テスト、可達性テストなど 컴포넌트 테스트는 React Testing Library 및 Playwright를 사용하여 React 컴포넌트와 페이지를 테스트하는 프로세스입니다. 단위 테스트, 통합 테스트, 접근성 테스트 등 Prueba componentes de React con React Testing Library y Playwright para asegurar la calidad de tu código Testez des composants React avec React Testing Library et Playwright pour assurer la qualité de votre code Testen Sie React-Komponenten mit React Testing Library und Playwright, um die Qualität Ihres Codes sicherzustellen Teste componentes React com React Testing Library e Playwright. Realize testes unitários e de ponta a ponta para garantir a qualidade do seu código. Тестируйте компоненты React с помощью React Testing Library и Playwright. Проводите юнит-тесты и тесты end-to-end, чтобы обеспечить качество вашего кода. اختبر مكونات React باستخدام مكتبة React Testing و Playwright. قم باختبارات الوحدة واختبارات النهاية إلى النهاية لضمان جودة кодك how to use component-testing component-testing setup guide React Testing Library tutorial Playwright E2E testing component-testing vs Jest install component-testing what is component-testing component-testing best practices React component testing examples 组件测试 React Testing Library Playwright 单元测试 集成测试 可访问性测试 视觉回归测试 E2E测试 AIエージェント Writes unit tests for component logic using React Testing Library Tests user interactions such as clicks, typing, and form submission with Playwright Performs E2E testing of complete user flows Conducts accessibility testing for React components Enables visual regression testing for UI validation Component-testing is a skill that utilizes React Testing Library and Playwright to test React components and pages for functionality and accessibility.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('elsolal/Skillz-Claude/performance-auditor', 'community', 'elsolal', 'Skillz-Claude', 'elsolal/Skillz-Claude', 'performance-auditor', 0, 0, 60, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:55.869Z', '584172dd49f8fc8dfbf2c5840f244617fe1c25048b1470e7876a50ae7aa6b99b', '{"id":"elsolal/Skillz-Claude/performance-auditor","name":"performance-auditor","description":{"en":"The performance-auditor skill analyzes application performance and proposes optimizations, benefiting developers using frameworks like Next, React, and Vue.","zh":"性能审计器是一种AI工具，用于分析和优化应用性能。它支持React、Next、Vue和Svelte等框架，并提供Bundle Analyzer等功能。","ja":"パフォーマンスオーディターは、AIエージェントを使用してアプリケーションのパフォーマンスを分析し、最適化するためのツールです。React、Next、Vue、Svelteなどのフレームワークをサポートしています。","ko":"성능 감사기는 리액트 및 뷰 애플리케이션의 성능을 분석하고 최적화하는 AI 도구입니다. 넥스트, 스벨트 등 다양한 프레임워크를 지원하며 번들 분석기 등의 기능을 제공합니다.","es":"El auditor de rendimiento analiza y optimiza el rendimiento de aplicaciones web, identificando oportunidades de mejora en frameworks como React y Next","fr":"L''auditeur de performance analyse et optimise les performances des applications web, en identifiant les opportunités d''amélioration dans des frameworks tels que React et Next","de":"Der Performance-Auditor analysiert und optimiert die Leistung von Webanwendungen, indem er Verbesserungsmöglichkeiten in Frameworks wie React und Next identifiziert","pt":"O Performance Auditor é uma ferramenta que analisa as performances de aplicações e propõe otimizações, suportando frameworks como React, Next e Vue","ru":"Performance Auditor — это инструмент, который анализирует производительность приложений и предлагает оптимизации, поддерживая фреймворки seperti React, Next и Vue","ar":"أداة فحص الأداء هي أداة تحليل أداء التطبيقات وتقترح تحسينات، تدعم إطارات مثل React و Next و Vue"},"seo":{"title":{"en":"Performance-Auditor: Optimization Setup Guide | AI Agent ...","zh":"性能审计器设置指南 - 优化应用性能","ja":"パフォーマンスオーディターのベストプラクティス - AIエージェントを使用したアプリケーションの最適化","ko":"성능 감사기 설정 가이드 - 리액트 및 뷰 애플리케이션 최적화","es":"Guía de configuración del auditor de rendimiento","fr":"Guide de démarrage de l''auditeur de performance","de":"Leitfaden zur Einrichtung des Performance-Auditors","pt":"Guia de Configuração do Performance Auditor para Otimizaç...","ru":"Руководство по настройке Performance Auditor для оптимиза...","ar":"دليل إعداد أداة فحص الأداء لتحسين التطبيقات"},"description":{"en":"Unlock performance boosts with our AI agent skill. Discover how to audit and optimize your application''s performance with ease. Get started now!","zh":"了解性能审计器的功能和特点，优化您的应用性能，提高用户体验。使用AI工具进行性能分析和优化。","ja":"パフォーマンスオーディターを使用してアプリケーションのパフォーマンスを分析し、最適化する方法を学びます。AIエージェントを活用して開発効率を向上させましょう。","ko":"성능 감사기를 사용하여 리액트 및 뷰 애플리케이션의 성능을 분석하고 최적화하는 방법을 알아보세요. 성능 분석과 최적화를 위한 AI 도구를 활용하세요.","es":"Optimice el rendimiento de su aplicación con el auditor de rendimiento, que analiza y sugiere mejoras para frameworks como React y Next","fr":"Améliorez les performances de votre application avec l''auditeur de performance, qui analyse et suggère des améliorations pour des frameworks tels que React e...","de":"Optimieren Sie die Leistung Ihrer Anwendung mit dem Performance-Auditor, der analysiert und Verbesserungsvorschläge für Frameworks wie React und Next macht","pt":"Descubra como o Performance Auditor pode ajudar a melhorar a eficiência da sua aplicação, identificando gargalos e propondo soluções","ru":"Узнайте, как Performance Auditor может помочь улучшить эффективность вашего приложения, выявляя узкие места и предлагая решения","ar":"تعرف على كيفية مساعدة أداة فحص الأداء في تحسين كفاءة تطبيقك، عن طريق تحديد المشاكل واقتراح حلول"},"definition":{"en":"performance-auditor is a skill that analyzes application performance, identifying areas for optimization in frameworks and bundle analyzers.","zh":"性能审计器是一种AI工具，用于分析和优化应用性能，提高用户体验。","ja":"パフォーマンスオーディターは、AIエージェントを使用してアプリケーションのパフォーマンスを分析し、最適化するためのツールです。","ko":"성능 감사기는 리액트 및 뷰 애플리케이션의 성능을 분석하고 최적화하는 AI 도구입니다.","es":"Un auditor de rendimiento es una herramienta que analiza y sugiere mejoras para optimizar el rendimiento de aplicaciones web","fr":"Un auditeur de performance est un outil qui analyse et suggère des améliorations pour optimiser les performances des applications web","de":"Ein Performance-Auditor ist ein Tool, das analysiert und Verbesserungsvorschläge macht, um die Leistung von Webanwendungen zu optimieren","pt":"O que é Performance Auditor? É uma ferramenta de análise de desempenho que ajuda a identificar e otimizar a eficiência de aplicações","ru":"Что такое Performance Auditor? Это инструмент анализа производительности, который помогает выявить и оптимизировать эффективность приложений","ar":"ما هي أداة فحص الأداء؟ هي أداة تحليل الأداء تساعد في تحديد وتحسين كفاءة التطبيقات"},"features":{"en":["Identifies framework environments via package.json grep for next/react/vue/svelte/nuxt/astro","Detects bundle analyzers like @next/bundle-analyzer and webpack-bundle-analyzer","Analyzes performance metrics to propose optimizations","Supports mode activation for performance auditing","Loads context to determine performance environment","Prioritizes actions based on required and optional patterns"],"zh":["支持React、Next、Vue和Svelte等框架","提供Bundle Analyzer等功能","自动分析应用性能","优化应用性能","提高用户体验"],"ja":["React、Next、Vue、Svelteなどのフレームワークをサポート","Bundle Analyzerなどの機能を提供","アプリケーションのパフォーマンスを自動分析","パフォーマンスを最適化","ユーザーエクスペリエンスを向上"],"ko":["리액트, 넥스트, 뷰, 스벨트 등 다양한 프레임워크 지원","번들 분석기 등의 기능 제공","애플리케이션 성능 자동 분석","성능 최적화","사용자 경험 향상"],"es":["Análisis de rendimiento de aplicaciones web","Identificación de oportunidades de mejora en frameworks como React y Next","Análisis de bundles con herramientas como @next/bundle-analyzer","Detección de dependencias y optimización de package.json","Soporte para frameworks como Next, React, Vue, Svelte y Nuxt","Análisis de rendimiento en tiempo de ejecución"],"fr":["Analyse des performances des applications web","Identification des opportunités d''amélioration dans des frameworks tels que React et Next","Analyse de bundles avec des outils tels que @next/bundle-analyzer","Détection de dépendances et optimisation de package.json","Prise en charge de frameworks tels que Next, React, Vue, Svelte et Nuxt","Analyse des performances en temps de execution"],"de":["Leistungsanalyse von Webanwendungen","Identifizierung von Verbesserungsmöglichkeiten in Frameworks wie React und Next","Analyse von Bundles mit Tools wie @next/bundle-analyzer","Erkennung von Abhängigkeiten und Optimierung von package.json","Unterstützung für Frameworks wie Next, React, Vue, Svelte und Nuxt","Leistungsanalyse in Echtzeit"],"pt":["Análise de desempenho de aplicações","Suporte a frameworks como React, Next e Vue","Identificação de gargalos e proposição de soluções","Integração com bundle analyzer","Análise de pacotes com Grep"],"ru":["Анализ производительности приложений","Поддержка фреймворков seperti React, Next и Vue","Выявление узких мест и предложение решений","Интеграция с bundle analyzer","Анализ пакетов с Grep"],"ar":["تحليل أداء التطبيقات","دعم إطارات مثل React و Next و Vue","تحديد المشاكل واقتراح حلول","تكامل مع أداة تحليل الحزمة","تحليل الحزم مع Grep"]},"keywords":{"en":["how to use performance-auditor","performance-auditor setup guide","performance optimization techniques","nextjs performance auditing","react performance optimization tools","what is performance-auditor","performance-auditor vs webpack-bundle-analyzer","performance-auditor install","performance-auditor alternative"],"zh":["性能审计器","AI工具","应用性能优化","React性能优化","Vue性能优化","Bundle Analyzer","性能分析","最优化"],"ja":["パフォーマンスオーディター","AIエージェント","アプリケーションのパフォーマンス最適化","Reactのパフォーマンス最適化","Vueのパフォーマンス最適化","Bundle Analyzer","パフォーマンス分析","最適化"],"ko":["성능 감사기","AI 도구","애플리케이션 성능 최적화","리액트 성능 최적화","뷰 성능 최적화","번들 분석기","성능 분석","최적화"],"es":["auditor de rendimiento","optimización de rendimiento","análisis de bundles","React","Next","Vue","Svelte","Nuxt","package.json","herramientas de desarrollo web"],"fr":["auditeur de performance","optimisation de performances","analyse de bundles","React","Next","Vue","Svelte","Nuxt","package.json","outils de développement web"],"de":["Performance-Auditor","Leistungsoptimierung","Bundleanalyse","React","Next","Vue","Svelte","Nuxt","package.json","Webentwicklungstools"],"pt":["performance auditor","otimização de aplicações","análise de desempenho","react","next","vue","bundle analyzer","grep"],"ru":["performance auditor","оптимизация приложений","анализ производительности","react","next","vue","bundle analyzer","grep","ИИ Агенты"],"ar":["أداة فحص الأداء","تحسين التطبيقات","تحليل الأداء","react","next","vue","أداة تحليل الحزمة","grep","أدوات الذكاء الاصطناعي"]}},"owner":"elsolal","repo":"Skillz-Claude","repoPath":"elsolal/Skillz-Claude","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.353Z","topics":[],"category":"community","skillMd":{"name":"performance-auditor","description":"Audit de performance du code et de lapplication. Analyse Lighthouse, bundle size, Core Web Vitals, et optimisations. Utiliser après limplémentation, avant une release, ou quand lutilisateur dit performance, slow, optimize, bundle size.","bodyPreview":"# Performance Auditor 🚀\n\n## Mode activé : Audit de Performance\n\nJe vais analyser les performances de l''application et proposer des optimisations.\n\n---\n\n## 📥 Contexte à charger\n\n**Au démarrage, identifier l''environnement de performance.**\n\n| Contexte | Pattern/Action | Priorité |\n|----------|----------------|----------|\n| Framework | `Grep: package.json` pour next/react/vue/svelte/nuxt/astro | Requis |\n| Bundle analyzer | `Grep: package.json` pour @next/bundle-analyzer/webpack-bundle-analyzer |","body":"# Performance Auditor 🚀\n\n## Mode activé : Audit de Performance\n\nJe vais analyser les performances de l''application et proposer des optimisations.\n\n---\n\n## 📥 Contexte à charger\n\n**Au démarrage, identifier l''environnement de performance.**\n\n| Contexte | Pattern/Action | Priorité |\n|----------|----------------|----------|\n| Framework | `Grep: package.json` pour next/react/vue/svelte/nuxt/astro | Requis |\n| Bundle analyzer | `Grep: package.json` pour @next/bundle-analyzer/webpack-bundle-analyzer | Optionnel |\n| Build output | `Glob: .next/ dist/ build/` | Optionnel |\n| Lighthouse | `Bash: which lighthouse` ou `npx lighthouse --version` | Optionnel |\n| Images | `Glob: **/*.{png,jpg,jpeg}` (compter) | Optionnel |\n\n### Instructions de chargement\n1. Détecter le framework frontend\n2. Vérifier si un bundle analyzer est disponible\n3. Localiser le build output\n4. Vérifier la disponibilité de Lighthouse pour les audits\n\n---\n\n## Activation\n\nAvant de commencer, je vérifie :\n\n- [ ] Application buildée ou URL disponible\n- [ ] Type d''audit identifié (bundle, runtime, Lighthouse)\n- [ ] Environnement (dev, staging, prod)\n\n---\n\n## Rôle & Principes\n\n**Rôle** : Expert performance qui identifie les goulots d''étranglement et propose des optimisations concrètes.\n\n**Principes** :\n\n1. **Measure First** : Toujours mesurer avant d''optimiser\n2. **User-Centric** : Focus sur les métriques perçues par l''utilisateur\n3. **Budget-Based** : Définir des budgets de performance\n4. **Progressive** : Améliorer par itérations\n\n**Règles** :\n\n- ⛔ Ne JAMAIS optimiser sans mesurer d''abord\n- ⛔ Ne JAMAIS sacrifier la lisibilité pour des micro-optimisations\n- ⛔ Ne JAMAIS ignorer les Core Web Vitals\n- ✅ Toujours quantifier l''impact des optimisations\n- ✅ Toujours prioriser par impact utilisateur\n- ✅ Toujours tester avant/après\n\n---\n\n## Process\n\n### 1. Analyse du contexte\n\n**Input requis** : URL de l''app ou chemin du build\n\nJe détermine :\n\n| Aspect | Questions |\n|--------|-----------|\n| **Type** | SPA, SSR, SSG, Hybrid ? |\n| **Framework** | Next.js, React, Vue ? |\n| **Hosting** | Vercel, Netlify, AWS ? |\n| **Cible** | Mobile, Desktop, Both ? |\n\n**⏸️ STOP** - Valider le contexte avant l''audit\n\n---\n\n### 2. Core Web Vitals\n\nLes 3 métriques essentielles :\n\n| Métrique | Description | Bon | Moyen | Mauvais |\n|----------|-------------|-----|-------|---------|\n| **LCP** | Largest Contentful Paint | < 2.5s | < 4s | > 4s |\n| **INP** | Interaction to Next Paint | < 200ms | < 500ms | > 500ms |\n| **CLS** | Cumulative Layout Shift | < 0.1 | < 0.25 | > 0.25 |\n\n#### Commande Lighthouse\n\n```bash\n# Audit complet\nnpx lighthouse https://example.com --output=json --output-path=./lighthouse-report.json\n\n# Mobile only\nnpx lighthouse https://example.com --preset=perf --emulated-form-factor=mobile\n\n# Desktop only\nnpx lighthouse https://example.com --preset=perf --emulated-form-factor=desktop\n```\n\n---\n\n### 3. Bundle Analysis\n\n#### Next.js\n\n```bash\n# Activer l''analyzer\nANALYZE=true npm run build\n\n# Ou avec le package\nnpx @next/bundle-analyzer\n```\n\n#### Webpack général\n\n```bash\n# Avec webpack-bundle-analyzer\nnpx webpack-bundle-analyzer stats.json\n\n# Avec source-map-explorer\nnpx source-map-explorer dist/**/*.js\n```\n\n#### Métriques clés\n\n| Métrique | Budget recommandé |\n|----------|------------------|\n| **JS total** | < 200 KB (gzip) |\n| **CSS total** | < 50 KB (gzip) |\n| **Largest chunk** | < 100 KB (gzip) |\n| **Initial load** | < 150 KB (gzip) |\n\n---\n\n### 4. Checklist d''optimisation\n\n#### Images\n\n```markdown\n- [ ] Format moderne (WebP, AVIF)\n- [ ] Dimensions adaptées (srcset)\n- [ ] Lazy loading\n- [ ] Placeholder blur\n- [ ] CDN avec cache\n```\n\n#### JavaScript\n\n```markdown\n- [ ] Code splitting\n- [ ] Tree shaking\n- [ ] Dynamic imports\n- [ ] Minification\n- [ ] Dead code elimination\n```\n\n#### CSS\n\n```markdown\n- [ ] Critical CSS inlined\n- [ ] Unused CSS removed\n- [ ] CSS-in-JS optimisé\n- [ ] Font subsetting\n```\n\n#### Réseau\n\n```markdown\n- [ ] Compression (gzip/brotli)\n- [ ] HTTP/2 ou HTTP/3\n- [ ] Cache headers optimaux\n- [ ] Preconnect aux domaines critiques\n- [ ] Prefetch des pages suivantes\n```\n\n#### Rendering\n\n```markdown\n- [ ] SSR/SSG quand possible\n- [ ] Hydration optimisée\n- [ ] Virtualization pour longues listes\n- [ ] Debounce/throttle des events\n```\n\n---\n\n### 5. Analyse des dépendances\n\nJe vérifie les dépendances lourdes :\n\n```bash\n# Top 10 packages par taille\nnpx bundle-phobia package.json\n\n# Alternative\nnpx depcheck --json | jq ''.dependencies''\n```\n\n#### Remplacements suggérés\n\n| Package lourd | Alternative légère | Économie |\n|---------------|-------------------|----------|\n| `moment` | `date-fns` ou `dayjs` | ~95% |\n| `lodash` | `lodash-es` (tree-shake) | ~80% |\n| `axios` | `ky` ou `fetch` | ~90% |\n| `uuid` | `nanoid` | ~70% |\n| `validator` | Native regex | ~99% |\n\n---\n\n### 6. Optimisations spécifiques\n\n#### Next.js\n\n```typescript\n// next.config.js\nmodule.exports = {\n  images: {\n    formats: [''image/avif'', ''image/webp''],\n    deviceSizes: [640, 750, 828, 1080, 1200],\n  },\n  experimental: {\n    optimizeCss: true,\n    optimizePackageImports: [''lucide-react'', ''@heroicons/react''],\n  },\n  compress: true,\n};\n```\n\n#### React\n\n```typescript\n// Lazy loading components\nconst HeavyComponent = lazy(() => import(''./HeavyComponent''));\n\n// Memoization\nconst MemoizedComponent = memo(ExpensiveComponent);\n\n// useMemo for expensive calculations\nconst result = useMemo(() => expensiveCalculation(data), [data]);\n```\n\n#### Fonts\n\n```typescript\n// Next.js font optimization\nimport { Inter } from ''next/font/google'';\n\nconst inter = Inter({\n  subsets: [''latin''],\n  display: ''swap'',\n  preload: true,\n});\n```\n\n---\n\n### 7. Budget de performance\n\nJe définis un budget :\n\n```json\n{\n  \"performance-budget\": {\n    \"javascript\": {\n      \"total\": \"200kb\",\n      \"per-route\": \"100kb\"\n    },\n    \"css\": {\n      \"total\": \"50kb\"\n    },\n    \"images\": {\n      \"per-image\": \"100kb\",\n      \"total\": \"500kb\"\n    },\n    \"fonts\": {\n      \"total\": \"100kb\"\n    },\n    \"metrics\": {\n      \"lcp\": \"2.5s\",\n      \"inp\": \"200ms\",\n      \"cls\": \"0.1\"\n    }\n  }\n}\n```\n\n---\n\n## Output Template\n\n```markdown\n# Performance Audit: [Project Name]\n\n## Summary\n\n| Métrique | Actuel | Cible | Status |\n|----------|--------|-------|--------|\n| **LCP** | [X]s | < 2.5s | 🟢/🟡/🔴 |\n| **INP** | [X]ms | < 200ms | 🟢/🟡/🔴 |\n| **CLS** | [X] | < 0.1 | 🟢/🟡/🔴 |\n| **Bundle JS** | [X] KB | < 200 KB | 🟢/🟡/🔴 |\n| **Bundle CSS** | [X] KB | < 50 KB | 🟢/🟡/🔴 |\n\n## Score: [XX]/100\n\n## Issues trouvées\n\n### 🔴 Critiques (P0)\n1. [Issue avec impact et recommandation]\n\n### 🟡 Importants (P1)\n1. [Issue avec impact et recommandation]\n\n### 🟢 Mineurs (P2)\n1. [Issue avec impact et recommandation]\n\n## Recommandations\n\n### Quick Wins (< 1h)\n- [ ] [Action 1] - Impact: [X]% amélioration\n- [ ] [Action 2] - Impact: [X]% amélioration\n\n### Medium Effort (1-4h)\n- [ ] [Action 3] - Impact: [X]% amélioration\n\n### Major Changes (> 4h)\n- [ ] [Action 4] - Impact: [X]% amélioration\n\n## Bundle Analysis\n\n[Tableau des plus gros packages]\n\n## Next Steps\n\n1. [Action prioritaire]\n2. [Action suivante]\n```\n\n**Fichier** : `docs/audits/PERF-{slug}-{date}.md`\n\n---\n\n## Output Validation\n\n### ✅ Checklist Output Performance Auditor\n\n| Critère | Status |\n|---------|--------|\n| Core Web Vitals mesurés | ✅/❌ |\n| Bundle size analysé | ✅/❌ |\n| Issues priorisées (P0/P1/P2) | ✅/❌ |\n| Recommandations avec impact | ✅/❌ |\n| Quick wins identifiés | ✅/❌ |\n| Budget défini | ✅/❌ |\n\n**Score minimum : 5/6**\n\n---\n\n## Auto-Chain\n\n```markdown\n## 🔗 Prochaine étape\n\n✅ Performance Audit terminé et sauvegardé.\n\n→ 🔒 **Lancer `/security-auditor`** pour audit de sécurité ?\n→ 💻 **Lancer `/code-implementer`** pour appliquer les optimisations ?\n\n---\n\n**[S] Security** | **[C] Code** | **[P] Pause**\n```\n\n---\n\n## Transitions\n\n- **Depuis Code** : \"Code terminé, je fais un audit performance ?\"\n- **Depuis Test** : \"Tests OK, on vérifie les performances ?\"\n- **Vers Security** : \"Performance auditée, on passe à la sécurité ?\"\n- **Vers Code** : \"Prêt à implémenter les optimisations ?\"\n\n---\n\n## Exemples\n\n### Audit d''une URL\n\n```bash\n/performance-auditor https://example.com\n```\n\n### Audit du build local\n\n```bash\n/performance-auditor ./dist\n```\n\n### Focus sur le bundle\n\n```bash\n/performance-auditor --bundle-only\n```\n\n### Focus sur Lighthouse\n\n```bash\n/performance-auditor --lighthouse https://example.com\n```\n\n---\n\n## Démarrage 🚀\n\n**Arguments reçus :** $ARGUMENTS\n\nJe vais maintenant :\n1. Analyser le contexte (framework, build)\n2. Mesurer les Core Web Vitals\n3. Analyser le bundle\n4. Identifier les goulots d''étranglement\n5. Proposer des optimisations priorisées\n\n---\n\n### Analyse en cours...\n"},"lastSynced":"2026-03-08T02:03:55.869Z","agentAnalysis":{"suitability":{"en":"Essential for Frontend Development Agents specializing in web performance optimization for modern JavaScript frameworks.","zh":"对于专门从事现代 JavaScript 框架 Web 性能优化的前端开发智能体至关重要。","ja":"現代の JavaScript フレームワークの Web パフォーマンス最適化を専門とするフロントエンド開発エージェントにとって不可欠です。","ko":"현대 JavaScript 프레임워크의 웹 성능 최적화를 전문으로 하는 프론트엔드 개발 에이전트에게 필수적입니다.","es":"Esencial para Agentes de Desarrollo Frontend especializados en optimización del rendimiento web para frameworks modernos de JavaScript.","fr":"Essentiel pour les Agents de Développement Frontend spécialisés dans l''optimisation des performances web pour les frameworks JavaScript modernes.","de":"Essenziell für Frontend-Development-Agents, die sich auf die Leistungsoptimierung für moderne JavaScript-Frameworks spezialisieren.","pt":"Essencial para Agentes de Desenvolvimento Frontend especializados em otimização de desempenho web para frameworks modernos de JavaScript.","ru":"Необходим для Агентов Frontend-разработки, специализирующихся на оптимизации веб-производительности для современных JavaScript-фреймворков.","ar":"أساسي لوكلاء تطوير الواجهة الأمامية المتخصصين في تحسين أداء الويب لأطر عمل JavaScript الحديثة."},"recommendation":{"en":"Enables comprehensive application performance analysis by automatically detecting framework environments through package.json scanning and identifying bundle analysis tools. Provides actionable optimization proposals specifically tailored for Next.js, React, Vue, Svelte, Nuxt, and Astro applications.","zh":"通过 package.json 扫描自动检测框架环境并识别打包分析工具，从而实现全面的应用程序性能分析。提供专门为 Next.js、React、Vue、Svelte、Nuxt 和 Astro 应用程序量身定制的、可操作的优化建议。","ja":"package.json のスキャンを通じてフレームワーク環境を自動検出し、バンドル分析ツールを特定することで、包括的なアプリケーションパフォーマンス分析を可能にします。Next.js、React、Vue、Svelte、Nuxt、Astro アプリケーションに特化した実用的な最適化提案を提供します。","ko":"package.json 스캐닝을 통해 프레임워크 환경을 자동으로 감지하고 번들 분석 도구를 식별함으로써 포괄적인 애플리케이션 성능 분석을 가능하게 합니다. Next.js, React, Vue, Svelte, Nuxt 및 Astro 애플리케이션에 특별히 맞춰진 실행 가능한 최적화 제안을 제공합니다.","es":"Permite un análisis completo del rendimiento de aplicaciones mediante la detección automática de entornos de frameworks a través del escaneo de package.json y la identificación de herramientas de análisis de bundles. Proporciona propuestas de optimización accionables específicamente adaptadas para aplicaciones Next.js, React, Vue, Svelte, Nuxt y Astro.","fr":"Permet une analyse complète des performances des applications en détectant automatiquement les environnements de frameworks via l''analyse du package.json et en identifiant les outils d''analyse de bundles. Fournit des propositions d''optimisation actionnables spécialement adaptées pour les applications Next.js, React, Vue, Svelte, Nuxt et Astro.","de":"Ermöglicht eine umfassende Anwendungsleistungsanalyse durch automatische Erkennung von Framework-Umgebungen mittels package.json-Scanning und Identifizierung von Bundle-Analyse-Tools. Bietet umsetzbare Optimierungsvorschläge, die speziell für Next.js-, React-, Vue-, Svelte-, Nuxt- und Astro-Anwendungen zugeschnitten sind.","pt":"Permite uma análise abrangente do desempenho do aplicativo, detectando automaticamente ambientes de framework por meio da verificação do package.json e identificando ferramentas de análise de pacotes. Fornece propostas de otimização acionáveis especificamente adaptadas para aplicações Next.js, React, Vue, Svelte, Nuxt e Astro.","ru":"Обеспечивает комплексный анализ производительности приложений за счет автоматического обнаружения сред фреймворков посредством сканирования package.json и идентификации инструментов анализа сборок. Предоставляет практические предложения по оптимизации, специально разработанные для приложений Next.js, React, Vue, Svelte, Nuxt и Astro.","ar":"يتيح تحليلًا شاملاً لأداء التطبيق من خلال الكشف التلقائي عن بيئات أطر العمل عبر فحص package.json وتحديد أدوات تحليل الحزم. يقدم مقترحات تحسين قابلة للتنفيذ مصممة خصيصًا لتطبيقات Next.js وReact وVue وSvelte وNuxt وAstro."},"useCases":{"en":["Automating framework detection via package.json analysis","Identifying bundle analyzer dependencies for performance monitoring","Generating framework-specific optimization recommendations","Auditing web application performance metrics"],"zh":["通过 package.json 分析实现框架检测自动化","识别用于性能监控的打包分析器依赖项","生成特定于框架的优化建议","审计 Web 应用程序性能指标"],"ja":["package.json 分析によるフレームワーク検出の自動化","パフォーマンス監視のためのバンドルアナライザーの依存関係の特定","フレームワーク固有の最適化推奨事項の生成","Web アプリケーションパフォーマンスメトリクスの監査"],"ko":["package.json 분석을 통한 프레임워크 감지 자동화","성능 모니터링을 위한 번들 분석기 종속성 식별","프레임워크별 최적화 권장 사항 생성","웹 애플리케이션 성능 메트릭 감사"],"es":["Automatización de la detección de frameworks mediante el análisis de package.json","Identificación de dependencias de analizadores de bundles para el monitoreo del rendimiento","Generación de recomendaciones de optimización específicas para cada framework","Auditoría de métricas de rendimiento de aplicaciones web"],"fr":["Automatisation de la détection de frameworks via l''analyse du package.json","Identification des dépendances d''analyseurs de bundles pour la surveillance des performances","Génération de recommandations d''optimisation spécifiques à chaque framework","Audit des métriques de performance des applications web"],"de":["Automatisierung der Framework-Erkennung durch package.json-Analyse","Identifizierung von Bundle-Analyzer-Abhängigkeiten für die Leistungsüberwachung","Erstellung von frameworkspezifischen Optimierungsempfehlungen","Prüfung von Webanwendungsleistungsmetriken"],"pt":["Automatização da detecção de frameworks por meio da análise do package.json","Identificação de dependências do analisador de pacotes para monitoramento de desempenho","Geração de recomendações de otimização específicas para o framework","Auditoria de métricas de desempenho de aplicações web"],"ru":["Автоматизация обнаружения фреймворков посредством анализа package.json","Идентификация зависимостей анализатора сборок для мониторинга производительности","Генерация рекомендаций по оптимизации для конкретных фреймворков","Аудит метрик производительности веб-приложений"],"ar":["أتمتة الكشف عن أطر العمل عبر تحليل package.json","تحديد تبعيات أداة تحليل الحزم لمراقبة الأداء","توليد توصيات تحسين محددة لكل إطار عمل","مراجعة مقاييس أداء تطبيقات الويب"]},"limitations":{"en":["Requires access to package.json files","Limited to JavaScript framework ecosystems (Next/React/Vue/Svelte/Nuxt/Astro)","Dependent on existing bundle analyzer tooling presence"],"zh":["需要访问 package.json 文件","仅限于 JavaScript 框架生态系统（Next/React/Vue/Svelte/Nuxt/Astro）","依赖于现有打包分析器工具的存在"],"ja":["package.json ファイルへのアクセスが必要","JavaScript フレームワークエコシステム (Next/React/Vue/Svelte/Nuxt/Astro) に限定される","既存のバンドルアナライザーツールの存在に依存する"],"ko":["package.json 파일에 대한 액세스 필요","JavaScript 프레임워크 생태계(Next/React/Vue/Svelte/Nuxt/Astro)로 제한됨","기존 번들 분석기 도구의 존재에 의존함"],"es":["Requiere acceso a archivos package.json","Limitado a ecosistemas de frameworks JavaScript (Next/React/Vue/Svelte/Nuxt/Astro)","Depende de la presencia existente de herramientas de análisis de bundles"],"fr":["Nécessite un accès aux fichiers package.json","Limité aux écosystèmes de frameworks JavaScript (Next/React/Vue/Svelte/Nuxt/Astro)","Dépend de la présence existante d''outils d''analyse de bundles"],"de":["Erfordert Zugriff auf package.json-Dateien","Beschränkt auf JavaScript-Framework-Ökosysteme (Next/React/Vue/Svelte/Nuxt/Astro)","Abhängig vom Vorhandensein bestehender Bundle-Analyzer-Tools"],"pt":["Requer acesso aos arquivos package.json","Limitado aos ecossistemas de frameworks JavaScript (Next/React/Vue/Svelte/Nuxt/Astro)","Dependente da presença existente de ferramentas de análise de pacotes"],"ru":["Требует доступа к файлам package.json","Ограничен экосистемами JavaScript-фреймворков (Next/React/Vue/Svelte/Nuxt/Astro)","Зависит от наличия существующего инструментария для анализа сборок"],"ar":["يتطلب الوصول إلى ملفات package.json","مقتصر على أنظمة أطر عمل JavaScript (Next/React/Vue/Svelte/Nuxt/Astro)","يعتمد على وجود أدوات تحليل الحزم الحالية"]},"version":4},"contentHash":"584172dd49f8fc8dfbf2c5840f244617fe1c25048b1470e7876a50ae7aa6b99b","qualityScore":60}');
