INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('elsolal/Skillz-Claude/performance-auditor', 'performance-auditor', 'elsolal', 'Skillz-Claude', 'community', 'performance-auditor elsolal Skillz-Claude community The performance-auditor skill analyzes application performance and proposes optimizations, benefiting developers using frameworks like Next, React, and Vue. 性能审计器是一种AI工具，用于分析和优化应用性能。它支持React、Next、Vue和Svelte等框架，并提供Bundle Analyzer等功能。 パフォーマンスオーディターは、AIエージェントを使用してアプリケーションのパフォーマンスを分析し、最適化するためのツールです。React、Next、Vue、Svelteなどのフレームワークをサポートしています。 성능 감사기는 리액트 및 뷰 애플리케이션의 성능을 분석하고 최적화하는 AI 도구입니다. 넥스트, 스벨트 등 다양한 프레임워크를 지원하며 번들 분석기 등의 기능을 제공합니다. El auditor de rendimiento analiza y optimiza el rendimiento de aplicaciones web, identificando oportunidades de mejora en frameworks como React y Next L''auditeur de performance analyse et optimise les performances des applications web, en identifiant les opportunités d''amélioration dans des frameworks tels que React et Next Der Performance-Auditor analysiert und optimiert die Leistung von Webanwendungen, indem er Verbesserungsmöglichkeiten in Frameworks wie React und Next identifiziert O Performance Auditor é uma ferramenta que analisa as performances de aplicações e propõe otimizações, suportando frameworks como React, Next e Vue Performance Auditor — это инструмент, который анализирует производительность приложений и предлагает оптимизации, поддерживая фреймворки seperti React, Next и Vue أداة فحص الأداء هي أداة تحليل أداء التطبيقات وتقترح تحسينات، تدعم إطارات مثل React و Next و Vue how to use performance-auditor performance-auditor setup guide performance optimization techniques nextjs performance auditing react performance optimization tools what is performance-auditor performance-auditor vs webpack-bundle-analyzer performance-auditor install performance-auditor alternative 性能审计器 AI工具 应用性能优化 React性能优化 Vue性能优化 Bundle Analyzer 性能分析 最优化 Identifies framework environments via package.json grep for next/react/vue/svelte/nuxt/astro Detects bundle analyzers like @next/bundle-analyzer and webpack-bundle-analyzer Analyzes performance metrics to propose optimizations Supports mode activation for performance auditing Loads context to determine performance environment Prioritizes actions based on required and optional patterns performance-auditor is a skill that analyzes application performance, identifying areas for optimization in frameworks and bundle analyzers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('juanlamadrid20/dbrx-multi-agent-retail-intelligence/asset-bundles', 'community', 'juanlamadrid20', 'dbrx-multi-agent-retail-intelligence', 'juanlamadrid20/dbrx-multi-agent-retail-intelligence', 'asset-bundles', 0, 0, 60, '2026-03-08T01:57:15.354Z', '2026-03-08T02:03:59.000Z', 'b0d775ee547f2bd28632cb989ce9b2393d0eba0005bae48d5d4e4bfb8c6f79a2', '{"id":"juanlamadrid20/dbrx-multi-agent-retail-intelligence/asset-bundles","name":"asset-bundles","description":{"en":"The asset-bundles skill enables developers to create Databricks Asset Bundles (DABs) for seamless deployment across dev, staging, and prod environments. It benefits developers working with Databricks and Spark Declarative Pipelines.","zh":"Databricks 资源包（DABs）用于多环境部署，支持 Spark Declarative Pipeline 配置和 SQL Alert 模式","ja":"Databricks Asset Bundle (DABs) は、多環境デプロイと Spark Declarative Pipeline 構成をサポートします","ko":"Databricks 자산 번들(DABs)은 多 환경 배포 및 Spark Declarative Pipeline 구성에 사용됩니다","es":"Los paquetes de assets permiten la creación de configuraciones para despliegues multi-entorno en Databricks. Aprende a configurarlos correctamente.","fr":"Les bundles d''assets permettent de créer des configurations pour des déploiements multi-environnement sur Databricks. Découvrez comment les configurer correctement.","de":"Asset-Bundles ermöglichen die Erstellung von Konfigurationen für Multi-Umgebungs-Deployments in Databricks. Erfahren Sie, wie Sie sie richtig konfigurieren können.","pt":"O Databricks Asset Bundle é uma ferramenta para criar pacotes de ativos para implantação multi-ambiente. Aprenda a configurá-lo com nosso guia.","ru":"Databricks Asset Bundle — это инструмент для создания пакетов активов для многосредовой установки. Узнайте, как его настроить с нашей помощью","ar":"حزمة موارد البيانات Databricks هي أداة لإنشاء حزم موارد لتنفيذها في بيئات متعددة. تعلم كيفية ضبطها باستخدام دليلنا"},"seo":{"title":{"en":"asset-bundles: Databricks Asset Bundle Setup Guide | AI A...","zh":"Databricks 资源包（DABs）设置指南","ja":"Databricks Asset Bundle (DABs) のベストプラクティス - AIエージェント","ko":"Databricks 자산 번들(DABs) 구성 가이드","es":"Guía de configuración de paquetes de assets para Databricks","fr":"Guide de configuration des bundles d''assets pour Databricks","de":"Konfigurationsleitfaden für Databricks-Asset-Bundles","pt":"Guia de Configuração de Pacotes de Ativos Databricks","ru":"Настройка ИИ Агентов: Руководство по Databricks Asset Bun...","ar":"دليل إعداد حزمة موارد البيانات Databricks"},"description":{"en":"Discover how to create and deploy Databricks Asset Bundles (DABs) for multi-environment setups. Learn more and get started with our expert guide.","zh":"了解如何创建和管理 Databricks 资源包（DABs），实现多环境部署和 Spark Declarative Pipeline 配置","ja":"Databricks Asset Bundle (DABs) を使用して多環境デプロイと Spark Declarative Pipeline 構成を実現する方法を学びましょう - AIエージェント","ko":"Databricks 자산 번들(DABs)을 생성하고 관리하여 多 환경 배포 및 Spark Declarative Pipeline 구성에 대해 알아보세요","es":"Aprende a crear y configurar paquetes de assets para despliegues multi-entorno en Databricks con nuestra guía paso a paso","fr":"Découvrez comment créer et configurer des bundles d''assets pour des déploiements multi-environnement sur Databricks avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Asset-Bundles für Multi-Umgebungs-Deployments in Databricks erstellen und konfigurieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a criar pacotes de ativos Databricks para implantação multi-ambiente com nosso guia passo a passo","ru":"Откройте для себя, как настраивать Databricks Asset Bundles для развертывания в нескольких средах с нашей подробной инструкцией","ar":"اكتشف كيفية إنشاء حزمة موارد البيانات Databricks لتنفيذها في بيئات متعددة باستخدام دليلنا الشامل"},"definition":{"en":"asset-bundles is a Databricks Asset Bundle (DAB) writer that facilitates multi-environment deployment through a structured project layout and configuration files like databricks.yml and resource definitions.","zh":"Databricks 资源包（DABs）是一种用于多环境部署的软件包","ja":"Databricks Asset Bundle (DABs) は、多環境デプロイ用のソフトウェア パッケージです","ko":"Databricks 자산 번들(DABs)은 多 환경 배포용 소프트웨어 패키지입니다","es":"Un paquete de assets es una colección de configuraciones y recursos para despliegues multi-entorno en Databricks","fr":"Un bundle d''assets est une collection de configurations et de ressources pour des déploiements multi-environnement sur Databricks","de":"Ein Asset-Bundle ist eine Sammlung von Konfigurationen und Ressourcen für Multi-Umgebungs-Deployments in Databricks","pt":"Pacote de ativos Databricks é um conjunto de recursos para implantação multi-ambiente","ru":"Databricks Asset Bundle — это набор ресурсов для многосредовой установки","ar":"حزمة موارد البيانات هي مجموعة من الموارد لتنفيذها في بيئات متعددة"},"features":{"en":["Creates Databricks Asset Bundles (DABs) for multi-environment deployment","Supports Spark Declarative Pipeline configurations via SDP_guidance.md","Includes SQL Alert schemas for critical alerts with API differences","Utilizes a structured project layout with databricks.yml and resource definitions","Enables deployment across dev, staging, and prod environments","References alerts_guidance.md for SQL Alert configurations"],"zh":["支持多环境部署（dev/staging/prod）","集成 Spark Declarative Pipeline 配置","支持 SQL Alert 模式","资源定义和代码组织","主配置文件（databricks.yml）和资源文件（resources/*.yml）"],"ja":["多環境デプロイ（dev/staging/prod）をサポート","Spark Declarative Pipeline 構成を統合","SQL Alert モードをサポート","リソース定義とコードの組織化","メイン構成ファイル（databricks.yml）とリソースファイル（resources/*.yml）"],"ko":["多 환경 배포（dev/staging/prod）를 지원","Spark Declarative Pipeline 구성 통합","SQL Alert 모드를 지원","자원 정의 및 코드 구성","주 구성 파일（databricks.yml）과 자원 파일（resources/*.yml）"],"es":["Creación de configuraciones para despliegues multi-entorno","Soporte para Spark Declarative Pipeline","Definición de recursos y código en src/","Compatibilidad con SQL Alert schemas","Estructura de bundle personalizable"],"fr":["Création de configurations pour des déploiements multi-environnement","Prise en charge de Spark Declarative Pipeline","Définition de ressources et de code dans src/","Compatibilité avec les schémas d''alerte SQL","Structure de bundle personnalisable"],"de":["Erstellung von Konfigurationen für Multi-Umgebungs-Deployments","Unterstützung für Spark Declarative Pipeline","Definition von Ressourcen und Code in src/","Kompatibilität mit SQL-Alert-Schemas","Anpassbare Bundle-Struktur"],"pt":["Criação de pacotes de ativos para implantação multi-ambiente","Suporte a configurações de pipeline declarativas","Definição de recursos com arquivos YAML","Organização de código e dashboards em diretórios separados","Suporte a esquemas de alertas SQL"],"ru":["Создание пакетов активов для многосредовой установки","Поддержка декларативных конфигураций конвейера","Определение ресурсов с помощью файлов YAML","Организация кода и панелей управления в отдельных директориях","Поддержка схем SQL-оповещений"],"ar":["إنشاء حزم موارد لتنفيذها في بيئات متعددة","دعم تكوين أنابيب إعلاني","تعريف الموارد باستخدام ملفات YAML","تنظيم الكود واللوحات في مجلدات منفصلة","دعم مخططات التنبيهات SQL"]},"keywords":{"en":["how to use asset-bundles","what is asset-bundles","Databricks Asset Bundle setup guide","asset-bundles vs Databricks notebooks","asset-bundles install","Databricks multi-environment deployment","Spark Declarative Pipeline configurations","asset-bundles tutorial","Databricks Asset Bundle best practices"],"zh":["Databricks 资源包","多环境部署","Spark Declarative Pipeline","SQL Alert","资源定义","代码组织","databricks.yml","resources/*.yml"],"ja":["Databricks Asset Bundle","多環境デプロイ","Spark Declarative Pipeline","SQL Alert","リソース定義","コードの組織化","databricks.yml","resources/*.yml","AIエージェント"],"ko":["Databricks 자산 번들","多 환경 배포","Spark Declarative Pipeline","SQL Alert","자원 정의","코드 구성","databricks.yml","resources/*.yml"],"es":["paquetes de assets Databricks","despliegues multi-entorno","Spark Declarative Pipeline","SQL Alert schemas","configuración de bundles","Databricks Asset Bundles","desarrollo de aplicaciones en Databricks"],"fr":["bundles d''assets Databricks","déploiements multi-environnement","Spark Declarative Pipeline","schémas d''alerte SQL","configuration de bundles","Databricks Asset Bundles","développement d''applications sur Databricks"],"de":["Asset-Bundles Databricks","Multi-Umgebungs-Deployments","Spark Declarative Pipeline","SQL-Alert-Schemas","Konfiguration von Bundles","Databricks Asset Bundles","Anwendungsentwicklung in Databricks"],"pt":["databricks asset bundle","pacotes de ativos","implantação multi-ambiente","configuração de pipeline","recursos yaml","código e dashboards","esquemas de alertas sql","databricks tutorial"],"ru":["Databricks Asset Bundle","пакеты активов","многосредовая установка","конфигурация конвейера","ресурсы yaml","код и панели управления","схемы SQL-оповещений","Databricks руководство"],"ar":["حزمة موارد البيانات","حزم موارد","تنفيذ في بيئات متعددة","تكوين أنابيب","موارد YAML","كود ولوحات","مخططات التنبيهات SQL","دليل البيانات"]}},"owner":"juanlamadrid20","repo":"dbrx-multi-agent-retail-intelligence","repoPath":"juanlamadrid20/dbrx-multi-agent-retail-intelligence","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.354Z","topics":[],"category":"community","skillMd":{"name":"asset-bundles","description":"Create and configure Databricks Asset Bundles (DABs) with best practices for multi-environment deployments. Use when working with: (1) Creating new DAB projects, (2) Adding resources (dashboards, pipelines, jobs, alerts), (3) Configuring multi-environment deployments, (4) Setting up permissions, (5) Deploying or running bundle resources","bodyPreview":"# Databricks Asset Bundle (DABs) Writer\n\n## Overview\nCreate DABs for multi-environment deployment (dev/staging/prod).\n\n## Reference Files\n\n- **[SDP_guidance.md](SDP_guidance.md)** - Spark Declarative Pipeline configurations\n- **[alerts_guidance.md](alerts_guidance.md)** - SQL Alert schemas (critical - API differs)\n\n## Bundle Structure\n\n```\nproject/\n├── databricks.yml           # Main config + targets\n├── resources/*.yml          # Resource definitions\n└── src/                     # Code/dashboar","body":"# Databricks Asset Bundle (DABs) Writer\n\n## Overview\nCreate DABs for multi-environment deployment (dev/staging/prod).\n\n## Reference Files\n\n- **[SDP_guidance.md](SDP_guidance.md)** - Spark Declarative Pipeline configurations\n- **[alerts_guidance.md](alerts_guidance.md)** - SQL Alert schemas (critical - API differs)\n\n## Bundle Structure\n\n```\nproject/\n├── databricks.yml           # Main config + targets\n├── resources/*.yml          # Resource definitions\n└── src/                     # Code/dashboard files\n```\n\n### Main Configuration (databricks.yml)\n\n```yaml\nbundle:\n  name: project-name\n\ninclude:\n  - resources/*.yml\n\nvariables:\n  catalog:\n    default: \"default_catalog\"\n  schema:\n    default: \"default_schema\"\n  warehouse_id:\n    lookup:\n      warehouse: \"Shared SQL Warehouse\"\n\ntargets:\n  dev:\n    default: true\n    mode: development\n    workspace:\n      profile: dev-profile\n    variables:\n      catalog: \"dev_catalog\"\n      schema: \"dev_schema\"\n\n  prod:\n    mode: production\n    workspace:\n      profile: prod-profile\n    variables:\n      catalog: \"prod_catalog\"\n      schema: \"prod_schema\"\n```\n\n### Dashboard Resources\n\n```yaml\nresources:\n  dashboards:\n    dashboard_name:\n      display_name: \"[${bundle.target}] Dashboard Title\"\n      file_path: ../src/dashboards/dashboard.lvdash.json  # Relative to resources/\n      warehouse_id: ${var.warehouse_id}\n      permissions:\n        - level: CAN_RUN\n          group_name: \"users\"\n```\n\n**Permission levels**: `CAN_READ`, `CAN_RUN`, `CAN_EDIT`, `CAN_MANAGE`\n\n### Pipelines\n\n**See [SDP_guidance.md](SDP_guidance.md)** for pipeline configuration\n\n### SQL Alerts\n\n**See [alerts_guidance.md](alerts_guidance.md)** - Alert schema differs significantly from other resources\n\n### Jobs Resources\n\n```yaml\nresources:\n  jobs:\n    job_name:\n      name: \"[${bundle.target}] Job Name\"\n      tasks:\n        - task_key: \"main_task\"\n          notebook_task:\n            notebook_path: ../src/notebooks/main.py  # Relative to resources/\n          new_cluster:\n            spark_version: \"13.3.x-scala2.12\"\n            node_type_id: \"i3.xlarge\"\n            num_workers: 2\n      schedule:\n        quartz_cron_expression: \"0 0 9 * * ?\"\n        timezone_id: \"America/Los_Angeles\"\n      permissions:\n        - level: CAN_VIEW\n          group_name: \"users\"\n```\n\n**Permission levels**: `CAN_VIEW`, `CAN_MANAGE_RUN`, `CAN_MANAGE`\n\n⚠️ **Cannot modify \"admins\" group permissions** on jobs - verify custom groups exist before use\n\n### Path Resolution\n\n⚠️ **Critical**: Paths depend on file location:\n\n| File Location | Path Format | Example |\n|--------------|-------------|---------|\n| `resources/*.yml` | `../src/...` | `../src/dashboards/file.json` |\n| `databricks.yml` targets | `./src/...` | `./src/dashboards/file.json` |\n\n**Why**: `resources/` files are one level deep, so use `../` to reach bundle root. `databricks.yml` is at root, so use `./`\n\n### Volume Resources\n\n```yaml\nresources:\n  volumes:\n    my_volume:\n      catalog_name: ${var.catalog}\n      schema_name: ${var.schema}\n      name: \"volume_name\"\n      volume_type: \"MANAGED\"\n```\n\n⚠️ **Volumes use `grants` not `permissions`** - different format from other resources\n\n### Apps Resources\n\n**Apps resource support added in Databricks CLI 0.239.0 (January 2025)**\n\nApps in DABs have a minimal configuration - environment variables are defined in `app.yaml` in the source directory, NOT in databricks.yml.\n\n#### Generate from Existing App (Recommended)\n\n```bash\n# Generate bundle config from existing CLI-deployed app\ndatabricks bundle generate app --existing-app-name my-app --key my_app --profile DEFAULT\n\n# This creates:\n# - resources/my_app.app.yml (minimal resource definition)\n# - src/app/ (downloaded source files including app.yaml)\n```\n\n#### Manual Configuration\n\n**resources/my_app.app.yml:**\n```yaml\nresources:\n  apps:\n    my_app:\n      name: my-app-${bundle.target}        # Environment-specific naming\n      description: \"My application\"\n      source_code_path: ../src/app         # Relative to resources/ dir\n```\n\n**src/app/app.yaml:** (Environment variables go here)\n```yaml\ncommand:\n  - \"python\"\n  - \"dash_app.py\"\n\nenv:\n  - name: USE_MOCK_BACKEND\n    value: \"false\"\n  - name: DATABRICKS_WAREHOUSE_ID\n    value: \"your-warehouse-id\"\n  - name: DATABRICKS_CATALOG\n    value: \"main\"\n  - name: DATABRICKS_SCHEMA\n    value: \"my_schema\"\n```\n\n**databricks.yml:**\n```yaml\nbundle:\n  name: my-bundle\n\ninclude:\n  - resources/*.yml\n\nvariables:\n  warehouse_id:\n    default: \"default-warehouse-id\"\n\ntargets:\n  dev:\n    default: true\n    mode: development\n    workspace:\n      profile: dev-profile\n    variables:\n      warehouse_id: \"dev-warehouse-id\"\n```\n\n#### Key Differences from Other Resources\n\n| Aspect | Apps | Other Resources |\n|--------|------|-----------------|\n| **Environment vars** | In `app.yaml` (source dir) | In databricks.yml or resource file |\n| **Configuration** | Minimal (name, description, path) | Extensive (tasks, clusters, etc.) |\n| **Source path** | Points to app directory | Points to specific files |\n\n⚠️ **Important**: When source code is in project root (not src/app), use `source_code_path: ..` in the resource file\n\n### Other Resources\n\nDABs supports schemas, models, experiments, clusters, warehouses, etc. Use `databricks bundle schema` to inspect schemas.\n\n**Reference**: [DABs Resource Types](https://docs.databricks.com/dev-tools/bundles/resources)\n\n## Common Commands\n\n### Validation\n```bash\ndatabricks bundle validate                    # Validate default target\ndatabricks bundle validate -t prod           # Validate specific target\n```\n\n### Deployment\n```bash\ndatabricks bundle deploy                      # Deploy to default target\ndatabricks bundle deploy -t prod             # Deploy to specific target\ndatabricks bundle deploy --auto-approve      # Skip confirmation prompts\ndatabricks bundle deploy --force             # Force overwrite remote changes\n```\n\n### Running Resources\n```bash\ndatabricks bundle run resource_name          # Run a pipeline or job\ndatabricks bundle run pipeline_name -t prod  # Run in specific environment\n\n# Apps require bundle run to start after deployment\ndatabricks bundle run app_resource_key -t dev    # Start/deploy the app\n```\n\n### Monitoring & Logs\n\n**View application logs (for Apps resources):**\n```bash\n# View logs for deployed apps\ndatabricks apps logs <app-name> --profile <profile-name>\n\n# Examples:\ndatabricks apps logs my-dash-app-dev -p DEFAULT\ndatabricks apps logs my-streamlit-app-prod -p DEFAULT\n```\n\n**What logs show:**\n- `[SYSTEM]` - Deployment progress, file updates, dependency installation\n- `[APP]` - Application output (print statements, errors)\n- Backend connection status\n- Deployment IDs and timestamps\n- Stack traces for errors\n\n**Key log patterns to look for:**\n- ✅ `Deployment successful` - Confirms deployment completed\n- ✅ `App started successfully` - App is running\n- ✅ `Initialized real backend` - Backend connected to Unity Catalog\n- ❌ `Error:` - Look for error messages and stack traces\n- 📝 `Requirements installed` - Dependencies loaded correctly\n\n### Cleanup\n```bash\ndatabricks bundle destroy -t dev\ndatabricks bundle destroy -t prod --auto-approve\n```\n\n---\n\n## Common Issues\n\n| Issue | Solution |\n|-------|----------|\n| **App deployment fails** | Check logs: `databricks apps logs <app-name>` for error details |\n| **App not connecting to Unity Catalog** | Check logs for backend connection errors; verify warehouse ID and permissions |\n| **Wrong permission level** | Dashboards: CAN_READ/RUN/EDIT/MANAGE; Jobs: CAN_VIEW/MANAGE_RUN/MANAGE |\n| **Path resolution fails** | Use `../src/` in resources/*.yml, `./src/` in databricks.yml |\n| **Catalog doesn''t exist** | Create catalog first or update variable |\n| **\"admins\" group error on jobs** | Cannot modify admins permissions on jobs |\n| **Volume permissions** | Use `grants` not `permissions` for volumes |\n| **Hardcoded catalog in dashboard** | Create environment-specific files or parameterize JSON |\n| **App not starting after deploy** | Apps require `databricks bundle run <resource_key>` to start |\n| **App env vars not working** | Environment variables go in `app.yaml` (source dir), not databricks.yml |\n| **Wrong app source path** | Use `../` from resources/ dir if source is in project root |\n| **Debugging any app issue** | First step: `databricks apps logs <app-name>` to see what went wrong |\n\n## Key Principles\n\n1. **Path resolution**: `../src/` in resources/*.yml, `./src/` in databricks.yml\n2. **Variables**: Parameterize catalog, schema, warehouse\n3. **Mode**: `development` for dev/staging, `production` for prod\n4. **Groups**: Use `\"users\"` for all workspace users\n5. **Job permissions**: Verify custom groups exist; can''t modify \"admins\"\n\n## Resources\n\n- [Databricks Asset Bundles Documentation](https://docs.databricks.com/dev-tools/bundles/)\n- [Bundle Resources Reference](https://docs.databricks.com/dev-tools/bundles/resources)\n- [Bundle Configuration Reference](https://docs.databricks.com/dev-tools/bundles/settings)\n- [Supported Resource Types](https://docs.databricks.com/aws/en/dev-tools/bundles/resources#resource-types)\n- [Examples Repository 1](https://github.com/databricks-solutions/databricks-dab-examples)\n- [Example Repository 2](https://github.com/databricks/bundle-examples)"},"lastSynced":"2026-03-08T02:03:59.000Z","agentAnalysis":{"suitability":{"en":"Ideal for Databricks-focused AI Agents requiring seamless multi-environment deployment capabilities for Spark Declarative Pipelines","zh":"适用于需要在多环境中无缝部署 Spark 声明式管道的 Databricks 专用 AI 代理的理想选择","ja":"Databricks に焦点を当てた AI エージェントが複数の環境にシームレスにデプロイできる機能を必要とする場合に最適","ko":"다중 환경에서 Spark 선언적 파이프라인을无缝으로 배포해야 하는 Databricks 중심의 AI 에이전트에 적합","es":"Ideal para agentes de inteligencia artificial centrados en Databricks que requieren capacidades de implementación multi-entorno sin problemas para Spark Declarative Pipelines","fr":"Idéal pour les agents d''intelligence artificielle axés sur Databricks nécessitant des capacités de déploiement multi-environnement sans interruption pour Spark Declarative Pipelines","de":"Ideal für auf Databricks fokussierte KI-Agents, die eine nahtlose Multi-Umgebungs-Bereitstellungs-Funktion für Spark Declarative Pipelines erfordern","pt":"Ideal para Agentes de IA focados em Databricks que requerem capacidades de implantação multi-ambiente sem interrupção para Pipelines Declarativas Spark","ru":"Идеально для агентов ИИ, ориентированных на Databricks, требующих бесшовных возможностей развертывания в нескольких средах для декларативных конвейеров Spark","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يركزون على Databricks و الذين يتطلبون إمكانيات النشر متعددة البيئات دون انقطاع لاسپارك أنابيب إعلانية"},"recommendation":{"en":"Empowers agents to create and manage Databricks Asset Bundles (DABs) for streamlined deployment across dev, staging, and prod environments, leveraging Spark Declarative Pipeline configurations and SQL Alert schemas","zh":"赋予代理创建和管理 Databricks 资产包（DABs），以便在开发、暂存和生产环境中实现流畅的部署，利用 Spark 声明式管道配置和 SQL 警报模式","ja":"エージェントが Databricks Asset Bundles (DABs) を作成および管理できるようにし、開発、ステージング、プロダクション環境全体でシームレスにデプロイできるようにし、Spark Declarative Pipeline 構成および SQL アラート スキーマを活用","ko":"에이전트가 Databricks 자산 번들(DABs)을 생성하고 관리할 수 있도록 하여 개발, 스테이징, 프로덕션 환경에서 원활하게 배포할 수 있도록하며 Spark 선언적 파이프라인 구성을 활용하고 SQL 경고 스키마를 사용","es":"Habilita a los agentes a crear y gestionar Databricks Asset Bundles (DABs) para una implementación fluida en los entornos de desarrollo, preproducción y producción, aprovechando las configuraciones de Spark Declarative Pipeline y los esquemas de alertas SQL","fr":"Permet aux agents de créer et de gérer des bundles d''actifs Databricks (DAB) pour un déploiement fluide dans les environnements de développement, de pré-production et de production, en exploitant les configurations de Spark Declarative Pipeline et les schémas d''alertes SQL","de":"Ermächtigt Agents, Databricks Asset Bundles (DABs) zu erstellen und zu verwalten, um eine nahtlose Bereitstellung in Entwicklung-, Staging- und Produktionsumgebungen zu ermöglichen, indem Spark Declarative Pipeline-Konfigurationen und SQL-Alert-Schemata genutzt werden","pt":"Habilita os agentes a criar e gerenciar Pacotes de Ativos Databricks (DABs) para implantação simplificada em ambientes de dev, staging e prod, aproveitando configurações de Pipelines Declarativas Spark e esquemas de Alertas SQL","ru":"Наделяет агентов возможностью создавать и управлять пакетами активов Databricks (DAB) для упрощенного развертывания в средах разработки, подготовки и производства, используя конфигурации декларативных конвейеров Spark и схемы оповещений SQL","ar":"يمنح الوكلاء القدرة على إنشاء وإدارة حزم أصول Databricks (DABs) لنشر مبسط عبر بيئات التطوير والمرحلة والإنتاج، مستفيداً من تكوينات أنابيب Spark الإعلانية ومخططات تنبيهات SQL"},"useCases":{"en":["Deploying Databricks applications across multiple environments","Managing Spark Declarative Pipelines for consistent workflow execution","Creating and configuring SQL Alerts for critical notifications"],"zh":["跨多个环境部署 Databricks 应用程序","管理 Spark 声明式管道以确保工作流的一致性执行","创建和配置 SQL 警报以实现关键通知"],"ja":["複数の環境に Databricks アプリケーションをデプロイする","ワークフローの一貫した実行を確保するために Spark Declarative Pipeline を管理する","重要な通知を実現するために SQL アラートを作成および構成する"],"ko":["다중 환경에서 Databricks 애플리케이션을 배포","일관된 워크플로우 실행을 보장하기 위해 Spark 선언적 파이프라인을 관리","중요한 알림을 구현하기 위해 SQL 경고를 생성하고 구성"],"es":["Implementar