INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('inocan-group/inferred-types/testing', 'testing', 'inocan-group', 'inferred-types', 'community', 'testing inocan-group inferred-types community This testing skill provides guidance on testing in TypeScript projects, covering runtime behavior and type correctness. It benefits developers working with TypeScript. 本测试技能提供了 TypeScript 项目测试的综合指南，涵盖运行时行为和类型正确性 このテストスキルは、TypeScript プロジェクトのテストに関する包括的なガイドを提供し、ランタイム動作とタイプの正しさをカバーします 이 테스트 스킬은 타입스크립트 프로젝트의 테스트에 대한 포괄적인 가이드를 제공하며, 런타임 동작과 유형의 올바름을 다룹니다 Nuestra habilidad de pruebas proporciona orientación sobre pruebas de runtime y corrección de tipos en proyectos de TypeScript Notre compétence en matière de tests fournit des conseils sur les tests de runtime et la correction de types dans les projets TypeScript Unsere Testfähigkeit bietet Anleitung zu Runtime-Tests und Typkorrektheit in TypeScript-Projekten Este skill fornece orientação abrangente sobre testes em projetos TypeScript, cobrindo testes de tempo de execução e correção de tipo Этот навык предоставляет комплексное руководство по тестированию в проектах TypeScript, включая тесты времени выполнения и типовую корректность يقدم هذا المهارة إرشادات شاملة للاختبار في مشاريع TypeScript، بما في ذلك اختبارات وقت التشغيل وصحّة النوع how to use testing in TypeScript what is testing in software development testing vs Jest testing setup guide for TypeScript TypeScript testing best practices runtime behavior testing tutorial TypeScript 测试 运行时行为 类型正确性 Test-Driven Development TDD TypeScript 项目测试 AI 测试工具 Provides comprehensive guidance on testing in TypeScript projects Covers runtime behavior testing for actual code execution Includes type correctness testing for robust code development Supports Test-Driven Development (TDD) for integrated workflows Helps structure tests effectively for optimal results Testing is a crucial aspect of software development that verifies the actual behavior and type correctness of code during execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('benjaminshoemaker/ai_coding_project_base/feature-technical-spec', 'community', 'benjaminshoemaker', 'ai_coding_project_base', 'benjaminshoemaker/ai_coding_project_base', 'feature-technical-spec', 0, 0, 60, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:05.275Z', '296e881084ba19bd02952f32ed14ed622b0cd1b8a3ce8f2dc037941c11c1a58b', '{"id":"benjaminshoemaker/ai_coding_project_base/feature-technical-spec","name":"feature-technical-spec","description":{"en":"The feature-technical-spec skill generates a feature technical specification document for AI coding assistants, guiding product specification, technical design, and implementation planning.","zh":"该工具包指导您完成产品规格、技术设计和实施规划，生成AI代理可以执行的文档","ja":"このツールキットは、AIエージェントが実行できるドキュメントを生成するための製品仕様、技術設計、実装計画を導きます","ko":"이 툴킷은 AI 에이전트가 실행할 수 있는 문서를 생성하기 위한 제품 사양, 기술 설계 및 구현 계획을 안내합니다","es":"El kit de herramientas de especificaciones técnicas de características te guía a través de la especificación de productos, diseño técnico y planificación de implementación.","fr":"Le kit d''outils de spécifications techniques de fonctionnalités vous guide à travers la spécification de produits, la conception technique et la planification de la mise en œuvre.","de":"Das Toolkit für technische Spezifikationen von Funktionen führt Sie durch die Produktspezifikation, technische Konzeption und Implementierungsplanung.","pt":"O feature-technical-spec é uma estrutura de prompt para construir produtos de software com assistentes de codificação de IA, produzindo documentos que os agentes de IA podem executar","ru":"Feature-technical-spec - это структурированная система для построения программных продуктов с помощью инструментов ИИ,产生я документы, которые ИИ агенты могут выполнить","ar":"الميزة الفنية هي إطار محفز لإنشاء منتجات برمجية باستخدام مساعدات الترميز الذكي، مما ينتج عنه مستندات يمكن للوكلاء الذكاء الاصطناعي تنفيذها"},"seo":{"title":{"en":"feature-technical-spec: Setup Guide for AI Agents","zh":"AI工具技术规格设置指南","ja":"AIエージェントのフィーチャー技術仕様ガイド","ko":"AI 에이전트 기능 기술 규격 설정 가이드","es":"Guía de Configuración para Especificaciones Técnicas de C...","fr":"Guide de Mise en Place pour les Spécifications Techniques...","de":"Einrichtungsleitfaden für Technische Spezifikationen von ...","pt":"Guia de Configuração de Especificações Técnicas de Recurs...","ru":"Настройка Технических Спецификаций Функций с ИИ Агентами","ar":"دليل إعداد المواصفات الفنية للميزات باستخدام أدوات الذكاء..."},"description":{"en":"Streamline your software development with feature-technical-spec. Learn how to generate technical specification documents and execute them with AI agents. Ge...","zh":"使用AI工具生成功能技术规格文档，包括产品规格、技术设计和实施规划","ja":"AIエージェントを使用してフィーチャー技術仕様ドキュメントを生成し、ソフトウェア開発を効率化する","ko":"AI 에이전트를 사용하여 기능 기술 규격 문서를 생성하고 소프트웨어 개발을 효율화하세요","es":"Aprende a crear documentos de especificaciones técnicas para características de software con agentes de IA. Mejora tu flujo de trabajo con nuestra guía práct...","fr":"Découvrez comment créer des documents de spécifications techniques pour les fonctionnalités de logiciels avec les outils d''IA. Améliorez votre flux de travai...","de":"Erfahren Sie, wie Sie technische Spezifikationsdokumente für Softwarefunktionen mit KI-Agenten erstellen. Verbessern Sie Ihren Arbeitsablauf mit unserem Prax...","pt":"Aprenda a criar documentos de especificações técnicas de recursos com o auxílio de assistentes de codificação de IA, incluindo diretrizes para especificação ...","ru":"Изучите, как создавать технические спецификации функций с помощью инструментов ИИ, включая руководство по spécification продукта и планированию реализации","ar":"تعلم كيفية إنشاء مستندات مواصفات فنية للميزات باستخدام مساعدات الترميز الذكي، بما في ذلك الإرشادات لتحديد مواصفات المنتج وتخطيط التنفيذ"},"definition":{"en":"feature-technical-spec is a structured prompt framework for building software products with AI coding assistants, producing documents for AI agents to execute.","zh":"功能技术规格是指使用AI工具生成的软件产品技术文档","ja":"フィーチャー技術仕様は、AIエージェントを使用して生成されたソフトウェア製品の技術文書です","ko":"기능 기술 규격은 AI 에이전트를 사용하여 생성된 소프트웨어 제품의 기술 문서입니다","es":"Una especificación técnica de características es un documento que describe los requisitos y la implementación de una función de software.","fr":"Une spécification technique de fonctionnalité est un document qui décrit les exigences et la mise en œuvre d''une fonctionnalité de logiciel.","de":"Eine technische Spezifikation von Funktionen ist ein Dokument, das die Anforderungen und die Implementierung einer Softwarefunktion beschreibt.","pt":"O que é feature-technical-spec? É uma estrutura de prompt para construir produtos de software com assistentes de codificação de IA","ru":"Что такое feature-technical-spec? Это структурированная система для построения программных продуктов с помощью инструментов ИИ","ar":"ما هي الميزة الفنية؟ هي إطار محفز لإنشاء منتجات برمجية باستخدام مساعدات الترميز الذكي"},"features":{"en":["Generates FEATURE_TECHNICAL_SPEC.md documents","Performs existing code analysis for similar functionality and integration points","Runs spec-verification for validation","Captures deferred requirements for future development","Creates a directory guard for organization","Checks prerequisites and prevents overwrite of existing files"],"zh":["生成功能技术规格文档","产品规格和技术设计","实施规划和代码分析","代码库成熟度评估","特性技术规格验证"],"ja":["フィーチャー技術仕様ドキュメントの生成","製品仕様と技術設計","実装計画とコード分析","コードベースの成熟度評価","フィーチャー技術仕様の検証"],"ko":["기능 기술 규격 문서 생성","제품 사양 및 기술 설계","구현 계획 및 코드 분석","코드베이스 성숙도 평가","기능 기술 규격 검증"],"es":["Generación de documentos de especificaciones técnicas para características de software","Análisis de código existente y puntos de integración","Evaluación de la madurez del código base","Verificación de especificaciones y captura de requisitos diferidos"],"fr":["Génération de documents de spécifications techniques pour les fonctionnalités de logiciels","Analyse de code existant et points d''intégration","Évaluation de la maturité du code base","Vérification de spécifications et capture de exigences différées"],"de":["Erstellung von technischen Spezifikationsdokumenten für Softwarefunktionen","Analyse von bestehendem Code und Integrationspunkten","Bewertung der Reife des Code-Basisses","Verifizierung von Spezifikationen und Erfassung von verschobenen Anforderungen"],"pt":["Geração de documentos de especificações técnicas de recursos","Análise de código existente e integração de funcionalidades","Avaliação da maturidade do código","Verificação de especificações","Prevenção de sobrescrita de arquivos existentes","Controle de progresso com checklist"],"ru":["Генерация технических спецификаций функций","Анализ существующего кода и интеграция функций","Оценка зрелости кода","Верификация спецификаций","Предотвращение перезаписи существующих файлов","Контроль прогресса с помощью чек-листа"],"ar":["إنشاء مستندات مواصفات فنية للميزات","تحليل الشفرة الحالية وتكامل الوظائف","تقييم نضج الشفرة","التحقق من المواصفات","منع الكتابة فوق الملفات الحالية","مراقبة التقدم باستخدام قائمة التحقق"]},"keywords":{"en":["how to use feature-technical-spec","feature-technical-spec setup guide","what is feature-technical-spec","feature-technical-spec alternative","feature-technical-spec vs competitors","feature-technical-spec install","generating technical specification documents","AI coding assistants","software development with AI"],"zh":["AI工具","功能技术规格","软件开发","产品规格","技术设计","实施规划","代码分析","代码库成熟度评估"],"ja":["AIエージェント","フィーチャー技術仕様","ソフトウェア開発","製品仕様","技術設計","実装計画","コード分析","コードベースの成熟度評価"],"ko":["AI 에이전트","기능 기술 규격","소프트웨어 개발","제품 사양","기술 설계","구현 계획","코드 분석","코드베이스 성숙도 평가"],"es":["agentes de inteligencia artificial","especificaciones técnicas de características","desarrollo de software","análisis de código","evaluación de madurez del código","verificación de especificaciones"],"fr":["outils d''IA","spécifications techniques de fonctionnalités","développement de logiciels","analyse de code","évaluation de la maturité du code","vérification de spécifications"],"de":["KI-Agenten","technische Spezifikationen von Funktionen","Softwareentwicklung","Code-Analyse","Bewertung der Reife des Code-Basisses","Verifizierung von Spezifikationen"],"pt":["ferramentas de inteligência artificial","especificações técnicas de recursos","assistente de codificação de IA","desenvolvimento de software","análise de código","verificação de especificações","planejamento de implementação","guia de configuração"],"ru":["инструменты ИИ","технические спецификации функций","инструменты ИИ для кодирования","разработка программного обеспечения","анализ кода","верификация спецификаций","планирование реализации","настройка технических спецификаций"],"ar":["أدوات الذكاء الاصطناعي","مواصفات فنية للميزات","مساعدات الترميز الذكي","تطوير البرمجيات","تحليل الشفرة","التحقق من المواصفات","تخطيط التنفيذ","دليل إعداد المواصفات الفنية"]}},"owner":"benjaminshoemaker","repo":"ai_coding_project_base","repoPath":"benjaminshoemaker/ai_coding_project_base","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.358Z","topics":[],"category":"community","skillMd":{"name":"feature-technical-spec","description":"Define technical approach (architecture, integration points, data model) for a feature through guided Q&A and write FEATURE_TECHNICAL_SPEC.md. Use after /feature-spec.","bodyPreview":"Generate a feature technical specification document for the feature `$1`.\n\n## Workflow\n\nCopy this checklist and track progress:\n\n```\nFeature Technical Spec Progress:\n- [ ] Directory guard\n- [ ] Check prerequisites (FEATURE_SPEC.md exists)\n- [ ] Existing file guard (prevent overwrite)\n- [ ] Existing code analysis (similar functionality, patterns, integration points)\n- [ ] Codebase maturity assessment\n- [ ] Generate FEATURE_TECHNICAL_SPEC.md\n- [ ] Run spec-verification\n- [ ] Capture deferred requi","body":"Generate a feature technical specification document for the feature `$1`.\n\n## Workflow\n\nCopy this checklist and track progress:\n\n```\nFeature Technical Spec Progress:\n- [ ] Directory guard\n- [ ] Check prerequisites (FEATURE_SPEC.md exists)\n- [ ] Existing file guard (prevent overwrite)\n- [ ] Existing code analysis (similar functionality, patterns, integration points)\n- [ ] Codebase maturity assessment\n- [ ] Generate FEATURE_TECHNICAL_SPEC.md\n- [ ] Run spec-verification\n- [ ] Capture deferred requirements\n- [ ] Cross-model review (if Codex available)\n```\n\n## Directory Guard\n\n1. If `.toolkit-marker` exists in the current working directory → **STOP**:\n   \"You''re in the toolkit repo. Feature skills run from your project directory.\n    Run: `cd ~/Projects/your-project && /feature-technical-spec $1`\"\n\n2. Check `.claude/toolkit-version.json` exists in the current working directory (confirms `/setup` was run).\n   If missing → **STOP**: \"Toolkit not installed. Run `/setup` from the toolkit first.\"\n\n3. Check `AGENTS.md` exists in the current working directory (confirms project root).\n   If missing → **STOP**: \"Run this from your project root (where AGENTS.md lives).\"\n\n## Arguments\n\n- `$1` = feature name (e.g., `analytics`, `dark-mode`)\n- If `$1` is empty, ask the user for the feature name\n- `PROJECT_ROOT` = current working directory\n- `FEATURE_DIR` = `PROJECT_ROOT/features/$1`\n\n## Prerequisites\n\n- Check that `FEATURE_DIR/FEATURE_SPEC.md` exists. If not:\n  \"FEATURE_SPEC.md not found at features/$1/. Run `/feature-spec $1` first.\"\n- Check that `PROJECT_ROOT/AGENTS.md` exists (indicates an existing project). If not, warn:\n  \"AGENTS.md not found. Feature development assumes an existing project. Did you mean to run `/product-spec` for a new project?\"\n\n## Existing File Guard (Prevent Overwrite)\n\nBefore asking any questions, check whether `FEATURE_DIR/FEATURE_TECHNICAL_SPEC.md` already exists.\n\n- If it does not exist: continue normally.\n- If it exists: **STOP** and ask the user what to do:\n  1. **Backup then overwrite (recommended)**: read the existing file and write it to `FEATURE_DIR/FEATURE_TECHNICAL_SPEC.md.bak.YYYYMMDD-HHMMSS`, then write the new document to `FEATURE_DIR/FEATURE_TECHNICAL_SPEC.md`\n  2. **Overwrite**: replace `FEATURE_DIR/FEATURE_TECHNICAL_SPEC.md` with the new document\n  3. **Abort**: do not write anything; suggest they rename/move the existing file first\n\n## Process\n\nRead `.claude/skills/feature-technical-spec/PROMPT.md` and follow its instructions exactly:\n\n1. Read `FEATURE_DIR/FEATURE_SPEC.md` as input\n\n2. **Perform Existing Code Analysis** (REQUIRED before any design):\n\n   **Note:** All code analysis should be performed on PROJECT_ROOT (current working directory).\n\n   a. **Similar Functionality Audit**\n      - Search for existing code that does something similar to what the feature needs\n      - List any utilities, helpers, or patterns that could be reused\n      - Flag if creating new code when existing code could be extended\n      - Output:\n        ```\n        SIMILAR FUNCTIONALITY FOUND\n        ---------------------------\n        - {file}: {description of similar functionality}\n        - {file}: {reusable utility/helper}\n\n        Recommendation: {extend existing | create new | hybrid approach}\n        ```\n\n   b. **Pattern Compliance Check**\n      - Identify how similar features are implemented in the codebase\n      - Note naming conventions, file organization, error handling patterns\n      - Document the \"house style\" for this type of feature\n      - Output:\n        ```\n        EXISTING PATTERNS\n        -----------------\n        File organization: {pattern}\n        Naming convention: {pattern}\n        Error handling: {pattern}\n        Testing approach: {pattern}\n        ```\n\n   c. **Integration Point Mapping**\n      - List every existing file/module the feature will touch\n      - For each, assess: complexity, test coverage, documentation quality\n      - Flag high-risk integration points\n      - Output:\n        ```\n        INTEGRATION POINTS\n        ------------------\n        | File | Risk | Coverage | Notes |\n        |------|------|----------|-------|\n        | {file} | High/Med/Low | X% | {concerns} |\n        ```\n\n3. **Assess codebase maturity** — Is this a legacy/brownfield codebase?\n   - Look for: outdated dependencies, missing tests, undocumented code, deprecated patterns\n   - If legacy indicators found, explicitly address technical debt, undocumented behavior, and human decision points\n\n4. Work through integration analysis, regression risks, and migration strategy\n\n5. Generate the final FEATURE_TECHNICAL_SPEC.md document, incorporating findings from step 2\n\n## Output\n\nWrite the completed specification to `FEATURE_DIR/FEATURE_TECHNICAL_SPEC.md`.\n\n## Verification (Automatic)\n\nAfter writing FEATURE_TECHNICAL_SPEC.md, run the spec-verification workflow:\n\n1. Read `.claude/skills/spec-verification/SKILL.md` for the verification process\n2. Verify context preservation: Check that all key items from FEATURE_SPEC.md appear in FEATURE_TECHNICAL_SPEC.md\n3. Run quality checks for vague language, missing rationale, undefined contracts, integration gaps\n4. Present any CRITICAL issues to the user with resolution options\n5. Apply fixes based on user choices\n6. Re-verify until clean or max iterations reached\n\n**IMPORTANT**: Do not proceed to \"Next Step\" until verification passes or user explicitly chooses to proceed with noted issues.\n\n## Deferred Requirements Capture (During Q&A)\n\n**IMPORTANT:** Capture deferred requirements interactively during the Q&A process, not after.\n\nWrite deferred items to `PROJECT_ROOT/DEFERRED.md` (not the feature directory).\n\n### When to Trigger\n\nDuring the Q&A, watch for signals that the user is deferring a technical decision:\n- \"out of scope\"\n- \"not in this feature\" / \"separate feature\"\n- \"v2\" / \"future version\"\n- \"premature optimization\"\n- \"technical debt we''ll address later\"\n- \"keep it simple for now\"\n- \"follow-up\" / \"future enhancement\"\n\n### Capture Flow\n\nWhen you detect a deferral signal, immediately use AskUserQuestion:\n\n```\nQuestion: \"Would you like to save this to your deferred requirements?\"\nHeader: \"Defer?\"\nOptions:\n  - \"Yes, capture it\" — I''ll ask a few quick questions to document it\n  - \"No, skip\" — Don''t record this\n```\n\n**If user selects \"Yes, capture it\":**\n\nAsk these clarifying questions:\n\n1. **What''s being deferred?**\n   \"In one sentence, what''s the technical decision or feature?\"\n   (Pre-fill with your understanding from context)\n\n2. **Why defer it?**\n   Options: \"Premature optimization\" / \"Out of scope\" / \"Separate feature\" / \"V2\" / \"Needs more research\" / \"Other\"\n\n3. **Notes for later?**\n   \"Any technical context that will help when revisiting this?\"\n   (Optional — user can skip)\n\n### Write to DEFERRED.md Immediately\n\nAfter collecting answers, append to `PROJECT_ROOT/DEFERRED.md` right away.\n\n**Add new section or append to existing feature section:**\n\n```markdown\n\n## From FEATURE_TECHNICAL_SPEC.md: {FEATURE_NAME} ({date})\n\n| Requirement | Reason | Notes |\n|-------------|--------|-------|\n| {user''s answer} | {selected reason} | {notes or \"—\"} |\n```\n\n### Continue Q&A\n\nAfter capturing (or skipping), continue the spec Q&A where you left off.\n\n## Cross-Model Review (Automatic)\n\nAfter verification passes, run cross-model review if Codex CLI is available:\n\n1. Check if Codex CLI is installed: `codex --version`\n2. If available, run `/codex-consult` with upstream context\n3. Present any findings to the user before proceeding\n\n**Consultation invocation:**\n```\n/codex-consult --upstream features/$1/FEATURE_SPEC.md --research \"{detected technologies from codebase}\" features/$1/FEATURE_TECHNICAL_SPEC.md\n```\n\n**If Codex finds issues:**\n- Show critical issues and recommendations\n- Ask user: \"Address findings before proceeding?\" (Yes/No)\n- If Yes: Apply suggested fixes\n- If No: Continue with noted issues\n\n**If Codex unavailable:** Skip silently and proceed to Next Step.\n\n## Error Handling\n\n| Situation | Action |\n|-----------|--------|\n| FEATURE_SPEC.md not found in `features/$1/` | Stop and report \"Run `/feature-spec $1` first\" |\n| PROMPT.md not found at `.claude/skills/feature-technical-spec/PROMPT.md` | Stop and report \"Skill asset missing — reinstall toolkit or run /setup\" |\n| Codebase too large for full code analysis (>5000 files) | Limit analysis to `src/`, `lib/`, and `app/` directories; note reduced scope in output |\n| DEFERRED.md write fails (permissions or disk) | Output deferred items to terminal, warn user, continue with spec generation |\n| Codex CLI invocation fails or times out | Log the error, skip cross-model review, proceed to Next Step |\n\n## Next Step\n\nWhen verification is complete, inform the user:\n```\nFEATURE_TECHNICAL_SPEC.md created and verified at features/$1/FEATURE_TECHNICAL_SPEC.md\n\nVerification: PASSED | PASSED WITH NOTES | NEEDS REVIEW\nCross-Model Review: PASSED | PASSED WITH NOTES | SKIPPED\nDeferred Requirements: {count} items captured to DEFERRED.md\n\nNext: Run /feature-plan $1\n```\n"},"lastSynced":"2026-03-08T02:04:05.275Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Coding Assistants needing comprehensive feature technical specification generation for product development and implementation planning.","zh":"非常适合需要为产品开发和实施规划生成全面特性技术规格的 AI 编码助手。","ja":"AI コーディング アシスタントが製品開発と実装計画のための包括的な機能の技術仕様を生成する必要がある場合に最適です。","ko":"제품 개발 및 구현 계획을 위한 포괄적인 기능 기술 사양을 생성해야 하는 AI 코딩 어시스턴트에게 적합합니다.","es":"Perfecto para asistentes de codificación de IA que necesitan una generación de especificaciones técnicas de características comprehensivas para el desarrollo y la planificación de la implementación de productos.","fr":"Parfait pour les assistants de codage IA nécessitant une génération complète de spécifications techniques de fonctionnalités pour le développement et la planification de la mise en œuvre de produits.","de":"Perfekt für AI-Coding-Assistenten, die eine umfassende Generierung von technischen Spezifikationen für Produktentwicklung und Implementierungsplanung benötigen.","pt":"Perfeito para Assistente de Codificação de IA que necessita de geração de especificações técnicas de recursos abrangentes para desenvolvimento de produtos e planejamento de implementação.","ru":"Идеально подходит для помощников кодирования ИИ, которым требуется всесторонняя генерация технических спецификаций функций для разработки продукта и планирования реализации.","ar":"مثالي لمساعدي كتابة البرمجيات الاصطناعية الذين يحتاجون إلى إنشاء مواصفات تقنية شاملة للميزات من أجل تطوير المنتجات وتنفيذ الخطة."},"recommendation":{"en":"Empowers agents to generate FEATURE_TECHNICAL_SPEC.md documents, facilitating directory guard implementation, prerequisite checks, and existing code analysis through spec-verification protocols and Markdown file formats.","zh":"赋予代理生成 FEATURE_TECHNICAL_SPEC.md 文档的能力，促进目录保护实现、先决条件检查和现有代码分析通过 spec-verification 协议和 Markdown 文件格式。","ja":"FEATURE_TECHNICAL_SPEC.md ドキュメントを生成するエージェントを可能にし、ディレクトリ ガードの実装、前提条件のチェック、および既存のコード分析を spec-verification プロトコルと Markdown ファイル形式を介して促進します。","ko":"에이전트가 FEATURE_TECHNICAL_SPEC.md 문서를 생성할 수 있도록 하여 디렉토리 가드 구현, 사전 조건 확인 및 기존 코드 분석을 spec-verification 프로토콜 및 Markdown 파일 형식을 통해 촉진합니다.","es":"Habilita a los agentes a generar documentos FEATURE_TECHNICAL_SPEC.md, facilitando la implementación de la protección de directorios, las comprobaciones de requisitos previos y el análisis de código existente a través de protocolos de verificación de especificaciones y formatos de archivo Markdown.","fr":"Permet aux agents de générer des documents FEATURE_TECHNICAL_SPEC.md, facilitant la mise en œuvre de la protection de répertoire, les vérifications de conditions préalables et l''analyse de code existant via des protocoles de vérification de spécifications et des formats de fichiers Markdown.","de":"Ermöglicht es Agenten, FEATURE_TECHNICAL_SPEC.md-Dokumente zu generieren, wodurch die Implementierung von Verzeichnisschutz, die Überprüfung von Vorbedingungen und die Analyse von bestehendem Code durch Spezifikationsprüfprotokolle und Markdown-Dateiformate erleichtert wird.","pt":"Habilita os agentes a gerar documentos FEATURE_TECHNICAL_SPEC.md, facilitando a implementação de guardas de diretório, verificações de pré-requisitos e análise de código existente por meio de protocolos de verificação de especificações e formatos de arquivo Markdown.","ru":"Наделяет агентов возможностью генерировать документы FEATURE_TECHNICAL_SPEC.md, что облегчает реализацию охраны каталогов, проверку предварительных требований и анализ существующего кода посредством протоколов верификации спецификаций и форматов файлов Markdown.","ar":"يمنح الوكلاء القدرة على إنشاء مستندات FEATURE_TECHNICAL_SPEC.md، مما يسهل تنفيذ حارس الدليل والتحقق من المتطلبات المسبقة وتحليل الكود الحالي من خلال بروتوكولات التحقق من المواصفات وتنسيقات الملفات Markdown."},"useCases":{"en":["Generating feature technical specification documents for AI coding assistants","Automating directory guard and existing file guard checks","Analyzing existing code for similar functionality and integration points"],"zh":["为 AI 编码助手生成特性技术规格文档","自动化目录保护和现有文件保护检查","分析现有代码以查找类似功能和集成点"],"ja":["AI コーディング アシスタントの機能技術仕様ドキュメントを生成する","ディレクトリ ガードと既存ファイル ガードのチェックを自動化する","類似の機能と統合ポイントを探すために既存のコードを分析する"],"ko":["AI 코딩 어시스턴트를 위한 기능 기술 사양 문서 생성","디렉토리 가드 및 기존 파일 가드 체크 자동화","유사한 기능 및 통합 지점을 찾기 위해 기존 코드 분석"],"es":["Generación de documentos de especificaciones técnicas de características para asistentes de codificación de IA","Automatización de comprobaciones de protección de directorios y archivos existentes","Análisis de código existente para funcionalidad similar y puntos de integración"],"fr":["Génération de documents de spécifications techniques de fonctionnalités pour les assistants de codage IA","Automatisation des vérifications de protection de répertoire et des fichiers existants","Analyse de code existant pour des fonctionnalités similaires et des points d''intégration"],"de":["Generierung von technischen Spezifikationsdokumenten für Funktionalitäten für AI-Coding-Assistenten","Automatisierung von Verzeichnisschutz- und bestehender Dateischutzprüfungen","Analyse von bestehendem Code für ähnliche Funktionalität und Integrationspunkte"],"pt":["Gerar documentos de especificação técnica de recursos para assistentes de codificação de IA","Automatizar verificações de guarda de diretório e guarda de arquivo existente","Analizar código existente para funcionalidades e pontos de integração semelhantes"],"ru":["Генерировать документы технической спецификации функций для помощников кодирования ИИ","Автоматизировать проверки охраны каталогов и охраны существующих файлов","Анализировать существующий код для аналогичных функций и точек интеграции"],"ar":["إنشاء مستندات مواصفات تقنية للميزات لمساعدي كتابة البرمجيات الاصطناعية","آليّة فحص حارس الدليل وحارس الملف الموجود","تحليل الكود الحالي للوظائف والنقاط المتشابهة للتكامل"]},"limitations":{"en":["Requires FEATURE_SPEC.md file to exist","Needs filesystem access for file operations","Limited to Markdown file format for FEATURE_TECHNICAL_SPEC.md generation"],"zh":["需要 FEATURE_SPEC.md 文件存在","需要文件系统访问权限以进行文件操作","FEATURE_TECHNICAL_SPEC.md 生成仅限于 Markdown 文件格式"],"ja":["FEATURE_SPEC.md ファイルが存在する必要がある","ファイル操作のためにファイル システムへのアクセスが必要である","FEATURE_TECHNICAL_SPEC.md の生成は Markdown ファイル形式に限定されている"],"ko":["FEATURE_SPEC.md 파일이 존재해야 함","파일 작업을 위해 파일 시스템에 액세스할 수 있어야 함","FEATURE_TECHNICAL_SPEC.md 생성은 Markdown 파일 형식으로 제한됨"],"es":["Requiere que el archivo FEATURE_SPEC.md exista","Necesita acceso al sistema de archivos para operaciones de archivo","Limitado al formato de archivo Markdown para la generación de FEATURE_TECHNICAL_SPEC.md"],"fr":["Nécessite l''existence du fichier FEATURE_SPEC.md","A besoin d''un accès au système de fichiers pour les opérations de fichier","Limité au format de fichier Markdown pour la génération de FEATURE_TECHNICAL_SPEC.md"],"de":["Benötigt die Existenz der Datei FEATURE_SPEC.md","Benötigt Dateisystemzugriff für Dateioperationen","Begrenzt auf das Markdown-Dateiformat für die Generierung von FEATURE_TECHNICAL_SPEC.md"],"pt":["Exige que o arquivo FEATURE_SPEC.md exista","Necessita acesso ao sistema de arquivos para operações de arquivo","Limitado ao formato de arquivo Markdown para geração de FEATURE_TECHNICAL_SPEC.md"],"ru":["Требует наличия файла FEATURE_SPEC.md","Требует доступа к файловой системе для операций с файлами","Ограничен форматом файла Markdown для генерации FEATURE_TECHNICAL_SPEC.md"],"ar":["يتطلب وجود ملف FEATURE_SPEC.md","يحتاج إلى وصول إلى نظام الملفات من أجل عمليات الملف","محدود بتنسيق ملف Markdown لإنشاء FEATURE_TECHNICAL_SPEC.md"]},"version":4},"contentHash":"296e881084ba19bd02952f32ed14ed622b0cd1b8a3ce8f2dc037941c11c1a58b","qualityScore":60}');
