INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('benjaminshoemaker/ai_coding_project_base/feature-technical-spec', 'feature-technical-spec', 'benjaminshoemaker', 'ai_coding_project_base', 'community', 'feature-technical-spec benjaminshoemaker ai_coding_project_base community The feature-technical-spec skill generates a feature technical specification document for AI coding assistants, guiding product specification, technical design, and implementation planning. 该工具包指导您完成产品规格、技术设计和实施规划，生成AI代理可以执行的文档 このツールキットは、AIエージェントが実行できるドキュメントを生成するための製品仕様、技術設計、実装計画を導きます 이 툴킷은 AI 에이전트가 실행할 수 있는 문서를 생성하기 위한 제품 사양, 기술 설계 및 구현 계획을 안내합니다 El kit de herramientas de especificaciones técnicas de características te guía a través de la especificación de productos, diseño técnico y planificación de implementación. Le kit d''outils de spécifications techniques de fonctionnalités vous guide à travers la spécification de produits, la conception technique et la planification de la mise en œuvre. Das Toolkit für technische Spezifikationen von Funktionen führt Sie durch die Produktspezifikation, technische Konzeption und Implementierungsplanung. O feature-technical-spec é uma estrutura de prompt para construir produtos de software com assistentes de codificação de IA, produzindo documentos que os agentes de IA podem executar Feature-technical-spec - это структурированная система для построения программных продуктов с помощью инструментов ИИ,产生я документы, которые ИИ агенты могут выполнить الميزة الفنية هي إطار محفز لإنشاء منتجات برمجية باستخدام مساعدات الترميز الذكي، مما ينتج عنه مستندات يمكن للوكلاء الذكاء الاصطناعي تنفيذها how to use feature-technical-spec feature-technical-spec setup guide what is feature-technical-spec feature-technical-spec alternative feature-technical-spec vs competitors feature-technical-spec install generating technical specification documents AI coding assistants software development with AI AI工具 功能技术规格 软件开发 产品规格 技术设计 实施规划 代码分析 代码库成熟度评估 Generates FEATURE_TECHNICAL_SPEC.md documents Performs existing code analysis for similar functionality and integration points Runs spec-verification for validation Captures deferred requirements for future development Creates a directory guard for organization Checks prerequisites and prevents overwrite of existing files feature-technical-spec is a structured prompt framework for building software products with AI coding assistants, producing documents for AI agents to execute.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Atyantik/python-modern-template/session-template', 'community', 'Atyantik', 'python-modern-template', 'Atyantik/python-modern-template', 'session-template', 0, 0, 60, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:05.377Z', '91629b6339ab042ee7899e558b5b402a52ebd86d8337dbc99b6bc8e7a9332914', '{"id":"Atyantik/python-modern-template/session-template","name":"session-template","description":{"en":"The session-template skill provides a comprehensive Copier template for modern Python projects, featuring quality enforcement, AI-assisted development, and extensive tooling. It benefits developers seeking efficient project setup and workflow management.","zh":"Session Template 是一个全面的 Copier 模板，用于现代 Python 项目，提供质量保证、AI 协助开发、Docker 支持和广泛的工具支持","ja":"セッションテンプレートは、モダンな Python プロジェクト向けの包括的な Copier テンプレートです。品質保証、AI アシスト開発、Docker サポート、および広範なツールサポートを提供します","ko":"세션 템플릿은 현대적인 파이썬 프로젝트를 위한 포괄적인 코피어 템플릿입니다. 품질 보증, AI 지원 개발, 도커 지원 및 광범위한 툴 지원을 제공합니다","es":"El Session Template es una plantilla integral para proyectos Python con calidad garantizada, desarrollo asistido por IA y soporte para Docker","fr":"Le Session Template est un modèle complet pour les projets Python avec qualité garantie, développement assisté par IA et prise en charge de Docker","de":"Das Session-Template ist eine umfassende Vorlage für Python-Projekte mit Qualitätsgarantie, KI-gestützter Entwicklung und Docker-Unterstützung","pt":"O session template é um modelo abrangente para projetos Python modernos com qualidade e desenvolvimento assistido por IA","ru":"Шаблон сессии - это комплексный шаблон для современных проектов Python с качеством и разработкой с помощью ИИ Агентов","ar":"قالب الجلسة هو نموذج شامل لمشاريع بايثون الحديثة مع جودة وتطوير مدعوم بالذكاء الاصطناعي"},"seo":{"title":{"en":"session-template: Comprehensive Setup Guide for AI Agents","zh":"Session Template 安装指南 - AI 工具集成和 Docker 支持","ja":"セッションテンプレートの設定方法 - AI エージェントと Docker サポート","ko":"세션 템플릿 설정 가이드 - AI 에이전트 및 도커 지원","es":"Guía de Configuración de Session Template para Proyectos ...","fr":"Guide de Configuration de Session Template pour les Proje...","de":"Einrichtungsleitfaden für Session-Template in Python-Proj...","pt":"Guia de Configuração do Session Template para Projetos Py...","ru":"Настройка Шаблона Сессии для Проектов Python с ИИ Агентами","ar":"دليل إعداد قالب الجلسة لمشاريع بايثون"},"description":{"en":"Unlock efficient Python development with session-template. Discover how to leverage AI-assisted development, Docker, and TDD workflows for modern projects. G...","zh":"了解如何使用 Session Template 实现 AI 驱动的 Python 项目开发，包括 TDD 工作流和 Docker 支持","ja":"セッションテンプレートを使用して AI ドリブンの Python プロジェクト開発を実現する方法を学びます。TDD ワークフローと Docker サポートを含みます","ko":"세션 템플릿을 사용하여 AI 기반의 파이썬 프로젝트 개발을 구현하는 방법을 알아보세요. TDD 워크플로와 도커 지원을 포함합니다","es":"Descubre cómo configurar el Session Template para proyectos Python modernos con integración de IA, Docker y pruebas TDD","fr":"Découvrez comment configurer le Session Template pour les projets Python modernes avec intégration d''IA, Docker et tests TDD","de":"Erfahren Sie, wie Sie das Session-Template für moderne Python-Projekte mit KI-Integration, Docker und TDD-Tests einrichten","pt":"Aprenda a configurar o session template para projetos Python com qualidade e desenvolvimento assistido por IA","ru":"Узнайте, как настроить шаблон сессии для проектов Python с качеством и разработкой с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد قالب الجلسة لمشاريع بايثون مع جودة وتطوير مدعوم بالذكاء الاصطناعي"},"definition":{"en":"session-template is a Copier template designed for modern Python projects, incorporating AI-assisted development, Docker support, and test-driven development workflows.","zh":"Session Template 是一个用于现代 Python 项目的 Copier 模板，提供 AI 驱动的开发和 Docker 支持","ja":"セッションテンプレートは、モダンな Python プロジェクト向けの Copier テンプレートであり、AI ドリブンの開発と Docker サポートを提供します","ko":"세션 템플릿은 현대적인 파이썬 프로젝트를 위한 코피어 템플릿으로, AI 기반의 개발과 도커 지원을 제공합니다","es":"El Session Template es una plantilla de Copier para proyectos Python que proporciona integración de IA, pruebas TDD y configuraciones de producción","fr":"Le Session Template est un modèle de Copier pour les projets Python qui offre une intégration d''IA, des tests TDD et des configurations de production","de":"Das Session-Template ist eine Copier-Vorlage für Python-Projekte, die KI-Integration, TDD-Tests und Produktionskonfigurationen bietet","pt":"O que é session template? Um modelo para projetos Python com qualidade e desenvolvimento assistido por IA","ru":"Что такое шаблон сессии? Шаблон для проектов Python с качеством и разработкой с помощью ИИ Агентов","ar":"ما هو قالب الجلسة؟ نموذج لمشاريع بايثون مع جودة وتطوير مدعوم بالذكاء الاصطناعي"},"features":{"en":["Supports TDD workflows with extensive testing capabilities","Features multi-AI integration for enhanced development","Includes production-ready configurations for streamlined deployment","Provides Docker support for containerized development environments","Enforces code quality and conventions through AI_DOCS/code-conventions.md","Facilitates project understanding through README.md and AI_DOCS/project-context.md"],"zh":["TDD 工作流","多 AI 集成","生产就绪配置","Docker 支持","质量保证"],"ja":["TDD ワークフロー","マルチ AI 統合","本番環境への準備","Docker サポート","品質保証"],"ko":["TDD 워크플로","멀티 AI 통합","생산 준비 구성","도커 지원","품질 보증"],"es":["Integración de IA para el desarrollo de proyectos","Soporte para Docker y configuraciones de producción","Pruebas TDD y flujos de trabajo de desarrollo","Cumplimiento de convenciones de código y estilos","Arquitectura y pila tecnológica documentadas"],"fr":["Intégration d''IA pour le développement de projets","Prise en charge de Docker et configurations de production","Tests TDD et flux de travail de développement","Respect des conventions de code et des styles","Architecture et pile technologique documentées"],"de":["KI-Integration für die Entwicklung von Projekten","Unterstützung für Docker und Produktionskonfigurationen","TDD-Tests und Entwicklungsworkflows","Einhaltung von Code-Konventionen und -Stilen","Dokumentierte Architektur und Technologie-Stack"],"pt":["TDD workflows","Integração multi-AI","Configurações prontas para produção","Suporte a Docker","Ferramentas extensivas"],"ru":["TDD workflows","Многофункциональная интеграция ИИ","Конфигурации готовые к производству","Поддержка Docker","Расширенные инструменты"],"ar":["TDD workflows","التكامل متعدد الذكاء الاصطناعي","التكوينات الجاهزة للإنتاج","دعم الدوكر","أدوات موسعة"]},"keywords":{"en":["how to use session-template","session-template setup guide","session-template alternative","session-template vs Copier","session-template install","what is session-template","session-template for Python development","AI-assisted development with session-template","session-template TDD workflow","session-template Docker support"],"zh":["Session Template","AI 工具","Python 项目","TDD 工作流","Docker 支持","质量保证","AI 驱动的开发"],"ja":["セッションテンプレート","AI エージェント","Python プロジェクト","TDD ワークフロー","Docker サポート","品質保証","AI ドリブンの開発"],"ko":["세션 템플릿","AI 에이전트","파이썬 프로젝트","TDD 워크플로","도커 지원","품질 보증","AI 기반의 개발"],"es":["Session Template","proyectos Python","herramientas de inteligencia artificial","desarrollo de software","pruebas TDD","Docker","configuraciones de producción","convenciones de código","estilos de código"],"fr":["Session Template","projets Python","outils d''intelligence artificielle","développement de logiciels","tests TDD","Docker","configurations de production","conventions de code","styles de code"],"de":["Session-Template","Python-Projekte","KI-Tools","Software-Entwicklung","TDD-Tests","Docker","Produktionskonfigurationen","Code-Konventionen","Code-Stile"],"pt":["session template","projetos python","desenvolvimento assistido por ia","qualidade de software","tdd workflows","integração multi-ai","docker","ferramentas de desenvolvimento"],"ru":["шаблон сессии","проекты python","разработка с помощью ИИ Агентов","качество программного обеспечения","tdd workflows","многофункциональная интеграция ИИ","docker","инструменты разработки"],"ar":["قالب الجلسة","مشاريع بايثون","التطوير المدعوم بالذكاء الاصطناعي","جودة البرمجيات","tdd workflows","التكامل متعدد الذكاء الاصطناعي","دوكر","أدوات التطوير"]}},"owner":"Atyantik","repo":"python-modern-template","repoPath":"Atyantik/python-modern-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.358Z","topics":[],"category":"community","skillMd":{"name":"session-template","description":"Apply task-specific templates to AI session plans using ai-update-plan. Use when starting a new task to load appropriate plan structure (feature, bugfix, refactor, documentation, security).","bodyPreview":"# Session Template Applier\n\n## ⚠️ MANDATORY: Read Project Documentation First\n\n**BEFORE applying session templates, you MUST read and understand the following project documentation:**\n\n### Core Project Documentation\n\n1. **README.md** - Project overview, features, and getting started\n2. **AI_DOCS/project-context.md** - Tech stack, architecture, development workflow\n3. **AI_DOCS/code-conventions.md** - Code style, formatting, best practices\n4. **AI_DOCS/tdd-workflow.md** - TDD process, testing sta","body":"# Session Template Applier\n\n## ⚠️ MANDATORY: Read Project Documentation First\n\n**BEFORE applying session templates, you MUST read and understand the following project documentation:**\n\n### Core Project Documentation\n\n1. **README.md** - Project overview, features, and getting started\n2. **AI_DOCS/project-context.md** - Tech stack, architecture, development workflow\n3. **AI_DOCS/code-conventions.md** - Code style, formatting, best practices\n4. **AI_DOCS/tdd-workflow.md** - TDD process, testing standards, coverage requirements\n\n### Session Context (if available)\n\n5. **.ai-context/ACTIVE_TASKS.md** - Current tasks and priorities\n6. **.ai-context/CONVENTIONS.md** - Project-specific conventions\n7. **.ai-context/RECENT_DECISIONS.md** - Recent architectural decisions\n8. **.ai-context/LAST_SESSION_SUMMARY.md** - Previous session summary\n\n### Additional AI Documentation\n\n9. **AI_DOCS/ai-tools.md** - Session management workflow (CRITICAL for this skill)\n10. **AI_DOCS/ai-skills.md** - Other specialized skills/agents available\n\n### Why This Matters\n\n- **Workflow Integration**: Understand how ai-update-plan fits into session management\n- **Template Selection**: Choose appropriate template based on project patterns\n- **Customization**: Adapt templates to match project-specific requirements\n- **Task Context**: Consider active tasks and recent decisions when planning\n\n**After reading these files, proceed with your template application task below.**\n\n---\n\n## Overview\n\nAutomatically apply task-specific planning templates to AI sessions, customizing generic steps with task-specific details.\n\n## When to Use\n\n- Starting a new AI session with `ai-start-task`\n- Need structured plan for common task types\n- Want to ensure all important steps are included\n- Standardizing workflow across team\n- Complex tasks needing comprehensive planning\n\n## Available Templates\n\n### 1. Feature Development (`feature`)\nFor adding new functionality\n\n### 2. Bug Fix (`bugfix`)\nFor fixing existing issues\n\n### 3. Refactoring (`refactor`)\nFor code improvement without behavior changes\n\n### 4. Documentation (`documentation`)\nFor doc updates and improvements\n\n### 5. Security Fix (`security`)\nFor security vulnerabilities and hardening\n\n## Usage Examples\n\n### Apply Template at Session Start\n\n```bash\n# Start session with feature template\napply feature development template for \"Add OAuth2 authentication\"\n```\n\n**Output:** Creates session with:\n- Research & design phase\n- TDD test-writing phase\n- Implementation phase\n- Security review phase\n- Documentation phase\n\n### Apply Template to Existing Session\n\n```bash\n# Mid-session, realize you need structured plan\napply refactoring template for current session\n```\n\n### Custom Template Selection\n\n```bash\n# Let skill analyze task and choose template\nsuggest template for \"Fix memory leak in data processor\"\n# → Skill suggests: \"bugfix\" template\n```\n\n## Template Structures\n\n### Feature Template\n\n**File:** `templates/feature.md`\n\n```markdown\n### Phase 1: Research & Design\n- [ ] Review related code in the codebase\n- [ ] Identify integration points\n- [ ] Design data models and interfaces\n- [ ] Document API contracts\n- [ ] Consider edge cases and error scenarios\n\n### Phase 2: Write Tests (TDD)\n- [ ] Write tests for happy path scenarios\n- [ ] Write tests for edge cases\n- [ ] Write tests for error handling\n- [ ] Write integration tests\n- [ ] Ensure tests fail initially (red phase)\n\n### Phase 3: Implementation\n- [ ] Implement core functionality\n- [ ] Add error handling\n- [ ] Add input validation\n- [ ] Add logging\n- [ ] Run tests - should pass (green phase)\n\n### Phase 4: Refactoring\n- [ ] Remove duplication (DRY)\n- [ ] Simplify complex logic\n- [ ] Improve naming\n- [ ] Add type hints where missing\n- [ ] Keep tests passing\n\n### Phase 5: Quality Check\n- [ ] Run make check (format, lint, test, security)\n- [ ] Fix all quality issues\n- [ ] Verify coverage ≥ 80%\n- [ ] Review with tdd-reviewer agent\n- [ ] Apply quality-fixer for auto-fixable issues\n\n### Phase 6: Documentation\n- [ ] Update README if user-facing changes\n- [ ] Add/update docstrings\n- [ ] Update API documentation\n- [ ] Add usage examples\n- [ ] Document configuration changes\n\n### Phase 7: Final Review\n- [ ] Review all changes with git diff\n- [ ] Test manually in development\n- [ ] Verify all edge cases work\n- [ ] Check performance implications\n- [ ] Ready for PR/commit\n```\n\n### Bugfix Template\n\n**File:** `templates/bugfix.md`\n\n```markdown\n### Phase 1: Reproduction\n- [ ] Reproduce the bug reliably\n- [ ] Document steps to reproduce\n- [ ] Identify affected components\n- [ ] Check if regression (previously working)\n- [ ] Review related issues\n\n### Phase 2: Root Cause Analysis\n- [ ] Add debug logging\n- [ ] Trace execution flow\n- [ ] Identify exact failure point\n- [ ] Understand why it fails\n- [ ] Document root cause\n\n### Phase 3: Write Reproduction Test (TDD)\n- [ ] Write test that reproduces the bug\n- [ ] Verify test fails (confirms bug exists)\n- [ ] Test should be specific to the bug\n- [ ] Include edge cases related to bug\n- [ ] Document expected vs actual behavior\n\n### Phase 4: Fix Implementation\n- [ ] Implement minimal fix for root cause\n- [ ] Avoid over-engineering the fix\n- [ ] Add defensive checks if needed\n- [ ] Add logging for future debugging\n- [ ] Verify test now passes\n\n### Phase 5: Regression Prevention\n- [ ] Add tests for related scenarios\n- [ ] Check if bug exists elsewhere\n- [ ] Add validation to prevent recurrence\n- [ ] Update error messages if applicable\n- [ ] Document why bug occurred\n\n### Phase 6: Quality & Testing\n- [ ] Run full test suite (no regressions)\n- [ ] Run make check\n- [ ] Verify coverage maintained/improved\n- [ ] Test manually with original report steps\n- [ ] Check performance not degraded\n\n### Phase 7: Documentation\n- [ ] Update changelog\n- [ ] Document fix in commit message\n- [ ] Add code comments explaining fix\n- [ ] Update docs if behavior changed\n- [ ] Reference issue number if applicable\n```\n\n### Refactoring Template\n\n**File:** `templates/refactor.md`\n\n```markdown\n### Phase 1: Establish Safety Net\n- [ ] Ensure tests exist for code being refactored\n- [ ] Run tests - all must pass (baseline)\n- [ ] Run make check - must pass\n- [ ] Commit current state (safety checkpoint)\n- [ ] Document current behavior\n\n### Phase 2: Identify Improvements\n- [ ] Identify code smells (duplication, complexity)\n- [ ] Find violations of SOLID principles\n- [ ] Look for unclear naming\n- [ ] Identify missing abstractions\n- [ ] List specific improvements needed\n\n### Phase 3: Plan Refactoring Steps\n- [ ] Break into small, safe steps\n- [ ] Prioritize by risk/impact\n- [ ] Identify dependencies between steps\n- [ ] Plan to keep tests green throughout\n- [ ] Consider breaking into multiple commits\n\n### Phase 4: Refactor Incrementally\n- [ ] Make one small change at a time\n- [ ] Run tests after each change\n- [ ] Keep tests passing (always green)\n- [ ] Commit after each successful step\n- [ ] If tests fail, revert and adjust approach\n\n### Phase 5: Improve Design\n- [ ] Extract methods/functions\n- [ ] Remove duplication (DRY)\n- [ ] Improve naming (clarity)\n- [ ] Simplify complex conditionals\n- [ ] Add type hints for clarity\n\n### Phase 6: Quality Verification\n- [ ] Run make check (must pass)\n- [ ] Verify no behavior changes\n- [ ] Check performance not degraded\n- [ ] Review with tdd-reviewer agent\n- [ ] Ensure coverage maintained\n\n### Phase 7: Documentation\n- [ ] Update docstrings for changed interfaces\n- [ ] Add comments for complex logic\n- [ ] Document why refactoring was needed\n- [ ] Update architecture docs if applicable\n- [ ] Record design decisions\n```\n\n### Documentation Template\n\n**File:** `templates/documentation.md`\n\n```markdown\n### Phase 1: Content Audit\n- [ ] Review existing documentation\n- [ ] Identify outdated content\n- [ ] Find missing documentation\n- [ ] Check for broken links\n- [ ] Review user feedback/questions\n\n### Phase 2: Content Planning\n- [ ] Define documentation scope\n- [ ] Identify target audience\n- [ ] Plan document structure\n- [ ] Prioritize sections to update\n- [ ] Gather technical details needed\n\n### Phase 3: Write/Update Content\n- [ ] Write clear, concise content\n- [ ] Add code examples\n- [ ] Include usage scenarios\n- [ ] Add diagrams/visuals if helpful\n- [ ] Follow documentation style guide\n\n### Phase 4: Code Examples\n- [ ] Ensure all code examples work\n- [ ] Test code examples actually run\n- [ ] Add comments to examples\n- [ ] Show both basic and advanced usage\n- [ ] Include error handling examples\n\n### Phase 5: Review & Polish\n- [ ] Check spelling and grammar\n- [ ] Verify technical accuracy\n- [ ] Ensure consistent terminology\n- [ ] Check formatting and layout\n- [ ] Validate all links work\n\n### Phase 6: Sync with Code\n- [ ] Update docstrings in code\n- [ ] Ensure API docs match implementation\n- [ ] Update type hints documentation\n- [ ] Sync version numbers\n- [ ] Update changelog\n\n### Phase 7: Validation\n- [ ] Have someone else review\n- [ ] Test following docs from scratch\n- [ ] Verify examples in clean environment\n- [ ] Check docs render correctly\n- [ ] Update AI_DOCS if relevant\n```\n\n### Security Fix Template\n\n**File:** `templates/security.md`\n\n```markdown\n### Phase 1: Vulnerability Assessment\n- [ ] Understand the security issue\n- [ ] Assess severity and impact\n- [ ] Identify affected versions\n- [ ] Check if actively exploited\n- [ ] Review security advisories\n\n### Phase 2: Impact Analysis\n- [ ] Identify all affected code paths\n- [ ] Determine data exposure risk\n- [ ] Check for similar issues elsewhere\n- [ ] Assess authentication/authorization impact\n- [ ] Review compliance implications\n\n### Phase 3: Security Test (TDD)\n- [ ] Write test demonstrating vulnerability\n- [ ] Test should fail (exploits vulnerability)\n- [ ] Test common attack vectors\n- [ ] Test boundary conditions\n- [ ] Document attack scenarios\n\n### Phase 4: Implement Fix\n- [ ] Apply principle of least privilege\n- [ ] Use secure coding practices\n- [ ] Validate all inputs\n- [ ] Sanitize outputs\n- [ ] Add rate limiting if applicable\n\n### Phase 5: Security Hardening\n- [ ] Add additional security checks\n- [ ] Implement defense in depth\n- [ ] Add security logging\n- [ ] Update authentication/authorization\n- [ ] Review encryption/hashing\n\n### Phase 6: Security Testing\n- [ ] Run security scan (Bandit)\n- [ ] Test with malicious inputs\n- [ ] Verify authentication works\n- [ ] Test authorization boundaries\n- [ ] Check for information disclosure\n\n### Phase 7: Security Review\n- [ ] Review with security-focused perspective\n- [ ] Check OWASP Top 10 compliance\n- [ ] Verify no new vulnerabilities introduced\n- [ ] Test error messages don''t leak info\n- [ ] Document security measures\n\n### Phase 8: Quality & Documentation\n- [ ] Run make check\n- [ ] Update security documentation\n- [ ] Add security comments in code\n- [ ] Document security assumptions\n- [ ] Plan coordinated disclosure if needed\n```\n\n## How It Works\n\n### Step 1: Analyze Task Description\n\nExtract keywords to determine task type:\n\n**Feature indicators:**\n- \"add\", \"implement\", \"create\", \"build\", \"new\"\n- \"feature\", \"functionality\", \"capability\"\n\n**Bugfix indicators:**\n- \"fix\", \"bug\", \"issue\", \"error\", \"broken\"\n- \"crash\", \"fail\", \"regression\"\n\n**Refactor indicators:**\n- \"refactor\", \"improve\", \"clean up\", \"reorganize\"\n- \"simplify\", \"optimize\", \"restructure\"\n\n**Documentation indicators:**\n- \"document\", \"docs\", \"README\", \"guide\"\n- \"explain\", \"describe\", \"instructions\"\n\n**Security indicators:**\n- \"security\", \"vulnerability\", \"exploit\", \"CVE\"\n- \"authentication\", \"authorization\", \"XSS\", \"SQL injection\"\n\n### Step 2: Load Template\n\nRead appropriate template from `templates/` directory:\n\n```bash\n# Load template file\ntemplate_file=\".claude/skills/session-template/templates/${template_type}.md\"\ncat \"$template_file\"\n```\n\n### Step 3: Customize Template\n\nCustomize generic steps with task-specific details:\n\n```markdown\n# Generic template:\n- [ ] Review related code in the codebase\n\n# Customized for \"Add OAuth2 authentication\":\n- [ ] Review related authentication code for OAuth2 integration\n```\n\n### Step 4: Apply to Session\n\nUse `ai-update-plan` to add items to the current session:\n\n```bash\n# Add each phase item to plan\nuv run ai-update-plan --add \"Review related authentication code\" --phase \"Phase 1\"\nuv run ai-update-plan --add \"Identify OAuth2 provider integration\" --phase \"Phase 1\"\n# ... etc\n```\n\n### Step 5: Display Plan\n\nShow the complete plan with progress tracking:\n\n```bash\nuv run ai-update-plan --show\n```\n\n## Integration with ai-update-plan\n\nThis skill leverages `ai-update-plan` features:\n\n### Add Items by Phase\n\n```bash\n# Add to specific phase\nuv run ai-update-plan --add \"Write OAuth2 tests\" --phase \"Phase 2\"\n```\n\n### Customize After Application\n\n```bash\n# Rename generic item to specific\nuv run ai-update-plan --rename \"Review related code\" \\\n  --to \"Review existing OAuth implementation\"\n\n# Remove irrelevant items\nuv run ai-update-plan --remove \"Add diagrams/visuals\"\n```\n\n### Track Progress\n\n```bash\n# Check off completed items\nuv run ai-update-plan \"Review related authentication code\"\n\n# Show progress\nuv run ai-update-plan --show\n```\n\n## Customization Guide\n\n### Creating Custom Templates\n\n1. Create new template file in `templates/`\n2. Follow standard phase structure\n3. Use checkbox format `- [ ]`\n4. Group related items in phases\n5. Include all quality gates\n\n**Example custom template:**\n\n```markdown\n### Phase 1: API Design\n- [ ] Define API endpoints\n- [ ] Document request/response formats\n- [ ] Choose authentication method\n- [ ] Plan rate limiting strategy\n\n### Phase 2: Implementation (TDD)\n- [ ] Write API endpoint tests\n- [ ] Implement endpoints\n- [ ] Add validation middleware\n- [ ] Add error handling\n\n### Phase 3: Integration\n- [ ] Test with client application\n- [ ] Update API documentation\n- [ ] Add usage examples\n- [ ] Deploy to staging\n```\n\n### Template Variables\n\nTemplates can include placeholders:\n\n```markdown\n- [ ] Review {module_name} module\n- [ ] Test {function_name} with various inputs\n- [ ] Update {doc_file} documentation\n```\n\nSkill will replace these based on task description analysis.\n\n## Output Format\n\nAfter applying template:\n\n```markdown\n## Session Template Applied: Feature Development\n\n**Template:** feature.md\n**Task:** Add OAuth2 authentication\n**Items Added:** 28\n\n### Plan Structure:\n- Phase 1: Research & Design (5 items)\n- Phase 2: Write Tests (5 items)\n- Phase 3: Implementation (5 items)\n- Phase 4: Refactoring (5 items)\n- Phase 5: Quality Check (4 items)\n- Phase 6: Documentation (3 items)\n- Phase 7: Final Review (5 items)\n\n### Customizations Applied:\n- Replaced \"Review related code\" → \"Review existing authentication for OAuth2\"\n- Added \"Research OAuth2 providers (Google, GitHub, Auth0)\"\n- Added \"Test token refresh mechanism\"\n- Removed generic placeholder items\n\n### View Your Plan:\n```bash\nuv run ai-update-plan --show\n```\n\n### Start Working:\nBegin with Phase 1, checking off items as you complete them:\n```bash\nuv run ai-update-plan \"Review existing authentication for OAuth2\"\n```\n\n### Customize Plan:\nAdd task-specific items:\n```bash\nuv run ai-update-plan --add \"Test SSO integration\" --phase \"Phase 2\"\n```\n\nRemove irrelevant items:\n```bash\nuv run ai-update-plan --remove \"Generic item\"\n```\n```\n\n## Best Practices\n\n1. **Apply template early** - Start session with template for comprehensive planning\n2. **Customize immediately** - Adjust generic items to be specific to your task\n3. **Remove irrelevant steps** - Don''t keep items that don''t apply\n4. **Add missing steps** - Template is starting point, not gospel\n5. **Track progress** - Check off items as you complete them\n6. **Update as you learn** - Adjust plan based on discoveries\n\n## Template Selection Guide\n\n**Use \"feature\" when:**\n- Adding new user-facing functionality\n- Building new API endpoints\n- Creating new modules/components\n- Adding new configuration options\n\n**Use \"bugfix\" when:**\n- Fixing reported issues\n- Resolving test failures\n- Addressing regressions\n- Patching security vulnerabilities (minor)\n\n**Use \"refactor\" when:**\n- Improving code structure\n- Reducing complexity\n- Removing duplication\n- Modernizing code patterns\n\n**Use \"documentation\" when:**\n- Updating README\n- Writing API docs\n- Creating usage guides\n- Improving code comments\n\n**Use \"security\" when:**\n- Fixing CVEs\n- Hardening authentication\n- Addressing OWASP issues\n- Implementing security features\n\n## Advanced Features\n\n### Multi-Template Application\n\nFor complex tasks, combine templates:\n\n```bash\n# Security fix that needs refactoring\napply security template\n# Then add refactoring items:\nuv run ai-update-plan --add \"Refactor auth module for clarity\" --phase \"Phase 9\"\n```\n\n### Template Inheritance\n\nCreate specialized templates that extend base templates:\n\n```markdown\n<!-- templates/api-feature.md -->\n<!-- Extends feature.md with API-specific items -->\n\n### Phase 1: API Research & Design\n- [ ] Review related API endpoints\n- [ ] Define OpenAPI/Swagger spec\n- [ ] Plan versioning strategy\n- [ ] Design request/response schemas\n- [ ] Plan rate limiting\n\n[... rest of feature template ...]\n```\n\n### Conditional Sections\n\nTemplates can include conditional guidance:\n\n```markdown\n### Phase X: Database Changes (if applicable)\n- [ ] Design schema changes\n- [ ] Write migration scripts\n- [ ] Test migration rollback\n- [ ] Update ORM models\n\n*Skip this phase if no database changes needed*\n```\n\n## Integration with Other Tools\n\n### With ai-start-task\n\n```bash\n# Start session and apply template atomically\nuv run ai-start-task \"Add OAuth2 authentication\" --template=feature\n```\n\n### With TDD Reviewer\n\nTemplate includes TDD-specific phases:\n- Phase 2: Write Tests (TDD)\n- Phase 5: Quality Check (includes tdd-reviewer)\n\n### With Quality Enforcer\n\nTemplate includes quality gates:\n- Phase 5: Quality Check (make check)\n- Phase 7: Final Review (quality verification)\n\n## Remember\n\nTemplates are **starting points**, not rigid requirements:\n- Customize for your specific task\n- Add missing items unique to your situation\n- Remove items that don''t apply\n- Adjust phases as you learn more\n\nThe goal is **structured flexibility** - enough structure to ensure quality, enough flexibility to adapt to reality.\n"},"lastSynced":"2026-03-08T02:04:05.377Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing efficient project setup and workflow management with quality enforcement and AI-assisted development.","zh":"适用于需要高效项目设置和工作流管理以及质量保证和AI辅助开发的Python开发代理。","ja":"Python開発エージェントが効率的なプロジェクト設定とワークフローマネジメント、および品質保証とAIアシスト開発を必要とする場合に適しています。","ko":"효율적인 프로젝트 설정 및 워크플로우 관리 및 품질 보증 및 AI 지원 개발이 필요한 파이썬 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo de Python que necesitan una configuración de proyecto eficiente y gestión de flujo de trabajo con cumplimiento de calidad y desarrollo asistido por IA.","fr":"Parfait pour les Agents de Développement Python ayant besoin d''une configuration de projet efficace et d''une gestion de workflow avec une application de qualité et un développement assisté par IA.","de":"Perfekt für Python-Entwicklungsagenten, die eine effiziente Projektsetup und Workflownutzung mit Qualitätsdurchsetzung und künstlicher Intelligenzunterstützter Entwicklung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Python que necessitam de configuração de projeto eficiente e gerenciamento de fluxo de trabalho com garantia de qualidade e desenvolvimento assistido por IA.","ru":"Идеально подходит для агентов разработки Python, которым необходима эффективная настройка проекта и управление рабочим процессом с обеспечением качества и разработкой с помощью ИИ.","ar":"مثالي للوكلاء المتقدمين في بايثون الذين يحتاجون إلى إعداد مشروع فعال وإدارة تدفق العمل مع ضمان الجودة والتنمية بمساعدة الذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to utilize comprehensive Copier templates for modern Python projects, featuring extensive tooling, AI-assisted development, and adherence to code conventions and best practices as outlined in README.md, AI_DOCS/project-context.md, AI_DOCS/code-conventions.md, and AI_DOCS/tdd-workflow.md.","zh":"赋予代理使用全面性的Copier模板用于现代Python项目，具有广泛的工具支持、AI辅助开发，以及遵循README.md、AI_DOCS/project-context.md、AI_DOCS/code-conventions.md和AI_DOCS/tdd-workflow.md中概述的代码约定和最佳实践。","ja":"エージェントがREADME.md、AI_DOCS/project-context.md、AI_DOCS/code-conventions.md、AI_DOCS/tdd-workflow.mdに概説されているコード規約とベストプラクティスに従った、現代的なPythonプロジェクト用の包括的なCopierテンプレートを利用できるようにします。広範なツールサポート、AIアシスト開発などを提供します。","ko":"README.md, AI_DOCS/project-context.md, AI_DOCS/code-conventions.md, AI_DOCS/tdd-workflow.md에 설명된 코드 규칙 및 모범 사례를 준수하는 현대적인 파이썬 프로젝트를 위한 포괄적인 Copier 템플릿을 에이전트가 사용할 수 있도록 합니다. 광범위한 툴링, AI 지원 개발 등을 제공합니다.","es":"Habilita a los agentes a utilizar plantillas de Copier integrales para proyectos Python modernos, que presentan una herramienta extensa, un desarrollo asistido por IA y el cumplimiento de las convenciones de código y las mejores prácticas descritas en README.md, AI_DOCS/project-context.md, AI_DOCS/code-conventions.md y AI_DOCS/tdd-workflow.md.","fr":"Permet aux agents d''utiliser des modèles de Copier complets pour les projets Python modernes, présentant une instrumentation extensive, un développement assisté par IA et le respect des conventions de code et des meilleures pratiques décrites dans README.md, AI_DOCS/project-context.md, AI_DOCS/code-conventions.md et AI_DOCS/tdd-workflow.md.","de":"Ermöglicht es Agenten, umfassende Copier-Vorlagen für moderne Python-Projekte zu nutzen, die umfangreiche Werkzeuge, künstlicher Intelligenzunterstützte Entwicklung und die Einhaltung von Codekonventionen und Best Practices wie in README.md, AI_DOCS/project-context.md, AI_DOCS/code-conventions.md und AI_DOCS/tdd-workflow.md beschrieben, aufweisen.","pt":"Habilita os agentes a utilizarem modelos de Copier abrangentes para projetos Python modernos, com ferramentas extensas, desenvolvimento assistido por IA e aderência às convenções de código e às melhores práticas descritas em README.md, AI_DOCS/project-context.md, AI_DOCS/code-conventions.md e AI_DOCS/tdd-workflow.md.","ru":"Позволяет агентам использовать комплексные шаблоны Copier для современных проектов Python, оснащенные обширным инструментарием, разработкой с помощью ИИ и соблюдением кодекса и лучших практик, изложенных в README.md, AI_DOCS/project-context.md, AI_DOCS/code-conventions.md и AI_DOCS/tdd-workflow.md.","ar":"تمكّن الوكلاء من استخدام نماذج Copier الشاملة لمشاريع بايثون الحديثة، مع أدوات شاملة وتنمية مدعومة بالذكاء الاصطناعي والامتثال للاتفاقيات والأفضل الممارسات الموضحة في README.md، AI_DOCS/project-context.md، AI_DOCS/code-conventions.md، AI_DOCS/tdd-workflow.md."},"useCases":{"en":["Automating project setup with quality enforcement","Generating projects with AI-assisted development tools","Enforcing code style and formatting conventions","Streamlining TDD workflow and testing standards"],"zh":["使用质量保证自动设置项目","使用AI辅助开发工具生成项目","强制执行代码样式和格式约定","简化TDD工作流程和测试标准"],"ja":["品質保証を使用してプロジェクトを自動設定する","AIアシスト開発ツールを使用してプロジェクトを生成する","コードスタイルとフォーマット規約を強制する","TDDワークフローとテスト標準を簡素化する"],"ko":["품질 보증을 사용하여 프로젝트를 자동 설정","AI 지원 개발 도구를 사용하여 프로젝트를 생성","코드 스타일 및 형식 규약을 강제","TDD 워크플로 및 테스트 표준을 간소화"],"es":["Automatización de la configuración del proyecto con cumplimiento de calidad","Generación de proyectos con herramientas de desarrollo asistidas por IA","Aplicación de convenciones de estilo y formato de código","Optimización del flujo de trabajo TDD y los estándares de prueba"],"fr":["Automatisation de la configuration du projet avec application de qualité","Génération de projets avec des outils de développement assistés par IA","Application des conventions de style et de formatage de code","Optimisation du flux de travail TDD et des normes de test"],"de":["Automatisierung der Projektsetup mit Qualitätsdurchsetzung","Erzeugung von Projekten mit künstlicher Intelligenzunterstützten Entwicklungstools","Durchsetzung von Code-Stil- und FormatierungsKonventionen","Optimierung des TDD-Workflows und der Teststandards"],"pt":["Automatizar a configuração do projeto com garantia de qualidade","Gerar projetos com ferramentas de desenvolvimento assistido por IA","Impor convenções de estilo e formatação de código","Otimizar o fluxo de trabalho TDD e os padrões de teste"],"ru":["Автоматизировать настройку проекта с обеспечением качества","Генерировать проекты с инструментами разработки с помощью ИИ","Внедрять конвенции стиля и форматирования кода","Оптимизировать рабочий процесс TDD и стандарты тестирования"],"ar":["تحسين إعداد المشروع تلقائيًا مع ضمان الجودة","توليد المشاريع بأدوات التنمية المدعومة بالذكاء الاصطناعي","فرض اتفاقيات نمط وتشكيل الكود","تحسين سير عمل TDD ومقاييس الاختبار"]},"limitations":{"en":["Requires reading and understanding of project documentation","Python projects only","Mandatory adherence to specified code conventions and workflow"],"zh":["需要阅读和理解项目文档","仅适用于Python项目","必须遵循指定的代码约定和工作流程"],"ja":["プロジェクトドキュメントを読み、理解する必要がある","Pythonプロジェクトのみ","指定されたコード規約とワークフローに必ず従う必要がある"],"ko":["프로젝트 문서를 읽고 이해해야 함","파이썬 프로젝트만 해당","지정된 코드 규칙 및 워크플로우를 반드시 따르야 함"],"es":["Requiere la lectura y comprensión de la documentación del proyecto","Solo proyectos de Python","Cumplimiento obligatorio de las convenciones de código y flujo de trabajo especificadas"],"fr":["Nécessite la lecture et la compréhension de la documentation du projet","Uniquement des projets Python","Respect obligatoire des conventions de code et du flux de travail spécifiés"],"de":["Benötigt das Lesen und Verstehen der Projektdokumentation","Nur Python-Projekte","Verpflichtende Einhaltung der festgelegten Codekonventionen und Workflows"],"pt":["Exige a leitura e a compreensão da documentação do projeto","Apenas projetos Python","Adesão obrigatória às convenções de código e ao fluxo de trabalho especificados"],"ru":["Требует чтения и понимания документации проекта","Только проекты Python","Обязательное соблюдение кодекса и рабочего процесса, указанных в спецификации"],"ar":["يتطلب قراءة وفهم وثائق المشروع","مشاريع بايثون فقط","الامتثال الإلزامي لاتفاقيات الكود والعملية المحددة"]},"version":4},"contentHash":"91629b6339ab042ee7899e558b5b402a52ebd86d8337dbc99b6bc8e7a9332914","qualityScore":60}');
