INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rohunvora/my-claude-skills/html-tools', 'html-tools', 'rohunvora', 'my-claude-skills', 'community', 'html-tools rohunvora my-claude-skills community html-tools enables developers to build single-file applications combining HTML, CSS, and JavaScript for useful functionality without build steps or servers. It''s ideal for client-side data processing, offline tools, and rapid prototyping. HTML工具允许您构建单文件应用，结合HTML、CSS和JavaScript，无需构建步骤、框架或服务器 HTMLツールを使用して、HTML、CSS、JavaScriptを組み合わせた単一ファイルアプリケーションを構築 HTML도구를 사용하여 HTML, CSS, JavaScript를 결합한 단일 파일 응용 프로그램을 구축 Herramientas HTML para crear aplicaciones de un solo archivo con funcionalidades útiles sin compilación ni servidores Outils HTML pour créer des applications en un seul fichier avec des fonctionnalités utiles sans compilation ni serveurs HTML-Tools zum Erstellen von Single-File-Anwendungen mit nützlichen Funktionen ohne Kompilierung oder Server As Ferramentas HTML permitem que os desenvolvedores criem aplicações de arquivo único com funcionalidades úteis sem necessidade de compilação ou servidores Инструменты HTML позволяют разработчикам создавать однофайловые приложения с полезными функциями без необходимости сборки или серверов أدوات HTML تمكن المطورين من إنشاء تطبيقات الملف الواحد بالمواصفات المفيدة دون الحاجة إلى خطوات البناء أو الخوادم how to use html-tools what is html-tools html-tools alternative html-tools vs simon willison html-tools setup guide html-tools install single-file application development client-side data processing tools offline-enabled web applications HTML工具 单文件应用 客户端数据处理 可视化 离线工作 快速原型开发 AIエージェント HTML开发 Combines HTML, CSS, and JavaScript for single-file applications Enables client-side data processing and visualization Supports offline functionality and easy sharing Allows for rapid prototyping and development Eliminates the need for build steps, frameworks, or servers Follows patterns from building 150+ single-file tools html-tools is a technique for building single-file applications that deliver useful functionality without requiring build steps, frameworks, or servers.');
