INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('maslennikov-ig/BuhBot/parse-package-json', 'parse-package-json', 'maslennikov-ig', 'BuhBot', 'community', 'parse-package-json maslennikov-ig BuhBot community The parse-package-json skill extracts structured data from package.json files for version management, dependency auditing, and metadata retrieval, benefiting developers and project managers. parse-package-json 是一个解析包管理数据的工具，用于提取 package.json 文件中的结构化数据 parse-package-json は package.json ファイルから構造化データを抽出するツールです parse-package-json는 패키지 관리 데이터를 분석하여 package.json 파일에서 구조화된 데이터를 추출하는 도구입니다 Parse-package-json es una herramienta para extraer datos estructurados de archivos package.json, ideal para la gestión de versiones y auditorías de dependencias Parse-package-json est un outil pour extraire des données structurées à partir de fichiers package.json, idéal pour la gestion de versions et les audits de dépendances Parse-package-json ist ein Tool zum Extrahieren strukturierter Daten aus package.json-Dateien, ideal für die Versionierung und Abhängigkeitsprüfung O parse-package-json é uma ferramenta para extrair dados estruturados de arquivos package.json, ideal para gerenciamento de versões e auditoria de dependências. ИИ Агент parse-package-json предназначен для извлечения структурированных данных из файлов package.json, подходящий для управления версиями и аудита зависимостей. parse-package-json هو أداة لاستخراج البيانات المهيكلة من ملفات package.json، مثالية لإدارة الإصدارات ومراجعة الإعتماديات. how to use parse-package-json parse-package-json setup guide parse-package-json alternative package.json parsing dependency auditing tools version management best practices parse-package-json install package metadata extraction parse-package-json package.json 解析 版本管理 依赖项审核 元数据检索 AI工具 AIエージェント Extracts current project version for release workflows Generates dependency lists for auditing and security checks Reads package metadata for reporting and analytics Validates package.json structure for error detection and debugging Loads package.json files using the Read tool parse-package-json is a skill that extracts structured data from package.json files for version management, dependency auditing, and metadata retrieval.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('msalganik/torchtune_config_writer/git-commit-push', 'community', 'msalganik', 'torchtune_config_writer', 'msalganik/torchtune_config_writer', 'git-commit-push', 0, 0, 60, '2026-03-08T01:57:15.362Z', '2026-03-08T02:04:17.645Z', '282f102bee5158a3205231ff7763863f94b1eff2d813bba0290a5bff8959baae', '{"id":"msalganik/torchtune_config_writer/git-commit-push","name":"git-commit-push","description":{"en":"The git-commit-push skill provides a structured workflow for committing changes to Git and pushing to GitHub, supporting Conventional Commits and custom formats. It benefits developers by ensuring reviewed changes and proper commit messages.","zh":"git-commit-push AIエージェント提供了结构化的 Git 提交和推送工作流程，确保更改被审查、提交消息有意义并遵循约定","ja":"git-commit-push AIエージェントは、変更をレビューし、コミットメッセージが意味を持ち、規約に従うことを保証する構造化された Git コミットとプッシュのワークフローを提供する","ko":"git-commit-push AI 에이전트는 변경 사항을 검토하고 커밋 메시지가 의미를 가지며 규약을 준수하는 것을 보장하는 구조化된 Git 커밋 및 푸시 워크플로우를 제공","es":"Git-commit-push es una herramienta de Python para commits y pushes automáticos en GitHub, que asegura commits significativos y seguros","fr":"Git-commit-push est un outil Python pour les commits et les pushes automatiques sur GitHub, qui assure des commits significatifs et sécurisés","de":"Git-commit-push ist ein Python-Tool für automatische Commits und Pushes auf GitHub, das sicherstellt, dass Commits bedeutungsvoll und sicher sind","pt":"O git-commit-push é uma ferramenta Python para gerar arquivos de configuração YAML do torchtune de forma programática","ru":"ИИ Агент git-commit-push - это инструмент Python для генерации файлов конфигурации YAML torchtune программно","ar":"أداة git-commit-push هي أداة Python لتوليد ملفات تعريف YAML لبرنامج torchtune بشكل برمجي"},"seo":{"title":{"en":"git-commit-push: Automated Git Workflow Setup Guide | AI ...","zh":"Git Commit 和 Push 设置指南 - AIエージェント","ja":"Git Commit と Push ベストプラクティス - AIエージェント","ko":"Git Commit 및 Push 설정 가이드 - AI 에이전트","es":"Guía de configuración de git-commit-push para desarrollad...","fr":"Configurer git-commit-push: Meilleures pratiques pour les...","de":"Einrichten von git-commit-push: Leitfaden für Entwickler","pt":"Guia de Configuração do git-commit-push para Desenvolvedores","ru":"ИИ Агент git-commit-push: Руководство по Настройке","ar":"إعداد أداة git-commit-push: دليل المطورين"},"description":{"en":"Streamline your Git workflow with git-commit-push. Learn how to automate commits and pushes to GitHub, ensuring meaningful commit messages and secure secret ...","zh":"使用 git-commit-push AIエージェント自动化 Git 提交和推送，确保遵循项目约定和安全标准","ja":"Git Commit と Push を自動化する git-commit-push AIエージェントを使用して、プロジェクトの規約とセキュリティ標準に従う","ko":"git-commit-push AI 에이전트를 사용하여 Git 커밋과 푸시를 자동화하고 프로젝트 규약 및 보안 표준을 준수","es":"Aprende a utilizar git-commit-push para commits y pushes automáticos en GitHub con esta herramienta de Python","fr":"Découvrez comment utiliser git-commit-push pour des commits et des pushes automatiques sur GitHub avec cet outil Python","de":"Erfahren Sie, wie Sie git-commit-push für automatische Commits und Pushes auf GitHub mit diesem Python-Tool verwenden","pt":"Aprenda a configurar o git-commit-push para melhorar o fluxo de trabalho de commit e push no GitHub","ru":"Настройте ИИ Агент git-commit-push для автоматизации процесса коммита и пуша в GitHub","ar":"تعرف على كيفية إعداد أداة git-commit-push لتحسين تدفق العمل في GitHub"},"definition":{"en":"git-commit-push is a Python tool that automates Git workflow, generating torchtune YAML configuration files and ensuring secure and meaningful commits and pushes to remote repositories.","zh":"git-commit-push 是一个 AIエージェント，用于自动化 Git 提交和推送，确保遵循项目约定和安全标准","ja":"git-commit-push は、Git コミットとプッシュを自動化する AIエージェントで、プロジェクトの規約とセキュリティ標準に従う","ko":"git-commit-push는 Git 커밋과 푸시를 자동화하는 AI 에이전트로, 프로젝트 규약 및 보안 표준을 준수","es":"Git-commit-push es una herramienta de Python que automatiza commits y pushes en GitHub","fr":"Git-commit-push est un outil Python qui automatise les commits et les pushes sur GitHub","de":"Git-commit-push ist ein Python-Tool, das Commits und Pushes auf GitHub automatisiert","pt":"O que é git-commit-push? É uma ferramenta para automatizar o processo de commit e push no GitHub","ru":"Что такое ИИ Агент git-commit-push? Это инструмент для автоматизации процесса коммита и пуша в GitHub","ar":"ما هي أداة git-commit-push؟ هي أداة لتحسين عملية الالتزام و الدفع في GitHub"},"features":{"en":["Automates Git commits and pushes to GitHub","Supports Conventional Commits and custom formats","Ensures meaningful commit messages and reviewed changes","Handles secrets securely to prevent accidental commits","Adapts to project conventions for seamless integration","Executes immediately using contextual autonomy for safe workflow"],"zh":["自动化 Git 提交和推送","支持 Conventional Commits 和自定义格式","确保提交消息有意义并遵循约定","防止秘密被提交","适应项目约定"],"ja":["Git コミットとプッシュの自動化","Conventional Commits とカスタム形式のサポート","コミットメッセージが意味を持ち、規約に従うことを保証","秘密のコミットを防止","プロジェクトの規約に適応"],"ko":["Git 커밋과 푸시 자동화","Conventional Commits 및 사용자 정의 형식 지원","커밋 메시지가 의미를 가지며 규약을 준수하는 것을 보장","비밀 커밋 방지","프로젝트 규약에 적응"],"es":["Soporte para Conventional Commits y formatos personalizados","Revisión de cambios antes de commits","Mensajes de commit significativos y seguros","Compatibilidad con secretos y datos confidenciales","Integración con GitHub para pushes automáticos"],"fr":["Prise en charge de Conventional Commits et de formats personnalisés","Révision des modifications avant les commits","Messages de commit significatifs et sécurisés","Compatibilité avec les secrets et les données confidentielles","Intégration avec GitHub pour les pushes automatiques"],"de":["Unterstützung für Conventional Commits und benutzerdefinierte Formate","Überprüfung von Änderungen vor Commits","Bedeutungsvolle und sichere Commit-Mitteilungen","Kompatibilität mit Geheimnissen und vertraulichen Daten","Integration mit GitHub für automatische Pushes"],"pt":["Geração de arquivos de configuração YAML do torchtune","Suporte a Conventional Commits e formatos personalizados","Execução imediata com autonomia contextual","Integração com o GitHub para push de commits","Suporte à revisão de alterações e mensagens de commit significativas"],"ru":["Генерация файлов конфигурации YAML torchtune","Поддержка Conventional Commits и пользовательских форматов","Немедленная执行 с контекстной автономией","Интеграция с GitHub для пуша коммитов","Поддержка проверки изменений и осмысленных сообщений о коммитах"],"ar":["توليد ملفات تعريف YAML لبرنامج torchtune","دعم الالتزامات التقليدية والأشكال المخصصة","تنفيذ فوري مع استقلالية سياقية","التكامل مع GitHub لدفع الالتزامات","دعم مراجعة التغييرات ورسائل الالتزام المعنية"]},"keywords":{"en":["how to use git-commit-push","git-commit-push setup guide","git-commit-push alternative","git-commit-push vs Git Flow","git-commit-push install","automated Git workflow","Conventional Commits","Git commit message conventions","GitHub workflow automation"],"zh":["Git Commit","Git Push","AIエージェント","自动化","项目约定","安全标准","Conventional Commits","自定义格式"],"ja":["Git コミット","Git プッシュ","AIエージェント","自動化","プロジェクトの規約","セキュリティ標準","Conventional Commits","カスタム形式"],"ko":["Git 커밋","Git 푸시","AI 에이전트","자동화","프로젝트 규약","보안 표준","Conventional Commits","사용자 정의 형식"],"es":["git-commit-push","herramienta de Python para GitHub","commits automáticos","pushes automáticos","Conventional Commits","seguridad de commits","integración con GitHub","desarrollo de software","herramientas de desarrollo"],"fr":["git-commit-push","outil Python pour GitHub","commits automatiques","pushes automatiques","Conventional Commits","sécurité des commits","intégration avec GitHub","développement de logiciels","outils de développement"],"de":["git-commit-push","Python-Tool für GitHub","automatische Commits","automatische Pushes","Conventional Commits","Sicherheit von Commits","Integration mit GitHub","Software-Entwicklung","Entwicklertools"],"pt":["git-commit-push","torchtune","ferramenta python","geração de arquivos yaml","conventional commits","github","autonomia contextual","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ИИ Агент git-commit-push","torchtune","инструмент Python","генерация файлов yaml","Conventional Commits","GitHub","контекстная автономия","разработка программного обеспечения","инструменты разработки"],"ar":["أداة git-commit-push","torchtune","أداة python","توليد ملفات yaml","الالتزامات التقليدية","github","استقلالية سياقية","تطوير البرمجيات","أدوات التطوير"]}},"owner":"msalganik","repo":"torchtune_config_writer","repoPath":"msalganik/torchtune_config_writer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.362Z","topics":[],"category":"community","skillMd":{"name":"git-commit-push","description":"This skill should be used when the user wants to commit their work to git and push to GitHub. It guides through reviewing changes, crafting meaningful commit messages following project conventions (including Conventional Commits when detected), creating commits with security checks, and pushing to remote repositories.","bodyPreview":"# Git Commit and Push\n\n## Overview\n\nThis skill provides a structured workflow for committing changes to git and pushing to GitHub. It ensures changes are reviewed, commit messages are meaningful and follow conventions, secrets are not committed, and commits are properly pushed to remote repositories. The skill adapts to project conventions, supporting both Conventional Commits and custom formats.\n\n**Execution Philosophy**: This skill uses **contextual autonomy** - it executes immediately for saf","body":"# Git Commit and Push\n\n## Overview\n\nThis skill provides a structured workflow for committing changes to git and pushing to GitHub. It ensures changes are reviewed, commit messages are meaningful and follow conventions, secrets are not committed, and commits are properly pushed to remote repositories. The skill adapts to project conventions, supporting both Conventional Commits and custom formats.\n\n**Execution Philosophy**: This skill uses **contextual autonomy** - it executes immediately for safe, straightforward commits, but asks for confirmation when changes are large, complex, or potentially risky. This balances speed with safety.\n\n## When to Use This Skill\n\nUse this skill when the user:\n- Explicitly requests to \"commit my work\" or \"push to GitHub\"\n- Says they want to save/commit/push their changes\n- Asks to create a commit or push code\n- Wants to share their work on GitHub\n\n## Workflow\n\n### Step 1: Review Changes\n\nBefore committing, review what has changed:\n\n1. **Check git status** to see modified, new, and deleted files:\n   ```bash\n   git status\n   ```\n\n2. **Analyze diff systematically**:\n   ```bash\n   git diff --stat  # Overview of changes\n   git diff         # Detailed line-by-line changes\n   ```\n\n3. **Categorize changes** to inform commit message:\n   - **New features**: New files, new functions, new capabilities\n   - **Bug fixes**: Modified logic, error handling improvements\n   - **Refactoring**: Structure changes with no behavior change\n   - **Documentation**: *.md files, code comments, docstrings\n   - **Tests**: Test files, test additions/modifications\n   - **Configuration**: Build files, dependencies, settings\n   - **Styling**: Formatting, whitespace, code style only\n\n4. **Check recent commits** to understand commit message style:\n   ```bash\n   git log --oneline -20\n   ```\n\n5. **Present summary** to the user:\n   - List all modified, new, and deleted files\n   - Highlight key changes by category\n   - Note total lines added/removed\n   - Flag any unusual patterns (large files, many deletions, etc.)\n\n### Step 2: Detect Project Convention\n\nDetermine if project uses Conventional Commits or custom format:\n\n1. **Check for Conventional Commits pattern**:\n   ```bash\n   # Look for type(scope): format in recent commits\n   git log --oneline -20 | grep -E \"^[a-f0-9]+ (feat|fix|docs|style|refactor|test|chore|perf|ci|build|revert)(\\(.+\\))?:\"\n   ```\n\n2. **Analyze result**:\n   - If ≥50% of commits match pattern → Project uses Conventional Commits\n   - Otherwise → Project uses custom format\n\n3. **Note the convention** for commit message crafting\n\n### Step 3: Craft Commit Message\n\nCreate a meaningful commit message following detected convention:\n\n#### If Conventional Commits Detected\n\nUse format: `type(scope): description`\n\n**Common types**:\n- `feat`: New feature or capability\n- `fix`: Bug fix\n- `docs`: Documentation changes only\n- `style`: Code style/formatting (no logic change)\n- `refactor`: Code restructuring (no behavior change)\n- `test`: Adding or modifying tests\n- `chore`: Maintenance, dependencies, build\n- `perf`: Performance improvements\n- `ci`: CI/CD pipeline changes\n- `build`: Build system or external dependencies\n\n**Optional scope**: Component or module affected (e.g., `auth`, `api`, `ui`)\n\n**Format**:\n```\ntype(scope): imperative summary (max 50 chars)\n\nOptional body explaining the change in detail.\nExplain WHY, not WHAT (the diff shows what).\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nCo-Authored-By: Claude <noreply@anthropic.com>\n```\n\n**Example**:\n```\nfeat(evaluation): add Inspect AI integration to experiment framework\n\nImplements Phase 4 evaluation support with:\n- User-written evaluation tasks workflow\n- Adapter-only checkpointing (200x storage reduction)\n- Complete working examples and documentation\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nCo-Authored-By: Claude <noreply@anthropic.com>\n```\n\n#### If Custom Format Detected\n\nMatch the project''s existing style:\n\n1. **Summarize changes** in 1-2 sentences (imperative, present tense)\n2. **Focus on \"why\"** rather than \"what\" (diff shows what changed)\n3. **Follow observed conventions** (capitalization, punctuation, length)\n4. **Keep concise** but informative\n\n**Format**:\n```\nSummary line (imperative mood, present tense)\n\nOptional detailed explanation of the changes.\nFocus on motivation and context.\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nCo-Authored-By: Claude <noreply@anthropic.com>\n```\n\n**Example**:\n```\nAdd evaluation configuration to experiment definition framework\n\nImplements Inspect AI integration, adapter-only checkpointing support,\nand complete working examples for Phase 4 implementation.\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nCo-Authored-By: Claude <noreply@anthropic.com>\n```\n\n### Step 4: Assess Commit Risk\n\nDetermine whether this commit is \"safe\" (autonomous) or \"risky\" (requires confirmation):\n\n**Safe commits** (execute autonomously):\n- ≤ 5 files changed\n- ≤ 500 total lines changed\n- Not committing to main/master branch\n- All changes are related (same category from Step 1)\n- No unusual patterns (massive deletions, binary files, etc.)\n- User specified which files to commit\n\n**Risky commits** (require confirmation):\n- > 5 files changed\n- > 500 total lines changed\n- Committing to main/master branch\n- Mixed change types (features + fixes + refactoring)\n- Many untracked files (unclear what to commit)\n- Large files (> 100KB)\n- Unusual patterns detected\n\n**If risky**, show summary and ask user:\n```\n⚠️ Large/complex commit detected\n\nFiles: 15 files changed (+2,500 lines, -300 lines)\nTypes: Features (8 files), Documentation (5 files), Tests (2 files)\nBranch: main\nMessage: \"Add evaluation configuration and examples\"\n\nThis appears to contain multiple logical changes.\nOptions:\n  [Y] Proceed with single commit\n  [n] Cancel (I''ll help you split it)\n  [s] Show detailed file list\n```\n\n**If safe**, proceed autonomously to Step 5.\n\n### Step 5: Check for Secrets\n\nBefore staging, scan for sensitive information:\n\n1. **Check unstaged changes for secret patterns**:\n   ```bash\n   git diff | grep -E \"(api[_-]?key|api[_-]?secret|password|token|secret[_-]?key|private[_-]?key|aws[_-]?access)\" -i\n   ```\n\n2. **Check for specific patterns**:\n   - AWS Access Keys: `AKIA[0-9A-Z]{16}`\n   - Generic API keys: `[a-zA-Z0-9_-]{32,}`\n   - Private keys: `-----BEGIN.*PRIVATE KEY-----`\n   - GitHub tokens: `ghp_`, `gho_`, `ghs_`, `ghr_`\n   - Bearer tokens: `Bearer [a-zA-Z0-9._-]+`\n   - Passwords in configs: `password\\s*[:=]\\s*[\"'']?[^\"''\\s]+`\n\n3. **Check for sensitive files**:\n   ```bash\n   git status --short | grep -E \"\\.env|credentials|secrets|\\.pem|\\.key|\\.p12\"\n   ```\n\n4. **If secrets detected**:\n   - ❌ **STOP immediately**\n   - Show user the matched patterns (without revealing full values)\n   - Explain the risk\n   - Ask user to:\n     - Remove secrets from code\n     - Use environment variables or secret management\n     - Add file to `.gitignore` if appropriate\n   - **Do not proceed** until secrets are removed\n\n5. **If no secrets detected**:\n   - ✅ Proceed to staging\n\n### Step 6: Stage and Commit Changes\n\n1. **Stage relevant files**:\n   ```bash\n   git add <file1> <file2> ...\n   ```\n\n   **Staging guidelines**:\n   - Stage files related to this logical change\n   - Do NOT stage unrelated changes (save for separate commit)\n   - Determine files to stage based on change analysis from Step 1\n   - **If autonomous**: Announce which files are being staged\n   - **If confirmed**: User already saw file list in confirmation\n\n2. **Verify staged changes**:\n   ```bash\n   git diff --staged --stat\n   ```\n\n3. **Announce or show commit message**:\n   - **If autonomous**: Announce message briefly (\"Committing: ''Add feature X''\")\n   - **If confirmed**: User already saw message in confirmation\n\n4. **Create commit** with formatted message:\n   ```bash\n   git commit -m \"$(cat <<''EOF''\n   <commit message here>\n\n   🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\n   Co-Authored-By: Claude <noreply@anthropic.com>\n   EOF\n   )\"\n   ```\n\n5. **Verify commit** was created:\n   ```bash\n   git log -1 --stat\n   ```\n\n### Step 7: Push to Remote\n\n1. **Check remote status**:\n   ```bash\n   git status  # Check if branch tracks remote\n   ```\n\n2. **Push to GitHub**:\n   ```bash\n   # If branch already tracks remote\n   git push\n\n   # If new branch (first push)\n   git push -u origin <branch-name>\n   ```\n\n3. **Confirm success**:\n   - Report push result to user\n   - Show number of commits pushed\n   - Provide remote URL if available\n   - Note any warnings or issues\n\n## Important Guidelines\n\n### Safety Rules\n\n- **Never push force** to main/master without explicit user confirmation\n- **Never skip hooks** (--no-verify) unless explicitly requested by user\n- **Never commit secrets** - stop and warn user if detected\n- **Check authorship** before amending commits (don''t amend others'' work)\n- **Check for large files** - warn if files > 100KB (may need Git LFS)\n- **Always verify** what''s being committed before executing\n\n### Best Practices\n\n1. **Review before committing** - show user what will be committed\n2. **Meaningful messages** - explain why changes were made, not just what\n3. **Atomic commits** - each commit should be a single logical change\n4. **Follow conventions** - detect and match project''s commit style\n5. **Add co-author attribution** - include Claude Code footer\n6. **Keep commits focused** - don''t mix refactoring with features\n\n### Commit Scope Guidelines\n\n**Good commit scope**:\n- ✅ One logical change per commit\n- ✅ Related files together (e.g., code + corresponding test)\n- ✅ Can be described in one sentence\n- ✅ Typically < 500 lines (unless it''s a rename/refactor)\n- ✅ All changes serve the same purpose\n\n**Signs to split commits**:\n- ❌ Using \"and\" more than once in commit message\n- ❌ Changes span multiple unrelated features\n- ❌ Mix of bug fixes and new features\n- ❌ Experimental changes alongside production code\n- ❌ \"WIP\", \"misc fixes\", or \"various updates\" messages\n\n**When to split**:\n```bash\n# If you have unrelated changes, stage selectively:\ngit add -p  # Interactively choose hunks to stage\n\n# Or stage specific files:\ngit add file1.py file1_test.py  # First commit: feature A\ngit commit -m \"feat: add feature A\"\n\ngit add file2.py file2_test.py  # Second commit: feature B\ngit commit -m \"feat: add feature B\"\n```\n\n### Error Handling\n\n**If commit fails**:\n- Check for pre-commit hooks modifying files\n- Review error message carefully\n- May need to stage hook-modified files and amend\n- Only amend if: (1) user requested it OR (2) fixing pre-commit hook changes AND it''s safe (check authorship, not pushed)\n\n**If secrets detected**:\n- Stop immediately, do not commit\n- Explain which patterns matched\n- Guide user to remove secrets\n- Suggest using environment variables or secret management\n- Consider adding `.gitignore` entries\n\n**If push fails**:\n- Check remote branch status (might need pull first)\n- Check for merge conflicts\n- Verify remote URL is correct\n- Check authentication/permissions\n- Report error to user with suggested fixes\n\n**If large files detected**:\n- Warn user about file sizes\n- Suggest Git LFS for files > 100KB\n- Ask if files should be committed or added to `.gitignore`\n\n## Example Interaction\n\n### Example 1: Conventional Commits Project\n\n**User**: \"I''d like to commit my work and push to GitHub\"\n\n**Assistant**:\n1. Runs `git status` and `git diff --stat`\n2. Analyzes: \"2 files changed (+1,269 lines)\"\n3. Categorizes: \"New feature (eval config), documentation\"\n4. Risk assessment: ✅ Safe (2 files, 1,269 lines, feature branch)\n5. Checks convention: Detects Conventional Commits (15/20 matches)\n6. Scans for secrets: ✅ None detected\n7. Announces: \"Committing: `feat(evaluation): add Inspect AI integration`\"\n8. Executes: `git add`, `git commit`, `git push`\n9. Reports: \"✓ Committed 795efaf and pushed to GitHub\"\n\n### Example 2: Large Commit Requiring Confirmation\n\n**User**: \"commit my changes\"\n\n**Assistant**:\n1. Analyzes: \"15 files changed (+2,847 lines, -156 lines)\"\n2. Categorizes: \"Features (8 files), docs (5 files), tests (2 files)\"\n3. Risk assessment: ⚠️ **Risky** (>5 files, >500 lines, mixed types)\n4. Scans for secrets: ✅ None detected\n5. Shows confirmation:\n   ```\n   ⚠️ Large commit with mixed changes detected\n\n   Files: 15 (+2,847 lines, -156 lines)\n   Categories: Features (8), Documentation (5), Tests (2)\n   Message: \"Add evaluation framework with examples and tests\"\n\n   Consider splitting into:\n   - Commit 1: Core evaluation framework (8 files)\n   - Commit 2: Documentation (5 files)\n   - Commit 3: Tests (2 files)\n\n   Proceed with single commit? [Y/n/split]\n   ```\n6. **Waits** for user response\n\n### Example 3: Secrets Detected (Always Blocks)\n\n**User**: \"commit my changes\"\n\n**Assistant**:\n1. Reviews changes: Modified config.py (+10 lines)\n2. Scans for secrets: ❌ **FOUND** pattern matching API key\n3. **STOPS**: \"⚠️ Security Warning: Detected potential API key in config.py\"\n4. Shows matched line: `api_key = \"sk_live_...\"`\n5. Advises: \"Please use environment variables instead: `api_key = os.getenv(''API_KEY'')`\"\n6. **Does not proceed** until user confirms secrets are removed\n\n## Notes\n\n- This skill follows the git safety protocol from the Bash tool documentation\n- Commit message format includes Claude Code attribution as per project conventions\n- Always run commands sequentially (staging, committing, pushing) not in parallel\n- Adapts to project conventions rather than enforcing a single standard\n- Uses **contextual autonomy**: executes immediately for safe commits, confirms for risky ones\n- Security checks are non-negotiable - always blocks on secrets\n- Thresholds: Safe ≤ 5 files, ≤ 500 lines, not main/master, single change type\n\n## References\n\n- [Conventional Commits Specification](https://www.conventionalcommits.org/)\n- [Git Commit Best Practices](https://cbea.ms/git-commit/)\n- [Pre-commit Framework](https://pre-commit.com/)\n- [Git Hooks Documentation](https://git-scm.com/docs/githooks)\n"},"lastSynced":"2026-03-08T02:04:17.645Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated Git workflows and Conventional Commits support.","zh":"适用于需要自动化 Git 工作流和 Conventional Commits 支持的开发代理。","ja":"Development Agent が自動化された Git ワークフローと Conventional Commits サポートを必要とする場合に最適です。","ko":"자동화된 Git 워크플로와 Conventional Commits 지원이 필요한 개발 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren flujos de trabajo de Git automatizados y soporte para Commits Convencionales.","fr":"Idéal pour les agents de développement nécessitant des flux de travail Git automatisés et une prise en charge des Commits Conventionnels.","de":"Ideal für Entwicklungssagenten, die automatisierte Git-Workflows und Unterstützung für Conventional Commits erfordern.","pt":"Ideal para Agentes de Desenvolvimento que requerem fluxos de trabalho automatizados do Git e suporte a Commits Convencionais.","ru":"Идеально подходит для агентов разработки, требующих автоматизированных рабочих процессов Git и поддержки Конвенциональных коммитов.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى سير عمل آلي في Git ودعم Commits التقليدية."},"recommendation":{"en":"Empowers agents to manage Git repositories efficiently, ensuring reviewed changes, meaningful commit messages, and secure pushing to GitHub using Conventional Commits and custom formats, while preventing secrets from being committed.","zh":"赋予代理管理 Git 仓库的能力，确保审查的更改、有意义的提交消息和使用 Conventional Commits 和自定义格式安全地推送到 GitHub，同时防止提交机密信息。","ja":"エージェントが Git リポジトリを効率的に管理できるようにし、レビューされた変更、意味のあるコミット メッセージ、Conventional Commits およびカスタム形式を使用して GitHub に安全にプッシュし、シークレットをコミットしないようにします。","ko":"에이전트가 Git 리포지토리를 효율적으로 관리할 수 있도록 하며, 검토된 변경 사항, 의미 있는 커밋 메시지 및 Conventional Commits와 사용자 지정 형식을 사용하여 GitHub에 안전하게 푸시하고, 비밀을 커밋하지 않도록 합니다.","es":"Permite a los agentes gestionar repositorios Git de manera eficiente, garantizando cambios revisados, mensajes de confirmación significativos y un envío seguro a GitHub utilizando Commits Convencionales y formatos personalizados, al mismo tiempo que evita que los secretos se confirmen.","fr":"Permet aux agents de gérer les référentiels Git de manière efficace, en garantissant des modifications examinées, des messages de validation significatifs et un pushing sécurisé vers GitHub en utilisant des Commits Conventionnels et des formats personnalisés, tout en empêchant les secrets d''être validés.","de":"Ermächtigt Agenten, Git-Repositorys effizient zu verwalten, indem sie überprüfte Änderungen, sinnvolle Commit-Nachrichten und sicheres Pushen zu GitHub mithilfe von Conventional Commits und benutzerdefinierten Formaten sicherstellen, während sie verhindern, dass Geheimnisse committet werden.","pt":"Habilita os agentes a gerenciar repositórios Git de forma eficiente, garantindo alterações revisadas, mensagens de commit significativas e envio seguro para o GitHub usando Commits Convencionais e formatos personalizados, enquanto impede que segredos sejam comprometidos.","ru":"Наделяет агентов возможностью эффективно управлять репозиториями Git, обеспечивая проверенные изменения, осмысленные сообщения коммитов и безопасную передачу в GitHub с использованием Конвенциональных коммитов и пользовательских форматов, а также предотвращая фиксацию секретов.","ar":"تمكّن الوكلاء من إدارة مستودعات Git بفعالية، مما يضمن مراجعة التغييرات ورسائل Commit ذات المعنى وإرسال آمن إلى GitHub باستخدام Commits التقليدية والتنسيقات المخصصة، مع منع تقديم الأسرار."},"useCases":{"en":["Automating commit and push processes for streamlined development","Enforcing Conventional Commits for consistent version control","Validating commit messages for adherence to project conventions"],"zh":["为流畅的开发自动化提交和推送过程","强制使用 Conventional Commits 进行一致的版本控制","验证提交消息以遵守项目约定"],"ja":["スムーズな開発のためのコミットとプッシュの自動化","一貫性のあるバージョン管理のための Conventional Commits の適用","プロジェクトの規約に従ったコミット メッセージの検証"],"ko":["원활한 개발을 위한 커밋 및 푸시 자동화","일관된 버전 관리를 위한 Conventional Commits 적용","프로젝트 규약을 준수한 커밋 메시지의 검증"],"es":["Automatizar procesos de confirmación y envío para un desarrollo optimizado","Aplicar Commits Convencionales para un control de versiones coherente","Validar mensajes de confirmación para garantizar el cumplimiento de las convenciones del proyecto"],"fr":["Automatiser les processus de validation et de pushing pour un développement rationalisé","Mettre en œuvre des Commits Conventionnels pour un contrôle de version cohérent","Valider les messages de validation pour garantir le respect des conventions du projet"],"de":["Automatisieren von Commit- und Push-Prozessen für eine optimierte Entwicklung","Durchsetzen von Conventional Commits für eine konsistente Versionskontrolle","Validieren von Commit-Nachrichten für die Einhaltung der Projektkonventionen"],"pt":["Automatizar processos de commit e push para desenvolvimento simplificado","Impor Commits Convencionais para controle de versão consistente","Validar mensagens de commit para aderência às convenções do projeto"],"ru":["Автоматизировать процессы коммита и пуша для упрощенного развития","Внедрять Конвенциональные коммиты для последовательного контроля версий","Проверять сообщения коммитов на соответствие проектным конвенциям"],"ar":["تشغيل تلقائي لعملية Commit و Push من أجل تطور مبسط","فرض Commits التقليدية من أجل ضبط إصدارات ثابت","التحقق من رسائل Commit لموافقتها على اتفاقيات المشروع"]},"limitations":{"en":["Requires Git installation and configuration","Needs access to GitHub for remote repository interactions","Adheres to specific commit message formats, potentially limiting flexibility"],"zh":["需要 Git 安装和配置","需要访问 GitHub 进行远程仓库交互","遵守特定的提交消息格式，可能会限制灵活性"],"ja":["Git のインストールと構成が必要","リモート リポジトリのやり取りのために GitHub へのアクセスが必要","特定のコミット メッセージ形式に従うため、柔軟性が制限される可能性がある"],"ko":["Git 설치 및 구성이 필요함","원격 리포지토리 상호 작용을 위해 GitHub에 접근할 수 있어야 함","특정 커밋 메시지 형식을 따르므로 유연성이 제한될 수 있음"],"es":["Requiere instalación y configuración de Git","Necesita acceso a GitHub para interacciones con el repositorio remoto","Se adhiere a formatos de mensaje de confirmación específicos, lo que podría limitar la flexibilidad"],"fr":["Nécessite l''installation et la configuration de Git","A besoin d''un accès à GitHub pour les interactions avec le référentiel distant","Se conforme à des formats de message de validation spécifiques, ce qui pourrait limiter la flexibilité"],"de":["Benötigt Git-Installation und -Konfiguration","Benötigt Zugriff auf GitHub für Interaktionen mit dem Remote-Repository","Befolgt spezifische Commit-Nachrichtenformate, was die Flexibilität möglicherweise einschränken könnte"],"pt":["Requer instalação e configuração do Git","Necessita acesso ao GitHub para interações de repositório remoto","Adere a formatos de mensagem de commit específicos, potencialmente limitando a flexibilidade"],"ru":["Требует установки и конфигурации Git","Требует доступа к GitHub для взаимодействия с удаленными репозиториями","Соблюдает конкретные форматы сообщений коммитов, потенциально ограничивая гибкость"],"ar":["يتطلب تثبيت وضبط Git","يحتاج إلى الوصول إلى GitHub للتفاعل مع المستودعات عن بُعد","يلتزم بتنسيقات رسائل Commit المحددة، مما قد يقيد المرونة"]},"version":4},"contentHash":"282f102bee5158a3205231ff7763863f94b1eff2d813bba0290a5bff8959baae","qualityScore":60}');
