INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('msalganik/torchtune_config_writer/git-commit-push', 'git-commit-push', 'msalganik', 'torchtune_config_writer', 'community', 'git-commit-push msalganik torchtune_config_writer community The git-commit-push skill provides a structured workflow for committing changes to Git and pushing to GitHub, supporting Conventional Commits and custom formats. It benefits developers by ensuring reviewed changes and proper commit messages. git-commit-push AIエージェント提供了结构化的 Git 提交和推送工作流程，确保更改被审查、提交消息有意义并遵循约定 git-commit-push AIエージェントは、変更をレビューし、コミットメッセージが意味を持ち、規約に従うことを保証する構造化された Git コミットとプッシュのワークフローを提供する git-commit-push AI 에이전트는 변경 사항을 검토하고 커밋 메시지가 의미를 가지며 규약을 준수하는 것을 보장하는 구조化된 Git 커밋 및 푸시 워크플로우를 제공 Git-commit-push es una herramienta de Python para commits y pushes automáticos en GitHub, que asegura commits significativos y seguros Git-commit-push est un outil Python pour les commits et les pushes automatiques sur GitHub, qui assure des commits significatifs et sécurisés Git-commit-push ist ein Python-Tool für automatische Commits und Pushes auf GitHub, das sicherstellt, dass Commits bedeutungsvoll und sicher sind O git-commit-push é uma ferramenta Python para gerar arquivos de configuração YAML do torchtune de forma programática ИИ Агент git-commit-push - это инструмент Python для генерации файлов конфигурации YAML torchtune программно أداة git-commit-push هي أداة Python لتوليد ملفات تعريف YAML لبرنامج torchtune بشكل برمجي how to use git-commit-push git-commit-push setup guide git-commit-push alternative git-commit-push vs Git Flow git-commit-push install automated Git workflow Conventional Commits Git commit message conventions GitHub workflow automation Git Commit Git Push AIエージェント 自动化 项目约定 安全标准 Conventional Commits 自定义格式 Automates Git commits and pushes to GitHub Supports Conventional Commits and custom formats Ensures meaningful commit messages and reviewed changes Handles secrets securely to prevent accidental commits Adapts to project conventions for seamless integration Executes immediately using contextual autonomy for safe workflow git-commit-push is a Python tool that automates Git workflow, generating torchtune YAML configuration files and ensuring secure and meaningful commits and pushes to remote repositories.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dojoengine/torii/create-a-plan', 'community', 'dojoengine', 'torii', 'dojoengine/torii', 'create-a-plan', 0, 0, 60, '2026-03-08T01:57:15.365Z', '2026-03-08T02:04:20.960Z', '76755dca1a8ade8c8e895de1efdf62f805b008bf3c8a9c427ad3a6c8bb1c1ddd', '{"id":"dojoengine/torii/create-a-plan","name":"create-a-plan","description":{"en":"The create-a-plan skill runs a structured technical interview to turn ideas into implementable plans, benefiting developers and project managers. It outputs organized plans for parallel execution.","zh":"create-a-plan技能运行结构化技术访谈，生成详细的可实施计划，输出组织用于并行执行","ja":"create-a-planスキルは、構造化された技術面接を実行して、詳細な実施可能な計画を生成し、出力を並列実行のために組織する","ko":"create-a-plan 스킬은 구조화된 기술 면접을 실행하여 상세한 실행 가능한 계획을 생성하고, 출력을 병렬 실행을 위해 조직","es":"Create a Plan es una habilidad que ejecuta una entrevista técnica estructurada para convertir ideas o especificaciones en planes detallados y ejecutables para Dojo","fr":"Create a Plan est une compétence qui exécute un entretien technique structuré pour transformer les idées ou les spécifications en plans détaillés et exécutables pour Dojo","de":"Create a Plan ist eine Fähigkeit, die ein strukturiertes technisches Interview durchführt, um Ideen oder Spezifikationen in detaillierte und ausführbare Pläne für Dojo umzuwandeln","pt":"O Create-a-Plan é uma ferramenta de indexação automática para Dojo que transforma ideias em planos detalhados e implementáveis","ru":"Create-a-Plan - это ИИ Агент для автоматической индексации Dojo, который превращает идеи в подробные и реализуемые планы","ar":"Create-a-Plan هو أداة الفهرسة الآلية للدوجو التي تحول الأفكار في خطط مفصلة وقابلة للتنفيذ"},"seo":{"title":{"en":"create-a-plan: Structured Technical Interview Setup Guide...","zh":"创建计划技能：AI工具自动化计划生成","ja":"create-a-planスキル：AIエージェントによる詳細計画作成","ko":"create-a-plan 스킬: AI 도구로 자동화된 계획 생성","es":"Guía de conf