INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Diogenesoftoronto/chrysalis-forge/building-racket-clis', 'building-racket-clis', 'Diogenesoftoronto', 'chrysalis-forge', 'community', 'building-racket-clis Diogenesoftoronto chrysalis-forge community Building Racket CLIs enables developers to create command-line applications with ease, utilizing racket/cmdline for efficient flag and argument parsing. This skill benefits developers seeking to build robust CLI tools. Racket CLI 应用程序构建技术，包括命令行解析和参数处理 Racket CLI アプリケーションの構築技術，包括コマンドライン解析とパラメータハンドリング Racket CLI 애플리케이션 구축 기술, 명령줄 파싱 및 매개변수 처리 포함 Construye aplicaciones CLI de Racket con el módulo racket/cmdline para el análisis de comandos y banderas Créez des applications CLI Racket avec le module racket/cmdline pour l''analyse de commandes et de drapeaux Erstellen Sie Racket-CLI-Anwendungen mit dem Modul racket/cmdline für die Befehlszeilenanalyse und Flaggen Construa aplicações CLI em Racket com facilidade, utilizando a biblioteca racket/cmdline para parsing de linha de comando Создавайте CLI приложения на Racket с легкостью, используя библиотеку racket/cmdline для разбора командной строки ابني تطبيقات واجهة سطر الأوامر Racket بسهولة، باستخدام المكتبة racket/cmdline لتحليل سطر الأوامر how to use building-racket-clis what is building-racket-clis building-racket-clis alternative building-racket-clis vs racket building-racket-clis install building-racket-clis setup guide racket/cmdline tutorial racket cli application development Racket CLI racket/cmdline 命令行解析 参数处理 CLI 应用程序构建 Racket 语言 AIエージェント Utilizes racket/cmdline for command-line flag and argument parsing Supports basic flags and arguments using #:once-each and #:args Enables verbose output with the -v or --verbose flag Allows for custom program names using #:program Processes filenames as arguments Defines output files using make-parameter Building-racket-clis is a skill for constructing command-line interface applications using the Racket programming language and racket/cmdline library.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mashharuki/lify-sample/lifi-dev', 'community', 'mashharuki', 'lify-sample', 'mashharuki/lify-sample', 'lifi-dev', 0, 0, 60, '2026-03-08T01:57:15.370Z', '2026-03-08T02:04:27.051Z', '10dec4ea270fce03826c7108fc6fed87bab969f6933e5c088146d459ef9ce0e6', '{"id":"mashharuki/lify-sample/lifi-dev","name":"lifi-dev","description":{"en":"lifi-dev is a comprehensive toolkit for building cross-chain swap and bridge applications with LI.FI. It benefits developers by providing a range of integration methods, including ready-made UI components and SDKs.","zh":"lifi-dev是一种综合工具包，用于构建跨链交换和桥接应用，支持60+链和800+协议","ja":"lifi-devは、クロスチェーンスワップとブリッジアプリケーションを構築するための包括的なツールキットです。60+のチェーンと800+のプロトコルをサポート","ko":"lifi-dev는 크로스체인 스왑 및 브릿지 애플리케이션을 구축하기 위한 포괄적인 도구 키트입니다. 60+ 체인 및 800+ 프로토콜을 지원","es":"li-fi-dev es un toolkit de desarrollo de cadena cruzada para aplicaciones de intercambio y puente con LI.FI, el protocolo de agregación de DEX y puente líder","fr":"li-fi-dev est un toolkit de développement de pont pour les applications d''échange et de pont avec LI.FI, le protocole d''agrégation de DEX et de pont leader","de":"li-fi-dev ist ein umfassendes Toolkit für Cross-Chain-Swaps und Brücken-Anwendungen mit LI.FI, dem führenden DEX- und Bridge-Aggregationsprotokoll","pt":"O Lifi-Dev é uma ferramenta abrangente para construir aplicações de troca e ponte de cadeias cruzadas com a protocolo de agregação de DEX e ponte líder, suportando 60+ cadeias e 800+ protocolos.","ru":"Lifi-Dev — это комплексный инструмент для создания приложений для перекрестных цепей и мостов с помощью ведущего протокола агрегации DEX и мостов, поддерживающего 60+ цепей и 800+ протоколов.","ar":"Lifi-Dev هو أداة شاملة لإنشاء تطبيقات للتبادل والجسور عبر السلاسل مع بروتوكول التجميع الرائد لDEX والجسور، يدعم 60+ سلاسل و800+ بروتوكول."},"seo":{"title":{"en":"lifi-dev: Cross-Chain Swap Setup Guide | AI Agent Skill","zh":"lifi-dev 集成指南 -跨链交换和桥接应用开发","ja":"lifi-dev セットアップガイド - クロスチェーンスワップとブリッジアプリケーション開発","ko":"lifi-dev 설정 가이드 - 크로스체인 스왑 및 브릿지 애플리케이션 개발","es":"Guía de configuración de li-fi-dev para desarrolladores","fr":"Guide de démarrage rapide pour li-fi-dev","de":"Einrichtungsleitfaden für li-fi-dev-Entwickler","pt":"Guia de Configuração do Lifi-Dev para Desenvolvedores","ru":"Настройка Lifi-Dev: Руководство для Разработчиков ИИ Агентов","ar":"دليل إعداد Lifi-Dev لمنشئي التطبيقات"},"description":{"en":"Unlock seamless cross-chain swaps with lifi-dev. Explore the ultimate toolkit for DEX and bridge aggregation, supporting 60+ chains and 800+ protocols. Get s...","zh":"使用lifi-dev开发跨链交换和桥接应用，支持60+链和800+协议，提供Widget、SDK等集成方法","ja":"lifi-devを使用してクロスチェーンスワップとブリッジアプリケーションを開発し、60+のチェーンと800+のプロトコルをサポート","ko":"lifi-dev를 사용하여 크로스체인 스왑 및 브릿지 애플리케이션을 개발하고 60+ 체인 및 800+ 프로토콜을 지원","es":"Aprende a integrar li-fi-dev en tu aplicación con nuestro toolkit de desarrollo de cadena cruzada","fr":"Découvrez comment intégrer li-fi-dev dans votre application avec notre toolkit de développement de pont","de":"Erfahren Sie, wie Sie li-fi-dev in Ihre Anwendung integrieren können, mit unserem umfassenden Toolkit für Cross-Chain-Swaps und Brücken","pt":"Aprenda a configurar o Lifi-Dev para criar aplicações de troca e ponte de cadeias cruzadas com a protocolo de agregação de DEX e ponte líder","ru":"Узнайте, как настроить Lifi-Dev для создания приложений для перекрестных цепей и мостов с помощью ведущего протокола агрегации DEX и мостов","ar":"تعرف على كيفية إعداد Lifi-Dev لإنشاء تطبيقات للتبادل والجسور عبر السلاسل مع بروتوكول التجميع الرائد لDEX والجسور"},"definition":{"en":"lifi-dev is a development support toolkit for LI.FI, a leading DEX and bridge aggregation protocol.","zh":"lifi-dev是一种用于构建跨链交换和桥接应用的综合工具包","ja":"lifi-devは、クロスチェーンスワップとブリッジアプリケーションを構築するためのツールキット","ko":"lifi-dev는 크로스체인 스왑 및 브릿지 애플리케이션을 구축하기 위한 도구 키트","es":"li-fi-dev es un conjunto de herramientas de desarrollo para crear aplicaciones de intercambio y puente de cadena cruzada con LI.FI","fr":"li-fi-dev est un ensemble d''outils de développement pour créer des applications d''échange et de pont de chaîne croisée avec LI.FI","de":"li-fi-dev ist ein Satz von Entwicklungstools, um Cross-Chain-Swap- und Brücken-Anwendungen mit LI.FI zu erstellen","pt":"O Lifi-Dev é uma ferramenta de desenvolvimento para criar aplicações de troca e ponte de cadeias cruzadas com a protocolo de agregação de DEX e ponte líder.","ru":"Lifi-Dev — это инструмент разработки для создания приложений для перекрестных цепей и мостов с помощью ведущего протокола агрегации DEX и мостов.","ar":"Lifi-Dev هو أداة تطوير لإنشاء تطبيقات للتبادل والجسور عبر السلاسل مع بروتوكول التجميع الرائد لDEX والجسور."},"features":{"en":["Offers three integration methods: Widget, SDK, and custom implementations","Supports 60+ chains and 800+ protocols for cross-chain swaps","Provides a ready-made UI component for quick integration (5 min setup)","Includes a TypeScript/JavaScript SDK for full control over UX","Enables building of bridge applications with LI.FI protocol"],"zh":["支持60+链和800+协议","提供Widget、SDK等集成方法","跨链交换和桥接应用开发","TypeScript/JavaScript支持","前端和后端开发支持"],"ja":["60+のチェーンと800+のプロトコルをサポート","Widget、SDKなどの統合方法を提供","クロスチェーンスワップとブリッジアプリケーション開発","TypeScript/JavaScriptサポート","フロントエンドとバックエンド開発サポート"],"ko":["60+ 체인 및 800+ 프로토콜 지원","Widget, SDK 등의 통합 방법 제공","크로스체인 스왑 및 브릿지 애플리케이션 개발","TypeScript/JavaScript 지원","프론트엔드와 백엔드 개발 지원"],"es":["Integración de LI.FI con 60+ cadenas y 800+ protocolos","Three integration methods: Widget, SDK y Full control over UX","Soporte para TypeScript y JavaScript","Customizable UI component","Full control sobre la experiencia del usuario","Soporte para aplicaciones de frontend y backend"],"fr":["Intégration de LI.FI avec 60+ chaînes et 800+ protocoles","Three methods d''intégration : Widget, SDK et Full control over UX","Prise en charge de TypeScript et JavaScript","Composant UI personnalisable","Contrôle total sur l''expérience utilisateur","Prise en charge des applications frontend et backend"],"de":["Integration von LI.FI mit 60+ Ketten und 800+ Protokollen","Drei Integrationsmethoden: Widget, SDK und Vollkontrolle über die Benutzeroberfläche","Unterstützung für TypeScript und JavaScript","Anpassbares UI-Component","Vollständige Kontrolle über die Benutzeroberfläche","Unterstützung für Frontend- und Backend-Anwendungen"],"pt":["Integração com Widget para UI personalizável","Controle total sobre UX com SDK em TypeScript/JavaScript","Suporte a 60+ cadeias e 800+ protocolos","Desenvolvimento de aplicações de troca e ponte de cadeias cruzadas","Protocolo de agregação de DEX e ponte líder"],"ru":["Интеграция с Widget для настраиваемого UI","Полный контроль над UX с помощью SDK на TypeScript/JavaScript","Поддержка 60+ цепей и 800+ протоколов","Разработка приложений для перекрестных цепей и мостов","Ведущий протокол агрегации DEX и мостов"],"ar":["التكامل مع Widget لوياجه المستخدم المخصصة","التحكم الكامل في UX باستخدام SDK بلغة TypeScript/JavaScript","دعم 60+ سلسلة و800+ بروتوكول","تطوير تطبيقات للتبادل والجسور عبر السلاسل","بروتوكول التجميع الرائد لDEX والجسور"]},"keywords":{"en":["how to use lifi-dev","lifi-dev setup guide","lifi-dev vs other DEX aggregators","lifi-dev install","cross-chain swap development","LI.FI protocol integration","what is lifi-dev","lifi-dev alternative","lifi-dev documentation"],"zh":["lifi-dev","跨链交换","桥接应用","Widget","SDK","TypeScript","JavaScript","前端开发","后端开发"],"ja":["lifi-dev","クロスチェーンスワップ","ブリッジアプリケーション","Widget","SDK","TypeScript","JavaScript","フロントエンド開発","バックエンド開発"],"ko":["lifi-dev","크로스체인 스왑","브릿지 애플리케이션","Widget","SDK","TypeScript","JavaScript","프론트엔드 개발","백엔드 개발"],"es":["li-fi-dev","desarrollo de cadena cruzada","intercambio de criptomonedas","puentes de blockchain","LI.FI","DEX","TypeScript","JavaScript","Widget","SDK"],"fr":["li-fi-dev","développement de chaîne croisée","échange de cryptomonnaies","ponts de blockchain","LI.FI","DEX","TypeScript","JavaScript","Widget","SDK"],"de":["li-fi-dev","Cross-Chain-Entwicklung","Kryptowährungsaustausch","Blockchain-Brücken","LI.FI","DEX","TypeScript","JavaScript","Widget","SDK"],"pt":["Lifi-Dev","Desenvolvimento de aplicações de troca e ponte de cadeias cruzadas","Protocolo de agregação de DEX e ponte líder","Widget para UI personalizável","SDK em TypeScript/JavaScript","Suporte a 60+ cadeias e 800+ protocolos","Guia de configuração do Lifi-Dev","Desenvolvedores de blockchain"],"ru":["Lifi-Dev","Разработка приложений для перекрестных цепей и мостов","Ведущий протокол агрегации DEX и мостов","Widget для настраиваемого UI","SDK на TypeScript/JavaScript","Поддержка 60+ цепей и 800+ протоколов","Руководство по настройке Lifi-Dev","Разработчики блокчейна"],"ar":["Lifi-Dev","تطوير تطبيقات للتبادل والجسور عبر السلاسل","بروتوكول التجميع الرائد لDEX والجسور","Widget لوياجه المستخدم المخصصة","SDK بلغة TypeScript/JavaScript","دعم 60+ سلسلة و800+ بروتوكول","دليل إعداد Lifi-Dev","مطورو البلوكشين"]}},"owner":"mashharuki","repo":"lify-sample","repoPath":"mashharuki/lify-sample","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.370Z","topics":[],"category":"community","skillMd":{"name":"lifi-dev","description":">","bodyPreview":"# LI.FI Development Support\n\nComprehensive toolkit for building cross-chain swap and bridge applications with LI.FI - the leading DEX and bridge aggregation protocol supporting 60+ chains and 800+ protocols.\n\n## Quick Start\n\n### Product Selection\n\nLI.FI offers three integration methods. Choose based on your use case:\n\n**Quick Decision**:\n- Ready-made UI component → **Widget** (5 min integration, highly customizable)\n- Full control over UX → **SDK** (TypeScript/JavaScript, frontend & backend)\n- D","body":"# LI.FI Development Support\n\nComprehensive toolkit for building cross-chain swap and bridge applications with LI.FI - the leading DEX and bridge aggregation protocol supporting 60+ chains and 800+ protocols.\n\n## Quick Start\n\n### Product Selection\n\nLI.FI offers three integration methods. Choose based on your use case:\n\n**Quick Decision**:\n- Ready-made UI component → **Widget** (5 min integration, highly customizable)\n- Full control over UX → **SDK** (TypeScript/JavaScript, frontend & backend)\n- Direct API access → **REST API** (language-agnostic, maximum flexibility)\n- Existing widget + custom logic → **Widget + SDK combo** (best of both worlds)\n\n**Integration Complexity**:\n- Widget: ⭐ (Easiest - drop-in component)\n- SDK: ⭐⭐ (Moderate - programmatic control)\n- API: ⭐⭐⭐ (Advanced - full customization)\n\n### Common Tasks\n\n**1. Add swap widget to your app**:\n- Review [widget_integration.tsx](scripts/widget_integration.tsx) for React integration\n- Key points: theme customization, chain filtering, event handling\n- Production-ready in under 5 minutes\n- See [widget-guide.md](references/widget-guide.md) for advanced customization\n\n**2. Execute cross-chain swap programmatically**:\n- Use [sdk_swap_example.ts](scripts/sdk_swap_example.ts) for SDK implementation\n- Key points: route optimization, gas estimation, slippage protection\n- See [sdk-guide.md](references/sdk-guide.md) for comprehensive SDK patterns\n\n**3. Get best swap route via API**:\n- Use [api_routes_example.ts](scripts/api_routes_example.ts) for direct API calls\n- Key points: rate limiting, error handling, route comparison\n- See [api-reference.md](references/api-reference.md) for complete endpoint documentation\n\n**4. Implement gas subsidy (LI.Fuel)**:\n- Use [gas_subsidy_example.ts](scripts/gas_subsidy_example.ts) for LI.Fuel integration\n- Solve cold-start problem on new chains\n- See [gas-subsidy-guide.md](references/gas-subsidy-guide.md) for implementation details\n\n**5. Monetize with integrator fees**:\n- Configure fees in [LI.FI Portal](https://portal.li.fi)\n- See [monetization-guide.md](references/monetization-guide.md) for fee structure and withdrawal\n\n## Core Workflows\n\n### Widget Integration\n\n**React/Next.js Integration**:\n```typescript\nimport { LiFiWidget, WidgetConfig } from ''@lifi/widget'';\n\n// 1. Configure widget\nconst widgetConfig: WidgetConfig = {\n  integrator: ''your-app-name'', // Required for analytics and fees\n\n  // Appearance\n  variant: ''expandable'', // ''default'' | ''wide'' | ''drawer'' | ''expandable''\n  theme: {\n    palette: {\n      primary: { main: ''#3f51b5'' },\n      secondary: { main: ''#f50057'' }\n    },\n    shape: { borderRadius: 12 }\n  },\n\n  // Chain & token filtering\n  fromChain: 1, // Ethereum\n  toChain: 137, // Polygon\n  fromToken: ''0x...'', // Specific token address (optional)\n\n  // Advanced configuration\n  fee: 0.03, // 0.03% integrator fee\n  slippage: 0.005, // 0.5% max slippage\n\n  // Event handlers\n  onRouteExecutionStarted: (route) => {\n    console.log(''Swap started:'', route);\n  },\n  onRouteExecutionCompleted: (route) => {\n    console.log(''Swap completed:'', route);\n  }\n};\n\n// 2. Render widget\nfunction App() {\n  return (\n    <div style={{ width: ''100%'', maxWidth: 500 }}>\n      <LiFiWidget config={widgetConfig} />\n    </div>\n  );\n}\n```\n\n**Vue.js Integration**:\n```vue\n<template>\n  <div class=\"widget-container\">\n    <lifi-widget :config=\"widgetConfig\" />\n  </div>\n</template>\n\n<script setup>\nimport { LiFiWidget } from ''@lifi/widget'';\n\nconst widgetConfig = {\n  integrator: ''your-app-name'',\n  variant: ''wide'',\n  theme: { palette: { primary: { main: ''#42b883'' } } }\n};\n</script>\n```\n\n**Vanilla JavaScript**:\n```html\n<!DOCTYPE html>\n<html>\n<head>\n  <link rel=\"stylesheet\" href=\"https://unpkg.com/@lifi/widget/dist/widget.css\">\n</head>\n<body>\n  <div id=\"lifi-widget\"></div>\n\n  <script src=\"https://unpkg.com/@lifi/widget\"></script>\n  <script>\n    window.lifi.createWidget({\n      container: document.getElementById(''lifi-widget''),\n      config: {\n        integrator: ''your-app-name'',\n        variant: ''default''\n      }\n    });\n  </script>\n</body>\n</html>\n```\n\nSee [widget_integration.tsx](scripts/widget_integration.tsx) for complete examples.\n\n### SDK Integration\n\n**Installation**:\n```bash\nnpm install @lifi/sdk\n# or\nyarn add @lifi/sdk\n# or\npnpm add @lifi/sdk\n```\n\n**Basic Swap Flow**:\n```typescript\nimport { LIFI } from ''@lifi/sdk'';\nimport { createWalletClient, http } from ''viem'';\nimport { mainnet } from ''viem/chains'';\n\n// 1. Initialize SDK\nconst lifi = new LIFI({\n  integrator: ''your-app-name'', // Required\n  apiKey: process.env.LIFI_API_KEY // Optional - higher rate limits\n});\n\n// 2. Get available chains and tokens\nconst chains = await lifi.getChains();\nconst tokens = await lifi.getTokens({ chains: [1, 137] }); // Ethereum & Polygon\n\n// 3. Get best route for swap\nconst routeRequest = {\n  fromChainId: 1,     // Ethereum\n  fromTokenAddress: ''0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'', // USDC\n  fromAmount: ''1000000000'', // 1000 USDC (6 decimals)\n  toChainId: 137,     // Polygon\n  toTokenAddress: ''0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359'', // USDC on Polygon\n  fromAddress: ''0x...'', // User wallet address\n\n  // Optional optimizations\n  options: {\n    slippage: 0.005,  // 0.5%\n    order: ''RECOMMENDED'', // or ''FASTEST'', ''CHEAPEST'', ''SAFEST''\n    allowSwitchChain: true\n  }\n};\n\nconst routes = await lifi.getRoutes(routeRequest);\nconst bestRoute = routes.routes[0]; // Pre-sorted by ''order'' parameter\n\n// 4. Check route details\nconsole.log(''Estimated time:'', bestRoute.steps.reduce((t, s) => t + s.estimate.executionDuration, 0), ''seconds'');\nconsole.log(''Gas cost:'', bestRoute.gasCostUSD);\nconsole.log(''Output amount:'', bestRoute.toAmountMin); // Minimum guaranteed\n\n// 5. Execute route\nconst wallet = createWalletClient({\n  chain: mainnet,\n  transport: http()\n});\n\n// Approve token spending if needed\nif (bestRoute.steps[0].action.fromToken.address !== ''0x0000000000000000000000000000000000000000'') {\n  const approvalTx = await lifi.approveToken({\n    walletClient: wallet,\n    token: bestRoute.steps[0].action.fromToken,\n    amount: bestRoute.steps[0].action.fromAmount,\n    spender: bestRoute.steps[0].estimate.approvalAddress\n  });\n  await approvalTx.wait();\n}\n\n// Execute swap\nconst execution = await lifi.executeRoute({\n  route: bestRoute,\n  walletClient: wallet,\n\n  // Event callbacks\n  updateRouteHook: (updatedRoute) => {\n    console.log(''Route updated:'', updatedRoute.status);\n  },\n  switchChainHook: async (requiredChainId) => {\n    // Handle chain switch in your UI\n    await wallet.switchChain({ id: requiredChainId });\n  },\n  acceptExchangeRateUpdateHook: (oldRate, newRate) => {\n    // Return true to accept rate changes\n    return confirm(`Rate changed from ${oldRate} to ${newRate}. Continue?`);\n  }\n});\n\nconsole.log(''Swap completed!'', execution);\n```\n\n**Advanced Route Filtering**:\n```typescript\n// Filter by specific bridges and exchanges\nconst routes = await lifi.getRoutes({\n  ...routeRequest,\n  options: {\n    bridges: { allow: [''stargate'', ''across'', ''hop''] },\n    exchanges: { allow: [''uniswap'', ''1inch''] },\n\n    // Exclude specific protocols\n    // bridges: { deny: [''multichain''] },\n\n    // Fee configuration\n    integrator: ''your-app'',\n    fee: 0.03 // 0.03% fee on fromAmount\n  }\n});\n```\n\nSee [sdk_swap_example.ts](scripts/sdk_swap_example.ts) for production-ready implementation.\n\n### API Integration\n\n**Base URL**: `https://li.quest/v1`\n\n**Authentication** (Optional):\n```bash\n# Higher rate limits with API key\ncurl -H \"x-lifi-api-key: YOUR_API_KEY\" https://li.quest/v1/...\n```\n\n**Get Route Quote**:\n```typescript\n// GET /quote\nconst response = await fetch(\n  ''https://li.quest/v1/quote?'' + new URLSearchParams({\n    fromChain: ''1'',\n    toChain: ''137'',\n    fromToken: ''0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'', // USDC\n    toToken: ''0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359'',   // USDC on Polygon\n    fromAmount: ''1000000000'', // 1000 USDC\n    fromAddress: ''0x...'',\n\n    // Optional\n    integrator: ''your-app-name'',\n    fee: ''0.03'', // 3% integrator fee (decimal format: 0.03 = 3%)\n    slippage: ''0.005'', // 0.5%\n    order: ''RECOMMENDED''\n  }),\n  {\n    headers: {\n      ''x-lifi-api-key'': process.env.LIFI_API_KEY // Optional\n    }\n  }\n);\n\nconst quote = await response.json();\n\n// Quote contains single optimized route\nconsole.log(''Estimated output:'', quote.estimate.toAmount);\nconsole.log(''Execution time:'', quote.estimate.executionDuration, ''seconds'');\nconsole.log(''Gas cost:'', quote.estimate.gasCosts);\n```\n\n**Get Multiple Routes**:\n```typescript\n// GET /advanced/routes - Returns multiple route options\nconst response = await fetch(\n  ''https://li.quest/v1/advanced/routes?'' + new URLSearchParams({\n    fromChainId: ''1'',\n    toChainId: ''137'',\n    fromTokenAddress: ''0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'',\n    toTokenAddress: ''0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359'',\n    fromAmount: ''1000000000'',\n    fromAddress: ''0x...''\n  })\n);\n\nconst { routes } = await response.json();\n\n// Compare multiple routes\nroutes.forEach((route, i) => {\n  console.log(`Route ${i + 1}:`);\n  console.log(''  Steps:'', route.steps.length);\n  console.log(''  Time:'', route.steps.reduce((t, s) => t + s.estimate.executionDuration, 0));\n  console.log(''  Output:'', route.toAmount);\n});\n```\n\n**Get Supported Chains**:\n```typescript\n// GET /chains\nconst response = await fetch(''https://li.quest/v1/chains'');\nconst chains = await response.json();\n\nchains.forEach(chain => {\n  console.log(`${chain.name} (${chain.id}): ${chain.nativeToken.symbol}`);\n});\n```\n\n**Get Supported Tokens**:\n```typescript\n// GET /tokens\nconst response = await fetch(\n  ''https://li.quest/v1/tokens?'' + new URLSearchParams({\n    chains: ''1,137,42161'' // Ethereum, Polygon, Arbitrum\n  })\n);\n\nconst { tokens } = await response.json();\n// Returns: { [chainId]: Token[] }\n```\n\n**Check Route Status**:\n```typescript\n// GET /status\nconst response = await fetch(\n  ''https://li.quest/v1/status?'' + new URLSearchParams({\n    txHash: ''0x...'',\n    bridge: ''stargate'', // Optional - speeds up lookup\n    fromChain: ''1'',\n    toChain: ''137''\n  })\n);\n\nconst status = await response.json();\nconsole.log(''Status:'', status.status); // ''DONE'' | ''PENDING'' | ''FAILED''\nconsole.log(''Destination tx:'', status.receiving?.txHash);\n```\n\nSee [api_routes_example.ts](scripts/api_routes_example.ts) and [api-reference.md](references/api-reference.md).\n\n### Gas Subsidy Implementation (LI.Fuel)\n\n**Problem**: Users bridging to a new chain lack native gas tokens.\n\n**Solution**: LI.Fuel converts a portion of bridged assets to destination chain''s native token.\n\n```typescript\nimport { LIFI } from ''@lifi/sdk'';\n\nconst lifi = new LIFI({ integrator: ''your-app'' });\n\n// Request route with gas subsidy\nconst routes = await lifi.getRoutes({\n  fromChainId: 1,     // Ethereum\n  fromTokenAddress: ''0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'', // USDC\n  fromAmount: ''1000000000'', // 1000 USDC\n  toChainId: 137,     // Polygon\n  toTokenAddress: ''0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359'', // USDC on Polygon\n  fromAddress: userAddress,\n\n  // Enable gas subsidy\n  fromAmountForGas: ''50000000'' // Convert 50 USDC to MATIC on Polygon\n});\n\n// Route automatically includes gas conversion step\nconst route = routes.routes[0];\n\n// Verify gas subsidy is included\nconst gasStep = route.steps.find(step => step.type === ''lifi'');\nif (gasStep?.includedSteps?.some(s => s.type === ''swap'' && s.action.toToken.address === ''0x0000000000000000000000000000000000000000'')) {\n  console.log(''Gas subsidy enabled: User will receive native tokens'');\n}\n```\n\n**API Version**:\n```typescript\nconst response = await fetch(\n  ''https://li.quest/v1/quote?'' + new URLSearchParams({\n    fromChain: ''1'',\n    toChain: ''137'',\n    fromToken: ''0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'',\n    toToken: ''0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359'',\n    fromAmount: ''1000000000'',\n    fromAddress: userAddress,\n\n    // Add gas subsidy parameter\n    fromAmountForGas: ''50000000'' // 50 USDC → MATIC\n  })\n);\n```\n\n**Limitations**:\n- ❌ Not supported with `/contractCalls` endpoint\n- ❌ Not supported via Composer (multi-action transactions)\n- ✅ Supported via `/quote` and `/routes` endpoints\n- ✅ Works with SDK''s `getRoutes()` method\n\nSee [gas_subsidy_example.ts](scripts/gas_subsidy_example.ts) and [gas-subsidy-guide.md](references/gas-subsidy-guide.md).\n\n### Fee Monetization\n\n**Earn revenue by adding integrator fees to swaps**:\n\n```typescript\n// 1. Register at https://portal.li.fi to get your integrator account\n\n// 2. Add fee parameter to SDK/API calls\nconst routes = await lifi.getRoutes({\n  ...routeRequest,\n\n  integrator: ''your-app-name'', // Required\n  fee: 0.03 // 3% fee (decimal: 0.03 = 3%, 0.001 = 0.1%)\n});\n\n// Fee is deducted from fromAmount automatically\n// Example: User sends 1000 USDC\n//   → 30 USDC goes to you (3%)\n//   → 970 USDC is swapped/bridged\n```\n\n**Fee Collection**:\n```typescript\n// Via API\nconst response = await fetch(''https://li.quest/v1/integrators/fees'', {\n  headers: {\n    ''Authorization'': ''Bearer YOUR_API_TOKEN'',\n    ''x-lifi-api-key'': ''YOUR_API_KEY''\n  }\n});\n\nconst { fees } = await response.json();\nconsole.log(''Collected fees:'', fees);\n\n// Withdraw via Portal or API\nawait fetch(''https://li.quest/v1/integrators/fees/withdraw'', {\n  method: ''POST'',\n  headers: {\n    ''Authorization'': ''Bearer YOUR_API_TOKEN'',\n    ''x-lifi-api-key'': ''YOUR_API_KEY''\n  },\n  body: JSON.stringify({\n    token: ''0x...'', // Token to withdraw\n    amount: ''1000000000'' // Amount\n  })\n});\n```\n\n**Base Fee Structure**:\n- LI.FI base fee: 0.25% on all transactions\n- Your integrator fee: Configurable (typically 0.1% - 1%)\n- User pays: LI.FI fee + your fee + protocol fees (DEX/bridge)\n\n**Volume Discounts**:\n- High-volume integrators can negotiate reduced LI.FI base fees\n- Contact LI.FI team for enterprise pricing\n\n**Important**:\n- ⚠️ Must withdraw fees from the same wallet used during integration\n- ⚠️ Switching wallets will lock previous fee claims\n- ✅ Can set up automatic consolidation and conversion to stablecoins\n\nSee [monetization-guide.md](references/monetization-guide.md) for complete setup guide.\n\n## Critical Security Requirements\n\n**Never deploy without**:\n\n1. **Slippage Protection**: Always set `slippage` parameter (default 0.5% = 0.005)\n2. **Amount Validation**: Verify `toAmountMin` in routes before execution\n3. **Token Approval Limits**: Approve exact amounts, not unlimited allowances\n4. **Rate Limiting**: Implement client-side rate limiting for API calls\n5. **Error Handling**: Handle network errors, route failures, and bridge delays\n6. **Chain Verification**: Verify user is on correct chain before execution\n7. **Transaction Monitoring**: Track transaction status across chains\n8. **API Key Protection**: Never expose API keys in frontend code (use backend proxy)\n9. **User Confirmation**: Show final amounts, fees, and execution time before swap\n10. **Bridge Risk Disclosure**: Inform users about bridge security and delays\n\n**Widget Security**:\n```typescript\nconst widgetConfig = {\n  integrator: ''your-app'',\n\n  // Prevent unlimited approvals (recommended)\n  infiniteApproval: false,\n\n  // Set maximum slippage\n  slippage: 0.005, // 0.5%\n\n  // Disable risky bridges (optional)\n  bridges: { deny: [''bridge-with-issues''] },\n\n  // Add transaction confirmation\n  onRouteExecutionStarted: (route) => {\n    // Log for monitoring\n    analytics.track(''swap_started'', {\n      fromChain: route.fromChainId,\n      toChain: route.toChainId,\n      amount: route.fromAmount\n    });\n  }\n};\n```\n\n**SDK Security**:\n```typescript\n// ✅ GOOD: Exact approval\nawait lifi.approveToken({\n  token: route.steps[0].action.fromToken,\n  amount: route.steps[0].action.fromAmount, // Exact amount\n  spender: route.steps[0].estimate.approvalAddress\n});\n\n// ❌ BAD: Unlimited approval\nawait lifi.approveToken({\n  token: route.steps[0].action.fromToken,\n  amount: ethers.MaxUint256, // Dangerous!\n  spender: route.steps[0].estimate.approvalAddress\n});\n\n// ✅ GOOD: Rate limiting\nconst rateLimit = {\n  maxRequests: 10,\n  perSeconds: 60\n};\n\n// ✅ GOOD: Timeout handling\nconst routePromise = lifi.getRoutes(request);\nconst timeoutPromise = new Promise((_, reject) =>\n  setTimeout(() => reject(new Error(''Route timeout'')), 30000)\n);\n\ntry {\n  const routes = await Promise.race([routePromise, timeoutPromise]);\n} catch (error) {\n  // Handle timeout or error\n}\n```\n\nSee [security.md](references/security.md) for complete security checklist.\n\n## Architecture Patterns\n\n### LI.FI Aggregation Architecture\n\n```\n┌─────────────────────────────────────────────┐\n│         Your Application (dApp)              │\n│  ┌─────────┐  ┌─────────┐  ┌─────────┐     │\n│  │ Widget  │  │   SDK   │  │   API   │     │\n│  └────┬────┘  └────┬────┘  └────┬────┘     │\n└───────┼───────────┼────────────┼───────────┘\n        │           │            │\n        └───────────┴────────────┘\n                    │\n        ┌───────────▼────────────┐\n        │   LI.FI Smart Router   │\n        │  (Route Optimization)  │\n        └───────────┬────────────┘\n                    │\n    ┌───────────────┼───────────────┐\n    │               │               │\n┌───▼────┐    ┌────▼─────┐   ┌────▼────┐\n│ Bridges│    │ DEX Agg  │   │ Solvers │\n│        │    │          │   │         │\n│Stargate│    │ Uniswap  │   │ 1inch   │\n│ Across │    │ Sushiswap│   │ 0x      │\n│  Hop   │    │ Curve    │   │ Kyber   │\n│Connext │    │ Balancer │   │ ParaSwap│\n└────────┘    └──────────┘   └─────────┘\n    │              │              │\n    └──────────────┴──────────────┘\n                   │\n          ┌────────▼─────────┐\n          │  60+ Blockchains  │\n          │ 800+ Protocols   │\n          └──────────────────┘\n```\n\n### Integration Decision Tree\n\n```\nStart: Need cross-chain swap/bridge functionality\n  │\n  ├─ Need UI component?\n  │  │\n  │  ├─ Yes → Use Widget\n  │  │        │\n  │  │        ├─ Basic theme customization → Widget default config\n  │  │        ├─ Advanced customization → Widget + custom theme\n  │  │        └─ Need custom logic → Widget + SDK hooks\n  │  │\n  │  └─ No → Need programmatic control?\n  │           │\n  │           ├─ TypeScript/JavaScript → Use SDK\n  │           │                          │\n  │           │                          ├─ Frontend → SDK + wallet provider\n  │           │                          └─ Backend → SDK + private key signer\n  │           │\n  │           └─ Other language/platform → Use REST API\n  │                                        │\n  │                                        ├─ Python/Go/Ruby → Direct HTTP\n  │                                        └─ Mobile native → HTTP client\n```\n\n### Multi-Step Route Flow\n\n```\nUser Swap: 1000 USDC (Ethereum) → USDT (Arbitrum)\n  │\n  ├─ Step 1 (SWAP on Ethereum):\n  │  └─ 1000 USDC → 1000 USDT via Uniswap V3\n  │\n  ├─ Step 2 (BRIDGE):\n  │  └─ 1000 USDT (Ethereum) → 998 USDT (Arbitrum) via Stargate\n  │     (2 USDT bridge fee)\n  │\n  └─ Result: 998 USDT on Arbitrum\n\nOptional: Gas Subsidy (LI.Fuel)\n  │\n  ├─ Step 2a (before bridge):\n  │  └─ 50 USDT → 0.05 ETH (for gas on Ethereum)\n  │\n  └─ Step 2b (on destination):\n     └─ Bridge converts 50 USDT → ~40 ARB native tokens\n     └─ User receives: 948 USDT + 40 ARB (for gas)\n```\n\n### Rate Limiting Architecture\n\n```\nWithout API Key (per IP):\n  ├─ /quote, /routes: 10 requests/minute\n  ├─ /chains, /tokens: 20 requests/minute\n  └─ /status: 30 requests/minute\n\nWith API Key (per key):\n  ├─ /quote, /routes: 100 requests/minute\n  ├─ /chains, /tokens: 200 requests/minute\n  └─ /status: 300 requests/minute\n\nEnterprise (contact LI.FI):\n  └─ Custom limits + dedicated infrastructure\n```\n\n## Development Setup\n\n### Dependencies\n\n**Widget Installation**:\n```bash\n# React\nnpm install @lifi/widget\n# Includes all peer dependencies\n\n# Vue\nnpm install @lifi/widget vue\n\n# Svelte\nnpm install @lifi/widget svelte\n\n# Vanilla JS (via CDN)\n# No installation needed - use <script> tag\n```\n\n**SDK Installation**:\n```bash\nnpm install @lifi/sdk viem\n# or with ethers\nnpm install @lifi/sdk ethers\n\n# TypeScript types included\n```\n\n**Additional Tools**:\n```bash\n# For API calls (if not using SDK)\nnpm install axios\n# or use native fetch (Node 18+, all modern browsers)\n\n# For wallet integration\nnpm install wagmi @wagmi/core viem\n# or\nnpm install @web3-react/core ethers\n```\n\n### Environment Setup\n\n```bash\n# .env\nLIFI_API_KEY=your_api_key_here          # Optional - get from portal.li.fi\nINTEGRATOR_NAME=your-app-name           # Required for analytics\nINTEGRATOR_FEE=0.03                     # Optional - your revenue %\n\n# Wallet (for backend/scripts)\nPRIVATE_KEY=0x...                        # For automated execution\nRPC_URL_ETHEREUM=https://eth.llamarpc.com\nRPC_URL_POLYGON=https://polygon.llamarpc.com\n# ... other chains\n```\n\n### Supported Chains\n\n**EVM Chains** (40+):\n- Ethereum, Arbitrum, Optimism, Base, Polygon, BSC, Avalanche\n- Gnosis, Fantom, Moonbeam, Moonriver, Celo, Aurora, Harmony\n- zkSync Era, Polygon zkEVM, Linea, Scroll, Mantle\n- And many more...\n\n**Non-EVM Chains** (20+):\n- Solana, Bitcoin (experimental), Cosmos ecosystem\n- More being added regularly\n\n**Testnet Support**:\n- Sepolia, Goerli, Mumbai, Arbitrum Goerli, Optimism Goerli\n- Check [api-reference.md](references/api-reference.md) for complete list\n\n### Key Contract Addresses\n\nLI.FI uses partner protocols (Uniswap, Stargate, etc.) - no proprietary contracts to deploy.\n\n**Integration Contracts** (for advanced use):\n- LI.FI Diamond Proxy: `0x1231DEB6f5749EF6cE6943a275A1D3E7486F4EaE` (multi-chain)\n- Receiver Contract: Varies by chain\n\n**Token Addresses** (commonly used):\n- USDC (Ethereum): `0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48`\n- USDC (Polygon): `0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359`\n- USDC (Arbitrum): `0xaf88d065e77c8cC2239327C5EDb3A432268e5831`\n- USDC (Optimism): `0x0b2C639c533813f4Aa9D7837CAf62653d097Ff85`\n- Native tokens: Use `0x0000000000000000000000000000000000000000`\n\nSee [api-reference.md](references/api-reference.md) for complete address list.\n\n## Testing\n\n### Widget Testing (React Testing Library)\n\n```typescript\nimport { render, screen, waitFor } from ''@testing-library/react'';\nimport { LiFiWidget } from ''@lifi/widget'';\n\ndescribe(''LiFi Widget Integration'', () => {\n  it(''should render widget with custom config'', () => {\n    const config = {\n      integrator: ''test-app'',\n      variant: ''wide'',\n      fromChain: 1,\n      toChain: 137\n    };\n\n    render(<LiFiWidget config={config} />);\n\n    expect(screen.getByTestId(''lifi-widget'')).toBeInTheDocument();\n  });\n\n  it(''should call onRouteExecutionCompleted'', async () => {\n    const onComplete = jest.fn();\n    const config = {\n      integrator: ''test-app'',\n      onRouteExecutionCompleted: onComplete\n    };\n\n    render(<LiFiWidget config={config} />);\n\n    // Simulate swap completion\n    // ... trigger swap in test environment\n\n    await waitFor(() => {\n      expect(onComplete).toHaveBeenCalled();\n    });\n  });\n});\n```\n\n### SDK Testing (Jest/Vitest)\n\n```typescript\nimport { LIFI } from ''@lifi/sdk'';\nimport { describe, it, expect, beforeEach } from ''vitest'';\n\ndescribe(''LI.FI SDK'', () => {\n  let lifi: LIFI;\n\n  beforeEach(() => {\n    lifi = new LIFI({\n      integrator: ''test-app''\n    });\n  });\n\n  it(''should fetch available chains'', async () => {\n    const chains = await lifi.getChains();\n\n    expect(chains.length).toBeGreaterThan(0);\n    expect(chains[0]).toHaveProperty(''id'');\n    expect(chains[0]).toHaveProperty(''name'');\n  });\n\n  it(''should get routes for valid swap'', async () => {\n    const routes = await lifi.getRoutes({\n      fromChainId: 1,\n      fromTokenAddress: ''0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'', // USDC\n      fromAmount: ''1000000000'', // 1000 USDC\n      toChainId: 137,\n      toTokenAddress: ''0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359'', // USDC Polygon\n      fromAddress: ''0x1234567890123456789012345678901234567890''\n    });\n\n    expect(routes.routes.length).toBeGreaterThan(0);\n    expect(routes.routes[0]).toHaveProperty(''fromAmount'');\n    expect(routes.routes[0]).toHaveProperty(''toAmount'');\n  });\n\n  it(''should handle invalid route request'', async () => {\n    await expect(\n      lifi.getRoutes({\n        fromChainId: 1,\n        fromTokenAddress: ''0xinvalid'',\n        fromAmount: ''1000000000'',\n        toChainId: 137,\n        toTokenAddress: ''0x...'',\n        fromAddress: ''0x...''\n      })\n    ).rejects.toThrow();\n  });\n});\n```\n\n### API Testing (curl)\n\n```bash\n# Test chain availability\ncurl https://li.quest/v1/chains | jq ''.[0]''\n\n# Test quote endpoint\ncurl \"https://li.quest/v1/quote?fromChain=1&toChain=137&fromToken=0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48&toToken=0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359&fromAmount=1000000000&fromAddress=0x1234567890123456789012345678901234567890\" \\\n  -H \"x-lifi-api-key: YOUR_API_KEY\" | jq ''.estimate''\n\n# Test with integrator fee\ncurl \"https://li.quest/v1/quote?fromChain=1&toChain=137&fromToken=0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48&toToken=0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359&fromAmount=1000000000&fromAddress=0x...&integrator=test-app&fee=0.03\" | jq ''.estimate.feeCosts''\n```\n\n### E2E Testing (Playwright)\n\n```typescript\nimport { test, expect } from ''@playwright/test'';\n\ntest(''complete swap flow with widget'', async ({ page }) => {\n  await page.goto(''http://localhost:3000'');\n\n  // Wait for widget to load\n  await page.waitForSelector(''#lifi-widget'');\n\n  // Configure swap\n  await page.fill(''input[name=\"fromAmount\"]'', ''100'');\n  await page.selectOption(''select[name=\"fromChain\"]'', ''1''); // Ethereum\n  await page.selectOption(''select[name=\"toChain\"]'', ''137''); // Polygon\n\n  // Click swap button\n  await page.click(''button:has-text(\"Swap\")'');\n\n  // Verify route display\n  await expect(page.locator(''.route-summary'')).toBeVisible();\n  await expect(page.locator(''.estimated-output'')).toContainText(''USDC'');\n\n  // In testnet: complete transaction\n  // In production: verify swap flow without execution\n});\n```\n\n## Common Pitfalls\n\n1. **Missing integrator name**: Required for analytics and fee collection\n   ```typescript\n   // ❌ BAD\n   const lifi = new LIFI({});\n\n   // ✅ GOOD\n   const lifi = new LIFI({ integrator: ''your-app-name'' });\n   ```\n\n2. **Ignoring route execution status**: Always monitor multi-step routes\n   ```typescript\n   // ❌ BAD - Fire and forget\n   await lifi.executeRoute({ route, walletClient });\n\n   // ✅ GOOD - Monitor status\n   const execution = await lifi.executeRoute({\n     route,\n     walletClient,\n     updateRouteHook: (route) => {\n       console.log(''Step'', route.steps.findIndex(s => s.execution?.status === ''PENDING''));\n     }\n   });\n   ```\n\n3. **Not handling chain switches**: Cross-chain swaps require chain switching\n   ```typescript\n   // ✅ GOOD\n   const execution = await lifi.executeRoute({\n     route,\n     walletClient,\n     switchChainHook: async (chainId) => {\n       await walletClient.switchChain({ id: chainId });\n     }\n   });\n   ```\n\n4. **Unlimited token approvals**: Security risk\n   ```typescript\n   // ❌ BAD\n   await token.approve(spender, ethers.MaxUint256);\n\n   // ✅ GOOD\n   await lifi.approveToken({\n     token: route.steps[0].action.fromToken,\n     amount: route.steps[0].action.fromAmount, // Exact amount\n     spender: route.steps[0].estimate.approvalAddress\n   });\n   ```\n\n5. **Exposing API keys in frontend**: Use backend proxy\n   ```typescript\n   // ❌ BAD - Frontend\n   const lifi = new LIFI({\n     apiKey: ''pk_live_...'' // Exposed in browser!\n   });\n\n   // ✅ GOOD - Backend proxy\n   // Frontend: Call your backend\n   const routes = await fetch(''/api/lifi/routes'', {\n     method: ''POST'',\n     body: JSON.stringify(routeRequest)\n   });\n\n   // Backend: Use API key securely\n   const lifi = new LIFI({\n     apiKey: process.env.LIFI_API_KEY\n   });\n   ```\n\n6. **Not handling bridge delays**: Some bridges take hours\n   ```typescript\n   // ✅ GOOD - Set expectations\n   console.log(''Estimated time:'', route.steps.reduce(\n     (total, step) => total + step.estimate.executionDuration,\n     0\n   ), ''seconds'');\n\n   if (route.steps.some(s => s.estimate.executionDuration > 3600)) {\n     alert(''This route may take over 1 hour. Continue?'');\n   }\n   ```\n\n7. **Wrong fee format**: Use decimal, not percentage\n   ```typescript\n   // ❌ BAD\n   fee: 3 // SDK interprets as 300%!\n\n   // ✅ GOOD\n   fee: 0.03 // 3%\n   ```\n\n8. **Ignoring rate limits**: Will get throttled\n   ```typescript\n   // ✅ GOOD - Implement rate limiting\n   const rateLimiter = new RateLimiter({\n     maxRequests: 10,\n     perSeconds: 60\n   });\n\n   await rateLimiter.throttle();\n   const routes = await lifi.getRoutes(request);\n   ```\n\n9. **Not validating user inputs**: Can cause API errors\n   ```typescript\n   // ✅ GOOD\n   if (!ethers.isAddress(fromAddress)) {\n     throw new Error(''Invalid address'');\n   }\n   if (BigInt(fromAmount) <= 0) {\n     throw new Error(''Amount must be positive'');\n   }\n   ```\n\n10. **Gas subsidy with contractCalls**: Not supported\n    ```typescript\n    // ❌ BAD - Will fail\n    const routes = await lifi.getRoutes({\n      ...request,\n      contractCalls: [...],\n      fromAmountForGas: ''50000000'' // Not supported together\n    });\n\n    // ✅ GOOD - Use separately\n    const routes = await lifi.getRoutes({\n      ...request,\n      fromAmountForGas: ''50000000'' // Works\n    });\n    ```\n\n## Resources\n\n### Official Documentation\n- **Main Site**: https://li.fi/\n- **Developer Docs**: https://docs.li.fi/\n- **SDK Documentation**: https://docs.li.fi/sdk/overview\n- **API Reference**: https://docs.li.fi/api-reference/introduction\n- **Widget Guide**: https://docs.li.fi/widget/overview\n\n### Integration Guides\n- **Gas Subsidy**: https://docs.li.fi/guides/gas-subsidy\n- **Latency Optimization**: https://docs.li.fi/guides/latency\n- **Fees & Monetization**: https://docs.li.fi/faqs/fees-monetization\n- **Security Best Practices**: https://docs.li.fi/guides/security\n\n### Tools & Dashboards\n- **LI.FI Portal**: https://portal.li.fi (fee management, analytics)\n- **Widget Playground**: https://widget.li.fi (test configurations)\n- **Route Explorer**: https://explorer.li.fi (track transactions)\n- **API Playground**: https://apidocs.li.fi (test API calls)\n\n### Code Examples\n- **GitHub Examples**: https://github.com/lifinance/examples\n- **Widget Templates**: https://github.com/lifinance/widget\n- **SDK Examples**: https://github.com/lifinance/sdk\n\n### Support\n- **Discord**: https://discord.gg/lifi\n- **Telegram**: https://t.me/lifiprotocol\n- **Twitter**: https://twitter.com/lifiprotocol\n- **GitHub Issues**: https://github.com/lifinance/sdk/issues\n- **Status Page**: https://status.li.fi/\n\n## Bundled Resources\n\n### Scripts\n- **[widget_integration.tsx](scripts/widget_integration.tsx)**: Complete Widget integration examples for React/Vue/Svelte\n- **[sdk_swap_example.ts](scripts/sdk_swap_example.ts)**: Production-ready SDK swap implementation with error handling\n- **[api_routes_example.ts](scripts/api_routes_example.ts)**: Direct API integration with rate limiting and monitoring\n- **[gas_subsidy_example.ts](scripts/gas_subsidy_example.ts)**: LI.Fuel gas subsidy implementation\n- **[fee_collection_example.ts](scripts/fee_collection_example.ts)**: Integrator fee setup and collection\n\n### References\n- **[widget-guide.md](references/widget-guide.md)**: Complete Widget customization and theming guide\n- **[sdk-guide.md](references/sdk-guide.md)**: Comprehensive SDK usage patterns and best practices\n- **[api-reference.md](references/api-reference.md)**: Full REST API endpoint documentation with examples\n- **[gas-subsidy-guide.md](references/gas-subsidy-guide.md)**: LI.Fuel implementation and optimization guide\n- **[monetization-guide.md](references/monetization-guide.md)**: Fee structure, collection, and revenue optimization\n- **[security.md](references/security.md)**: Security best practices and audit checklist\n- **[supported-chains.md](references/supported-chains.md)**: Complete list of supported chains and tokens\n- **[bridge-comparison.md](references/bridge-comparison.md)**: Bridge protocol comparison and selection guide\n\n### Assets\n- **[widget-theme-template.ts](assets/widget-theme-template.ts)**: Custom theme configuration template\n- **[rate-limiter.ts](assets/rate-limiter.ts)**: Production-ready rate limiting implementation\n- **[error-handler.ts](assets/error-handler.ts)**: Comprehensive error handling utilities\n\n## Support Context7 Integration\n\nWhen the user needs up-to-date documentation or specific implementation details not covered in this skill:\n\n1. Use LI.FI official docs as primary source: https://docs.li.fi/\n2. For SDK-specific questions: Use Context7 with \"@lifi/sdk\"\n3. For Widget customization: Use Context7 with \"@lifi/widget\"\n4. Combine Context7 results with this skill''s security guidelines\n\nExample:\n```\nUser: \"How do I customize the widget theme for dark mode?\"\n→ Check widget-guide.md for theme basics\n→ Use Context7: query-docs with \"@lifi/widget\" for latest theme options\n→ Apply security patterns from security.md for safe integration\n```\n\n## Advanced Topics\n\n### Multi-Chain Portfolio Management\n\nTrack user balances across all chains:\n\n```typescript\nimport { LIFI } from ''@lifi/sdk'';\n\nasync function getMultiChainBalances(userAddress: string) {\n  const lifi = new LIFI({ integrator: ''portfolio-app'' });\n\n  // Get all supported chains\n  const chains = await lifi.getChains();\n\n  // Get token balances for each chain\n  const balances = await Promise.all(\n    chains.map(async (chain) => {\n      const tokens = await lifi.getTokenBalances(userAddress, [chain.id]);\n      return {\n        chain: chain.name,\n        tokens: tokens.filter(t => parseFloat(t.amount) > 0)\n      };\n    })\n  );\n\n  return balances.filter(b => b.tokens.length > 0);\n}\n```\n\n### Route Optimization Strategies\n\n```typescript\n// Get multiple routes and compare\nconst routes = await lifi.getRoutes({\n  ...baseRequest,\n  options: {\n    // Get fastest, cheapest, and recommended routes\n    order: ''RECOMMENDED''\n  }\n});\n\n// Compare routes\nconst comparison = routes.routes.map(route => ({\n  id: route.id,\n  outputAmount: route.toAmount,\n  executionTime: route.steps.reduce((t, s) => t + s.estimate.executionDuration, 0),\n  gasCostUSD: route.gasCostUSD,\n  steps: route.steps.length\n}));\n\n// Sort by custom criteria\nconst bestByOutput = [...comparison].sort((a, b) =>\n  parseFloat(b.outputAmount) - parseFloat(a.outputAmount)\n)[0];\n\nconst bestByTime = [...comparison].sort((a, b) =>\n  a.executionTime - b.executionTime\n)[0];\n```\n\n### Custom Event Tracking\n\n```typescript\nconst widgetConfig = {\n  integrator: ''analytics-app'',\n\n  // Track all widget events\n  onRouteHighValueLoss: (route, loss) => {\n    analytics.track(''high_value_loss_warning'', {\n      expectedOutput: route.toAmount,\n      actualOutput: route.toAmountMin,\n      lossAmount: loss\n    });\n  },\n\n  onRouteExecutionStarted: (route) => {\n    analytics.track(''swap_started'', {\n      fromChain: route.fromChainId,\n      toChain: route.toChainId,\n      fromToken: route.fromToken.symbol,\n      toToken: route.toToken.symbol,\n      amount: route.fromAmount\n    });\n  },\n\n  onRouteExecutionCompleted: (route) => {\n    analytics.track(''swap_completed'', {\n      routeId: route.id,\n      executionTime: Date.now() - route.executionStartedAt,\n      actualOutput: route.toAmountMin\n    });\n  },\n\n  onRouteExecutionFailed: (route, error) => {\n    analytics.track(''swap_failed'', {\n      routeId: route.id,\n      error: error.message,\n      step: route.steps.findIndex(s => s.execution?.status === ''FAILED'')\n    });\n  }\n};\n```\n\n### Webhook Integration (Backend)\n\n```typescript\nimport express from ''express'';\nimport { createHmac } from ''crypto'';\n\nconst app = express();\n\napp.post(''/webhooks/lifi'', express.json(), (req, res) => {\n  // Verify webhook signature\n  const signature = req.headers[''x-lifi-signature''];\n  const payload = JSON.stringify(req.body);\n\n  const expectedSignature = createHmac(''sha256'', process.env.LIFI_WEBHOOK_SECRET)\n    .update(payload)\n    .digest(''hex'');\n\n  if (signature !== expectedSignature) {\n    return res.status(401).send(''Invalid signature'');\n  }\n\n  // Process webhook\n  const { event, data } = req.body;\n\n  switch (event) {\n    case ''route.completed'':\n      // Update database, notify user, etc.\n      console.log(''Route completed:'', data.routeId);\n      break;\n\n    case ''route.failed'':\n      // Handle failure, refund user, etc.\n      console.log(''Route failed:'', data.routeId, data.error);\n      break;\n\n    case ''fee.collected'':\n      // Track revenue\n      console.log(''Fee collected:'', data.amount, data.token);\n      break;\n  }\n\n  res.status(200).send(''OK'');\n});\n```\n\n## Performance Optimization\n\n### Caching Strategies\n\n```typescript\n// Cache chain and token data (rarely changes)\nimport { LRUCache } from ''lru-cache'';\n\nconst chainCache = new LRUCache({\n  max: 100,\n  ttl: 1000 * 60 * 60 // 1 hour\n});\n\nasync function getChainsWithCache() {\n  const cached = chainCache.get(''chains'');\n  if (cached) return cached;\n\n  const lifi = new LIFI({ integrator: ''your-app'' });\n  const chains = await lifi.getChains();\n\n  chainCache.set(''chains'', chains);\n  return chains;\n}\n\n// Cache routes for same parameters (short TTL)\nconst routeCache = new LRUCache({\n  max: 50,\n  ttl: 1000 * 30 // 30 seconds\n});\n\nasync function getRoutesWithCache(request) {\n  const cacheKey = JSON.stringify(request);\n  const cached = routeCache.get(cacheKey);\n  if (cached) return cached;\n\n  const lifi = new LIFI({ integrator: ''your-app'' });\n  const routes = await lifi.getRoutes(request);\n\n  routeCache.set(cacheKey, routes);\n  return routes;\n}\n```\n\n### Parallel Route Fetching\n\n```typescript\n// Fetch routes for multiple token pairs in parallel\nasync function getMultipleRoutes(requests) {\n  const lifi = new LIFI({ integrator: ''your-app'' });\n\n  const routePromises = requests.map(request =>\n    lifi.getRoutes(request).catch(err => ({\n      error: err.message,\n      request\n    }))\n  );\n\n  const results = await Promise.all(routePromises);\n\n  return results.filter(r => !r.error);\n}\n\n// Usage\nconst routes = await getMultipleRoutes([\n  { fromChainId: 1, toChainId: 137, ... },\n  { fromChainId: 1, toChainId: 42161, ... },\n  { fromChainId: 137, toChainId: 10, ... }\n]);\n```\n\n### Widget Performance\n\n```typescript\n// Lazy load widget\nimport { lazy, Suspense } from ''react'';\n\nconst LiFiWidget = lazy(() => import(''@lifi/widget'').then(m => ({ default: m.LiFiWidget })));\n\nfunction App() {\n  return (\n    <Suspense fallback={<div>Loading swap widget...</div>}>\n      <LiFiWidget config={widgetConfig} />\n    </Suspense>\n  );\n}\n```\n\n## Migration Guides\n\n### From 0x API to LI.FI\n\n```typescript\n// Before (0x)\nconst response = await fetch(\n  `https://api.0x.org/swap/v1/quote?` + new URLSearchParams({\n    sellToken: ''ETH'',\n    buyToken: ''DAI'',\n    sellAmount: ''1000000000000000000''\n  })\n);\n\n// After (LI.FI)\nconst lifi = new LIFI({ integrator: ''migrated-from-0x'' });\nconst routes = await lifi.getRoutes({\n  fromChainId: 1,\n  fromTokenAddress: ''0x0000000000000000000000000000000000000000'', // ETH\n  fromAmount: ''1000000000000000000'',\n  toChainId: 1,\n  toTokenAddress: ''0x6B175474E89094C44Da98b954EedeAC495271d0F'', // DAI\n  fromAddress: userAddress\n});\n\nconst bestRoute = routes.routes[0];\n// Execute with SDK or display in Widget\n```\n\n### From 1inch API to LI.FI\n\n```typescript\n// Before (1inch)\nconst response = await fetch(\n  `https://api.1inch.dev/swap/v5.2/1/quote?` + new URLSearchParams({\n    src: ''0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE'', // ETH\n    dst: ''0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'', // USDC\n    amount: ''1000000000000000000''\n  }),\n  { headers: { ''Authorization'': `Bearer ${API_KEY}` } }\n);\n\n// After (LI.FI) - Includes 1inch + other aggregators\nconst routes = await lifi.getRoutes({\n  fromChainId: 1,\n  fromTokenAddress: ''0x0000000000000000000000000000000000000000'',\n  fromAmount: ''1000000000000000000'',\n  toChainId: 1,\n  toTokenAddress: ''0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'',\n  fromAddress: userAddress,\n\n  // Optional: Prefer 1inch if migrating gradually\n  options: {\n    exchanges: { allow: [''1inch'', ''uniswap'', ''sushiswap''] }\n  }\n});\n```\n\n## Enterprise Features\n\nFor high-volume applications, contact LI.FI for:\n\n- **Dedicated Infrastructure**: Private RPC nodes and dedicated API instances\n- **Custom Rate Limits**: Higher throughput for enterprise needs\n- **Volume Discounts**: Reduced fees for high transaction volumes\n- **Priority Support**: Dedicated technical support and integration assistance\n- **Custom Analytics**: Advanced reporting and monitoring dashboards\n- **SLA Guarantees**: Uptime and performance guarantees\n\nContact: partnerships@li.fi\n"},"lastSynced":"2026-03-08T02:04:27.051Z","agentAnalysis":{"suitability":{"en":"Perfect for Blockchain Agents needing cross-chain swap and bridge application development with LI.FI protocol support.","zh":"非常适合需要跨链交换和桥接应用开发的区块链代理，并支持 LI.FI 协议。","ja":"ブロックチェーンエージェントがクロスチェーンスワップおよびブリッジアプリケーション開発を必要とする場合に最適で、LI.FI プロトコルをサポートしています。","ko":"크로스 체인 스왑 및 브리지 애플리케이션 개발이 필요한 블록チェ인 에이전트에게 적합하며, LI.FI 프로토콜을 지원합니다.","es":"Perfecto para agentes de Blockchain que necesitan desarrollo de aplicaciones de intercambio y puente entre cadenas con soporte del protocolo LI.FI.","fr":"Parfait pour les agents Blockchain qui ont besoin de développement d''applications d''échange et de pont entre chaînes avec prise en charge du protocole LI.FI.","de":"Perfekt für Blockchain-Agents, die Entwicklung von Cross-Chain-Swap- und Bridge-Anwendungen mit LI.FI-Protokoll-Unterstützung benötigen.","pt":"Perfeito para Agentes de Blockchain que necessitam de desenvolvimento de aplicativos de troca e ponte de cadeia cruzada com suporte ao protocolo LI.FI.","ru":"Идеально подходит для агентов блокчейна, которым требуется разработка приложений для межцепочечного обмена и мостов с поддержкой протокола LI.FI.","ar":"مثالي لعميل Blockchain الذين يحتاجون إلى تطوير تطبيقات التبادل والجسور متعددة السلاسل مع دعم بروتوكول LI.FI."},"recommendation":{"en":"Empowers agents to build seamless cross-chain interactions using LI.FI''s comprehensive toolkit, providing ready-made UI components and SDKs for TypeScript and JavaScript, enabling support for 60+ chains and 800+ protocols.","zh":"赋予代理构建无缝跨链交互的能力，使用 LI.FI 的综合工具包，提供适用于 TypeScript 和 JavaScript 的预制 UI 组件和 SDK，支持 60 多个链和 800 多个协议。","ja":"エージェントがシームレスなクロスチェーン相互作用を構築できるようにすることで、LI.FI の包括的なツールキットを使用し、TypeScript と JavaScript 用の事前作成された UI コンポーネントと SDK を提供し、60以上のチェーンと800以上のプロトコルをサポートします。","ko":"에이전트가 무결점의 크로스 체인 상호 작용을 구축할 수 있도록 강화하여, LI.FI의 포괄적인 툴킷을 사용하고, TypeScript 및 JavaScript를 위한 미리 구성된 UI 구성 요소 및 SDK를 제공하며, 60개 이상의 체인 및 800개 이상의 프로토콜을 지원합니다.","es":"Habilita a los agentes a crear interacciones entre cadenas de forma fluida utilizando la herramienta completa de LI.FI, proporcionando componentes de interfaz de usuario prefabricados y SDK para TypeScript y JavaScript, lo que permite el soporte para 60+ cadenas y 800+ protocolos.","fr":"Permet aux agents de créer des interactions entre chaînes de manière fluide en utilisant la boîte à outils complète de LI.FI, fournissant des composants d''interface utilisateur prêts à l''emploi et des SDK pour TypeScript et JavaScript, permettant ainsi la prise en charge de 60+ chaînes et 800+ protocoles.","de":"Ermächtigt Agenten, nahtlose Cross-Chain-Interaktionen mithilfe der umfassenden Toolbox von LI.FI zu erstellen, die vorgefertigte Benutzeroberflächenelemente und SDKs für TypeScript und JavaScript bereitstellt, wodurch die Unterstützung für 60+ Ketten und 800+ Protokolle ermöglicht wird.","pt":"Habilita os agentes a construir interações entre cadeias cruzadas sem problemas, usando a ferramenta abrangente da LI.FI, fornecendo componentes de UI prontos e SDKs para TypeScript e JavaScript, habilitando o suporte a 60+ cadeias e 800+ protocolos.","ru":"Наделяет агентов возможностью создавать беспроблемные взаимодействия между цепочками, используя комплексный инструментарий LI.FI, предоставляющий готовые компоненты UI и SDK для TypeScript и JavaScript, обеспечивая поддержку 60+ цепочек и 800+ протоколов.","ar":"يتمكن العملاء من بناء تفاعلات متعددة السلاسل بدون مشاكل باستخدام أداة LI.FI الشاملة، وتوفير مكونات UI جاهزة و SDKs لـ TypeScript و JavaScript، وتمكين دعم 60+ سلسلة و 800+ بروتوكول."},"useCases":{"en":["Developing cross-chain swap applications with LI.FI''s widget integration","Building custom bridge applications using LI.FI''s SDK for full control over UX","Integrating LI.FI''s protocol into existing blockchain projects for expanded chain support"],"zh":["使用 LI.FI的小部件集成开发跨链交换应用","使用 LI.FI的SDK构建自定义桥接应用以控制 UX","将 LI.FI的协议集成到现有的区块链项目中以扩展链支持"],"ja":["LI.FI のウィジェット統合を使用してクロスチェーンスワップアプリケーションを開発する","LI.FI の SDK を使用してカスタムブリッジアプリケーションを構築して UX を完全に制御する","LI.FI のプロトコルを既存のブロックチェーンプロジェクトに統合してチェーンサポートを拡張する"],"ko":["LI.FI의 위젯 통합을 사용하여 크로스 체인 스왑 애플리케이션 개발하기","LI.FI의 SDK를 사용하여 사용자 지정 브리지 애플리케이션 구축하여 UX를 완전히 제어하기","LI.FI의 프로토콜을 기존 블록체인 프로젝트에 통합하여 체인 지원 확장하기"],"es":["Desarrollar aplicaciones de intercambio entre cadenas con la integración del widget de LI.FI","Crear aplicaciones de puente personalizadas utilizando el SDK de LI.FI para un control total sobre la UX","Integrar el protocolo de LI.FI en proyectos de blockchain existentes para una ampliación de la compatibilidad de cadenas"],"fr":["Développer des applications d''échange entre chaînes avec l''intégration du widget de LI.FI","Créer des applications de pont personnalisées en utilisant le SDK de LI.FI pour un contrôle total sur l''UX","Intégrer le protocole de LI.FI dans des projets de blockchain existants pour une expansion de la prise en charge des chaînes"],"de":["Entwicklung von Cross-Chain-Swap-Anwendungen mit der Widget-Integration von LI.FI","Erstellen von benutzerdefinierten Bridge-Anwendungen unter Verwendung des LI.FI-SDK für die vollständige Kontrolle über die UX","Integration des LI.FI-Protokolls in bestehende Blockchain-Projekte für eine erweiterte Kettenunterstützung"],"pt":["Desenvolver aplicações de troca de cadeias cruzadas com integração do widget da LI.FI","Construir aplicações de ponte personalizadas usando o SDK da LI.FI para controle total sobre a UX","Integrar o protocolo da LI.FI em projetos de blockchain existentes para expansão do suporte à cadeia"],"ru":["Разработка приложений для межцепочечного обмена с интеграцией виджета LI.FI","Создание пользовательских приложений-мостов с использованием SDK LI.FI для полного контроля над UX","Интеграция протокола LI.FI в существующие проекты блокчейна для расширения поддержки цепочки"],"ar":["تطوير تطبيقات متعددة السلاسل باستخدام تكامل ويدج LI.FI","بناء تطبيقات جسر مخصصة باستخدام SDK LI.FI للسيطرة الكاملة على UX","دمج بروتوكول LI.FI في مشاريع Blockchain الحالية لتوسيع دعم السلسلة"]},"limitations":{"en":["Requires LI.FI protocol compatibility","Limited to chains and protocols supported by LI.FI"],"zh":["需要 LI.FI 协议兼容性","仅限于 LI.FI 支持的链和协议"],"ja":["LI.FI プロトコルとの互換性が必要","LI.FI がサポートするチェーンとプロトコルに限定される"],"ko":["LI.FI 프로토콜과 호환성이 필요함","LI.FI가 지원하는 체인 및 프로토콜에만 제한됨"],"es":["Requiere compatibilidad con el protocolo de LI.FI","Limitado a las cadenas y protocolos compatibles con LI.FI"],"fr":["Nécessite la compatibilité avec le protocole de LI.FI","Limité aux chaînes et protocoles pris en charge par LI.FI"],"de":["Benötigt Kompatibilität mit dem LI.FI-Protokoll","Begrenzt auf Ketten und Protokolle, die von LI.FI unterstützt werden"],"pt":["Exige compatibilidade com o protocolo LI.FI","Limitado às cadeias e protocolos suportados pela LI.FI"],"ru":["Требует совместимости с протоколом LI.FI","Ограничен цепочками и протоколами, поддерживаемыми LI.FI"],"ar":["يتطلب توافقًا مع بروتوكول LI.FI","محدود بالسلاسل والبروتوكولات التي يدعمها LI.FI"]},"version":4},"contentHash":"10dec4ea270fce03826c7108fc6fed87bab969f6933e5c088146d459ef9ce0e6","qualityScore":60}');
