INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mashharuki/lify-sample/lifi-dev', 'lifi-dev', 'mashharuki', 'lify-sample', 'community', 'lifi-dev mashharuki lify-sample community lifi-dev is a comprehensive toolkit for building cross-chain swap and bridge applications with LI.FI. It benefits developers by providing a range of integration methods, including ready-made UI components and SDKs. lifi-dev是一种综合工具包，用于构建跨链交换和桥接应用，支持60+链和800+协议 lifi-devは、クロスチェーンスワップとブリッジアプリケーションを構築するための包括的なツールキットです。60+のチェーンと800+のプロトコルをサポート lifi-dev는 크로스체인 스왑 및 브릿지 애플리케이션을 구축하기 위한 포괄적인 도구 키트입니다. 60+ 체인 및 800+ 프로토콜을 지원 li-fi-dev es un toolkit de desarrollo de cadena cruzada para aplicaciones de intercambio y puente con LI.FI, el protocolo de agregación de DEX y puente líder li-fi-dev est un toolkit de développement de pont pour les applications d''échange et de pont avec LI.FI, le protocole d''agrégation de DEX et de pont leader li-fi-dev ist ein umfassendes Toolkit für Cross-Chain-Swaps und Brücken-Anwendungen mit LI.FI, dem führenden DEX- und Bridge-Aggregationsprotokoll O Lifi-Dev é uma ferramenta abrangente para construir aplicações de troca e ponte de cadeias cruzadas com a protocolo de agregação de DEX e ponte líder, suportando 60+ cadeias e 800+ protocolos. Lifi-Dev — это комплексный инструмент для создания приложений для перекрестных цепей и мостов с помощью ведущего протокола агрегации DEX и мостов, поддерживающего 60+ цепей и 800+ протоколов. Lifi-Dev هو أداة شاملة لإنشاء تطبيقات للتبادل والجسور عبر السلاسل مع بروتوكول التجميع الرائد لDEX والجسور، يدعم 60+ سلاسل و800+ بروتوكول. how to use lifi-dev lifi-dev setup guide lifi-dev vs other DEX aggregators lifi-dev install cross-chain swap development LI.FI protocol integration what is lifi-dev lifi-dev alternative lifi-dev documentation lifi-dev 跨链交换 桥接应用 Widget SDK TypeScript JavaScript 前端开发 后端开发 Offers three integration methods: Widget, SDK, and custom implementations Supports 60+ chains and 800+ protocols for cross-chain swaps Provides a ready-made UI component for quick integration (5 min setup) Includes a TypeScript/JavaScript SDK for full control over UX Enables building of bridge applications with LI.FI protocol lifi-dev is a development support toolkit for LI.FI, a leading DEX and bridge aggregation protocol.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danielcastro-dev/speclet/speclet-council', 'community', 'danielcastro-dev', 'speclet', 'danielcastro-dev/speclet', 'speclet-council', 0, 0, 60, '2026-03-08T01:57:15.379Z', '2026-03-08T02:05:32.195Z', '663fae451a3968865fea2426f4a2b99bbc594d02a6335336acf83b4dedd6b3c0', '{"id":"danielcastro-dev/speclet/speclet-council","name":"speclet-council","description":{"en":"The speclet-council skill automates code review by validating input files, invoking reviewers, and generating audit artifacts. It benefits developers by streamlining the review process.","zh":"Speclet Council 是一个自动化审查和审计工具，使用 GPT 和 GLM 进行代码审查","ja":"Speclet Council は自動化レビューと監査ツールです。GPT と GLM を使用してコードをレビューします","ko":"Speclet Council는 자동화 리뷰 및 감사 도구입니다. GPT와 GLM을 사용하여 코드를 리뷰합니다","es":"speclet-council es una habilidad que permite la revisión de especificaciones y tickets mediante la invocación de revisores en paralelo y la generación de artefactos de auditoría","fr":"speclet-council est une compétence qui permet la revue de spécifications et de tickets en invoquant des réviseurs en parallèle et en générant des artefacts d''audit","de":"speclet-council ist eine Fähigkeit, die die Überprüfung von Spezifikationen und Tickets ermöglicht, indem sie Überprüfer parallel aufruft und Audit-Artefakte generiert","pt":"O Speclet Council é uma ferramenta de revisão de código que valida e emite artefatos de auditoria. Ele invoca dois revisores em paralelo e sintetiza feedback com clustering temático.","ru":"Спеклет Совет - это инструмент для обзора кода, который проверяет и выдает артефакты аудита. Он вызывает двух рецензентов параллельно и синтезирует обратную связь с помощью тематического кластеринга.","ar":"مجلس Speclet هو أداة مراجعة التعليمات البرمجية التي تعمل على التحقق وإصدار مستندات التدقيق. وهو يستدعي两个 مراجعين متوازيًا ويتخلف ملاحظات باستخدام التجميع المواضيعي"},"seo":{"title":{"en":"speclet-council: Automated Code Review Setup Guide | AI A...","zh":"Speclet Council 设置指南 - 自动化审查和审计","ja":"Speclet Council セットアップガイド - 自動化レビューと監査","ko":"Speclet Council 설정 가이드 - 자동화 리뷰 및 감사","es":"Guía de Configuración de speclet-council para Revisión de...","fr":"Guide de Configuration de speclet-council pour la Revue d...","de":"Konfigurationsleitfaden für speclet-council zur Überprüfu...","pt":"Guia de Configuração do Speclet Council - Ferramenta de R...","ru":"Настройка Спеклет Совета - Инструмент для обзора кода ИИ ...","ar":"دليل إعداد مجلس Speclet - أداة مراجعة التعليمات البرمجية"},"description":{"en":"Unlock efficient code review with speclet-council. Learn how to automate your review process and improve code quality. Get started now!","zh":"Speclet Council 是一个 AI 工具，用于自动化审查和审计。了解如何设置和使用它来提高代码质量","ja":"Speclet Council は AI エージェントです。自動化レビューと監査を使用してコード品質を向上させる方法を学びましょう","ko":"Speclet Council는 자동화 리뷰 및 감사를 위한 AI 에이전트입니다. 설정 방법과 사용 방법을 알아보세요","es":"Aprenda a configurar speclet-council para realizar revisiones de especificaciones y tickets de forma eficiente con herramientas de IA como GPT y GLM","fr":"Découvrez comment configurer speclet-council pour effectuer des revues de spécifications et de tickets de manière efficace avec des outils d''IA tels que GPT ...","de":"Erfahren Sie, wie Sie speclet-council konfigurieren, um Spezifikationen und Tickets effizient mit AI-Tools wie GPT und GLM zu überprüfen","pt":"Aprenda a configurar o Speclet Council, uma ferramenta de revisão de código que valida e emite artefatos de auditoria com tecnologias como GPT e GLM.","ru":"Узнайте, как настроить Спеклет Совет, инструмент для обзора кода, который проверяет и выдает артефакты аудита с помощью технологий GPT и GLM ИИ Агентов.","ar":"تعرف على كيفية إعداد مجلس Speclet، أداة مراجعة التعليمات البرمجية التي تعمل على التحقق وإصدار مستندات التدقيق باستخدام تقنيات مثل GPT وGLM"},"definition":{"en":"speclet-council is a skill that automates council reviews over drafts, specs, or tickets, emitting audit artifacts and providing feedback through thematic clustering.","zh":"Speclet Council 是一个自动化代码审查和审计的 AI 工具","ja":"Speclet Council はコードの自動化レビューと監査を行う AI エージェントです","ko":"Speclet Council는 코드의 자동화 리뷰 및 감사를 수행하는 AI 에이전트입니다","es":"speclet-council es una herramienta de IA que realiza revisiones de especificaciones y tickets mediante la invocación de revisores y la generación de artefactos de auditoría","fr":"speclet-council est un outil d''IA qui effectue des revues de spécifications et de tickets en invoquant des réviseurs et en générant des artefacts d''audit","de":"speclet-council ist ein AI-Tool, das Spezifikationen und Tickets überprüft, indem es Überprüfer aufruft und Audit-Artefakte generiert","pt":"O Speclet Council é uma ferramenta de revisão de código que valida e emite artefatos de auditoria automaticamente.","ru":"Спеклет Совет - это инструмент для автоматического обзора кода и выдачи артефактов аудита.","ar":"مجلس Speclet هو أداة مراجعة التعليمات البرمجية التي تعمل على التحقق وإصدار مستندات التدقيق آليًا"},"features":{"en":["Validates target input files such as draft.md, spec.json, or ticket files","Invokes two reviewers, GPT and GLM, in parallel with per-reviewer timeouts and retries","Generates a Review Status Header indicating succeeded or failed models","Synthesizes feedback using thematic clustering and collapsible HTML tags","Writes council-session.md files for audit and review purposes"],"zh":["使用 GPT 和 GLM 进行代码审查","支持并行审查和超时重试","生成审查状态头和可折叠的 HTML 标签","写入 .speclet/council-session.md 文件","使用主题聚类合成反馈"],"ja":["GPT と GLM を使用してコードをレビュー","並列レビューとタイムアウト再試行をサポート","レビュー状態ヘッダーと可折叠の HTML タグを生成",".speclet/council-session.md ファイルを書き出す","テーマクラスタリングを使用してフィードバックを合成"],"ko":["GPT와 GLM을 사용하여 코드를 리뷰","병렬 리뷰 및 타임아웃 재시도를 지원","리뷰 상태 헤더 및 접을 수 있는 HTML 태그를 생성",".speclet/council-session.md 파일을 작성","테마 클러스터링을 사용하여 피드백을 합성"],"es":["Validación de la existencia del archivo de especificación","Invocación de revisores en paralelo con tiempos de espera y reintentos","Generación de un encabezado de estado de revisión","Uso de clustering temático para sintetizar comentarios","Generación de artefactos de auditoría en formato Markdown"],"fr":["Validation de l''existence du fichier de spécification","Invocation de réviseurs en parallèle avec des délais d''attente et des reprises","Génération d''un en-tête d''état de revue","Utilisation du clustering thématique pour synthétiser les commentaires","Génération d''artefacts d''audit au format Markdown"],"de":["Validierung der Existenz der Spezifikationsdatei","Aufruf von Überprüfern in Parallelschaltung mit Wartezeiten und Wiederholungen","Generierung eines Überprüfungsstatus-Headers","Verwendung von thematischem Clustering zur Synthese von Kommentaren","Generierung von Audit-Artefakten im Markdown-Format"],"pt":["Validação de entrada de código","Invocação de dois revisores em paralelo","Síntese de feedback com clustering temático","Emissão de artefatos de auditoria","Suporte a tecnologias como GPT e GLM"],"ru":["Проверка входного кода","Вызов двух рецензентов параллельно","Синтез обратной связи с помощью тематического кластеринга","Выдача артефактов аудита","Поддержка технологий GPT и GLM ИИ Агентов"],"ar":["التحقق من مدخلات التعليمات البرمجية","استدعاء مراجعين متوازيًا","تخلف الملاحظات باستخدام التجميع المواضيعي","إصدار مستندات التدقيق","دعم تقنيات مثل GPT وGLM"]},"keywords":{"en":["how to use speclet-council","speclet-council setup guide","speclet-council alternative","speclet-council vs automated code review tools","speclet-council install","what is speclet-council","speclet-council for AI agents","automated code review with speclet-council","speclet-council tutorial"],"zh":["Speclet Council","AI 工具","自动化审查","代码审查","GPT","GLM","并行审查","超时重试","审查状态头"],"ja":["Speclet Council","AI エージェント","自動化レビュー","コードレビュー","GPT","GLM","並列レビュー","タイムアウト再試行","レビュー状態ヘッダー"],"ko":["Speclet Council","AI 에이전트","자동화 리뷰","코드 리뷰","GPT","GLM","병렬 리뷰","타임아웃 재시도","리뷰 상태 헤더"],"es":["herramientas de IA para revisiones","revisión de especificaciones","revisión de tickets","GPT","GLM","clustering temático","arte factos de auditoría","Markdown"],"fr":["outils d''IA pour les revues","revue de spécifications","revue de tickets","GPT","GLM","clustering thématique","artefacts d''audit","Markdown"],"de":["AI-Tools für Überprüfungen","Überprüfung von Spezifikationen","Überprüfung von Tickets","GPT","GLM","thematisches Clustering","Audit-Artefakte","Markdown"],"pt":["Speclet Council","revisão de código","ferramenta de revisão","validação de código","GPT","GLM","clustering temático","artefatos de auditoria"],"ru":["Спеклет Совет","обзор кода","инструмент для обзора","проверка кода","GPT","GLM","тематическое кластеринг","артефакты аудита","ИИ Агенты"],"ar":["مجلس Speclet","مراجعة التعليمات البرمجية","أداة مراجعة","التحقق من التعليمات البرمجية","GPT","GLM","التجميع المواضيعي","مستندات التدقيق","أدوات الذكاء الاصطناعي"]}},"owner":"danielcastro-dev","repo":"speclet","repoPath":"danielcastro-dev/speclet","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.379Z","topics":[],"category":"community","skillMd":{"name":"speclet-council","description":"Run parallel reviews on draft/spec/ticket inputs and emit Council artifacts","bodyPreview":"# Speclet Council Skill\n\nRun a council review over a draft, spec, or ticket input, then emit audit artifacts.\n\n## What I Do\n\n- Validate the target input exists (`draft.md`, `spec.json`, or a ticket file)\n- Invoke two reviewers (GPT, GLM) in parallel with per-reviewer timeouts and retries\n- Collect critiques and generate a **Review Status Header** (succeeded vs. failed models)\n- Synthesize feedback using **Thematic Clustering** and collapsible HTML tags\n- Write `.speclet/council-session.md` and `","body":"# Speclet Council Skill\n\nRun a council review over a draft, spec, or ticket input, then emit audit artifacts.\n\n## What I Do\n\n- Validate the target input exists (`draft.md`, `spec.json`, or a ticket file)\n- Invoke two reviewers (GPT, GLM) in parallel with per-reviewer timeouts and retries\n- Collect critiques and generate a **Review Status Header** (succeeded vs. failed models)\n- Synthesize feedback using **Thematic Clustering** and collapsible HTML tags\n- Write `.speclet/council-session.md` and `.speclet/council-summary.md`\n- Write optional `.speclet/draft.review.md` (full Council Review)\n- Support `--dry-run` mode with mocked reviewer outputs\n\n## When to Use Me\n\nUse this after a target exists and before conversion/implementation:\n\n```\nUse the speclet-council skill\n```\n\n### Supported Targets\n\n- Draft: `.speclet/draft.md` (default)\n- Spec: `.speclet/spec.json` or an explicit spec path\n- Ticket: `.speclet/tickets/<TICKET-ID>/draft.md` or `ticket-draft.md`\n\n### Example Invocations\n\n```\nUse the speclet-council skill\nUse the speclet-council skill for .speclet/spec.json\nUse the speclet-council skill for .speclet/tickets/TICKET-1/draft.md\n```\n\nIf the user says \"use speclet-council to review this spec.json\" or \"review this ticket\", treat the referenced file as the target input.\n\n## Setup (Required)\n\nReviewers must be configured in your `oh-my-opencode.json`:\n\n- `plan-reviewer-gpt` (implementability)\n- `plan-reviewer-glm` (clean design and completeness)\n\nOnly these two reviewers are used by this skill.\n\nEach agent should be configured to use a distinct model in your OpenCode config (for true multi-model reviews). If they all point to the same model, the council will run but not be multi-model.\n\n**Permissions (recommended):**\n- `read`: allow\n- `webfetch`: allow (optional)\n- `edit`: deny\n- `bash`: deny\n- `call_omo_agent`: deny\n- `background_task`: allow (only for the orchestrator)\n\nDo not edit `oh-my-opencode.json` from this repo; document this setup for the user.\n\n## Inputs\n\n- Target input (default: `.speclet/draft.md`)\n- Reviewer prompts in `skills/speclet-council/prompts/`\n\n## Outputs\n\n- `.speclet/council-session.md` (full audit log)\n- `.speclet/council-summary.md` (executive summary)\n- `.speclet/draft.review.md` (optional full review)\n\nNote: Always read existing artifact files before writing to avoid OpenCode validation errors.\nArtifacts are written regardless of target type.\n\n## Your Task\n\n### Step 1: Validate Target Exists\n\nDefault target is `.speclet/draft.md` unless a path is provided by the user.\n\nSupported targets:\n- `.speclet/draft.md`\n- `.speclet/spec.json`\n- `.speclet/tickets/<TICKET-ID>/draft.md` or `ticket-draft.md`\n\nIf missing, fail with:\n\n```\n❌ Missing target file\nProvide a valid draft/spec/ticket path before using speclet-council.\n```\n\n### Step 2: Load Reviewer Prompts\n\nUse these prompt templates:\n\n- `skills/speclet-council/prompts/reviewer-gpt.md`\n- `skills/speclet-council/prompts/reviewer-glm.md`\n\nEach prompt defines a strict output contract. Do not embed the target content in the orchestration prompt; instruct reviewers to read the target path directly. Orchestration prompts must be in English.\n\nIf the target is `spec.json`, reviewers should focus on story sizing, acceptance criteria verifiability, file lists, and non-goals.\nIf the target is a ticket draft, reviewers should focus on scope isolation, missing requirements, and ticket metadata alignment.\n\n### Step 3: Parallel Review Invocation\n\nLaunch all reviewers in parallel using `background_task`.\n\nPseudo-flow:\n\n```typescript\nfor (const reviewer of [\"gpt\", \"glm\"]) {\n  background_task(\n    agent=`plan-reviewer-${reviewer}`,\n    description=`Council Review: ${reviewer}`,\n    prompt=`[ENGLISH INSTRUCTIONS ONLY]\\n\\nPlease read the target file and respond in the target''s language.`\n  );\n}\n```\n\n**Defaults:**\n- Per-reviewer timeout: 500s\n- Max retries: 3\n- Backoff: 1s → 2s → 4s\n\n### Step 4: Classify Errors and Retry\n\nRetry only for transient errors. If using `background_task`, monitor the task status via `background_output`.\n\nTransient errors:\n- Timeouts\n- Rate limit / 429\n- Temporary network failures\n\nDo not retry for:\n- Invalid model name\n- Permission denied\n- Missing agent configuration\n\nIf a reviewer fails after max retries, record the failure and continue.\n\n### Step 5: Collect Results\n\nRetrieve each task with `background_output(task_id=\"...\", block=true)` and map it back to its reviewer.\nNote: Ensure you wait for all tasks to complete or timeout before proceeding to synthesis.\n\n**Review Status Header:**\nGenerate a summary table or list showing the status of each reviewer.\n- ✅ [Model Name] (Success)\n- ⚠️ [Model Name] (Failed/Timeout)\n\nIf **zero** reviewers succeed, fail with:\n\n```\n❌ All reviewers failed\nCheck API keys, network, or agent configuration. Try again or reduce the reviewer set.\n```\n\nIf any reviewer fails due to missing agent configuration, include a reminder to install or configure agents as described in the Setup section.\n\n### Step 6: Synthesize Council Review\n\nUse a specialized synthesis prompt to consolidate all issues using **Thematic Clustering**:\n1. **Thematic Grouping**: Identify shared problems across reviewers and group them under a single descriptive heading.\n2. **Nuance Preservation**: Do NOT delete unique details. If Reviewer A found a race condition and Reviewer B found a general concurrency limit in the same area, list them both as distinct perspectives under the same theme.\n3. **UX Formatting**: Use HTML `<details>` and `<summary>` tags. The summary MUST contain the severity (🔴 HIGH, 🟡 MEDIUM, 🟢 LOW) and the theme title.\n4. **Reviewer Attribution**: Clearly state which models identified each issue.\n5. **Language Parity**: Detect the language of the target and ensure the synthesis matches it exactly.\n6. **HTML Integrity**: Ensure all `<details>` blocks are correctly opened and closed.\n\nBefore writing any artifacts, read the existing files (if any) to avoid OpenCode read-before-write violations.\n\nWrite the full Council Review into `.speclet/draft.review.md` (not into the target file).\n\n```markdown\n# Council Review\n\n### Status\n- ✅ plan-reviewer-gpt\n- ✅ plan-reviewer-glm\n\n<details>\n<summary>🔴 HIGH: [Theme Title]</summary>\n\n- **Reviewers:** GPT, GLM\n- **Problem:** [Consolidated description of the theme]\n- **Specific Notes:**\n  - **Opus:** [Unique architectural nuance]\n  - **GPT:** [Unique implementation detail]\n- **Consolidated Suggestion:** [Actionable fix merging both suggestions]\n</details>\n```\n\n### Step 7: Write Council Artifacts\n\nWrite `.speclet/council-session.md` with a deterministic audit log (include the target path in the header):\n\n\n```markdown\n# Council Session\n\n- Target: path/to/target\n- Started: YYYY-MM-DD HH:MM\n- Finished: YYYY-MM-DD HH:MM\n\n## Review Tasks\n- plan-reviewer-gpt\n  - task_id: <id>\n  - status: success|failed\n  - attempts: N\n  - error: [if failed]\n- plan-reviewer-glm\n  - task_id: <id>\n  - status: success|failed\n  - attempts: N\n  - error: [if failed]\n\n## Critiques\n### plan-reviewer-gpt\n[raw critique output]\n\n### plan-reviewer-glm\n[raw critique output]\n```\n\nWrite `.speclet/council-summary.md` as an executive summary (read the file first if it already exists):\n\n```markdown\n# Council Summary\n\n- Total issues: N\n- By severity: High H / Medium M / Low L\n- By reviewer: gpt X / glm Y\n\n## Decisions\n- Accepted: [list]\n- Rejected: [list]\n- Deferred: [list]\n\n## Draft Changes\n- Council Review saved to .speclet/draft.review.md\n```\n\n### Step 8: Git Commit Rule\n\nDo not create commits unless the user explicitly asks.\n\n### Step 9: Dry-Run Mode\n\nWhen invoked with `--dry-run`:\n- Do not call external models\n- Use mocked reviewer outputs embedded in the skill\n- Still write council-session.md, council-summary.md, and draft.review.md\n\nUse this to validate the workflow without API costs.\n\n## Notes\n\n- This skill never modifies the target file; use /speclet-consolidate to merge accepted feedback when reviewing drafts.\n- **English-First Protocol:** Internal orchestration prompts and background task instructions are in English for reliability, but final user-facing output matches the target''s language.\n- Webfetch policies can only be enforced via reviewer prompts or disabled in agent config.\n"},"lastSynced":"2026-03-08T02:05:32.195Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated validation and thematic clustering capabilities for draft, spec, or ticket inputs.","zh":"适用于需要自动验证和主题聚类功能的代码审查代理，用于草稿、规格或票据输入。","ja":"コードレビュー代理が自動バリデーションとテーマクラスタリング機能を必要とする場合に最適です。ドラフト、仕様、またはチケット入力用です。","ko":"자동 검증 및 주제 클러스터링 기능이 필요한 코드 리뷰 에이전트에 적합합니다. 초안, 사양 또는 티켓 입력에 사용됩니다.","es":"Perfecto para agentes de revisión de código que necesitan validación automatizada y capacidades de agrupación temática para borradores, especificaciones o entradas de tickets.","fr":"Parfait pour les agents de revue de code nécessitant une validation automatisée et des capacités de regroupement thématique pour les brouillons, spécifications ou entrées de tickets.","de":"Perfekt für Code-Review-Agents, die eine automatisierte Überprüfung und thematische Clustering-Funktionen für Entwürfe, Spezifikationen oder Ticket-Eingaben benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de validação automatizada e capacidades de clusterização temática para entradas de rascunho, especificação ou bilhete.","ru":"Идеально подходит для агентов проверки кода, требующих автоматической проверки и возможностей тематической кластеризации для черновых, спецификаций или билетных входных данных.","ar":"مثالي لعمليات المراجعة البرمجية التي تحتاج إلى التحقق الآلي وقدرات التجميع المواضيعي لمدخلات المسودة أو المواصفة أو التذكرة."},"recommendation":{"en":"Empowers agents to invoke parallel reviewers like GPT and GLM with per-reviewer timeouts and retries, generating audit artifacts and review status headers, and synthesizing feedback using thematic clustering and collapsible HTML tags for files like `draft.md`, `spec.json`, and ticket files.","zh":"赋予代理以并行方式调用审查者，如GPT和GLM，具有每个审查者的超时和重试，生成审计工件和审查状态头，并使用主题聚类和可折叠的HTML标签合成反馈，适用于`draft.md`、`spec.json`和票据文件等。","ja":"GPTやGLMのようなレビューアーを並列に呼び出して、タイムアウトやリトライを実行し、監査アーティファクトやレビュー状態ヘッダーを生成し、テーマクラスタリングや折りたたみ可能なHTMLタグを使用してフィードバックを合成します。`draft.md`、`spec.json`、チケットファイルなどのファイルに使用します。","ko":"GPT 및 GLM과 같은 리뷰어를 병렬로 호출하여 타임아웃 및 재시도를 수행하고 감사 아티팩트 및 리뷰 상태 헤더를 생성하며 주제 클러스터링 및折りたたみ 가능한 HTML 태그를 사용하여 피드백을 생성합니다. `draft.md`, `spec.json`, 티켓 파일 등에 사용됩니다.","es":"Habilita a los agentes a invocar revisores paralelos como GPT y GLM con timeouts y reintentos por revisor, generando artefactos de auditoría y encabezados de estado de revisión, y sintetizando comentarios utilizando agrupación temática y etiquetas HTML plegables para archivos como `draft.md`, `spec.json` y archivos de tickets.","fr":"Permet aux agents d''invoker des relecteurs parallèles comme GPT et GLM avec des timeouts et des reprises par relecteur, générant des artefacts d''audit et des en-têtes de statut de revue, et synthétisant des commentaires en utilisant le regroupement thématique et des balises HTML pliables pour des fichiers comme `draft.md`, `spec.json` et des fichiers de tickets.","de":"Ermöglicht es Agenten, parallele Überprüfer wie GPT und GLM mit Zeitlimits und Wiederholungen pro Überprüfer aufzurufen, Audit-Artefakte und Überprüfungsstatus-Header zu generieren und Feedback mithilfe thematischer Clustering und klappbarer HTML-Tags für Dateien wie `draft.md`, `spec.json` und Ticket-Dateien zu synthetisieren.","pt":"Habilita agentes a invocar revisores paralelos como GPT e GLM com tempos limite e retries por revisor, gerando artefatos de auditoria e cabeçalhos de status de revisão, e sintetizando feedback usando clusterização temática e tags HTML collapsíveis para arquivos como `draft.md`, `spec.json` e arquivos de bilhete.","ru":"Позволяет агентам вызывать параллельных рецензентов, таких как GPT и GLM, с таймаутами и повторами для каждого рецензента, генерируя артефакты аудита и заголовки статуса проверки, а также синтезируя обратную связь с помощью тематической кластеризации и сворачиваемых тегов HTML для файлов, таких как `draft.md`, `spec.json` и билетные файлы.","ar":"تمكن العميل من استدعاء مراجعين متوازيين مثل GPT و GLM مع مهلات زمنية و إعادة المحاولة لكل مراجع، وتوليد مستندات تدقيق و عناوين حالة المراجعة، وأيضا توليد反馈 باستخدام التجميع المواضيعي و علامات HTML القابلة للطي لملفات مثل `draft.md` و `spec.json` وملفات التذكرة."},"useCases":{"en":["Automating code review for draft and spec files","Generating audit artifacts like `.speclet/council-session.md`","Invoking parallel reviewers with retries for robust feedback"],"zh":["自动化草稿和规格文件的代码审查","生成监审文件，如`.speclet/council-session.md`","调用具有重试的并行审查者以获得强大的反馈"],"ja":["ドラフトと仕様ファイルのコードレビューを自動化する","監査ファイルを生成する、たとえば`.speclet/council-session.md`","リトライを伴う並列レビューアーを呼び出して強力なフィードバックを得る"],"ko":["초안 및 사양 파일의 코드 리뷰를 자동화하는","감사 파일을 생성하는, 예를 들어 `.speclet/council-session.md`","재시도를 포함한 병렬 리뷰어를 호출하여 강력한 피드백을 얻는"],"es":["Automatizar la revisión de código para archivos de borrador y especificación","Generar artefactos de auditoría como `.speclet/council-session.md`","Invocar revisores paralelos con reintentos para obtener comentarios robustos"],"fr":["Automatiser la revue de code pour les fichiers de brouillon et de spécification","Générer des artefacts d''audit comme `.speclet/council-session.md`","Invoker des relecteurs parallèles avec des reprises pour obtenir des commentaires robustes"],"de":["Automatisierung der Code-Überprüfung für Entwurfs- und Spezifikationsdateien","Erzeugen von Audit-Artefakten wie `.speclet/council-session.md`","Aufrufen paralleler Überprüfer mit Wiederholungen für robustes Feedback"],"pt":["Automatizar a revisão de código para arquivos de rascunho e especificação","Gerar artefatos de auditoria como `.speclet/council-session.md`","Invocar revisores paralelos com retries para feedback robusto"],"ru":["Автоматизировать проверку кода для черновых и спецификаций файлов","Генерировать артефакты аудита, такие как `.speclet/council-session.md`","Вызывать параллельных рецензентов с повторами для прочной обратной связи"],"ar":["أتمتة عملية المراجعة البرمجية لملفات المسودة والمواصفة","توليد مستندات تدقيق مثل `.speclet/council-session.md`","استدعاء مراجعين متوازيين مع إعادة المحاولة لتعزيز الرد"]},"limitations":{"en":["Requires input files like `draft.md`, `spec.json`, or ticket files to exist","Dependent on GPT and GLM reviewers for feedback generation","Needs filesystem access to write audit artifacts"],"zh":["需要输入文件，如`draft.md`、`spec.json`或票据文件，存在","依赖GPT和GLM审查者生成反馈","需要文件系统访问权限来写入审计文件"],"ja":["入力ファイルが必要、たとえば`draft.md`、`spec.json`、またはチケットファイル","GPTやGLMのようなレビューアーに依存してフィードバックを生成する","監査ファイルを書き込むためにファイルシステムへのアクセスが必要"],"ko":["입력 파일이 필요, 예를 들어 `draft.md`, `spec.json`, 또는 티켓 파일","GPT 및 GLM과 같은 리뷰어에 의존하여 피드백을 생성하는","감사 파일을 작성하기 위해 파일 시스템에 대한 액세스가 필요함"],"es":["Requiere que existan archivos de entrada como `draft.md`, `spec.json` o archivos de tickets","Depende de los revisores GPT y GLM para la generación de comentarios","Necesita acceso al sistema de archivos para escribir artefactos de auditoría"],"fr":["Nécessite que des fichiers d''entrée comme `draft.md`, `spec.json` ou des fichiers de tickets existent","Dépend des relecteurs GPT et GLM pour la génération de commentaires","A besoin d''un accès au système de fichiers pour écrire des artefacts d''audit"],"de":["Benötigt die Existenz von Eingabedateien wie `draft.md`, `spec.json` oder Ticket-Dateien","Hängt von den Überprüfern GPT und GLM für die Feedback-Generierung ab","Benötigt Dateisystem-Zugriff, um Audit-Artefakte zu schreiben"],"pt":["Requer arquivos de entrada como `draft.md`, `spec.json` ou arquivos de bilhete para existir","Depende de revisores GPT e GLM para geração de feedback","Necessita de acesso ao sistema de arquivos para escrever artefatos de auditoria"],"ru":["Требует наличия входных файлов, таких как `draft.md`, `spec.json` или билетные файлы","Зависит от рецензентов GPT и GLM для генерации обратной связи","Требует доступа к файловой системе для записи артефактов аудита"],"ar":["يتطلب وجود ملفات إدخال مثل `draft.md` و `spec.json` وملفات التذكرة","يعتمد على مراجعي GPT و GLM لتوليد الرد","يحتاج إلى الوصول إلى نظام الملفات لكتابة مستندات التدقيق"]},"version":4},"contentHash":"663fae451a3968865fea2426f4a2b99bbc594d02a6335336acf83b4dedd6b3c0","qualityScore":60}');
