INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danielcastro-dev/speclet/speclet-council', 'speclet-council', 'danielcastro-dev', 'speclet', 'community', 'speclet-council danielcastro-dev speclet community The speclet-council skill automates code review by validating input files, invoking reviewers, and generating audit artifacts. It benefits developers by streamlining the review process. Speclet Council 是一个自动化审查和审计工具，使用 GPT 和 GLM 进行代码审查 Speclet Council は自動化レビューと監査ツールです。GPT と GLM を使用してコードをレビューします Speclet Council는 자동화 리뷰 및 감사 도구입니다. GPT와 GLM을 사용하여 코드를 리뷰합니다 speclet-council es una habilidad que permite la revisión de especificaciones y tickets mediante la invocación de revisores en paralelo y la generación de artefactos de auditoría speclet-council est une compétence qui permet la revue de spécifications et de tickets en invoquant des réviseurs en parallèle et en générant des artefacts d''audit speclet-council ist eine Fähigkeit, die die Überprüfung von Spezifikationen und Tickets ermöglicht, indem sie Überprüfer parallel aufruft und Audit-Artefakte generiert O Speclet Council é uma ferramenta de revisão de código que valida e emite artefatos de auditoria. Ele invoca dois revisores em paralelo e sintetiza feedback com clustering temático. Спеклет Совет - это инструмент для обзора кода, который проверяет и выдает артефакты аудита. Он вызывает двух рецензентов параллельно и синтезирует обратную связь с помощью тематического кластеринга. مجلس Speclet هو أداة مراجعة التعليمات البرمجية التي تعمل على التحقق وإصدار مستندات التدقيق. وهو يستدعي两个 مراجعين متوازيًا ويتخلف ملاحظات باستخدام التجميع المواضيعي how to use speclet-council speclet-council setup guide speclet-council alternative speclet-council vs automated code review tools speclet-council install what is speclet-council speclet-council for AI agents automated code review with speclet-council speclet-council tutorial Speclet Council AI 工具 自动化审查 代码审查 GPT GLM 并行审查 超时重试 审查状态头 Validates target input files such as draft.md, spec.json, or ticket files Invokes two reviewers, GPT and GLM, in parallel with per-reviewer timeouts and retries Generates a Review Status Header indicating succeeded or failed models Synthesizes feedback using thematic clustering and collapsible HTML tags Writes council-session.md files for audit and review purposes speclet-council is a skill that automates council reviews over drafts, specs, or tickets, emitting audit artifacts and providing feedback through thematic clustering.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blockscout/mcp-server/implementation-plan-review', 'community', 'blockscout', 'mcp-server', 'blockscout/mcp-server', 'implementation-plan-review', 0, 0, 60, '2026-03-08T01:57:15.385Z', '2026-03-08T02:05:45.158Z', 'bcf01d24e8de601d15506b9c13d66142a1d58f53677dc749f18548f93acb6f1e', '{"id":"blockscout/mcp-server/implementation-plan-review","name":"implementation-plan-review","description":{"en":"The implementation-plan-review skill wraps Blockscout APIs to expose blockchain data, helping developers review implementation plans for coverage and correctness. It benefits developers working with blockchain data and Model Context Protocol.","zh":"Implementation Plan Review 技术审查实现计划，确保其覆盖范围、正确性和代码库适配性，基于 Model Context Protocol 封装区块链数据","ja":"Implementation Plan Review 技術は、実装計画をレビューし、そのカバレッジ、正確性、コードベースの適合性を確認します。また、Model Context Protocol を使用してブロックチェーンデータを公開します","ko":"Implementation Plan Review 기술은 구현 계획을 검토하고 범위, 정확성 및 코드베이스 적합성을 확인하며 Model Context Protocol 기반의 블록체인 데이터를 노출합니다","es":"Revisa planes de implementación con implementation-plan-review, que utiliza Model Context Protocol y Blockscout APIs para exponer datos de blockchain","fr":"Révisez les plans de mise en œuvre avec implementation-plan-review, qui utilise Model Context Protocol et Blockscout APIs pour exposer des données de blockchain","de":"Überprüfen Sie Implementierungspläne mit implementation-plan-review, das Model Context Protocol und Blockscout APIs verwendet, um Blockchain-Daten zu exponieren","pt":"O agente Implementation-Plan-Review revisa planos de implementação para cobertura, correção e adequação à base de código atual, utilizando Blockscout APIs e Model Context Protocol.","ru":"ИИ Агент Implementation-Plan-Review проверяет планы реализации на предмет покрытия, правильности и соответствия текущей базе кода, используя Blockscout APIs и Model Context Protocol.","ar":"وكيل الذكاء الاصطناعي Implementation-Plan-Review يراجع خطط التنفيذ لتغطية الصواب والملاءمة للقاعدة الكود الحالية، مستخدماً Blockscout APIs وبروتوكول السياق النمطي"},"seo":{"title":{"en":"implementation-plan-review: Expert Code Review Setup Guid...","zh":"Implementation Plan Review 设置指南 - 基于 Model Context Protoc...","ja":"Implementation Plan Review 導入ガイド - Model Context Protocol...","ko":"Implementation Plan Review 설정 가이드 - Model Context Protoco...","es":"Guía de configuración de implementation-plan-review para ...","fr":"Guide de mise en œuvre de implementation-plan-review pour...","de":"Einrichtungsleitfaden für implementation-plan-review für ...","pt":"Guia de Configuração do Plano de Implementação com Model ...","ru":"Настройка ИИ Агента Implementation-Plan-Review: Руководст...","ar":"دليل إعداد خطة التنفيذ مع بروتوكول السياق النمطي"},"description":{"en":"Discover how to review implementation plans with precision using Model Context Protocol and Blockscout APIs. Learn to optimize your codebase today!","zh":"使用 Implementation Plan Review 技术，审查实现计划的覆盖范围、正确性和代码库适配性，基于 Model Context Protocol 封装区块链数据","ja":"Implementation Plan Review 技術を使用して、実装計画のカバレッジ、正確性、コードベースの適合性をレビューし、Model Context Protocol を使用したブロックチェーンデータを公開します","ko":"Implementation Plan Review 기술을 사용하여 구현 계획의 범위, 정확성 및 코드베이스 적합성을 검토하고 Model Context Protocol 기반의 블록체인 데이터를 노출합니다","es":"Aprende a revisar planes de implementación con implementation-plan-review, una herramienta de AI Agent que utiliza Model Context Protocol y Blockscout APIs","fr":"Découvrez comment réviser les plans de mise en œuvre avec implementation-plan-review, un outil d''AI Agent qui utilise Model Context Protocol et Blockscout APIs","de":"Erfahren Sie, wie Sie Implementierungspläne mit implementation-plan-review überprüfen, einem AI-Tool, das Model Context Protocol und Blockscout APIs verwendet","pt":"Aprenda a revisar planos de implementação com o agente de AI Implementation-Plan-Review, integrado ao Blockscout APIs e Model Context Protocol.","ru":"Откройте для себя возможности ИИ Агента Implementation-Plan-Review для проверки планов реализации, интегрированного с Blockscout APIs и Model Context Protocol.","ar":"اكتشف كيفية مراجعة خطط التنفيذ باستخدام وكيل الذكاء الاصطناعي Implementation-Plan-Review، المتكامل مع Blockscout APIs وبروتوكول السياق النمطي"},"definition":{"en":"implementation-plan-review is a skill that reviews implementation plans for coverage, correctness, and fit with the current codebase using Blockscout APIs and Model Context Protocol.","zh":"Implementation Plan Review 是一种技术，用于审查实现计划的覆盖范围、正确性和代码库适配性","ja":"Implementation Plan Review は、実装計画のカバレッジ、正確性、コードベースの適合性をレビューする技術です","ko":"Implementation Plan Review 는 구현 계획의 범위, 정확성 및 코드베이스 적합성을 검토하는 기술입니다","es":"Implementation-plan-review es una herramienta de AI Agent que revisa planes de implementación para cubrimiento, corrección y ajuste con la base de código actual","fr":"Implementation-plan-review est un outil d''AI Agent qui révise les plans de mise en œuvre pour la couverture, la correction et l''ajustement avec la base de code actuelle","de":"Implementation-plan-review ist ein AI-Tool, das Implementierungspläne für Abdeckung, Korrektheit und Anpassung an den aktuellen Codebestand überprüft","pt":"O que é Implementation-Plan-Review? É um agente de AI que revisa planos de implementação para garantir cobertura, correção e adequação.","ru":"Что такое Implementation-Plan-Review? Это ИИ Агент, проверяющий планы реализации на предмет покрытия, правильности и соответствия.","ar":"ما هو Implementation-Plan-Review؟ هو وكيل ذكاء اصطناعي يراجع خطط التنفيذ لضمان التغطية والصواب والملاءمة"},"features":{"en":["Wraps Blockscout APIs to expose blockchain data","Reviews implementation plans for coverage and correctness","Supports local file paths for implementation plans and issue/requirements","Fetches GitHub issues into local files using the bundled script","Requires gh auth and network access for GitHub issue fetching","Works with Model Context Protocol for optimized code review"],"zh":["封装 Blockscout APIs","基于 Model Context Protocol 公开区块链数据","支持本地文件路径和 GitHub 问题编号","使用 gh 脚本自动化 GitHub 问题获取"],"ja":["Blockscout APIs をラップする","Model Context Protocol を使用してブロックチェーンデータを公開する","ローカルファイルパスと GitHub の問題番号をサポートする","gh スクリプトを使用して GitHub の問題を自動取得する"],"ko":["Blockscout APIs封装","Model Context Protocol 기반의 블록체인 데이터 공개","로컬 파일 경로 및 GitHub 이슈 번호 지원","gh 스크립트를 사용한 GitHub 이슈 자동获取"],"es":["Revisión de planes de implementación para cubrimiento y corrección","Uso de Model Context Protocol para exponer datos de blockchain","Integración con Blockscout APIs para obtener datos de blockchain","Compatibilidad con GitHub para obtener números de problemas","Uso de scripts empaquetados para obtener archivos locales"],"fr":["Révision des plans de mise en œuvre pour la couverture et la correction","Utilisation de Model Context Protocol pour exposer des données de blockchain","Intégration avec Blockscout APIs pour obtenir des données de blockchain","Compatibilité avec GitHub pour obtenir des numéros de problèmes","Utilisation de scripts empaquetés pour obtenir des fichiers locaux"],"de":["Überprüfung von Implementierungsplänen für Abdeckung und Korrektheit","Verwendung von Model Context Protocol, um Blockchain-Daten zu exponieren","Integration mit Blockscout APIs, um Blockchain-Daten zu erhalten","Kompatibilität mit GitHub, um Problemmnummern zu erhalten","Verwendung von gebündelten Skripten, um lokale Dateien zu erhalten"],"pt":["Revisão de planos de implementação para cobertura e correção","Integração com Blockscout APIs para exposição de dados de blockchain","Utilização do Model Context Protocol para garantir adequação à base de código","Suporte a arquivos locais e issues do GitHub","Requisitos de autenticação do GitHub para acesso à rede"],"ru":["Проверка планов реализации на предмет покрытия и правильности","Интеграция с Blockscout APIs для предоставления данных блокчейна","Использование Model Context Protocol для обеспечения соответствия базе кода","Поддержка локальных файлов и issue GitHub","Требования аутентификации GitHub для доступа к сети"],"ar":["مراجعة خطط التنفيذ لتغطية الصواب","التكامل مع Blockscout APIs لتحميل بيانات السلسلة الكتلوية","استخدام بروتوكول السياق النمطي لضمان الملاءمة للقاعدة الكود","دعم الملفات المحلية وissues GitHub","متطلبات المصادقة من GitHub للوصول إلى الشبكة"]},"keywords":{"en":["how to use implementation-plan-review","implementation-plan-review alternative","implementation-plan-review setup guide","what is implementation-plan-review","implementation-plan-review vs code review tools","implementation-plan-review install","blockchain data review","Model Context Protocol tutorials","Blockscout APIs documentation"],"zh":["AIエージェント","Implementation Plan Review","Model Context Protocol","Blockscout APIs","区块链数据","代码库适配性","实现计划审查"],"ja":["AIエージェント","Implementation Plan Review","Model Context Protocol","Blockscout APIs","ブロックチェーンデータ","コードベースの適合性","実装計画レビュー"],"ko":["AI 에이전트","Implementation Plan Review","Model Context Protocol","Blockscout APIs","블록체인 데이터","코드베이스 적합성","구현 계획 검토"],"es":["herramientas de AI Agent","implementation-plan-review","Model Context Protocol","Blockscout APIs","desarrollo de blockchain","revisión de planes de implementación","github","CLI"],"fr":["outils d''AI Agent","implementation-plan-review","Model Context Protocol","Blockscout APIs","développement de blockchain","révision des plans de mise en œuvre","github","CLI"],"de":["AI-Tools","implementation-plan-review","Model Context Protocol","Blockscout APIs","Blockchain-Entwicklung","Überprüfung von Implementierungsplänen","github","CLI"],"pt":["Implementation-Plan-Review","Blockscout APIs","Model Context Protocol","revisão de plano de implementação","integração com GitHub","autenticação do GitHub","desenvolvimento de software","ferramentas de AI para desenvolvedores"],"ru":["Implementation-Plan-Review","Blockscout APIs","Model Context Protocol","проверка плана реализации","интеграция с GitHub","аутентификация GitHub","разработка программного обеспечения","инструменты ИИ для разработчиков"],"ar":["Implementation-Plan-Review","Blockscout APIs","بروتوكول السياق النمطي","مراجعة خطة التنفيذ","التكامل مع GitHub","مصادقة GitHub","تطوير البرمجيات","أدوات الذكاء الاصطناعي للمطورين"]}},"owner":"blockscout","repo":"mcp-server","repoPath":"blockscout/mcp-server","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.385Z","topics":[],"category":"community","skillMd":{"name":"implementation-plan-review","description":"Expert review of an implementation plan against a GitHub issue/enhancement description (provided as a local file or a GitHub issue URL) and the current repository codebase. Use when asked to critique a plan for correctness, completeness, codebase alignment, risks, and test/rollout readiness (do not implement).","bodyPreview":"# Implementation Plan Review (Expert)\n\nReview an implementation plan for coverage, correctness, and fit with the current codebase. Do not implement.\n\n## Inputs\n\n- Implementation plan: a local file path.\n- Issue/requirements: either (a) a local file path, or (b) a GitHub issue number (run from the target repo so `gh` resolves it).\n\nIf the user provides a GitHub issue number, prefer fetching it into a local file using the bundled script (requires `gh` auth and network access; otherwise ask for a l","body":"# Implementation Plan Review (Expert)\n\nReview an implementation plan for coverage, correctness, and fit with the current codebase. Do not implement.\n\n## Inputs\n\n- Implementation plan: a local file path.\n- Issue/requirements: either (a) a local file path, or (b) a GitHub issue number (run from the target repo so `gh` resolves it).\n\nIf the user provides a GitHub issue number, prefer fetching it into a local file using the bundled script (requires `gh` auth and network access; otherwise ask for a local issue description file):\n\n```bash\nbash .codex/skills/implementation-plan-review/scripts/fetch_github_issue.sh <issue-number> --out /tmp/issue.md\n```\n\nIf the script reports that `gh` is not authenticated (exit code `3`), ask the user to run:\n\n```bash\ngh auth login\n```\n\n## Workflow\n\n1) Ensure repo startup constraints are satisfied:\n   - In this repository, run `$codex-session-bootstrap` before doing any other work.\n\n2) Read the two inputs in full:\n   - Plan file\n   - Issue description file (or the fetched `/tmp/issue.md`)\n\n3) Apply strict versioning-comment policy:\n   - Do **not** request or suggest any version bump (package version, `server.json`, etc.) unless the **issue description explicitly requires** a version bump/release/publish/tag.\n   - Even if the plan changes externally-consumed surfaces (tool schemas, REST/OpenAPI, manifests), treat missing version bump steps as **intentional** unless the issue says otherwise.\n\n4) Validate codebase reality (start targeted, expand as needed):\n   - Start by finding referenced modules/configs/env vars/tests with `rg` (fast and low-noise).\n   - Prefer opening the minimal set of files *first* to confirm patterns and naming, but broaden freely if you suspect hidden coupling or cross-cutting behavior (e.g., shared helpers, config loading, response models, pagination, truncation).\n   - If the plan touches MCP tools, REST API, docs, or tests, cross-check relevant `.cursor/rules/*.mdc` guidance.\n   - If it improves confidence, use any other repo investigation strategy (e.g., inspect docs like `SPEC.md`/`API.md`, check tests, use `git blame`, or run unit tests/lint locally).\n\nSuggested commands (adapt as needed):\n\n```bash\nrg -n \"name_in_plan|function_in_plan|ENV_VAR_IN_PLAN\" -S .\nrg -n \"ToolResponse\\\\[|@mcp\\\\.tool\\\\(|log_tool_invocation\" blockscout_mcp_server -S\nrg -n \"ServerConfig\\\\(|BaseSettings\\\\(|BLOCKSCOUT_\" blockscout_mcp_server/config.py -S\nrg -n \"pytest\\\\.mark\\\\.integration|tests/integration|tests/tools\" tests -S\n```\n\n1) Produce the review in the required format (next section).\n\n## Required output format\n\nProduce a review with these sections:\n\n### 1) Understanding\n\n- Issue summary\n- Acceptance criteria (bulleted)\n\n### 2) Plan ↔ Requirements coverage\n\n- What is covered well\n- What is missing / ambiguous\n\n### 3) Codebase alignment\n\n- Key files/modules you inspected (with paths)\n- Assumptions in the plan that match the codebase\n- Assumptions that don’t match (explain and suggest correction)\n\n### 4) Review comments (actionable)\n\nProvide comments as a list. Each comment must include:\n\n- Severity: `Blocker | Major | Minor | Question | Nit`\n- Location: plan section/step + (when relevant) repo file/function/class\n- Problem: what’s wrong / missing\n- Recommendation: concrete change to the plan\n- Rationale: why it matters (bug risk / security / perf / maintainability)\n\n**Testing gaps rule:**\n\n- List every specific missing/incorrect test as an actionable comment in **§4**.\n- In **§6**, provide a consolidated checklist that references those items **without repeating full explanations**.\n\n### 5) Junior-dev readiness check\n\n- Missing prerequisites, commands, step ordering, “how to verify”\n- Where the plan needs more explicit detail\n\n### 6) Test & rollout strategy\n\n- Consolidated test checklist (Unit / Integration / E2E / Negative & security / Performance & regression), referencing §4 test comments\n- Migration/rollback plan if applicable\n- Feature flags / safe rollout suggestions if applicable\n\n## Review focus checklist (use as prompts, not new requirements)\n\n- Coverage: every acceptance criterion mapped to plan steps.\n- Codebase alignment: paths, module structure, naming, existing helpers and patterns.\n- Edge cases & compatibility: pagination, timeouts, empty results, truncation limits, backward compatibility.\n- Security: input validation, SSRF/DNS rebinding boundaries, secrets handling, logging redaction, auth assumptions.\n- Performance/scale: API call counts, caching, pagination strategy, long-running tasks/progress updates.\n- Ops/observability: error handling, logs, metrics/telemetry/analytics implications, rollout/rollback.\n- Versioning: only comment if explicitly required by the issue description; otherwise assume omission is intentional.\n"},"lastSynced":"2026-03-08T02:05:45.158Z","agentAnalysis":{"suitability":{"en":"Ideal for Blockchain Analysis Agents requiring advanced implementation plan review capabilities for coverage and correctness","zh":"适用于需要高级实施计划审查能力以确保覆盖范围和正确性的区块链分析代理","ja":"ブロックチェーン分析エージェントが実装計画のカバレッジと正しさを確認するための高度な実装計画のレビュー機能を必要とする場合に最適","ko":"구현 계획을 검토하여 범위와 정확성을 확인해야 하는 블록체인 분석 에이전트에 적합","es":"Ideal para agentes de análisis de Blockchain que requieren capacidades de revisión de planes de implementación avanzados para cobertura y corrección","fr":"Idéal pour les agents d''analyse de Blockchain nécessitant des capacités de révision de plans de mise en œuvre avancées pour la couverture et la correction","de":"Ideal für Blockchain-Analyse-Agents, die erweiterte Implementierungsplan-Überprüfungsfunktionen für Abdeckung und Korrektheit erfordern","pt":"Ideal para Agentes de Análise de Blockchain que requerem capacidades de revisão avançada de planos de implementação para cobertura e correção","ru":"Идеально для Агентов анализа блокчейна, требующих продвинутых возможностей проверки планов реализации для покрытия и правильности","ar":"مثالي للوكلاء تحليل البلوكشين الذين يتطلبون خطة تنفيذ متقدمة لمراجعة القدرات لتغطية الصواب"},"recommendation":{"en":"Empowers agents to review implementation plans for blockchain data, utilizing Blockscout APIs and Model Context Protocol, ensuring fit with the current codebase and validating correctness through comprehensive analysis of local files and GitHub issues","zh":"使代理能够利用Blockscout API和Model Context Protocol审查区块链数据的实施计划，确保与当前代码库的兼容性，并通过对本地文件和GitHub问题的全面分析验证正确性","ja":"エージェントがBlockscout APIとModel Context Protocolを利用してブロックチェーンデータの実装計画をレビューできるようにし、現在のコードベースとの適合性を確保し、ローカルファイルとGitHubの問題の包括的な分析を通じて正しさを検証する","ko":"에이전트가 블록체인 데이터의 구현 계획을 검토할 수 있도록 하여 Blockscout API와 Model Context Protocol을 활용하고, 현재 코드베이스와의 호환성을 보장하며, 로컬 파일과 GitHub 문제에 대한 포괄적인 분석을 통해 정확성을 검증","es":"Habilita a los agentes a revisar planes de implementación para datos de blockchain, utilizando las API de Blockscout y el Protocolo de Contexto de Modelo, asegurando la compatibilidad con el código base actual y validando la corrección a través de un análisis exhaustivo de archivos locales y problemas de GitHub","fr":"Permet aux agents de réviser les plans de mise en œuvre pour les données de blockchain, en utilisant les API Blockscout et le Protocole de Contexte de Modèle, en garantissant l''adéquation avec le code base actuel et en validant la correction grâce à une analyse exhaustive des fichiers locaux et des problèmes de GitHub","de":"Ermächtigt Agents, Implementierungspläne für Blockchain-Daten zu überprüfen, indem sie Blockscout-APIs und das Model Context Protocol verwenden, um die Übereinstimmung mit dem aktuellen Codebase sicherzustellen und die Korrektheit durch eine umfassende Analyse von lokalen Dateien und GitHub-Problemen zu überprüfen","pt":"Habilita agentes a revisar planos de implementação para dados de blockchain, utilizando Blockscout APIs e Protocolo de Contexto de Modelo, garantindo a compatibilidade com o código atual e validando a correção por meio de análise abrangente de arquivos locais e problemas do GitHub","ru":"Наделяет агентов возможностью проверки планов реализации для данных блокчейна, используя Blockscout API и Протокол контекста модели, обеспечивая соответствие текущей базе кода и проверяя правильность посредством всестороннего анализа локальных файлов и проблем GitHub","ar":"تمكين الوكلاء من مراجعة خطط التنفيذ لبيانات البلوكشين، باستخدام Blockscout APIs وبروتوكول سياق النموذج، وضمان ملاءمة مع قاعدة الشفرة الحالية والتحقق من الصحة من خلال تحليل شاملة للملفات المحلية ومشاكل GitHub"},"useCases":{"en":["Reviewing implementation plans for coverage and correctness","Validating blockchain data integration with Model Context Protocol","Debugging implementation plans against GitHub issues"],"zh":["审查实现计划以确保覆盖范围和正确性","使用Model Context Protocol验证区块链数据集成","调试实现计划以解决GitHub问题"],"ja":["カバレッジと正しさを確保するための実装計画のレビュー","Model Context Protocolを使用したブロックチェーンデータの統合の検証","GitHubの問題に対する実装計画のデバッグ"],"ko":["범위와 정확성을 확인하기 위한 구현 계획 검토","Model Context Protocol을 사용한 블록체인 데이터 통합 검증","GitHub 문제를 해결하기 위한 구현 계획 디버깅"],"es":["Revisar planes de implementación para cobertura y corrección","Validar la integración de datos de blockchain con el Protocolo de Contexto de Modelo","Depurar planes de implementación contra problemas de GitHub"],"fr":["Réviser les plans de mise en œuvre pour la couverture et la correction","Valider l''intégration des données de blockchain avec le Protocole de Contexte de Modèle","Déboguer les plans de mise en œuvre par rapport aux problèmes de GitHub"],"de":["Überprüfen von Implementierungsplänen für Abdeckung und Korrektheit","Überprüfen der Integration von Blockchain-Daten mit dem Model Context Protocol","Fehlerbehebung von Implementierungsplänen gegen GitHub-Probleme"],"pt":["Revisar planos de implementação para cobertura e correção","Validar integração de dados de blockchain com Protocolo de Contexto de Modelo","Depurar planos de implementação contra problemas do GitHub"],"ru":["Проверка планов реализации для покрытия и правильности","Проверка интеграции данных блокчейна с Протоколом контекста модели","Отладка планов реализации по отношению к проблемам GitHub"],"ar":["مراجعة خطط التنفيذ لتغطية الصواب","التحقق من صحة دمج بيانات البلوكشين مع بروتوكول سياق النموذج","تصحيح خطط التنفيذ مقابل مشاكل GitHub"]},"limitations":{"en":["Requires Blockscout API access","Needs `gh` authentication and network access for GitHub issue resolution","Limited to reviewing, not implementing, plans"],"zh":["需要Blockscout API访问","需要`gh`身份验证和网络访问以解决GitHub问题","仅限于审查，不实施计划"],"ja":["Blockscout APIへのアクセスが必要","GitHubの問題を解決するために`gh`の認証とネットワークアクセスが必要","計画のレビューのみ、実装は行わない"],"ko":["Blockscout API 액세스가 필요","GitHub 문제를 해결하려면 `gh` 인증 및 네트워크 액세스가 필요","계획 검토만 가능, 구현은 불가"],"es":["Requiere acceso a la API de Blockscout","Necesita autenticación `gh` y acceso a la red para la resolución de problemas de GitHub","Limitado a la revisión, no a la implementación, de planes"],"fr":["Nécessite un accès à l''API Blockscout","Nécessite une authentification `gh` et un accès au réseau pour la résolution des problèmes de GitHub","Limité à la révision, et non à la mise en œuvre, des plans"],"de":["Benötigt Zugriff auf die Blockscout-API","Benötigt `gh`-Authentifizierung und Netzwerkzugriff für die Lösung von GitHub-Problemen","Begrenzt auf die Überprüfung, nicht auf die Implementierung, von Plänen"],"pt":["Requer acesso à Blockscout API","Necessita de autenticação `gh` e acesso à rede para resolução de problemas do GitHub","Limitado à revisão, não à implementação, de planos"],"ru":["Требует доступа к Blockscout API","Требует аутентификации `gh` и доступа к сети для решения проблем GitHub","Ограничен проверкой, а не реализацией, планов"],"ar":["يتطلب الوصول إلى Blockscout API","يتطلب مصادقة `gh` ووصول إلى الشبكة لحل مشاكل GitHub","محدود بالمراجعة، وليس التنفيذ، الخطط"]},"version":4},"contentHash":"bcf01d24e8de601d15506b9c13d66142a1d58f53677dc749f18548f93acb6f1e","qualityScore":60}');
