INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('blockscout/mcp-server/implementation-plan-review', 'implementation-plan-review', 'blockscout', 'mcp-server', 'community', 'implementation-plan-review blockscout mcp-server community The implementation-plan-review skill wraps Blockscout APIs to expose blockchain data, helping developers review implementation plans for coverage and correctness. It benefits developers working with blockchain data and Model Context Protocol. Implementation Plan Review 技术审查实现计划，确保其覆盖范围、正确性和代码库适配性，基于 Model Context Protocol 封装区块链数据 Implementation Plan Review 技術は、実装計画をレビューし、そのカバレッジ、正確性、コードベースの適合性を確認します。また、Model Context Protocol を使用してブロックチェーンデータを公開します Implementation Plan Review 기술은 구현 계획을 검토하고 범위, 정확성 및 코드베이스 적합성을 확인하며 Model Context Protocol 기반의 블록체인 데이터를 노출합니다 Revisa planes de implementación con implementation-plan-review, que utiliza Model Context Protocol y Blockscout APIs para exponer datos de blockchain Révisez les plans de mise en œuvre avec implementation-plan-review, qui utilise Model Context Protocol et Blockscout APIs pour exposer des données de blockchain Überprüfen Sie Implementierungspläne mit implementation-plan-review, das Model Context Protocol und Blockscout APIs verwendet, um Blockchain-Daten zu exponieren O agente Implementation-Plan-Review revisa planos de implementação para cobertura, correção e adequação à base de código atual, utilizando Blockscout APIs e Model Context Protocol. ИИ Агент Implementation-Plan-Review проверяет планы реализации на предмет покрытия, правильности и соответствия текущей базе кода, используя Blockscout APIs и Model Context Protocol. وكيل الذكاء الاصطناعي Implementation-Plan-Review يراجع خطط التنفيذ لتغطية الصواب والملاءمة للقاعدة الكود الحالية، مستخدماً Blockscout APIs وبروتوكول السياق النمطي how to use implementation-plan-review implementation-plan-review alternative implementation-plan-review setup guide what is implementation-plan-review implementation-plan-review vs code review tools implementation-plan-review install blockchain data review Model Context Protocol tutorials Blockscout APIs documentation AIエージェント Implementation Plan Review Model Context Protocol Blockscout APIs 区块链数据 代码库适配性 实现计划审查 Wraps Blockscout APIs to expose blockchain data Reviews implementation plans for coverage and correctness Supports local file paths for implementation plans and issue/requirements Fetches GitHub issues into local files using the bundled script Requires gh auth and network access for GitHub issue fetching Works with Model Context Protocol for optimized code review implementation-plan-review is a skill that reviews implementation plans for coverage, correctness, and fit with the current codebase using Blockscout APIs and Model Context Protocol.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('akiojin/xLLM/gh-fix-ci', 'community', 'akiojin', 'xLLM', 'akiojin/xLLM', 'gh-fix-ci', 0, 0, 60, '2026-03-08T01:57:15.391Z', '2026-03-08T02:06:10.126Z', '94c0546d84a24daa25732db63c4d6f8102ef7a66085c6f261fcc57ffe31e1cf8', '{"id":"akiojin/xLLM/gh-fix-ci","name":"gh-fix-ci","description":{"en":"The gh-fix-ci skill automates CI fixes for GitHub repositories, inspecting PRs for failing checks, merge conflicts, and reviewer comments. It benefits developers by streamlining their workflow.","zh":"gh-fix-ci是一种自动化CI检查修复的工具，通过gh命令行工具检查PR的CI状态、合并冲突、更新分支要求等","ja":"gh-fix-ciは、CIチェックの修復を自動化するツールです。ghコマンドラインツールを使用してPRのCI状態、マージコンフリクト、ブランチ要件の更新などを確認します","ko":"gh-fix-ci는 CI 확인을 자동화하는 도구로 gh 명령줄 도구를 사용하여 PR의 CI 상태, 병합 충돌, 분기 요구 사항 업데이트 등을 확인합니다","es":"gh-fix-ci es una herramienta que inspecciona solicitudes de extracción para verificaciones de CI fallidas y propone un plan de reparación","fr":"gh-fix-ci est un outil qui inspecte les demandes d''extraction pour les vérifications de CI échouées et propose un plan de réparation","de":"gh-fix-ci ist ein Tool, das Pull-Requests auf fehlgeschlagene CI-Prüfungen überprüft und einen Reparaturplan vorschlägt","pt":"O gh-fix-ci é uma ferramenta que inspeciona PRs para erros de CI e propõe planos de correção","ru":"ИИ Агент gh-fix-ci - это инструмент, который проверяет PR на ошибки CI и предлагает планы их исправления","ar":"وحدة غ-فيكس-سي آي هي أداة تقوم بفحص الطلبات الجديدة لاكتشاف أخطاء سي آي وتقترح خططاً لتصحيحها"},"seo":{"title":{"en":"gh-fix-ci: Automated CI Fix Setup Guide | AI Agent Skill","zh":"gh-fix-ci CI检查修复设置指南","ja":"gh-fix-ci CIチェック修復ベストプラクティス","ko":"gh-fix-ci CI 확인 修复 가이드","es":"Guía de configuración para gh-fix-ci: Reparación de verif...","fr":"Guide de configuration pour gh-fix-ci : Réparation des vé...","de":"Konfigurationsleitfaden für gh-fix-ci: Reparatur von CI-P...","pt":"Guia de Configuração do gh-fix-ci para Correção de Erros ...","ru":"Настройка ИИ Агента gh-fix-ci для Исправления Ошибок CI","ar":"دليل إعداد وحدات غ-فيكس-سي آي لتصحيح أخطاء سي آي"},"description":{"en":"Streamline your GitHub workflow with gh-fix-ci. Learn how to automate CI fixes, resolve merge conflicts, and manage reviewer comments. Get started now!","zh":"使用gh-fix-ci自动化CI检查修复，提高代码质量和开发效率，了解更多","ja":"gh-fix-ciを使用してCIチェックの修復を自動化し、コード品質と開発効率を向上させる","ko":"gh-fix-ci를 사용하여 CI 확인을 자동화하고 코드 품질 및 개발 효율성을 향상시키는 방법","es":"Aprende a configurar gh-fix-ci para reparar verificaciones de CI fallidas en GitHub Actions y mejorar tus flujos de trabajo","fr":"Découvrez comment configurer gh-fix-ci pour réparer les vérifications de CI échouées dans GitHub Actions et améliorer vos flux de travail","de":"Erfahren Sie, wie Sie gh-fix-ci konfigurieren, um fehlgeschlagene CI-Prüfungen in GitHub Actions zu beheben und Ihre Workflows zu verbessern","pt":"Aprenda a configurar o gh-fix-ci para automatizar a correção de erros de CI em seus projetos GitHub com GitHub Actions","ru":"Узнайте, как настроить ИИ Агент gh-fix-ci для автоматизации исправления ошибок CI в ваших проектах GitHub с помощью GitHub Actions","ar":"تعرف على كيفية إعداد وحدات غ-فيكس-سي آي لآليّة تصحيح أخطاء سي آي في مشاريعك على جيثب باستخدام جيثب أكشنز"},"definition":{"en":"gh-fix-ci is a skill that automates GitHub CI fixes by inspecting PRs for issues and proposing a fix plan using the gh command.","zh":"gh-fix-ci是一种自动化CI检查修复的AI工具","ja":"gh-fix-ciは、CIチェックの修復を自動化するAIエージェントです","ko":"gh-fix-ci는 CI 확인을 자동화하는 AI 에이전트입니다","es":"gh-fix-ci es una herramienta de reparación de verificaciones de CI que utiliza GitHub Actions","fr":"gh-fix-ci est un outil de réparation de vérifications de CI qui utilise GitHub Actions","de":"gh-fix-ci ist ein Tool zur Reparatur von CI-Prüfungen, das GitHub Actions verwendet","pt":"O gh-fix-ci é uma ferramenta de automação que ajuda a corrigir erros de CI em projetos GitHub","ru":"ИИ Агент gh-fix-ci - это инструмент автоматизации, помогающий исправлять ошибки CI в проектах GitHub","ar":"وحدة غ-فيكس-سي آي هي أداة آليّة لمساعدة تصحيح أخطاء سي آي في مشاريع جيثب"},"features":{"en":["Inspects PRs for failing CI checks using GitHub Actions","Detects merge conflicts and updates branch requirements","Manages reviewer comments, including review summaries and inline comments","Proposes a fix plan using the plan skill and implements after approval","Resolves threads and notifies reviewers"],"zh":["自动化CI检查修复","检查PR的CI状态、合并冲突、更新分支要求","使用gh命令行工具","支持更新分支要求和合并冲突修复","支持代码审查和审查线程管理"],"ja":["CIチェックの修復を自動化","PRのCI状態、マージコンフリクト、ブランチ要件の更新を確認","ghコマンドラインツールを使用","ブランチ要件の更新とマージコンフリクトの修復をサポート","コードレビューとレビュースレッド管理をサポート"],"ko":["CI 확인을 자동화","PR의 CI 상태, 병합 충돌, 분기 요구 사항 업데이트를 확인","gh 명령줄 도구 사용","분기 요구 사항 업데이트와 병합 충돌 修复을 지원","코드 리뷰와 리뷰 스레드 관리를 지원"],"es":["Inspección de solicitudes de extracción para verificaciones de CI fallidas","Detección de conflictos de fusión","Actualización de requisitos de rama base","Análisis de comentarios de revisores y resúmenes de revisión","Implementación de un plan de reparación después de la aprobación explícita"],"fr":["Inspection des demandes d''extraction pour les vérifications de CI échouées","Détection de conflits de fusion","Mise à jour des exigences de branche de base","Analyse des commentaires des réviseurs et des résumés de révision","Mise en œuvre d''un plan de réparation après approbation explicite"],"de":["Überprüfung von Pull-Requests auf fehlgeschlagene CI-Prüfungen","Erkennung von Merge-Konflikten","Aktualisierung der Basisbranch-Anforderungen","Analyse von Reviewer-Kommentaren und Review-Zusammenfassungen","Umsetzung eines Reparaturplans nach expliziter Genehmigung"],"pt":["Inspeciona PRs para erros de CI com GitHub Actions","Propõe planos de correção para erros de CI","Implementa planos de correção após aprovação explícita","Resolve threads de revisão e notifica revisores","Verifica conflitos de mesclagem e requisitos de branch"],"ru":["Проверяет PR на ошибки CI с помощью GitHub Actions","Предлагает планы исправления ошибок CI","Реализует планы исправления после явного одобрения","Решает нити обзора и уведомляет обозревателей","Проверяет конфликты слияния и требования к ветке"],"ar":["تفحص الطلبات الجديدة لاكتشاف أخطاء سي آي باستخدام جيثب أكشنز","يقترح خططاً لتصحيح أخطاء سي آي","ينفذ خطط التصحيح بعد الموافقة الصريحة","يحلّ threads المراجعة ويُخطّئ المراجعين","يفحص صراعات الدمج ومتطلبات الفرع"]},"keywords":{"en":["how to use gh-fix-ci","gh-fix-ci setup guide","github actions ci fix","automate ci fixes","gh-fix-ci vs github actions","gh-fix-ci install","github pr checks","ci fix plan","github reviewer comments"],"zh":["gh-fix-ci","CI检查修复","自动化CI检查","gh命令行工具","代码质量","开发效率","AI工具","CI工具","代码审查"],"ja":["gh-fix-ci","CIチェック修復","自動化CIチェック","ghコマンドラインツール","コード品質","開発効率","AIエージェント","CIツール","コードレビュー"],"ko":["gh-fix-ci","CI 확인","자동화 CI 확인","gh 명령줄 도구","코드 품질","개발 효율성","AI 에이전트","CI 도구","코드 리뷰"],"es":["gh-fix-ci","reparación de verificaciones de CI","GitHub Actions","solicitudes de extracción","conflictos de fusión","revisores de código","herramientas de desarrollo","integración continua"],"fr":["gh-fix-ci","réparation des vérifications de CI","GitHub Actions","demandes d''extraction","conflits de fusion","réviseurs de code","outils de développement","intégration continue"],"de":["gh-fix-ci","Reparatur von CI-Prüfungen","GitHub Actions","Pull-Requests","Merge-Konflikte","Code-Reviewer","Entwicklungstools","kontinuierliche Integration"],"pt":["gh-fix-ci","correção de erros de CI","GitHub Actions","automação de CI","ferramentas de desenvolvimento","github","ci/cd","devops"],"ru":["ИИ Агент gh-fix-ci","исправление ошибок CI","GitHub Actions","автоматизация CI","инструменты разработки","github","ci/cd","devops","ИИ Агенты"],"ar":["وحدة غ-فيكس-سي آي","تصحيح أخطاء سي آي","جيثب أكشنز","آليّة سي آي","أدوات التطوير","جيثب","سي آي/سي دي","ديفأوبس","وحدات الذكاء الاصطناعي"]}},"owner":"akiojin","repo":"xLLM","repoPath":"akiojin/xLLM","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.391Z","topics":[],"category":"community","skillMd":{"name":"gh-fix-ci","description":"Inspect GitHub PR for CI failures, merge conflicts, update-branch requirements, reviewer comments, change requests, and unresolved review threads. Create fix plans and implement after user approval. Resolve review threads and notify reviewers after fixes.","bodyPreview":"# Gh PR Checks Plan Fix\n\n## Overview\n\nUse gh to inspect PRs for:\n\n- Failing CI checks (GitHub Actions)\n- Merge conflicts\n- Update Branch requirements (base branch advanced)\n- Reviewer comments (review summaries, inline comments, issue comments)\n- Change Requests from reviewers\n- Unresolved review threads\n\nThen propose a fix plan, implement after explicit approval, and optionally resolve threads and notify reviewers.\n\n- Depends on the `plan` skill for drafting and approving the fix plan.\n\nPrereq:","body":"# Gh PR Checks Plan Fix\n\n## Overview\n\nUse gh to inspect PRs for:\n\n- Failing CI checks (GitHub Actions)\n- Merge conflicts\n- Update Branch requirements (base branch advanced)\n- Reviewer comments (review summaries, inline comments, issue comments)\n- Change Requests from reviewers\n- Unresolved review threads\n\nThen propose a fix plan, implement after explicit approval, and optionally resolve threads and notify reviewers.\n\n- Depends on the `plan` skill for drafting and approving the fix plan.\n\nPrereq: ensure `gh` is authenticated (for example, run `gh auth login` once), then run `gh auth status` with escalated permissions (include workflow/repo scopes) so `gh` commands succeed.\n\n## Inputs\n\n- `repo`: path inside the repo (default `.`)\n- `pr`: PR number or URL (optional; defaults to current branch PR)\n- `mode`: inspection mode (`checks`, `conflicts`, `reviews`, `all`)\n- `max-review-comments`: max reviewer comments to list per category\n- `required-only`: limit CI checks to required checks only (uses `gh pr checks --required`)\n- `gh` authentication for the repo host\n\n## Quick start\n\n```bash\n# Inspect all (CI, conflicts, reviews) - default mode\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\"\n\n# CI checks only\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --mode checks\n\n# Conflicts only\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --mode conflicts\n\n# Reviews only (Change Requests + Unresolved Threads)\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --mode reviews\n\n# JSON output\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --json\n\n# Required checks only (if gh supports --required)\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --mode checks --required-only\n\n# Limit review comment output\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --max-review-comments 30\n\n# Resolve all unresolved threads after fixing\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --resolve-threads\n\n# Add a comment to notify reviewers\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --add-comment \"Fixed all issues. Please re-review.\"\n```\n\n## Workflow\n\n1. **Verify gh authentication.**\n   - Run `gh auth status` in the repo with escalated scopes (workflow/repo).\n   - If unauthenticated, ask the user to log in before proceeding.\n\n2. **Resolve the PR.**\n   - Prefer the current branch PR: `gh pr view --json number,url`.\n   - If the user provides a PR number or URL, use that directly.\n\n3. **Inspect based on mode:**\n\n   **Conflicts Mode (`--mode conflicts`):**\n   - Check `mergeable` and `mergeStateStatus` fields.\n   - If `CONFLICTING` or `DIRTY`, report conflict details.\n   - If `BEHIND`, report that the base branch advanced and an Update Branch is required.\n   - Suggest resolution steps: fetch base branch, merge/rebase, resolve conflicts.\n\n   **Reviews Mode (`--mode reviews`):**\n   - Fetch reviews with `CHANGES_REQUESTED` state.\n   - Fetch unresolved review threads using GraphQL.\n   - Fetch reviewer comments (review summaries, inline review comments, issue comments).\n   - Display reviewer, comment body, file path, and line number.\n   - Decide if reviewer feedback requires action (any change request, unresolved thread, or reviewer comment).\n\n   **Checks Mode (`--mode checks`):**\n   - Run bundled script to inspect failing CI checks.\n   - Add `--required-only` to limit output to required checks when supported.\n   - Fetch GitHub Actions logs and extract failure snippets.\n   - For external checks (Buildkite, etc.), report URL only.\n\n   **All Mode (`--mode all`):**\n   - Run all inspections above.\n\n4. **Summarize issues for the user.**\n   - Provide clear summary of all detected issues.\n   - Call out conflicts, change requests, unresolved threads, and CI failures.\n\n5. **Create a plan.**\n   - Use the `plan` skill to draft a fix plan and request approval.\n\n6. **Implement after approval.**\n   - Apply the approved plan, summarize diffs/tests.\n\n7. **Resolve review threads (optional).**\n   - With `--resolve-threads`, resolve all unresolved threads via GraphQL mutation.\n   - Requires `Repository Permissions > Contents: Read and Write`.\n\n8. **Notify reviewers (optional).**\n   - With `--add-comment \"message\"`, post a comment to the PR.\n   - Useful for notifying reviewers that issues have been addressed.\n\n9. **Recheck status.**\n   - After changes, suggest re-running `gh pr checks` to confirm.\n\n## Bundled Resources\n\n### scripts/inspect_pr_checks.py\n\nComprehensive PR inspection tool. Exits non-zero when issues remain.\n\n**Arguments:**\n\n| Argument | Default | Description |\n|----------|---------|-------------|\n| `--repo` | `.` | Path inside the target Git repository |\n| `--pr` | (current) | PR number or URL |\n| `--mode` | `all` | Inspection mode: `checks`, `conflicts`, `reviews`, `all` |\n| `--max-lines` | 160 | Max lines for log snippets |\n| `--context` | 30 | Context lines around failure markers |\n| `--max-review-comments` | 50 | Max reviewer comments to list per category |\n| `--required-only` | false | Limit CI checks to required checks only |\n| `--json` | false | Emit JSON output |\n| `--resolve-threads` | false | Resolve unresolved review threads |\n| `--add-comment` | (none) | Add a comment to the PR |\n\n**Exit codes:**\n\n- `0`: No issues found\n- `1`: Issues detected or error occurred\n\n## New Features\n\n### Conflict Detection\n\nDetects merge conflicts via `mergeable` and `mergeStateStatus` fields.\n\n- `CONFLICTING` / `DIRTY`: Conflict detected\n- `BEHIND`: Base branch advanced; Update Branch required\n- `MERGEABLE` / `CLEAN`: No conflicts\n\n### Change Request Handling\n\nFetches reviews with `state == \"CHANGES_REQUESTED\"` and displays:\n\n- Reviewer name\n- Review body\n- Submission timestamp\n\n### Reviewer Comments\n\nFetches reviewer feedback beyond change requests:\n\n- Review summaries with comment bodies\n- Inline review comments (file/line)\n- PR issue comments\n- Marks review action required if any reviewer feedback exists\n\n### Unresolved Review Threads\n\nUses GraphQL to fetch threads where `isResolved == false`:\n\n- File path and line number\n- Thread ID (for resolution)\n- Comment author and body\n- Outdated status\n\n### Resolve Conversation\n\nUse `--resolve-threads` to mark threads as resolved via GraphQL mutation `resolveReviewThread`.\n\n**Required permissions:**\n\n- Fine-grained PAT: `Pull requests` + `Contents: Read and Write`\n- Classic PAT: `repo` scope\n\n### Reviewer Notification\n\nUse `--add-comment \"message\"` to post a summary comment to the PR after fixes.\n\n## Output Examples\n\n### Text Output\n\n```text\nPR #123: Comprehensive Check Results\n============================================================\n\nMERGE STATUS\n------------------------------------------------------------\nMergeable: CONFLICTING\nMerge State: DIRTY\nBase: main <- Head: feature/my-branch\nAction Required: Resolve conflicts before merging\n\nCHANGE REQUESTS\n------------------------------------------------------------\nFrom @reviewer1 (2025-01-15):\n  \"Please fix these issues...\"\n\nUNRESOLVED REVIEW THREADS\n------------------------------------------------------------\n[1] src/main.ts:42\n    Thread ID: PRRT_xxx123\n    @reviewer1: This needs refactoring...\n\nCI FAILURES\n------------------------------------------------------------\nCheck: build\nDetails: https://github.com/...\nFailure snippet:\n  Error: TypeScript compilation failed\n  ...\n============================================================\n```\n\n### JSON Output\n\n```json\n{\n  \"pr\": \"123\",\n  \"conflicts\": {\n    \"hasConflicts\": true,\n    \"mergeable\": \"CONFLICTING\",\n    \"mergeStateStatus\": \"DIRTY\",\n    \"baseRefName\": \"main\",\n    \"headRefName\": \"feature/my-branch\"\n  },\n  \"changeRequests\": [\n    {\n      \"id\": 123456,\n      \"reviewer\": \"reviewer1\",\n      \"body\": \"Please fix these issues...\",\n      \"submittedAt\": \"2025-01-15T12:00:00Z\"\n    }\n  ],\n  \"unresolvedThreads\": [\n    {\n      \"id\": \"PRRT_xxx123\",\n      \"path\": \"src/main.ts\",\n      \"line\": 42,\n      \"comments\": [\n        {\"author\": \"reviewer1\", \"body\": \"This needs refactoring\"}\n      ]\n    }\n  ],\n  \"ciFailures\": [\n    {\n      \"name\": \"build\",\n      \"status\": \"ok\",\n      \"logSnippet\": \"...\"\n    }\n  ]\n}\n```\n"},"lastSynced":"2026-03-08T02:06:10.126Z","agentAnalysis":{"suitability":{"en":"Perfect for GitHub Management Agents needing automated CI fix capabilities for streamlining developer workflows.","zh":"适用于需要自动化CI修复功能来简化开发人员工作流的GitHub管理代理。","ja":"GitHub Management Agentsが開発者のワークフローを簡素化するために自動化されたCI修復機能を必要とする場合に適しています。","ko":"개발자 워크플로를簡素化하기 위한 자동화된 CI 수정 기능이 필요한 GitHub 관리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Gestión de GitHub que necesitan capacidades de reparación de CI automatizadas para optimizar los flujos de trabajo de los desarrolladores.","fr":"Parfait pour les Agents de gestion de GitHub ayant besoin de capacités de correction de CI automatisées pour rationaliser les flux de travail des développeurs.","de":"Perfekt für GitHub-Management-Agents, die automatisierte CI-Fix-Fähigkeiten für die Optimierung der Entwickler-Workflows benötigen.","pt":"Perfeito para Agentes de Gerenciamento do GitHub que precisam de capacidades de correção de CI automatizadas para otimizar os fluxos de trabalho dos desenvolvedores.","ru":"Идеально подходит для агентов управления GitHub, которым необходимы автоматические возможности исправления CI для оптимизации рабочих процессов разработчиков.","ar":"مثالي للوكلاء إدارة جيت هاب الذين يحتاجون إلى قدرات إصلاحCI خود độngية لتسريع تدفقات العمل للمطورين."},"recommendation":{"en":"Empowers agents to inspect PRs for failing GitHub Actions checks, merge conflicts, and reviewer comments, then propose and implement fix plans using GitHub protocols and APIs, streamlining workflow with explicit approval and optional thread resolution and reviewer notification.","zh":"赋予代理检查PR的失败的GitHub Actions检查、合并冲突和审查者评论，然后使用GitHub协议和API提出和实施修复计划，简化工作流程，显示明确的批准和可选的线程解析和审查者通知。","ja":"エージェントがPRの失敗したGitHub Actionsのチェック、マージの競合、レビュアーのコメントを確認し、次にGitHubのプロトコルとAPIを使用して修正プランを提案して実施することで、ワークフローを簡素化し、明示的な承認とオプションのスレッドの解決とレビュアーの通知を提供する。","ko":"에이전트가 PR의 실패한 GitHub Actions 체크, 병합 충돌 및 리뷰어의 댓글을 조사한 다음 GitHub 프로토콜 및 API를 사용하여 수정 계획을 제안하고 구현하여 워크플ロー를 단순화하고 명시적인 승인 및 선택적 스레드 해결 및 리뷰어 알림을 제공합니다.","es":"Habilita a los agentes a inspeccionar solicitudes de extracción para comprobaciones de GitHub Actions con errores, conflictos de fusión y comentarios de revisores, y luego proponer e implementar planes de reparación utilizando protocolos y APIs de GitHub, racionalizando el flujo de trabajo con aprobación explícita y resolución de hilos opcional y notificación de revisores.","fr":"Permet aux agents d''inspecter les demandes d''extraction pour les vérifications de GitHub Actions ayant échoué, les conflits de fusion et les commentaires des relecteurs, puis de proposer et de mettre en œuvre des plans de correction en utilisant les protocoles et les API de GitHub, en rationalisant le flux de travail avec une approbation explicite et une résolution de fil et une notification de relecteur facultative.","de":"Ermächtigt Agenten, Pull-Requests auf fehlgeschlagene GitHub-Actions-Prüfungen, Merge-Konflikte und Reviewer-Kommentare zu überprüfen, und anschließend Reparaturpläne mithilfe von GitHub-Protokollen und APIs vorzuschlagen und umzusetzen, wodurch der Workflow mit expliziter Genehmigung und optionaler Threadauflösung und Reviewer-Benachrichtigung rationalisiert wird.","pt":"Permite que os agentes inspecionem PRs para verificações de ações do GitHub com falha, conflitos de mesclagem e comentários de revisores, então proponham e implementem planos de correção usando protocolos e APIs do GitHub, otimizando o fluxo de trabalho com aprovação explícita e resolução de thread opcional e notificação de revisor.","ru":"Наделяет агентов возможностью проверять PR на наличие неудачных проверок GitHub Actions, конфликтов слияния и комментариев рецензентов, а затем предлагать и реализовывать планы исправления с использованием протоколов и API GitHub, оптимизируя рабочий процесс с явным одобрением и необязательным решением проблемы и уведомлением рецензента.","ar":"تمكن الوكلاء من فحص طلبات السحب للتحقق من عمليات فحص إجراءات جيت هاب الفاشلة والتحديثات المتضاربة وتعليقات المراجعين، ثم يقترحون وينفذون خطط الإصلاح باستخدام بروتوكولات وواجهات برمجة تطبيقات جيت هاب، مع تسريع تدفق العمل بالموافقة الصريحة وإصلاح الخيط الاختياري وإعلام المراجع."},"useCases":{"en":["Automating CI fixes for GitHub repositories","Inspecting PRs for failing checks and merge conflicts","Resolving reviewer comments and change requests"],"zh":["自动化GitHub仓库的CI修复","检查PR的失败检查和合并冲突","解决审查者评论和更改请求"],"ja":["GitHubリポジトリのCI修正の自動化","PRの失敗したチェックとマージの競合の確認","レビュアーのコメントと変更リクエストの解決"],"ko":["GitHub 리포지토리의 CI 수정 자동화","PR의 실패한 체크 및 병합 충돌 확인","리뷰어의 댓글 및 변경 요청 해결"],"es":["Automatización de reparaciones de CI para repositorios de GitHub","Inspección de solicitudes de extracción para comprobaciones con errores y conflictos de fusión","Resolución de comentarios de revisores y solicitudes de cambios"],"fr":["Automatisation des corrections de CI pour les référentiels GitHub","Inspection des demandes d''extraction pour les vérifications ayant échoué et les conflits de fusion","Résolution des commentaires des relecteurs et des demandes de modification"],"de":["Automatisierung von CI-Reparaturen für GitHub-Repositorys","Überprüfung von Pull-Requests auf fehlgeschlagene Prüfungen und Merge-Konflikte","Auflösung von Reviewer-Kommentaren und Änderungsanfragen"],"pt":["Automatizar correções de CI para repositórios do GitHub","Inspecionar PRs para verificações com falha e conflitos de mesclagem","Resolver comentários de revisores e solicitações de alteração"],"ru":["Автоматизировать исправления CI для репозиториев GitHub","Проверять PR на наличие неудачных проверок и конфликтов слияния","Решать комментарии рецензентов и запросы на изменение"],"ar":["تأتمة إصلاحات CI لمستودعات جيت هاب","فحص طلبات السحب للبحث عن عمليات فحص فاشلة وتحديثات متضاربة","حل تعليقات المراجعين وطلبات التغيير"]},"limitations":{"en":["Depends on the `plan` skill for drafting and approving fix plans","Requires GitHub API access and repository permissions"],"zh":["依赖于`plan`技能来草拟和批准修复计划","需要GitHub API访问和仓库权限"],"ja":["修正プランの草案作成と承認に`plan`スキルに依存する","GitHub APIアクセスとリポジトリの権限が必要"],"ko":["수정 계획 초안 및 승인에 `plan` 스킬에 의존함","GitHub API 액세스 및 리포지토리 권한이 필요"],"es":["Depende de la habilidad `plan` para elaborar y aprobar planes de reparación","Requiere acceso a la API de GitHub y permisos de repositorio"],"fr":["Dépend de la compétence `plan` pour établir et approuver les plans de correction","Nécessite un accès à l''API de GitHub et des autorisations de référentiel"],"de":["Hängt von der Fähigkeit `plan` für die Erstellung und Genehmigung von Reparaturplänen ab","Benötigt GitHub-API-Zugriff und Repository-Berechtigungen"],"pt":["Depende da habilidade `plan` para elaborar e aprovar planos de correção","Exige acesso à API do GitHub e permissões de repositório"],"ru":["Зависит от навыка `plan` для составления и утверждения планов исправления","Требует доступа к API GitHub и разрешений репозитория"],"ar":["يعتمد على مهارة `plan` لصياغة وموافقة خطط الإصلاح","يتطلب الوصول إلى واجهة برمجة تطبيقات جيت هاب وأذونات المستودع"]},"version":4},"contentHash":"94c0546d84a24daa25732db63c4d6f8102ef7a66085c6f261fcc57ffe31e1cf8","qualityScore":60}');
