INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('akiojin/xLLM/gh-fix-ci', 'gh-fix-ci', 'akiojin', 'xLLM', 'community', 'gh-fix-ci akiojin xLLM community The gh-fix-ci skill automates CI fixes for GitHub repositories, inspecting PRs for failing checks, merge conflicts, and reviewer comments. It benefits developers by streamlining their workflow. gh-fix-ci是一种自动化CI检查修复的工具，通过gh命令行工具检查PR的CI状态、合并冲突、更新分支要求等 gh-fix-ciは、CIチェックの修復を自動化するツールです。ghコマンドラインツールを使用してPRのCI状態、マージコンフリクト、ブランチ要件の更新などを確認します gh-fix-ci는 CI 확인을 자동화하는 도구로 gh 명령줄 도구를 사용하여 PR의 CI 상태, 병합 충돌, 분기 요구 사항 업데이트 등을 확인합니다 gh-fix-ci es una herramienta que inspecciona solicitudes de extracción para verificaciones de CI fallidas y propone un plan de reparación gh-fix-ci est un outil qui inspecte les demandes d''extraction pour les vérifications de CI échouées et propose un plan de réparation gh-fix-ci ist ein Tool, das Pull-Requests auf fehlgeschlagene CI-Prüfungen überprüft und einen Reparaturplan vorschlägt O gh-fix-ci é uma ferramenta que inspeciona PRs para erros de CI e propõe planos de correção ИИ Агент gh-fix-ci - это инструмент, который проверяет PR на ошибки CI и предлагает планы их исправления وحدة غ-فيكس-سي آي هي أداة تقوم بفحص الطلبات الجديدة لاكتشاف أخطاء سي آي وتقترح خططاً لتصحيحها how to use gh-fix-ci gh-fix-ci setup guide github actions ci fix automate ci fixes gh-fix-ci vs github actions gh-fix-ci install github pr checks ci fix plan github reviewer comments gh-fix-ci CI检查修复 自动化CI检查 gh命令行工具 代码质量 开发效率 AI工具 CI工具 代码审查 Inspects PRs for failing CI checks using GitHub Actions Detects merge conflicts and updates branch requirements Manages reviewer comments, including review summaries and inline comments Proposes a fix plan using the plan skill and implements after approval Resolves threads and notifies reviewers gh-fix-ci is a skill that automates GitHub CI fixes by inspecting PRs for issues and proposing a fix plan using the gh command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LixvYang/common-skills/doc-sync', 'community', 'LixvYang', 'common-skills', 'LixvYang/common-skills', 'doc-sync', 0, 0, 60, '2026-03-08T01:57:15.395Z', '2026-03-08T02:06:18.890Z', '7ca62ea69f6ae30fb5084fed5f90f8d0eba162406d5d4aec0f2cd074269bd5f1', '{"id":"LixvYang/common-skills/doc-sync","name":"doc-sync","description":{"en":"The doc-sync skill enforces a self-documenting architecture, automatically updating related documentation after code changes. This benefits developers by ensuring consistent and accurate documentation.","zh":"Doc-Sync 技能实现代码和文档的自动同步，通过自文档化架构确保文档的准确性和及时性","ja":"Doc-Sync は AIエージェントによる自動文書化を実現し、コードの変更が文書に自動的に反映されるようにします","ko":"Doc-Sync 는 문서 자동 동기화 기술을 통해 코드의 변경이 문서에 자동으로 반영되도록 합니다","es":"Doc-Sync es una habilidad que garantiza la sincronización de la documentación con los cambios de código, mejorando la eficiencia y reduciendo errores","fr":"Doc-Sync est une compétence qui assure la synchronisation de la documentation avec les modifications de code, améliorant l''efficacité et réduisant les erreurs","de":"Doc-Sync ist eine Fähigkeit, die die Synchronisation von Dokumentation und Code-Änderungen sicherstellt, die Effizienz verbessert und Fehler reduziert","pt":"O Doc-Sync é uma habilidade que impõe um padrão estrito de sincronização de documentação, onde as alterações no código atualizam automaticamente a documentação relacionada.","ru":"Doc-Sync - это навык, который обеспечивает строгий шаблон синхронизации документации, при котором изменения кода автоматически обновляют связанную документацию","ar":"Doc-Sync هو مهارة يفرض نمطًا صارمًا لدمج التوثيق ، حيث يتم تحديث الوثائق ذات الصلة تلقائيًا عند تغيير الكود"},"seo":{"title":{"en":"doc-sync: Automated Documentation Setup Guide | AI Agent ...","zh":"Doc-Sync 文档同步设置指南","ja":"Doc-Sync: AIエージェントによる自動文書化のベストプラクティス","ko":"Doc-Sync 문서 자동 동기화 설정 가이드","es":"Guía de configuración de Doc-Sync: Arquitectura de docume...","fr":"Guide de configuration de Doc-Sync: Architecture de docum...","de":"Doc-Sync Konfigurationsleitfaden: Selbst dokumentierende ...","pt":"Guia de Configuração do Doc-Sync: Sincronização de Docume...","ru":"ИИ Агент Doc-Sync: Руководство по Настройке Автоматическо...","ar":"دليل إعداد Doc-Sync: دمج التوثيق الآلي"},"description":{"en":"Discover how doc-sync enforces strict documentation synchronization. Learn to automate README.md updates and more. Get started with doc-sync today!","zh":"了解 Doc-Sync 文档同步技能的技术细节，自动更新代码和文档，实现自文档化架构","ja":"Doc-Sync を使用して AIエージェントによる自動文書化を実現し、コードと文書を同期させる","ko":"Doc-Sync 문서 자동 동기화 기술을 활용하여 코드와 문서를 실시간으로 업데이트 하세요","es":"Aprende a configurar Doc-Sync para mantener tu documentación actualizada con cambios de código. Mejora la eficiencia con nuestra guía de configuración","fr":"Découvrez comment configurer Doc-Sync pour maintenir votre documentation à jour avec les modifications de code. Améliorez l''efficacité avec notre guide de co...","de":"Erfahren Sie, wie Sie Doc-Sync konfigurieren, um Ihre Dokumentation mit Code-Änderungen aktuell zu halten. Verbessern Sie die Effizienz mit unserem Konfigura...","pt":"Aprenda a configurar o Doc-Sync para manter sua documentação atualizada automaticamente. Descubra como implementar a arquitetura de documentação self-documen...","ru":"Узнайте, как настроить Doc-Sync для автоматического обновления документации. Откройте для себя, как реализовать самодокументирующую архитектуру","ar":"تعرف على كيفية إعداد Doc-Sync لتحديث الوثائق تلقائيًا. اكتشف كيفية تنفيذ هندسة التوثيق الذاتي"},"definition":{"en":"doc-sync is a skill that implements a documentation synchronization pattern, where code changes trigger immediate updates to corresponding documentation, following a three-level structure.","zh":"Doc-Sync 是一种文档同步技能，通过自动更新代码和文档实现自文档化架构","ja":"Doc-Sync は、AIエージェントによる自動文書化を実現するスキルであり、コードの変更が文書に自動的に反映される","ko":"Doc-Sync 는 문서 자동 동기화 기술을 활용하여 코드와 문서를 동기화하는 스킬입니다","es":"Doc-Sync es una arquitectura de documentación automática que mantiene la documentación actualizada con cambios de código","fr":"Doc-Sync est une architecture de documentation auto-documentée qui maintient la documentation à jour avec les modifications de code","de":"Doc-Sync ist eine selbst dokumentierende Architektur, die die Dokumentation mit Code-Änderungen aktuell hält","pt":"O Doc-Sync é uma habilidade de sincronização de documentação que mantém a documentação atualizada automaticamente com as alterações no código","ru":"Doc-Sync - это навык синхронизации документации, который автоматически обновляет документацию при изменении кода","ar":"Doc-Sync هو مهارة دمج التوثيق التي تحتفظ بالتوثيق محدثًا تلقائيًا مع التغييرات في الكود"},"features":{"en":["Enforces a strict documentation synchronization pattern","Automatically updates README.md files after code changes","Follows a three-level documentation structure","Ensures functional, architectural, and implementation changes update corresponding documentation","Implements the principle that Documentation = Code"],"zh":["自动更新代码和文档","自文档化架构","README.md 根文档支持","三层文档结构","代码变化自动更新文档"],"ja":["コードと文書の自動同期","自文書化アーキテクチャ","README.md ルート文書のサポート","3 層文書構造","コードの変更が文書に自動的に反映される"],"ko":["코드와 문서의 자동 동기화","문서 자동 동기화 기술","README.md 루트 문서 지원","3단계 문서 구조","코드의 변경이 문서에 자동으로 반영되는 기능"],"es":["Estructura de documentación de tres niveles","Actualización automática de la documentación con cambios de código","Requerimiento de un archivo README.md en la raíz del proyecto","Sincronización de la documentación con la arquitectura del código","Implementación de un patrón de documentación consistente"],"fr":["Structure de documentation à trois niveaux","Mise à jour automatique de la documentation avec les modifications de code","Exigence d''un fichier README.md à la racine du projet","Synchronisation de la documentation avec l''architecture du code","Mise en œuvre d''un modèle de documentation cohérent"],"de":["Dreistufige