INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LixvYang/common-skills/doc-sync', 'doc-sync', 'LixvYang', 'common-skills', 'community', 'doc-sync LixvYang common-skills community The doc-sync skill enforces a self-documenting architecture, automatically updating related documentation after code changes. This benefits developers by ensuring consistent and accurate documentation. Doc-Sync 技能实现代码和文档的自动同步，通过自文档化架构确保文档的准确性和及时性 Doc-Sync は AIエージェントによる自動文書化を実現し、コードの変更が文書に自動的に反映されるようにします Doc-Sync 는 문서 자동 동기화 기술을 통해 코드의 변경이 문서에 자동으로 반영되도록 합니다 Doc-Sync es una habilidad que garantiza la sincronización de la documentación con los cambios de código, mejorando la eficiencia y reduciendo errores Doc-Sync est une compétence qui assure la synchronisation de la documentation avec les modifications de code, améliorant l''efficacité et réduisant les erreurs Doc-Sync ist eine Fähigkeit, die die Synchronisation von Dokumentation und Code-Änderungen sicherstellt, die Effizienz verbessert und Fehler reduziert O Doc-Sync é uma habilidade que impõe um padrão estrito de sincronização de documentação, onde as alterações no código atualizam automaticamente a documentação relacionada. Doc-Sync - это навык, который обеспечивает строгий шаблон синхронизации документации, при котором изменения кода автоматически обновляют связанную документацию Doc-Sync هو مهارة يفرض نمطًا صارمًا لدمج التوثيق ، حيث يتم تحديث الوثائق ذات الصلة تلقائيًا عند تغيير الكود how to use doc-sync doc-sync setup guide what is doc-sync doc-sync alternative doc-sync vs documentation tools doc-sync install automated documentation synchronization self-documenting architecture README.md automation Doc-Sync 文档同步 自文档化架构 自动更新代码 README.md 三层文档结构 AI工具 代码管理 Enforces a strict documentation synchronization pattern Automatically updates README.md files after code changes Follows a three-level documentation structure Ensures functional, architectural, and implementation changes update corresponding documentation Implements the principle that Documentation = Code doc-sync is a skill that implements a documentation synchronization pattern, where code changes trigger immediate updates to corresponding documentation, following a three-level structure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ncolex/oc33ren/bird', 'community', 'ncolex', 'oc33ren', 'ncolex/oc33ren', 'bird', 0, 0, 60, '2026-03-08T01:57:15.401Z', '2026-03-08T02:06:46.060Z', 'c7fa854f93c7ff74210f664bf29b6d4e64adfad85aad6241a981ef7234ab72d9', '{"id":"ncolex/oc33ren/bird","name":"bird","description":{"en":"The bird skill provides a fast X/Twitter CLI using GraphQL and cookie-based authentication, benefiting developers who need to interact with Twitter APIs. It offers various installation options, including npm, Homebrew, and one-shot commands.","zh":"Bird 是一个快速的 Twitter CLI 工具，使用 GraphQL 和 Cookie 身份验证。它支持多种安装方式，包括 npm、Homebrew 和一键安装","ja":"Bird は、GraphQL と Cookie 認証を使用した高速な Twitter CLI ツールです。npm、Homebrew、ワンショットインストールなど、複数のインストール方法をサポートしています","ko":"Bird는 GraphQL 및 쿠키 인증을 사용하는 빠른 Twitter CLI 도구입니다. npm, Homebrew 및 일회성 설치 등 여러 설치 방법을 지원합니다","es":"bird es una CLI de Twitter rápida que utiliza autenticación por cookie y soporte para GraphQL. Instala y configura bird para empezar a usarlo.","fr":"bird est une CLI Twitter rapide qui utilise l''authentification par cookie et prend en charge GraphQL. Installez et configurez bird pour commencer à l''utiliser.","de":"bird ist eine schnelle Twitter-CLI, die Cookie-Authentifizierung und GraphQL-Unterstützung verwendet. Installieren und konfigurieren Sie bird, um loszulegen.","pt":"O Bird é uma CLI de Fast X/Twitter que utiliza GraphQL e autenticação por cookie. Ele oferece uma forma rápida e fácil de interagir com a API do Twitter.","ru":"Bird - это быстрый CLI для Twitter, использующий GraphQL и аутентификацию по cookie. Он предоставляет быстрый и легкий способ взаимодействия с API Twitter.","ar":"طائر هو واجهة سطر أوامر سريعة لتويتر التي تستخدم GraphQL وتوثيق بواسطة كوكي. وهو يوفر طريقة سريعة وسهلة للتفاعل مع واجهة برمجة تطبيقات تويتر"},"seo":{"title":{"en":"bird: Fast X/Twitter CLI Setup Guide | AI Agent Skill","zh":"Bird 快速指南：使用 GraphQL 和 Cookie 身份验证的 Twitter CLI","ja":"Bird の設定方法：GraphQL と Cookie 認証を使用した Twitter CLI","ko":"Bird 설정 가이드: GraphQL 및 쿠키 인증을 사용하는 Twitter CLI","es":"Guía de configuración de bird: CLI de Twitter con autenti...","fr":"Guide de configuration de bird : CLI Twitter avec authent...","de":"Bird-Setup-Leitfaden: Twitter-CLI mit Cookie-Authentifizi...","pt":"Guia de Configuração do Bird: CLI de Fast X/Twitter com G...","ru":"Настройка Bird: Быстрый CLI для Twitter с GraphQL и аутен...","ar":"دليل إعداد طائر: واجهة سطر أوامر سريعة ل تويتر باستخدام G..."},"description":{"en":"Discover how to use bird, a fast X/Twitter CLI using GraphQL + cookie auth. Learn to install and authenticate with bird today!","zh":"了解 Bird 的安装、身份验证和功能，使用 GraphQL 和 Cookie 身份验证的 Twitter CLI 工具","ja":"Bird のインストール、認証、機能について学び、GraphQL と Cookie 認証を使用した Twitter CLI ツールを活用する","ko":"Bird 설치, 인증 및 기능에 대해 알아보고 GraphQL 및 쿠키 인증을 사용하는 Twitter CLI 도구를 사용해 보세요","es":"Descubre cómo configurar bird, una CLI de Twitter rápida con autenticación por cookie y soporte para GraphQL","fr":"Découvrez comment configurer bird, une CLI Twitter rapide avec authentification par cookie et prise en charge de GraphQL","de":"Erfahren Sie, wie Sie bird konfigurieren, eine schnelle Twitter-CLI mit Cookie-Authentifizierung und GraphQL-Unterstützung","pt":"Aprenda a configurar o Bird, uma CLI de Fast X/Twitter que utiliza GraphQL e autenticação por cookie para desenvolvedores","ru":"Узнайте, как настроить Bird, быстрый CLI для Twitter, использующий GraphQL и аутентификацию по cookie для разработчиков","ar":"تعلم كيفية إعداد طائر، واجهة سطر أوامر سريعة لتويتر التي تستخدم GraphQL وتوثيق بواسطة كوكي للمطورين"},"definition":{"en":"bird is a fast X/Twitter command-line interface (CLI) that utilizes GraphQL and cookie-based authentication for interacting with Twitter APIs.","zh":"Bird 是一个使用 GraphQL 和 Cookie 身份验证的 Twitter 命令行工具","ja":"Bird は、GraphQL と Cookie 認証を使用した Twitter のコマンドラインツールです","ko":"Bird는 GraphQL 및 쿠키 인증을 사용하는 Twitter 명령줄 도구입니다","es":"bird es una herramienta de línea de comandos de Twitter que utiliza autenticación por cookie y GraphQL","fr":"bird est un outil de ligne de commande Twitter qui utilise l''authentification par cookie et GraphQL","de":"bird ist ein Twitter-CLI-Tool, das Cookie-Authentifizierung und GraphQL verwendet","pt":"O Bird é uma ferramenta de linha de comando que utiliza GraphQL e autenticação por cookie para interagir com a API do Twitter","ru":"Bird - это инструмент командной строки, использующий GraphQL и аутентификацию по cookie для взаимодействия с API Twitter","ar":"طائر هو أداة سطر أوامر تستخدم GraphQL وتوثيق بواسطة كوكي للتفاعل مع واجهة برمجة تطبيقات تويتر"},"features":{"en":["Uses GraphQL for querying Twitter APIs","Employs cookie-based authentication for secure interactions","Supports installation via npm, Homebrew, and one-shot commands","Allows authentication using --auth-token, --ct0, or --cookie-source","Enables checking of active authentication sources with bird check","Supports Chrome profile directory specification for Arc/Brave browsers"],"zh":["使用 GraphQL 进行快速的 Twitter 数据查询","支持 Cookie 身份验证","多种安装方式，包括 npm、Homebrew 和一键安装","支持浏览器 Cookie 和手动 Token 身份验证","检查当前身份验证状态"],"ja":["GraphQL を使用した高速な Twitter データの問い合わせ","Cookie 認証のサポート","複数のインストール方法、npm、Homebrew、ワンショットインストールなど","ブラウザ Cookie と手動 Token 認証のサポート","現在の認証状態の確認"],"ko":["GraphQL을 사용한 빠른 Twitter 데이터 쿼리","쿠키 인증 지원","여러 설치 방법: npm, Homebrew 및 일회성 설치","브라우저 쿠키 및 수동 토큰 인증 지원","현재 인증 상태 확인"],"es":["Autenticación por cookie","Soporte para GraphQL","Instalación mediante npm o Homebrew","Uso de --auth-token o --ct0 para pasar cookies","Compatibilidad con Arc/Brave mediante --chrome-profile-dir","Comando de verificación de autenticación con bird check"],"fr":["Authentification par cookie","Prise en charge de GraphQL","Installation via npm ou Homebrew","Utilisation de --auth-token ou --ct0 pour passer les cookies","Compatibilité avec Arc/Brave via --chrome-profile-dir","Commande de vérification d''authentification avec bird check"],"de":["Cookie-Authentifizierung","GraphQL-Unterstützung","Installation über npm oder Homebrew","Verwendung von --auth-token oder --ct0 zum Übergeben von Cookies","Kompatibilität mit Arc/Brave über --chrome-profile-dir","Authentifizierungsprüfung mit bird check"],"pt":["Utiliza GraphQL para interagir com a API do Twitter","Autenticação por cookie para acesso seguro","Instalação fácil via npm ou Homebrew","Suporte a autenticação via token ou cookie","Comando ''check'' para verificar a fonte de autenticação ativa"],"ru":["Использует GraphQL для взаимодействия с API Twitter","Аутентификация по cookie для безопасного доступа","Легкая установка через npm или Homebrew","Поддержка аутентификации через токен или cookie","Команда ''check'' для проверки активного источника аутентификации"],"ar":["يستخدم GraphQL للتفاعل مع واجهة برمجة تطبيقات تويتر","توثيق بواسطة كوكي للوصول الآمن","تثبيت سهل عبر npm أو Homebrew","دعم التوثيق عبر رمز أو كوكي","أمر ''check'' للتحقق من مصدر التوثيق النشط"]},"keywords":{"en":["how to use bird","bird install","bird setup guide","what is bird","bird alternative","bird vs twurl","twitter cli","graphql twitter api","cookie auth twitter"],"zh":["Bird Twitter CLI","GraphQL Twitter","Cookie 身份验证","Twitter 命令行工具","快速 Twitter 数据查询","AIエージェント","Twitter API"],"ja":["Bird Twitter CLI","GraphQL Twitter","Cookie 認証","Twitter コマンドラインツール","高速な Twitter データの問い合わせ","AIエージェント","Twitter API"],"ko":["Bird Twitter CLI","GraphQL Twitter","쿠키 인증","Twitter 명령줄 도구","빠른 Twitter 데이터 쿼리","AI 에이전트","Twitter API"],"es":["bird CLI","Twitter CLI","autenticación por cookie","GraphQL","npm","Homebrew","herramientas de desarrollo","desarrollo de software","agentes de inteligencia artificial","herramientas de línea de comandos"],"fr":["bird CLI","Twitter CLI","authentification par cookie","GraphQL","npm","Homebrew","outils de développement","développement de logiciels","agents d''intelligence artificielle","outils de ligne de commande"],"de":["bird-CLI","Twitter-CLI","Cookie-Authentifizierung","GraphQL","npm","Homebrew","Entwicklertools","Software-Entwicklung","Künstliche-Intelligenz-Agenten","Befehlszeilen-Tools"],"pt":["bird cli","graphql twitter","autenticação por cookie","ferramenta de linha de comando","api twitter","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["bird cli","graphql twitter","аутентификация по cookie","инструмент командной строки","api twitter","разработка программного обеспечения","инструменты разработки"],"ar":["طائر واجهة سطر أوامر","graphql تويتر","توثيق بواسطة كوكي","أداة سطر أوامر","واجهة برمجة تطبيقات تويتر","تطوير البرمجيات","أدوات التطوير"]}},"owner":"ncolex","repo":"oc33ren","repoPath":"ncolex/oc33ren","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.401Z","topics":[],"category":"community","skillMd":{"name":"bird","description":"X/Twitter CLI for reading, searching, posting, and engagement via cookies.","bodyPreview":"# bird 🐦\n\nFast X/Twitter CLI using GraphQL + cookie auth.\n\n## Install\n\n```bash\n# npm/pnpm/bun\nnpm install -g @steipete/bird\n\n# Homebrew (macOS, prebuilt binary)\nbrew install steipete/tap/bird\n\n# One-shot (no install)\nbunx @steipete/bird whoami\n```\n\n## Authentication\n\n`bird` uses cookie-based auth.\n\nUse `--auth-token` / `--ct0` to pass cookies directly, or `--cookie-source` for browser cookies.\n\nRun `bird check` to see which source is active. For Arc/Brave, use `--chrome-profile-dir <path>`.\n\n##","body":"# bird 🐦\n\nFast X/Twitter CLI using GraphQL + cookie auth.\n\n## Install\n\n```bash\n# npm/pnpm/bun\nnpm install -g @steipete/bird\n\n# Homebrew (macOS, prebuilt binary)\nbrew install steipete/tap/bird\n\n# One-shot (no install)\nbunx @steipete/bird whoami\n```\n\n## Authentication\n\n`bird` uses cookie-based auth.\n\nUse `--auth-token` / `--ct0` to pass cookies directly, or `--cookie-source` for browser cookies.\n\nRun `bird check` to see which source is active. For Arc/Brave, use `--chrome-profile-dir <path>`.\n\n## Commands\n\n### Account & Auth\n\n```bash\nbird whoami                    # Show logged-in account\nbird check                     # Show credential sources\nbird query-ids --fresh         # Refresh GraphQL query ID cache\n```\n\n### Reading Tweets\n\n```bash\nbird read <url-or-id>          # Read a single tweet\nbird <url-or-id>               # Shorthand for read\nbird thread <url-or-id>        # Full conversation thread\nbird replies <url-or-id>       # List replies to a tweet\n```\n\n### Timelines\n\n```bash\nbird home                      # Home timeline (For You)\nbird home --following          # Following timeline\nbird user-tweets @handle -n 20 # User''s profile timeline\nbird mentions                  # Tweets mentioning you\nbird mentions --user @handle   # Mentions of another user\n```\n\n### Search\n\n```bash\nbird search \"query\" -n 10\nbird search \"from:steipete\" --all --max-pages 3\n```\n\n### News & Trending\n\n```bash\nbird news -n 10                # AI-curated from Explore tabs\nbird news --ai-only            # Filter to AI-curated only\nbird news --sports             # Sports tab\nbird news --with-tweets        # Include related tweets\nbird trending                  # Alias for news\n```\n\n### Lists\n\n```bash\nbird lists                     # Your lists\nbird lists --member-of         # Lists you''re a member of\nbird list-timeline <id> -n 20  # Tweets from a list\n```\n\n### Bookmarks & Likes\n\n```bash\nbird bookmarks -n 10\nbird bookmarks --folder-id <id>           # Specific folder\nbird bookmarks --include-parent           # Include parent tweet\nbird bookmarks --author-chain             # Author''s self-reply chain\nbird bookmarks --full-chain-only          # Full reply chain\nbird unbookmark <url-or-id>\nbird likes -n 10\n```\n\n### Social Graph\n\n```bash\nbird following -n 20           # Users you follow\nbird followers -n 20           # Users following you\nbird following --user <id>     # Another user''s following\nbird about @handle             # Account origin/location info\n```\n\n### Engagement Actions\n\n```bash\nbird follow @handle            # Follow a user\nbird unfollow @handle          # Unfollow a user\n```\n\n### Posting\n\n```bash\nbird tweet \"hello world\"\nbird reply <url-or-id> \"nice thread!\"\nbird tweet \"check this out\" --media image.png --alt \"description\"\n```\n\n**⚠️ Posting risks**: Posting is more likely to be rate limited; if blocked, use the browser tool instead.\n\n## Media Uploads\n\n```bash\nbird tweet \"hi\" --media img.png --alt \"description\"\nbird tweet \"pics\" --media a.jpg --media b.jpg  # Up to 4 images\nbird tweet \"video\" --media clip.mp4            # Or 1 video\n```\n\n## Pagination\n\nCommands supporting pagination: `replies`, `thread`, `search`, `bookmarks`, `likes`, `list-timeline`, `following`, `followers`, `user-tweets`\n\n```bash\nbird bookmarks --all                    # Fetch all pages\nbird bookmarks --max-pages 3            # Limit pages\nbird bookmarks --cursor <cursor>        # Resume from cursor\nbird replies <id> --all --delay 1000    # Delay between pages (ms)\n```\n\n## Output Options\n\n```bash\n--json          # JSON output\n--json-full     # JSON with raw API response\n--plain         # No emoji, no color (script-friendly)\n--no-emoji      # Disable emoji\n--no-color      # Disable ANSI colors (or set NO_COLOR=1)\n--quote-depth n # Max quoted tweet depth in JSON (default: 1)\n```\n\n## Global Options\n\n```bash\n--auth-token <token>       # Set auth_token cookie\n--ct0 <token>              # Set ct0 cookie\n--cookie-source <source>   # Cookie source for browser cookies (repeatable)\n--chrome-profile <name>    # Chrome profile name\n--chrome-profile-dir <path> # Chrome/Chromium profile dir or cookie DB path\n--firefox-profile <name>   # Firefox profile\n--timeout <ms>             # Request timeout\n--cookie-timeout <ms>      # Cookie extraction timeout\n```\n\n## Config File\n\n`~/.config/bird/config.json5` (global) or `./.birdrc.json5` (project):\n\n```json5\n{\n  cookieSource: [\"chrome\"],\n  chromeProfileDir: \"/path/to/Arc/Profile\",\n  timeoutMs: 20000,\n  quoteDepth: 1,\n}\n```\n\nEnvironment variables: `BIRD_TIMEOUT_MS`, `BIRD_COOKIE_TIMEOUT_MS`, `BIRD_QUOTE_DEPTH`\n\n## Troubleshooting\n\n### Query IDs stale (404 errors)\n\n```bash\nbird query-ids --fresh\n```\n\n### Cookie extraction fails\n\n- Check browser is logged into X\n- Try different `--cookie-source`\n- For Arc/Brave: use `--chrome-profile-dir`\n\n---\n\n**TL;DR**: Read/search/engage with CLI. Post carefully or use browser. 🐦\n"},"lastSynced":"2026-03-08T02:06:46.060Z","agentAnalysis":{"suitability":{"en":"Perfect for Social Media Agents needing fast Twitter API interactions via GraphQL and cookie-based authentication.","zh":"非常适合需要快速Twitter API交互的社交媒体代理，通过GraphQL和基于cookie的身份验证。","ja":"Twitter APIとの高速なやり取りが必要なソーシャルメディアエージェントに最適で、GraphQLとCookieベースの認証を使用します。","ko":"빠른 Twitter API 상호 작용이 필요한 소셜 미디어 에이전트에게 적합하며 GraphQL 및 쿠키 기반 인증을 통해 제공됩니다.","es":"Perfecto para Agentes de Medios Sociales que necesitan interacciones rápidas con la API de Twitter a través de GraphQL y autenticación basada en cookies.","fr":"Parfait pour les Agents de Médias Sociaux ayant besoin d''interactions rapides avec l''API Twitter via GraphQL et authentification basée sur les cookies.","de":"Perfekt für Social-Media-Agents, die schnelle Twitter-API-Interaktionen über GraphQL und cookie-basierte Authentifizierung benötigen.","pt":"Perfeito para Agentes de Mídia Social que necessitam de interações rápidas com a Twitter API via GraphQL e autenticação baseada em cookies.","ru":"Идеально для социальных медиа-агентов, которым необходимы быстрые взаимодействия с Twitter API через GraphQL и аутентификацию на основе файлов cookie.","ar":"مثالي للوكلاء الإعلاميين الاجتماعيين الذين يحتاجون إلى تفاعلات سريعة مع واجهة برمجة تطبيقات تويتر عبر GraphQL والتحقق من هوية المستخدم بالاعتماد على الكوكيز."},"recommendation":{"en":"Empowers agents to leverage GraphQL and cookie-based authentication for seamless Twitter API interactions, utilizing npm, Homebrew, or one-shot commands for flexible installation, and supporting various authentication methods including --auth-token, --ct0, and --cookie-source.","zh":"赋予代理使用GraphQL和基于cookie的身份验证来实现无缝的Twitter API交互，利用npm、Homebrew或一键命令进行灵活的安装，并支持包括--auth-token、--ct0和--cookie-source在内的各种身份验证方法。","ja":"エージェントがGraphQLとCookieベースの認証を使用してシームレスなTwitter APIのやり取りを行えるようにし、npm、Homebrew、またはワンショットコマンドを使用した柔軟なインストールを可能にし、--auth-token、--ct0、--cookie-sourceを含むさまざまな認証方法をサポートします。","ko":"에이전트가 GraphQL 및 쿠키 기반 인증을 사용하여無縫な Twitter API 상호 작용을 수행할 수 있도록 하며, npm, Homebrew 또는 일회성 명령을 사용한 유연한 설치를 지원하며, --auth-token, --ct0 및 --cookie-source를 포함한 다양한 인증 방법을 지원합니다.","es":"Habilita a los agentes a aprovechar GraphQL y la autenticación basada en cookies para interacciones sin problemas con la API de Twitter, utilizando npm, Homebrew o comandos de un solo disparo para una instalación flexible, y admitiendo varios métodos de autenticación, incluyendo --auth-token, --ct0 y --cookie-source.","fr":"Permet aux agents d''utiliser GraphQL et l''authentification basée sur les cookies pour des interactions fluides avec l''API Twitter, en utilisant npm, Homebrew ou des commandes à usage unique pour une installation flexible, et en prenant en charge diverses méthodes d''authentification, notamment --auth-token, --ct0 et --cookie-source.","de":"Ermächtigt die Agenten, GraphQL und cookie-basierte Authentifizierung für nahtlose Twitter-API-Interaktionen zu nutzen, indem npm, Homebrew oder Einmal-Befehle für eine flexible Installation verwendet werden und verschiedene Authentifizierungsmethoden unterstützt werden, einschließlich --auth-token, --ct0 und --cookie-source.","pt":"Habilita os agentes a aproveitar o GraphQL e a autenticação baseada em cookies para interações sem interrupções com a Twitter API, utilizando npm, Homebrew ou comandos de instalação flexíveis de um único disparo, e suportando vários métodos de autenticação, incluindo --auth-token, --ct0 e --cookie-source.","ru":"Наделяет агентов возможностью использовать GraphQL и аутентификацию на основе файлов cookie для бесшовных взаимодействий с Twitter API, используя npm, Homebrew или одноразовые команды для гибкой установки, и поддерживая различные методы аутентификации, включая --auth-token, --ct0 и --cookie-source.","ar":"تمكّن الوكلاء من الاستفادة من GraphQL والتحقق من هوية المستخدم بالاعتماد على الكوكيز لتفاعلات واجهة برمجة تطبيقات تويتر بدون انقطاع، باستخدام npm وHomebrew أو أوامر تثبيت مرنة ذات إطلاق واحد، ودعم طرق التحقق من الهوية المختلفة بما في ذلك --auth-token و --ct0 و --cookie-source."},"useCases":{"en":["Automating Twitter API requests using GraphQL","Authenticating with Twitter APIs via cookie-based auth","Debugging Twitter API issues with bird''s check command"],"zh":["使用GraphQL自动执行Twitter API请求","使用基于cookie的身份验证与Twitter API进行身份验证","使用鸟类检查命令调试Twitter API问题"],"ja":["GraphQLを使用してTwitter APIのリクエストを自動化する","Cookieベースの認証を使用してTwitter APIを認証する","鳥のチェックコマンドを使用してTwitter APIの問題をデバッグする"],"ko":["GraphQL을 사용하여 Twitter API 요청을 자동화하는 것","쿠키 기반 인증을 사용하여 Twitter API를 인증하는 것","새 체크 명령을 사용하여 Twitter API 문제를 디버깅하는 것"],"es":["Automatizar solicitudes de la API de Twitter utilizando GraphQL","Autenticar con las API de Twitter a través de autenticación basada en cookies","Depurar problemas de la API de Twitter con el comando bird''s check"],"fr":["Automatiser les requêtes d''API Twitter à l''aide de GraphQL","S''authentifier auprès des API Twitter via l''authentification basée sur les cookies","Déboguer les problèmes d''API Twitter avec la commande bird''s check"],"de":["Automatisierung von Twitter-API-Anfragen mit GraphQL","Authentifizierung bei Twitter-APIs über cookie-basierte Authentifizierung","Fehlerbehebung bei Twitter-API-Problemen mit dem Befehl bird''s check"],"pt":["Automatizar solicitações da Twitter API usando GraphQL","Autenticar com as Twitter APIs via autenticação baseada em cookies","Depurar problemas da Twitter API com o comando bird''s check"],"ru":["Автоматизировать запросы к Twitter API с помощью GraphQL","Аутентифицироваться с Twitter API через аутентификацию на основе файлов cookie","Отладить проблемы Twitter API с помощью команды bird''s check"],"ar":["أتمتة طلبات واجهة برمجة تطبيقات تويتر باستخدام GraphQL","التحقق من هوية المستخدم مع واجهات برمجة تطبيقات تويتر عن طريق التحقق من هوية المستخدم بالاعتماد على الكوكيز","تصحيح أخطاء واجهة برمجة تطبيقات تويتر باستخدام أمر bird''s check"]},"limitations":{"en":["Requires Twitter API access","Cookie-based authentication limitations apply","Dependent on npm, Homebrew, or bun for installation"],"zh":["需要Twitter API访问","基于cookie的身份验证的限制适用","依赖于npm、Homebrew或bun进行安装"],"ja":["Twitter APIへのアクセスが必要","Cookieベースの認証の制限が適用される","npm、Homebrew、またはbunに依存してインストールする"],"ko":["Twitter API 액세스가 필요함","쿠키 기반 인증의 제한 사항이 적용됨","npm, Homebrew 또는 bun에 의존하여 설치함"],"es":["Requiere acceso a la API de Twitter","Se aplican limitaciones de autenticación basada en cookies","Dependiente de npm, Homebrew o bun para la instalación"],"fr":["Nécessite un accès à l''API Twitter","Les limitations d''authentification basée sur les cookies s''appliquent","Dépend de npm, Homebrew ou bun pour l''installation"],"de":["Benötigt Zugriff auf die Twitter-API","Cookie-basierte Authentifizierungseinschränkungen gelten","Abhängig von npm, Homebrew oder bun für die Installation"],"pt":["Exige acesso à Twitter API","Limitações da autenticação baseada em cookies se aplicam","Dependente de npm, Homebrew ou bun para instalação"],"ru":["Требует доступа к Twitter API","Применяются ограничения аутентификации на основе файлов cookie","Зависит от npm, Homebrew или bun для установки"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات تويتر","تطبق قيود التحقق من هوية المستخدم بالاعتماد على الكوكيز","يعتمد على npm وHomebrew أو bun للتثبيت"]},"version":4},"contentHash":"c7fa854f93c7ff74210f664bf29b6d4e64adfad85aad6241a981ef7234ab72d9","qualityScore":60}');
