INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('synaptiai/agent-capability-standard/detect', 'detect', 'synaptiai', 'agent-capability-standard', 'community', 'detect synaptiai agent-capability-standard community The detect skill enables AI agents to scan data sources for specified patterns or entities, providing binary presence detection with associated signal strength. This capability benefits developers building reliable AI agent systems. Detect是一种AIエージェント能力，用于扫描数据源以确定指定模式、实体或条件的存在。它提供二进制检测和信号强度 Detectは、AIエージェントの構成可能な能力の一つで、データソースをスキャンして指定されたパターン、エンティティ、または条件の存在を決定するために使用されます。二進数検出と信号強度を提供します Detect는 AI 에이전트 능력 중 하나로, 데이터 소스를 검색하여 지정된 패턴, 엔티티 또는 조건의 존재를 결정하는 데 사용됩니다. 이진 감지 및 신호 강도를 제공합니다 La detección de patrones es una capacidad fundamental de los Agentes de IA, que permite identificar la presencia o ausencia de un patrón específico en los datos. La détection de modèles est une capacité fondamentale des outils d''IA, qui permet d''identifier la présence ou l''absence d''un modèle spécifique dans les données. Die Mustererkennung ist eine grundlegende Fähigkeit von KI-Agents, die es ermöglicht, die Anwesenheit oder Abwesenheit eines bestimmten Musters in den Daten zu identifizieren. O detect é uma capacidade de agente que permite scanner fontes de dados para determinar a presença de padrões ou condições específicas. Ele fornece uma determinação clara e booleana da presença ou ausência do padrão Detect - это способность агента, которая позволяет сканировать источники данных для определения наличия определенных шаблонов или условий. Он предоставляет четкое и булево определение наличия или отсутствия шаблона для ИИ Агентов يسمح Detect بفحص مصادر البيانات لتحديد وجود أنماط أو ظروف محددة. كما يقدم تحديدًا واضحًا وثنائيًا للوجود أو الغياب للأنماط للأدوات الذكية how to use detect for AI agents what is detect in AI detect alternative for binary presence detection detect vs pattern recognition detect install guide for AI agents detect setup tutorial for developers detect API for composable AI capabilities detect examples for grounded world modeling AIエージェント Detect 二进制检测 信号强度 AIエージェント能力标准 原子能力 数据源扫描 模式识别 Clear boolean determination of presence/absence Evidence-based confidence scores with false positive risk assessment Compatibility with schemas/output_schema.yaml Support for grounded world modeling with trust-aware conflict resolution Type-safe workflow DSL for composable AI agent capabilities Grounded Agency philosophy for structural agent reliability detect is a binary presence detection capability that determines whether a specified pattern or entity is present in a data source, with associated signal strength and evidence anchors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flight505/nano-banana/diagram', 'community', 'flight505', 'nano-banana', 'flight505/nano-banana', 'diagram', 0, 0, 60, '2026-03-08T01:57:15.402Z', '2026-03-08T02:06:48.989Z', 'b579e670caeddd77c186891d61153b20a2fbc0c0e8563344f5c5bcf8cf8dfa9a', '{"id":"flight505/nano-banana/diagram","name":"diagram","description":{"en":"The diagram skill generates technical diagrams using natural language descriptions, benefiting developers and technical writers. It leverages Nano Banana Pro for intelligent quality review.","zh":"Nano Banana Pro AI工具支持通过自然语言描述生成技术图表，具有智能迭代和质量审查功能","ja":"Nano Banana Pro AIエージェントは、自然言語で説明することでテクニカルダイアグラムを生成します","ko":"나노 바나나 프로 AI 에이전트는自然어로 기술 다이어그램을 설명하여 생성합니다","es":"Generación de diagramas técnicos con Nano Banana Pro, que utiliza inteligencia artificial para crear diagramas de alta calidad.","fr":"Génération de diagrammes techniques avec Nano Banana Pro, qui utilise l''intelligence artificielle pour créer des diagrammes de haute qualité.","de":"Erstellung von technischen Diagrammen mit Nano Banana Pro, das künstliche Intelligenz nutzt, um Diagramme in hoher Qualität zu erstellen.","pt":"O Nano Banana Pro gera diagramas técnicos de alta qualidade utilizando inteligência artificial para revisão de qualidade, com recursos como iteração inteligente e revisão de qualidade AI","ru":"Nano Banana Pro генерирует технические диаграммы высокого качества, используя ИИ для проверки качества, с функциями như умная итерация и проверка качества ИИ","ar":"يولد Nano Banana Pro مخططات فنية عالية الجودة باستخدام الذكاء الاصطناعي لمراجعة الجودة، مع ميزات مثل التكرار الذكي ومراجعة الجودة AI"},"seo":{"title":{"en":"Diagram: AI-Powered Image Generation for Claude Code | AI...","zh":"图表生成设置指南 - Nano Banana Pro AI工具","ja":"ダイアグラム生成ベストプラクティス - AIエージェントNano Banana Pro","ko":"다이어그램 생성 가이드 - 나노 바나나 프로 AI 에이전트","es":"Guía de configuración de diagramas con Agentes de IA","fr":"Guide de mise en place de diagrammes avec Outils d''IA","de":"Einrichtungsleitfaden für Diagramme mit KI-Tools","pt":"Guia de Configuração de Diagramas com Nano Banana Pro","ru":"ИИ Агенты: Руководство по Настройке Диаграмм с Nano Banan...","ar":"دليل إعداد المخططات باستخدام Nano Banana Pro"},"description":{"en":"Unlock efficient diagram creation with Nano Banana Pro. Learn how to generate publication-quality diagrams using AI quality review and smart iteration.","zh":"使用Nano Banana Pro AI工具生成高质量的技术图表，支持智能迭代和质量审查","ja":"AIエージェントNano Banana Proを使用して、高品質のテクニカルダイアグラムを生成します","ko":"나노 바나나 프로 AI 에이전트를 사용하여 전문적인 기술 다이어그램을 생성하세요","es":"Genera diagramas técnicos de alta calidad con Nano Banana Pro y Claude Code. Aprende a configurar y utilizar esta herramienta de IA para tus necesidades de d...","fr":"Générez des diagrammes techniques de haute qualité avec Nano Banana Pro et Claude Code. Découvrez comment configurer et utiliser cet outil d''IA pour vos beso...","de":"Erstellen Sie technische Diagramme in hoher Qualität mit Nano Banana Pro und Claude Code. Erfahren Sie, wie Sie dieses KI-Tool für Ihre Entwicklungszwecke ei...","pt":"Aprenda a gerar diagramas técnicos de alta qualidade com o Nano Banana Pro, utilizando inteligência artificial para revisão de qualidade","ru":"Изучите, как генерировать технические диаграммы высокого качества с помощью Nano Banana Pro, используя ИИ для проверки качества","ar":"تعرف على كيفية إنشاء مخططات فنية عالية الجودة باستخدام Nano Banana Pro، باستخدام الذكاء الاصطناعي لمراجعة الجودة"},"definition":{"en":"Diagram is an AI-powered image and diagram generation tool for Claude Code, utilizing Nano Banana Pro for automatic creation of publication-quality diagrams.","zh":"图表生成是指使用AI工具生成技术图表的过程，Nano Banana Pro支持智能迭代和质量审查","ja":"ダイアグラム生成は、AIエージェントを使用してテクニカルダイアグラムを生成するプロセスです","ko":"다이어그램 생성은 나노 바나나 프로 AI 에이전트를 사용하여 기술 다이어그램을 생성하는 과정입니다","es":"Un diagrama es una representación visual de información que utiliza símbolos y gráficos para comunicar conceptos y relaciones.","fr":"Un diagramme est une représentation visuelle d''informations qui utilise des symboles et des graphiques pour communiquer des concepts et des relations.","de":"Ein Diagramm ist eine visuelle Darstellung von Informationen, die Symbole und Grafiken verwendet, um Konzepte und Beziehungen zu vermitteln.","pt":"O que é um diagrama gerado por IA? É um diagrama técnico criado automaticamente utilizando inteligência artificial para revisão de qualidade","ru":"Что такое диаграмма, сгенерированная ИИ? Это техническая диаграмма, созданная автоматически с помощью ИИ для проверки качества","ar":"ما هو المخطط المولّد بالذكاء الاصطناعي؟ إنه مخطط فني يتم إنشاؤه تلقائيًا باستخدام الذكاء الاصطناعي لمراجعة الجودة"},"features":{"en":["Smart Iteration: regenerates diagrams only if quality is below threshold","Document-Type Aware: applies different quality standards for various document types","AI Quality Review: utilizes Gemini 3 Pro for professional quality review","Automatic Generation: creates publication-quality diagrams using natural language descriptions"],"zh":["智能迭代：仅在质量低于阈值时重新生成","文档类型感知：不同文档类型具有不同的质量标准","AI质量审查：Gemini 3 Pro审查每个生成的图表"],"ja":["スマートイテレーション：品質が閾値以下の場合のみ再生成","ドキュメントタイプアウェア：異なるドキュメントタイプには異なる品質基準","AI品質レビュー：Gemini 3 Proが生成された各ダイアグラムをレビュー"],"ko":["스마트 반복: 품질이 임계값 아래일 때만 다시 생성","문서 유형 인식: 다른 문서 유형에는 다른 품질 표준","AI 품질 검토: Gemini 3 Pro가 생성된 각 다이어그램을 검토"],"es":["Iteración inteligente con regeneración condicional","Conocimiento del tipo de documento para ajustar la calidad","Revisión de calidad de AI con Gemini 3 Pro","Generación de diagramas técnicos de alta calidad","Compatibilidad con Claude Code para desarrollo de software"],"fr":["Itération intelligente avec régénération conditionnelle","Connaissance du type de document pour ajuster la qualité","Révision de qualité d''IA avec Gemini 3 Pro","Génération de diagrammes techniques de haute qualité","Compatibilité avec Claude Code pour le développement de logiciels"],"de":["Intelligente Iteration mit bedingter Regenerierung","Dokumenten-Typ-Kenntnis zur Anpassung der Qualität","Qualitätsprüfung von KI mit Gemini 3 Pro","Erstellung von technischen Diagrammen in hoher Qualität","Kompatibilität mit Claude Code für Software-Entwicklung"],"pt":["Iteração inteligente para regeneração apenas quando a qualidade está abaixo do limiar","Revisão de qualidade AI com Gemini 3 Pro","Suporte a diferentes tipos de documentos com padrões de qualidade variados","Geração de diagramas técnicos de alta qualidade"],"ru":["Умная итерация для регенерации только когда качество ниже порога","Проверка качества ИИ с Gemini 3 Pro","Поддержка разных типов документов с разными стандартами качества","Генерация технических диаграмм высокого качества"],"ar":["التكرار الذكي لإعادة_GENERATION فقط عند وجود جودة أقل من العتبة","مراجعة الجودة AI مع Gemini 3 Pro","دعم مستندات مختلفة مع معايير جودة متغيرة","إنشاء مخططات فنية عالية الجودة"]},"keywords":{"en":["how to use diagram generation","diagram alternative to manual creation","diagram setup guide for Claude Code","what is diagram generation","diagram vs traditional image creation","installing Nano Banana Pro for diagram"],"zh":["图表生成","AI工具","Nano Banana Pro","智能迭代","质量审查","技术图表"],"ja":["ダイアグラム生成","AIエージェント","Nano Banana Pro","スマートイテレーション","品質レビュー","テクニカルダイアグラム"],"ko":["다이어그램 생성","AI 에이전트","나노 바나나 프로","스마트 반복","품질 검토","기술 다이어그램"],"es":["diagramas técnicos","herramientas de IA","generación de diagramas","Nano Banana Pro","Claude Code","desarrollo de software","inteligencia artificial","representación visual de información"],"fr":["diagrammes techniques","outils d''IA","génération de diagrammes","Nano Banana Pro","Claude Code","développement de logiciels","intelligence artificielle","représentation visuelle d''informations"],"de":["technische Diagramme","KI-Tools","Erstellung von Diagrammen","Nano Banana Pro","Claude Code","Software-Entwicklung","künstliche Intelligenz","visuelle Darstellung von Informationen"],"pt":["diagramas técnicos","inteligência artificial","revisão de qualidade","Nano Banana Pro","Gemini 3 Pro","geração de diagramas","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["технические диаграммы","искусственный интеллект","проверка качества","Nano Banana Pro","Gemini 3 Pro","генерация диаграмм","разработка программного обеспечения","инструменты разработки"],"ar":["المخططات الفنية","الذكاء الاصطناعي","مراجعة الجودة","Nano Banana Pro","Gemini 3 Pro","إنشاء المخططات","تطوير البرمجيات","أدوات التطوير"]}},"owner":"flight505","repo":"nano-banana","repoPath":"flight505/nano-banana","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.402Z","topics":[],"category":"community","skillMd":{"name":"diagram","description":"Generate publication-quality technical diagrams using Nano Banana Pro (gemini-3-pro-image-preview) with AI-powered quality review. Smart iteration only regenerates when quality is below threshold. Supports resolution control (512px–4K).","bodyPreview":"# Nano Banana - Diagram Generation\n\n## Overview\n\nGenerate any technical diagram by describing it in natural language. Nano Banana Pro automatically creates publication-quality diagrams with intelligent quality review.\n\n**Key Features:**\n- 🍌 **Smart Iteration**: Only regenerates if quality is below threshold (saves API calls)\n- 🎯 **Document-Type Aware**: Different quality standards for different document types\n- 🔍 **AI Quality Review**: Gemini 3 Pro reviews each generation for professional sta","body":"# Nano Banana - Diagram Generation\n\n## Overview\n\nGenerate any technical diagram by describing it in natural language. Nano Banana Pro automatically creates publication-quality diagrams with intelligent quality review.\n\n**Key Features:**\n- 🍌 **Smart Iteration**: Only regenerates if quality is below threshold (saves API calls)\n- 🎯 **Document-Type Aware**: Different quality standards for different document types\n- 🔍 **AI Quality Review**: Gemini 3 Pro reviews each generation for professional standards\n- 📊 **Publication-Ready**: High contrast, readable fonts, colorblind-friendly\n\n## When to Use This Skill\n\nUse this skill when you need:\n\n- **Architecture Diagrams**: System designs, microservices, C4 models\n- **Flowcharts**: Process flows, decision trees, user journeys\n- **Data Models**: ERD diagrams, schema visualizations\n- **Sequence Diagrams**: API interactions, message flows\n- **Infrastructure Diagrams**: Cloud architecture, deployment topologies\n- **Pipeline Diagrams**: CI/CD, data pipelines, ML workflows\n- **Any Technical Visualization**: Describe it, Nano Banana creates it\n\n## Quick Start\n\n```bash\n# Generate an architecture diagram\npython3 skills/diagram/scripts/generate_diagram.py \"Microservices architecture with API gateway, auth service, and database\" -o architecture.png --doc-type architecture\n\n# Generate a flowchart for a presentation\npython3 skills/diagram/scripts/generate_diagram.py \"User authentication flow with OAuth2\" -o auth_flow.png --doc-type presentation\n\n# Generate with higher resolution\npython3 skills/diagram/scripts/generate_diagram.py \"Complex system diagram\" -o system.png --resolution 2K\n\n# Generate with verbose output\npython3 skills/diagram/scripts/generate_diagram.py \"Database schema for e-commerce\" -o schema.png -v\n```\n\n### Editing Existing Diagrams\n\nUse `/nano-banana:edit` to modify an existing diagram, or call the script directly:\n\n```bash\n# Edit via command (recommended)\n/nano-banana:edit architecture.png \"Add a Redis cache layer between the API and database\"\n\n# Edit via script directly\npython3 skills/diagram/scripts/generate_diagram_ai.py \"Add Redis cache layer\" --input architecture.png -o architecture_edit1.png --doc-type architecture\n```\n\n**When to edit vs. regenerate:**\n- **Edit** when the diagram structure is correct but needs additions or modifications\n- **Regenerate** when the layout or overall approach needs rethinking\n\n## Document Types & Quality Thresholds\n\nDifferent documents have different quality requirements. Nano Banana automatically adjusts:\n\n| Document Type | Threshold | Best For |\n|--------------|-----------|----------|\n| `specification` | 8.5/10 | Technical specs, PRDs |\n| `architecture` | 8.0/10 | Architecture documents |\n| `proposal` | 8.0/10 | Business proposals |\n| `journal` | 8.5/10 | Academic publications |\n| `conference` | 8.0/10 | Conference papers |\n| `thesis` | 8.0/10 | Dissertations |\n| `grant` | 8.0/10 | Grant proposals |\n| `sprint` | 7.5/10 | Sprint planning |\n| `report` | 7.5/10 | Technical reports |\n| `preprint` | 7.5/10 | arXiv, bioRxiv |\n| `readme` | 7.0/10 | README files |\n| `poster` | 7.0/10 | Academic posters |\n| `presentation` | 6.5/10 | Slides, talks |\n| `default` | 7.5/10 | General purpose |\n\n**Smart Iteration**: If the first generation scores above the threshold, no second iteration is performed. This saves time and API costs.\n\n## Diagram Examples\n\n### System Architecture\n```bash\npython3 generate_diagram.py \"Three-tier web application architecture with:\n- React frontend\n- Node.js API layer with load balancer\n- PostgreSQL database with read replicas\n- Redis cache layer\n- CDN for static assets\" -o three_tier.png --doc-type architecture\n```\n\n### Sequence Diagram\n```bash\npython3 generate_diagram.py \"Sequence diagram showing OAuth2 authorization code flow:\n1. User clicks login\n2. App redirects to auth server\n3. User authenticates\n4. Auth server returns code\n5. App exchanges code for token\n6. App accesses protected resource\" -o oauth_flow.png --doc-type specification\n```\n\n### Data Flow\n```bash\npython3 generate_diagram.py \"Data pipeline showing:\n- Data ingestion from multiple sources (API, files, streaming)\n- ETL processing with Apache Spark\n- Data warehouse (Snowflake)\n- BI dashboards and ML model training\" -o pipeline.png --doc-type report\n```\n\n### C4 Model - Container Diagram\n```bash\npython3 generate_diagram.py \"C4 Container diagram for e-commerce platform:\n- Web App (React SPA)\n- Mobile App (React Native)\n- API Gateway (Kong)\n- Order Service (Python)\n- Payment Service (Go)\n- Inventory Service (Java)\n- PostgreSQL Database\n- Redis Cache\n- RabbitMQ Message Queue\" -o c4_container.png --doc-type architecture\n```\n\n## How It Works\n\n1. **Initial Generation**: Nano Banana Pro (`gemini-3-pro-image-preview`) generates the diagram\n2. **Quality Review**: Gemini 3 Pro evaluates on 5 criteria:\n   - Technical Accuracy (0-2 pts)\n   - Clarity and Readability (0-2 pts)\n   - Label Quality (0-2 pts)\n   - Layout and Composition (0-2 pts)\n   - Professional Appearance (0-2 pts)\n3. **Decision**: If score ≥ threshold → Done! If score < threshold → Iterate\n4. **Improvement**: Feedback is incorporated into an improved prompt\n5. **Regeneration**: New diagram generated with improvements (max 2 iterations)\n\n## Output Files\n\nFor an output path of `diagram.png`, you''ll get:\n- `diagram_v1.png` - First iteration\n- `diagram_v2.png` - Second iteration (if needed)\n- `diagram.png` - Final version (copy of best iteration)\n- `diagram_review_log.json` - Quality scores and review details\n\n## Configuration\n\n### Option 1: Google Gemini API (Recommended)\n```bash\nexport GEMINI_API_KEY=''your_gemini_key_here''\n```\nGet a key at https://aistudio.google.com/apikey (free tier available).\n\n### Option 2: OpenRouter (Alternative)\n```bash\nexport OPENROUTER_API_KEY=''your_api_key_here''\n```\nGet a key at https://openrouter.ai/keys. Required for non-Google models.\n\n### .env File\nCreate a `.env` file in your project with either key:\n```\nGEMINI_API_KEY=your_gemini_key_here\n```\n\n**Auto-detection:** When both keys are set, the Google direct API is preferred. Use `--provider openrouter` to force OpenRouter.\n\n## Tips for Better Diagrams\n\n### Be Specific\n```bash\n# ❌ Too vague\n\"System diagram\"\n\n# ✅ Specific and detailed\n\"Microservices architecture diagram showing user service, order service, and payment service communicating via REST APIs, with a shared PostgreSQL database and Redis cache\"\n```\n\n### Include Relationships\n```bash\n# ✅ Good - describes connections\n\"Data flow diagram showing:\n- User uploads file to S3\n- Lambda triggered on upload\n- Lambda processes and stores metadata in DynamoDB\n- SNS notifies downstream services\"\n```\n\n### Specify Style When Needed\n```bash\n# ✅ Style hints\n\"Flowchart with decision diamonds for the loan approval process, using green for approved paths and red for rejected paths\"\n```\n\n## Python API\n\n```python\nfrom skills.diagram.scripts.generate_diagram_ai import NanoBananaGenerator\n\ngenerator = NanoBananaGenerator(verbose=True)\nresults = generator.generate_iterative(\n    user_prompt=\"Kubernetes cluster architecture with ingress, services, and pods\",\n    output_path=\"k8s_arch.png\",\n    iterations=2,\n    doc_type=\"architecture\"\n)\n\nprint(f\"Final Score: {results[''final_score'']}/10\")\nprint(f\"Early Stop: {results[''early_stop'']}\")\n```\n\n## Integration with Other Skills\n\n- Use with **sprint planning** to visualize user story workflows\n- Use with **architecture research** to diagram ADR decisions\n- Use with **building blocks** to visualize component relationships\n- Use with **competitive analysis** to create comparison diagrams\n\n## Troubleshooting\n\n### \"OPENROUTER_API_KEY not found\"\nSet the environment variable or create a `.env` file. See Configuration section.\n\n### Low Quality Scores\n- Add more detail to your prompt\n- Specify relationships between components\n- Use a higher threshold document type to force more iterations\n\n### Generation Timeout\nComplex diagrams may take up to 2 minutes. The timeout is set to 120 seconds per API call.\n\n## Cost Considerations\n\n- Gemini 3 Pro Image: ~$2/M input, ~$12/M output tokens\n- Simple diagram (1 iteration): ~$0.05-0.15\n- Complex diagram (2 iterations): ~$0.10-0.30\n- Smart iteration saves costs by stopping early when quality is sufficient\n"},"lastSynced":"2026-03-08T02:06:48.989Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing advanced diagram generation capabilities for documentation.","zh":"非常适合需要高级图表生成功能的技术写作代理，用于文档编制。","ja":"技術文章作成エージェントが高度な図表生成機能を必要とするドキュメント向けに最適です。","ko":"문서 작성에 고급 도표 생성 기능이 필요한 기술 작성을 위한 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Escritura Técnica que necesitan capacidades avanzadas de generación de diagramas para documentación.","fr":"Parfait pour les Agents d''Écriture Technique ayant besoin de capacités avancées de génération de diagrammes pour la documentation.","de":"Perfekt für technische Schreibagenten, die erweiterte Diagrammgenerierungsfunktionen für die Dokumentation benötigen.","pt":"Perfeito para Agentes de Escrita Técnica que precisam de capacidades avançadas de geração de diagramas para documentação.","ru":"Идеально подходит для агентов технической писанины, которым необходимы продвинутые возможности генерации диаграмм для документации.","ar":"مثالي للوكلاء الكتابيين الفنيين الذين يحتاجون إلى إمكانيات متقدمة لإنشاء مخططات للوثائق."},"recommendation":{"en":"Empowers agents to generate publication-quality technical diagrams using natural language descriptions, leveraging Nano Banana Pro for intelligent quality review and supporting document-type aware quality standards, including AI quality review with Gemini 3 Pro.","zh":"赋予代理使用自然语言描述生成出版级技术图表的能力，利用Nano Banana Pro进行智能质量审查，并支持文档类型感知的质量标准，包括使用Gemini 3 Pro的AI质量审查。","ja":"エージェントが自然言語の説明を使用して出版レベルの技術図表を生成することを可能にし、Nano Banana Proを使用したインテリジェントな品質レビューを利用し、Gemini 3 Proを使用したAI品質レビューを含むドキュメントタイプに応じた品質基準をサポートします。","ko":"에이전트가 자연 언어 설명을 사용하여 출판 수준의 기술 도표를 생성할 수 있도록 하며, Nano Banana Pro를 사용한 지능형 품질 검토를 활용하고, Gemini 3 Pro를 사용한 AI 품질 검토를 포함한 문서 유형에 따른 품질 표준을 지원합니다.","es":"Habilita a los agentes a generar diagramas técnicos de calidad de publicación utilizando descripciones en lenguaje natural, aprovechando Nano Banana Pro para una revisión de calidad inteligente y apoyando normas de calidad conscientes del tipo de documento, incluida la revisión de calidad de IA con Gemini 3 Pro.","fr":"Permet aux agents de générer des diagrammes techniques de qualité d''édition à l''aide de descriptions en langage naturel, en exploitant Nano Banana Pro pour une révision de qualité intelligente et en prenant en charge les normes de qualité sensibles au type de document, y compris la révision de qualité IA avec Gemini 3 Pro.","de":"Ermächtigt Agenten, technische Diagramme in Publikationsqualität mit natürlichen Sprachbeschreibungen zu generieren, indem Nano Banana Pro für eine intelligente Qualitätsprüfung genutzt und dokumenttypabhängige Qualitätsstandards unterstützt werden, einschließlich Qualitätsprüfung von KI mit Gemini 3 Pro.","pt":"Habilita os agentes a gerar diagramas técnicos de publicação de alta qualidade usando descrições em linguagem natural, aproveitando o Nano Banana Pro para revisão de qualidade inteligente e suportando padrões de qualidade de documento, incluindo revisão de qualidade de IA com Gemini 3 Pro.","ru":"Наделяет агентов возможностью генерировать технические диаграммы высокого качества, используя описания на естественном языке, tận dụng возможности Nano Banana Pro для интеллектуальной проверки качества и поддержки стандартов качества документов, включая проверку качества ИИ с Gemini 3 Pro.","ar":"تمكن الوكلاء من إنشاء مخططات فنية منشورات ذات جودة عالية باستخدام وصفات اللغة الطبيعية، واستخدام Nano Banana Pro لمراجعة الجودة الذكية ودعم معايير الجودة للوثائق، بما في ذلك مراجعة الجودة الاصطناعية مع Gemini 3 Pro."},"useCases":{"en":["Generating technical diagrams for software documentation","Automating diagram updates based on natural language descriptions","Creating document-type aware diagrams with smart iteration"],"zh":["为软件文档生成技术图表","基于自然语言描述自动更新图表","使用智能迭代创建文档类型感知图表"],"ja":["ソフトウェアドキュメント用の技術図表の生成","自然言語の説明に基づく図表の自動更新","スマートイテレーションを使用したドキュメントタイプに応じた図表の作成"],"ko":["소프트웨어 문서를 위한 기술 도표 생성","자연 언어 설명을 기반으로 도표 자동 업데이트","스마트 반복을 사용한 문서 유형에 따른 도표 생성"],"es":["Generación de diagramas técnicos para documentación de software","Automatización de actualizaciones de diagramas en función de descripciones en lenguaje natural","Creación de diagramas conscientes del tipo de documento con iteración inteligente"],"fr":["Génération de diagrammes techniques pour la documentation logicielle","Automatisation des mises à jour de diagrammes en fonction de descriptions en langage naturel","Création de diagrammes sensibles au type de document avec itération intelligente"],"de":["Generierung technischer Diagramme für Software-Dokumentation","Automatisierung von Diagramm-Aktualisierungen basierend auf natürlichen Sprachbeschreibungen","Erstellung dokumenttypabhängiger Diagramme mit intelligenter Iteration"],"pt":["Gerar diagramas técnicos para documentação de software","Automatizar atualizações de diagramas com base em descrições de linguagem natural","Criar diagramas conscientes do tipo de documento com iteração inteligente"],"ru":["Генерировать технические диаграммы для документации программного обеспечения","Автоматизировать обновления диаграмм на основе описаний на естественном языке","Создавать диаграммы, осведомлённые о типе документа, с умной итерацией"],"ar":["إنشاء مخططات فنية لتوثيق البرمجيات","تحديث المخططات تلقائيًا بالاعتماد على وصفات اللغة الطبيعية","إنشاء مخططات مدروسة لنوع الوثيقة مع تكرار ذكي"]},"limitations":{"en":["Requires Nano Banana Pro for intelligent quality review","Dependent on Gemini 3 Pro for AI quality review"],"zh":["需要Nano Banana Pro进行智能质量审查","依赖Gemini 3 Pro进行AI质量审查"],"ja":["インテリジェントな品質レビューのためにNano Banana Proが必要","AI品質レビューのためにGemini 3 Proに依存"],"ko":["지능형 품질 검토를 위해 Nano Banana Pro가 필요","AI 품질 검토를 위해 Gemini 3 Pro에 의존"],"es":["Requiere Nano Banana Pro para una revisión de calidad inteligente","Dependiente de Gemini 3 Pro para la revisión de calidad de IA"],"fr":["Nécessite Nano Banana Pro pour une révision de qualité intelligente","Dépend