INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('flight505/nano-banana/diagram', 'diagram', 'flight505', 'nano-banana', 'community', 'diagram flight505 nano-banana community The diagram skill generates technical diagrams using natural language descriptions, benefiting developers and technical writers. It leverages Nano Banana Pro for intelligent quality review. Nano Banana Pro AI工具支持通过自然语言描述生成技术图表，具有智能迭代和质量审查功能 Nano Banana Pro AIエージェントは、自然言語で説明することでテクニカルダイアグラムを生成します 나노 바나나 프로 AI 에이전트는自然어로 기술 다이어그램을 설명하여 생성합니다 Generación de diagramas técnicos con Nano Banana Pro, que utiliza inteligencia artificial para crear diagramas de alta calidad. Génération de diagrammes techniques avec Nano Banana Pro, qui utilise l''intelligence artificielle pour créer des diagrammes de haute qualité. Erstellung von technischen Diagrammen mit Nano Banana Pro, das künstliche Intelligenz nutzt, um Diagramme in hoher Qualität zu erstellen. O Nano Banana Pro gera diagramas técnicos de alta qualidade utilizando inteligência artificial para revisão de qualidade, com recursos como iteração inteligente e revisão de qualidade AI Nano Banana Pro генерирует технические диаграммы высокого качества, используя ИИ для проверки качества, с функциями như умная итерация и проверка качества ИИ يولد Nano Banana Pro مخططات فنية عالية الجودة باستخدام الذكاء الاصطناعي لمراجعة الجودة، مع ميزات مثل التكرار الذكي ومراجعة الجودة AI how to use diagram generation diagram alternative to manual creation diagram setup guide for Claude Code what is diagram generation diagram vs traditional image creation installing Nano Banana Pro for diagram 图表生成 AI工具 Nano Banana Pro 智能迭代 质量审查 技术图表 Smart Iteration: regenerates diagrams only if quality is below threshold Document-Type Aware: applies different quality standards for various document types AI Quality Review: utilizes Gemini 3 Pro for professional quality review Automatic Generation: creates publication-quality diagrams using natural language descriptions Diagram is an AI-powered image and diagram generation tool for Claude Code, utilizing Nano Banana Pro for automatic creation of publication-quality diagrams.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Heyvhuang/ship-faster/mcp-cloudflare', 'community', 'Heyvhuang', 'ship-faster', 'Heyvhuang/ship-faster', 'mcp-cloudflare', 0, 0, 60, '2026-03-08T01:57:15.403Z', '2026-03-08T02:06:49.398Z', '6c6ca1e7a6fb6626aed5dc112b2204726f64a3ee16d94312391394a61d0883a4', '{"id":"Heyvhuang/ship-faster/mcp-cloudflare","name":"mcp-cloudflare","description":{"en":"The mcp-cloudflare skill enables developers to interact with Cloudflare services via MCP, streamlining workflow integration and troubleshooting. It benefits developers working with Cloudflare Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit, and Container Sandbox.","zh":"Cloudflare MCP技能提供了与Cloudflare服务的交互，包括Workers、KV、R2、D1、Hyperdrive、Observability、Builds、Audit和Container Sandbox","ja":"Cloudflare MCPスキルは、Workers、KV、R2、D1、Hyperdrive、Observability、Builds、Audit、Container SandboxなどのCloudflareサービスとの相互作用を提供します","ko":"Cloudflare MCP 스킬은 Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit, Container Sandbox 등의 Cloudflare 서비스와의 상호 작용을 제공합니다","es":"MCP Cloudflare es una habilidad que permite a los desarrolladores interactuar con los servicios de Cloudflare, como Workers, KV y R2, para crear soluciones personalizadas","fr":"MCP Cloudflare est une compétence qui permet aux développeurs d''interagir avec les services Cloudflare, tels que Workers, KV et R2, pour créer des solutions personnalisées","de":"MCP Cloudflare ist eine Fähigkeit, die es Entwicklern ermöglicht, mit Cloudflare-Diensten wie Workers, KV und R2 zu interagieren, um individuelle Lösungen zu erstellen","pt":"O mcp-cloudflare é uma habilidade que permite interagir com serviços Cloudflare via MCP. Ele suporta Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit e Container Sandbox.","ru":"Mcp-cloudflare - это навык, который позволяет взаимодействовать с сервисами Cloudflare через MCP. Он поддерживает Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit и Container Sandbox.","ar":"mcp-cloudflare هو مهارة تمكن من التفاعل مع خدمات Cloudflare عبر MCP. يدعم Workers، KV، R2، D1، Hyperdrive، Observability، Builds، Audit و Container Sandbox."},"seo":{"title":{"en":"mcp-cloudflare: Cloudflare Services Integration Setup Gui...","zh":"Cloudflare MCP技能集成指南","ja":"Cloudflare MCPスキルのセットアップガイド - AIエージェント","ko":"Cloudflare MCP 스킬 설정 가이드 - AI 도구","es":"Guía de configuración de MCP Cloudflare para desarrolladores","fr":"Guide d''intégration de MCP Cloudflare pour les développeurs","de":"Einrichtungsleitfaden für MCP Cloudflare-Entwickler","pt":"Guia de Configuração do mcp-cloudflare: Integração com Se...","ru":"Настройка mcp-cloudflare: Работа с сервисами Cloudflare ч...","ar":"دليل إعداد mcp-cloudflare: التفاعل مع خدمات Cloudflare"},"description":{"en":"Unlock Cloudflare''s potential with mcp-cloudflare. Discover how to integrate Workers, KV, R2, and more into your workflows. Get started with our expert guide...","zh":"了解Cloudflare MCP技能的技术细节，实现Workers、KV、R2、D1等服务的集成","ja":"Cloudflare MCPスキルの技術的な詳細を学び、Workers、KV、R2、D1などのサービスを統合する","ko":"Cloudflare MCP 스킬의 기술적 세부 사항을 알아보고 Workers, KV, R2, D1 등의 서비스를 통합하세요","es":"Aprende a interactuar con los servicios de Cloudflare mediante MCP, incluyendo Workers, KV, R2, D1, Hyperdrive y más","fr":"Découvrez comment interagir avec les services Cloudflare via MCP, notamment Workers, KV, R2, D1, Hyperdrive et plus","de":"Erfahren Sie, wie Sie mit Cloudflare-Diensten über MCP interagieren, einschließlich Workers, KV, R2, D1, Hyperdrive und mehr","pt":"Aprenda a integrar o mcp-cloudflare com serviços Cloudflare como Workers, KV, R2, D1 e mais. Veja como otimizar sua configuração e melhorar a produtividade.","ru":"Узнайте, как настроить mcp-cloudflare для работы с сервисами Cloudflare, такими как Workers, KV, R2, D1 и другими. Улучшите свою производительность и оптимиз...","ar":"تعرف على كيفية دمج mcp-cloudflare مع خدمات Cloudflare مثل Workers، KV، R2، D1 وغيرها. تحسين إنتاجيتك وتكوين أفضل"},"definition":{"en":"mcp-cloudflare is a skill that allows interaction with Cloudflare services via MCP, facilitating file-based pipeline management and workflow integration.","zh":"Cloudflare MCP技能是一种AI工具，用于与Cloudflare服务进行交互","ja":"Cloudflare MCPスキルは、Cloudflareサービスとの相互作用を可能にするAIエージェントの一種です","ko":"Cloudflare MCP 스킬은 Cloudflare 서비스와 상호 작용할 수 있는 AI 도구의 한 종류입니다","es":"MCP Cloudflare es una habilidad que permite la interacción con servicios de Cloudflare para desarrolladores","fr":"MCP Cloudflare est une compétence qui permet l''interaction avec les services Cloudflare pour les développeurs","de":"MCP Cloudflare ist eine Fähigkeit, die die Interaktion mit Cloudflare-Diensten für Entwickler ermöglicht","pt":"O mcp-cloudflare é uma habilidade de AI que integra serviços Cloudflare com MCP.","ru":"Mcp-cloudflare - это навык ИИ, который интегрирует сервисы Cloudflare с MCP.","ar":"mcp-cloudflare هو مهارة ذكاء اصطناعي التي تدمج خدمات Cloudflare مع MCP."},"features":{"en":["Interacts with Cloudflare Workers for serverless computing","Utilizes Cloudflare KV for secure key-value storage","Supports Cloudflare R2 for object storage and retrieval","Enables Observability for monitoring and analytics","Facilitates Builds and Audit for streamlined development and security","Integrates with Container Sandbox for secure testing and deployment"],"zh":["支持Workers、KV、R2、D1等Cloudflare服务","提供文件基于的流水线（Pass Paths Only）","推荐的目录结构：`runs/<workflow>/active/<run_id>/`","支持Observability、Builds、Audit和Container Sandbox","实现Hyperdrive等高级功能"],"ja":["Workers、KV、R2、D1などのCloudflareサービスをサポート","ファイルベースのパイプライン（Pass Paths Only）を提供","推奨ディレクトリ構造：`runs/<workflow>/active/<run_id>/`","Observability、Builds、Audit、Container Sandboxをサポート","Hyperdriveなどの高度な機能を実現"],"ko":["Workers, KV, R2, D1 등의 Cloudflare 서비스 지원","파일 기반의 파이프라인（Pass Paths Only） 제공","추천 디렉토리 구조：`runs/<workflow>/active/<run_id>/`","Observability, Builds, Audit, Container Sandbox 지원","Hyperdrive 등의 고급 기능 구현"],"es":["Integración con Cloudflare Workers","Acceso a Cloudflare KV y R2","Compatibilidad con Hyperdrive y Observability","Soporte para Builds y Audit","Integración con Container Sandbox"],"fr":["Intégration avec Cloudflare Workers","Accès à Cloudflare KV et R2","Compatibilité avec Hyperdrive et Observability","Prise en charge des Builds et Audit","Intégration avec Container Sandbox"],"de":["Integration mit Cloudflare Workers","Zugriff auf Cloudflare KV und R2","Kompatibilität mit Hyperdrive und Observability","Unterstützung für Builds und Audit","Integration mit Container Sandbox"],"pt":["Suporte a Workers","Integração com KV","Acesso a R2","Suporte a D1","Hyperdrive","Observability"],"ru":["Поддержка Workers","Интеграция с KV","Доступ к R2","Поддержка D1","Hyperdrive","Наблюдаемость"],"ar":["دعم Workers","التكامل مع KV","الوصول إلى R2","دعم D1","Hyperdrive","متابعة"]},"keywords":{"en":["how to use mcp-cloudflare","mcp-cloudflare setup guide","Cloudflare Workers integration","mcp-cloudflare vs Cloudflare API","mcp-cloudflare install","what is mcp-cloudflare","mcp-cloudflare alternative","Cloudflare services integration","mcp-cloudflare tutorial","Cloudflare R2 storage"],"zh":["Cloudflare MCP技能","AI工具","Cloudflare服务","Workers","KV","R2","D1","Hyperdrive","Observability","Builds","Audit","Container Sandbox"],"ja":["Cloudflare MCPスキル","AIエージェント","Cloudflareサービス","Workers","KV","R2","D1","Hyperdrive","Observability","Builds","Audit","Container Sandbox"],"ko":["Cloudflare MCP 스킬","AI 도구","Cloudflare 서비스","Workers","KV","R2","D1","Hyperdrive","Observability","Builds","Audit","Container Sandbox"],"es":["MCP Cloudflare","Cloudflare Workers","KV y R2","Hyperdrive","Observability","Desarrollo de aplicaciones en la nube","Herramientas de desarrollo de Cloudflare","Integración de MCP con Cloudflare"],"fr":["MCP Cloudflare","Cloudflare Workers","KV et R2","Hyperdrive","Observability","Développement d''applications dans le cloud","Outils de développement Cloudflare","Intégration de MCP avec Cloudflare"],"de":["MCP Cloudflare","Cloudflare Workers","KV und R2","Hyperdrive","Observability","Anwendungsentwicklung in der Cloud","Cloudflare-Entwicklungstools","MCP-Integration mit Cloudflare"],"pt":["mcp-cloudflare","serviços Cloudflare","MCP","Workers","KV","R2","D1","Hyperdrive","Observability"],"ru":["mcp-cloudflare","сервисы Cloudflare","MCP","Workers","KV","R2","D1","Hyperdrive","Наблюдаемость","ИИ Агенты"],"ar":["mcp-cloudflare","خدمات Cloudflare","MCP","Workers","KV","R2","D1","Hyperdrive","متابعة","أدوات الذكاء الاصطناعي"]}},"owner":"Heyvhuang","repo":"ship-faster","repoPath":"Heyvhuang/ship-faster","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.403Z","topics":[],"category":"community","skillMd":{"name":"mcp-cloudflare","description":"Manage Workers/KV/R2/D1/Hyperdrive via Cloudflare MCP, perform observability/build troubleshooting/audit/container sandbox operations. Triggers: worker/KV/R2/D1/logs/build/deploy/screenshot/audit/sandbox. Three permission tiers: Diagnose (read-only), Change (write requires confirmation), Super Admin (isolated environment). Write operations must follow read-first, user confirmation, post-execution verification.","bodyPreview":"# Cloudflare MCP Skill\n\nInteract with Cloudflare services via MCP: Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit, Container Sandbox.\n\n## File-based Pipeline (Pass Paths Only)\n\nWhen integrating troubleshooting/changes into multi-step workflows, persist all evidence and artifacts to disk, passing only paths between agents/sub-agents.\n\nRecommended directory structure (within project): `runs/<workflow>/active/<run_id>/`\n\n- Input: `01-input/goal.md` (symptoms/objectives), `01-input/co","body":"# Cloudflare MCP Skill\n\nInteract with Cloudflare services via MCP: Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit, Container Sandbox.\n\n## File-based Pipeline (Pass Paths Only)\n\nWhen integrating troubleshooting/changes into multi-step workflows, persist all evidence and artifacts to disk, passing only paths between agents/sub-agents.\n\nRecommended directory structure (within project): `runs/<workflow>/active/<run_id>/`\n\n- Input: `01-input/goal.md` (symptoms/objectives), `01-input/context.json` (account/worker/resource/time_range, etc.)\n- Evidence: `02-analysis/observability.md`, `02-analysis/audit.md`, `02-analysis/screenshots/`\n- Plan: `03-plans/change-plan.md` (write operation plan; must write here and await confirmation first)\n- Output: `05-final/report.md` (conclusion + evidence chain + tool call summary + next steps)\n- Logs: `logs/events.jsonl` (summary of each tool call)\n\n## Permission Tiers (Core Principles)\n\n| Tier | Purpose | Tool Scope | Risk Control |\n|------|---------|------------|--------------|\n| **Diagnose** | Read-only/query/troubleshoot | Observability, Builds, Browser, Audit | Default entry point, no write operations |\n| **Change** | Create/modify/delete resources | Workers Bindings (KV/R2/D1) | Requires user confirmation, post-execution verification |\n| **Super Admin** | Highest privileges | All + Container Sandbox | Only in isolated environments/test accounts |\n\n## Tool Reference\n\n### Diagnose Tier (Read-only)\n\n**Observability**\n| Tool | Purpose |\n|------|---------|\n| `query_worker_observability` | Query logs/metrics (events, CPU, error rate) |\n| `observability_keys` | Discover available fields |\n| `observability_values` | Explore field values |\n\n**Builds**\n| Tool | Purpose |\n|------|---------|\n| `workers_builds_list_builds` | List build history |\n| `workers_builds_get_build` | Get build details |\n| `workers_builds_get_build_logs` | Get build logs |\n\n**Browser Rendering (Page Capture)**\n| Tool | Purpose |\n|------|---------|\n| `get_url_html_content` | Fetch page HTML |\n| `get_url_markdown` | Convert to Markdown |\n| `get_url_screenshot` | Take page screenshot |\n\n**Audit Logs**\n| Tool | Purpose |\n|------|---------|\n| `auditlogs_by_account_id` | Pull change history by time range |\n\n### Change Tier (Write Operations)\n\n**Account**\n| Tool | Purpose |\n|------|---------|\n| `accounts_list` | List accounts |\n| `set_active_account` | Set active account |\n\n**Builds (Settings)**\n| Tool | Purpose |\n|------|---------|\n| `workers_builds_set_active_worker` | ⚠️ Set active worker (requires confirmation) |\n\n**KV**\n| Tool | Purpose |\n|------|---------|\n| `kv_namespaces_list` | List namespaces |\n| `kv_namespace_get` | Get details |\n| `kv_namespace_create` | Create (⚠️ requires confirmation) |\n| `kv_namespace_update` | Update (⚠️ requires confirmation) |\n| `kv_namespace_delete` | Delete (⚠️ requires confirmation) |\n\n**R2**\n| Tool | Purpose |\n|------|---------|\n| `r2_buckets_list` | List buckets |\n| `r2_bucket_get` | Get details |\n| `r2_bucket_create` | Create (⚠️ requires confirmation) |\n| `r2_bucket_delete` | Delete (⚠️ requires confirmation) |\n\n**D1**\n| Tool | Purpose |\n|------|---------|\n| `d1_databases_list` | List databases |\n| `d1_database_get` | Get details |\n| `d1_database_query` | Execute SQL |\n| `d1_database_create` | Create (⚠️ requires confirmation) |\n| `d1_database_delete` | Delete (⚠️ requires confirmation) |\n\n**Hyperdrive**\n| Tool | Purpose |\n|------|---------|\n| `hyperdrive_configs_list` | List configs |\n| `hyperdrive_config_get` | Get details |\n| `hyperdrive_config_create` | Create (⚠️ requires confirmation) |\n| `hyperdrive_config_edit` | Edit (⚠️ requires confirmation) |\n| `hyperdrive_config_delete` | Delete (⚠️ requires confirmation) |\n\n**Workers**\n| Tool | Purpose |\n|------|---------|\n| `workers_list` | List workers |\n| `workers_get_worker` | Get worker details |\n| `workers_get_worker_code` | Get source code |\n\n### Super Admin Tier (Container Sandbox)\n\n| Tool | Purpose |\n|------|---------|\n| `container_initialize` | Initialize container (~10 min lifecycle) |\n| `container_exec` | Execute command |\n| `container_file_write` | Write file |\n| `container_file_read` | Read file |\n| `container_files_list` | List files |\n| `container_file_delete` | Delete file |\n\n**Container Notes**: No persistent state, short lifespan, only for temporary tasks (running tests/reproducing issues/parsing data).\n\n## Security Rules (Must Follow)\n\n### Read Operations\n1. **Define scope first**: account / worker / resource ID\n2. **No account? Run `accounts_list` first**\n3. Conclusions must have evidence chain: logs/screenshots/audit records\n\n### Write Operations (Three-step Flow)\n```\n1. Plan: Read current state first (list/get)\n2. Confirm: Output precise change (name/ID/impact scope), await user confirmation\n3. Execute: create/delete/update\n4. Verify: audit logs + observability confirm no new errors\n```\n\n### Prohibited Actions\n- ❌ Execute create/delete/update without confirmation\n- ❌ Delete production resources (unless user explicitly says \"delete production xxx\")\n- ❌ Use Super Admin privileges in non-isolated environments\n- ❌ Use container sandbox as persistent environment\n\n## Operation Workflows\n\n### Troubleshooting Flow (Typical)\n```\n1. Clarify symptoms → worker name/time range/error type\n2. query_worker_observability to pull logs/metrics\n3. If build-related → workers_builds_get_build_logs\n4. If page-related → get_url_screenshot to reproduce\n5. Trace changes → auditlogs_by_account_id\n6. Summarize: root cause + evidence + fix recommendations\n```\n\n### Resource Management Flow\n```\n1. accounts_list → set_active_account\n2. List resources (kv_namespaces_list / r2_buckets_list / d1_databases_list)\n3. Plan changes → present to user\n4. Execute after confirmation\n5. Verify: audit logs + observability shows no errors\n```\n\n## Output Format\n\n- **Language**: English\n- **Structure**: Conclusion → Key data/evidence → Tool call summary → Next steps\n- **Write operations**: Must clearly list operations to be executed and impact scope\n\nExample output:\n```\n✅ Investigation complete: worker `api-gateway` experienced 5xx spike between 18:00-18:30\n\nRoot cause: New code deployed threw TypeError when processing /v2/users\nEvidence:\n- Logs: 18:02 first occurrence of \"Cannot read property ''id'' of undefined\"\n- Audit: 18:00 user dev@example.com deployed new version\n- Metrics: error_rate jumped from 0.1% to 12%\n\nRecommendation: Roll back to previous version, or fix /v2/users handler\n```\n\n## Error Handling\n\n| Situation | Action |\n|-----------|--------|\n| Account not set | Run `accounts_list` → `set_active_account` first |\n| Resource doesn''t exist | Verify ID/name is correct, list available resources |\n| Insufficient permissions | Explain required permissions, suggest checking API token scope |\n| Observability query too long | Split into smaller time ranges, ask more specific questions |\n\n## Scenario Examples\n\nSee [scenarios.md](scenarios.md) for 20 real-world development scenarios.\n"},"lastSynced":"2026-03-08T02:06:49.398Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloudflare-focused Agents needing streamlined workflow integration and troubleshooting via MCP","zh":"非常适合需要通过MCP实现工作流集成和故障排除的Cloudflare专注代理","ja":"MCPを介したワークフロー統合とトラブルシューティングを必要とするCloudflareに特化したエージェントに最適","ko":"MCP를 통해 워크플로 통합 및 문제 해결이 필요한 Cloudflare 전문 에이전트에게 완벽함","es":"Perfecto para agentes centrados en Cloudflare que necesitan una integración de flujo de trabajo simplificada y solución de problemas a través de MCP","fr":"Parfait pour les agents axés sur Cloudflare nécessitant une intégration de workflow simplifiée et une résolution de problèmes via MCP","de":"Perfekt für Cloudflare-fokussierte Agenten, die eine vereinfachte Workflow-Integration und Fehlerbehebung über MCP benötigen","pt":"Perfeito para Agentes focados na Cloudflare que necessitam de integração de fluxo de trabalho simplificado e solução de problemas via MCP","ru":"Идеально для агентов, ориентированных на Cloudflare, которым необходима упрощенная интеграция рабочего процесса и устранение неполадок через MCP","ar":"مثالي لموظفي الوكالة المعنيين بـ Cloudflare الذين يحتاجون إلى دمج تدفق العمل المُبسط وتصحيح الأخطاء من خلال MCP"},"recommendation":{"en":"Empowers agents to interact with Cloudflare services such as Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit, and Container Sandbox, leveraging file-based pipelines and disk-persisted evidence for robust troubleshooting and automation, utilizing protocols and file structures like `runs/<workflow>/active/<run_id>/`","zh":"赋予代理与Cloudflare服务交互的能力，例如Workers、KV、R2、D1、Hyperdrive、Observability、Builds、Audit和Container Sandbox，利用基于文件的管道和磁盘持久化证据实现强大的故障排除和自动化，使用诸如`runs/<workflow>/active/<run_id>/`的协议和文件结构","ja":"エージェントがCloudflareサービス（Workers、KV、R2、D1、Hyperdrive、Observability、Builds、Audit、Container Sandbox）とやり取りできるようにし、ファイルベースのパイプラインとディスクに永続化された証拠を利用して強力なトラブルシューティングと自動化を実現し、`runs/<workflow>/active/<run_id>/`などのプロトコルとファイル構造を使用","ko":"에이전트가 Cloudflare 서비스(Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit 및 Container Sandbox)와 상호 작용할 수 있도록 하며, 파일 기반 파이프라인과 디스크에 영속화된 증거를 활용하여 강력한 문제 해결 및 자동화를 제공하고, `runs/<workflow>/active/<run_id>/`와 같은 프로토콜 및 파일 구조를 사용","es":"Habilita a los agentes a interactuar con servicios de Cloudflare como Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit y Container Sandbox, aprovechando tuberías basadas en archivos y evidencia persistente en disco para una solución de problemas robusta y automatización, utilizando protocolos y estructuras de archivos como `runs/<workflow>/active/<run_id>/`","fr":"Permet aux agents d''interagir avec des services Cloudflare tels que Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit et Container Sandbox, en exploitant des pipelines basés sur des fichiers et des preuves persistantes sur disque pour un dépannage robuste et une automatisation, en utilisant des protocoles et des structures de fichiers comme `runs/<workflow>/active/<run_id>/`","de":"Ermächtigt Agenten, mit Cloudflare-Diensten wie Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit und Container Sandbox zu interagieren, indem Dateibasierte Pipelines und auf Datenträger persistente Beweise für robuste Fehlersuche und Automatisierung genutzt werden, unter Verwendung von Protokollen und Dateistrukturen wie `runs/<workflow>/active/<run_id>/`","pt":"Habilita os agentes a interagir com serviços da Cloudflare, como Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit e Container Sandbox, aproveitando pipelines baseadas em arquivos e evidências persistidas em disco para solução de problemas robusta e automação, utilizando protocolos e estruturas de arquivos como `runs/<workflow>/active/<run_id>/`","ru":"Позволяет агентам взаимодействовать с сервисами Cloudflare, такими как Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit и Container Sandbox, используя файловые конвейеры и доказательства, сохраненные на диске, для надежной отладки и автоматизации, используя протоколы и структуры файлов, такие как `runs/<workflow>/active/<run_id>/`","ar":"تمكين الموظفين من التفاعل مع خدمات Cloudflare مثل Workers و KV و R2 و D1 و Hyperdrive و Observability و Builds و Audit و Container Sandbox، من خلال استخدام خطوط أنابيب قائمة على الملفات والأدلة المحفوظة على القرص لتصحيح الأخطاء القوي وتأتمة، باستخدام بروتوكولات وهياكل الملفات مثل `runs/<workflow>/active/<run_id>/`"},"useCases":{"en":["Automating Cloudflare Worker deployments","Debugging issues with Cloudflare KV and R2 storage","Optimizing Cloudflare Observability and Builds for enhanced performance"],"zh":["自动化Cloudflare Worker部署","调试Cloudflare KV和R2存储问题","优化Cloudflare Observability和Builds以提高性能"],"ja":["Cloudflare Workerのデプロイを自動化する","Cloudflare KVとR2ストレージの問題をデバッグする","Cloudflare ObservabilityとBuildsを最適化してパフォーマンスを向上させる"],"ko":["Cloudflare Worker 배포 자동화","Cloudflare KV 및 R2 스토리지 문제 해결","Cloudflare Observability 및 Builds 최적화하여 성능 향상"],"es":["Implementación automática de despliegues de Cloudflare Worker","Depuración de problemas con el almacenamiento de Cloudflare KV y R2","Optimización de Cloudflare Observability y Builds para un rendimiento mejorado"],"fr":["Déploiement automatisé de Workers Cloudflare","Débogage des problèmes avec le stockage Cloudflare KV et R2","Optimisation de Cloudflare Observability et Builds pour une performance améliorée"],"de":["Automatisierung von Cloudflare-Worker-Deployments","Fehlerbehebung bei Problemen mit Cloudflare-KV- und R2-Speicher","Optimierung von Cloudflare-Observability und Builds für eine verbesserte Leistung"],"pt":["Automação de implantações de Cloudflare Worker","Depuração de problemas com armazenamento Cloudflare KV e R2","Otimização de Cloudflare Observability e Builds para desempenho aprimorado"],"ru":["Автоматизация развертывания Cloudflare Worker","Отладка проблем с хранилищем Cloudflare KV и R2","Оптимизация Cloudflare Observability и Builds для повышения производительности"],"ar":["تأتمة نشر Cloudflare Worker","تصحيح أخطاء التخزين Cloudflare KV و R2","تحسين أداء Cloudflare Observability و Builds"]},"limitations":{"en":["Requires MCP compatibility","Filesystem access needed for persisting evidence and artifacts","Specific directory structure required for workflow integration"],"zh":["需要MCP兼容性","需要文件系统访问以持久化证据和工件","需要特定的目录结构以实现工作流集成"],"ja":["MCPの互換性が必要","証拠とアーティファクトを永続化するためにファイルシステムへのアクセスが必要","ワークフロー統合を実現するために特定のディレクトリ構造が必要"],"ko":["MCP 호환성 필요","증거 및 아티팩트를 영속화하기 위해 파일 시스템 액세스가 필요","워크플로 통합을 위해 특정 디렉토리 구조가 필요"],"es":["Requiere compatibilidad con MCP","Se necesita acceso al sistema de archivos para persistir evidencia y artefactos","Se requiere una estructura de directorio específica para la integración de flujos de trabajo"],"fr":["Nécessite la compatibilité avec MCP","L''accès au système de fichiers est nécessaire pour persister les preuves et les artefacts","Une structure de répertoire spécifique est requise pour l''intégration de workflow"],"de":["Benötigt MCP-Kompatibilität","Zugriff auf das Dateisystem ist erforderlich, um Beweise und Artefakte zu persistieren","Eine spezifische Verzeichnisstruktur ist erforderlich für die Workflow-Integration"],"pt":["Requer compatibilidade com MCP","Acesso ao sistema de arquivos necessário para persistir evidências e artefatos","Estrutura de diretório específica necessária para integração de fluxo de trabalho"],"ru":["Требуется совместимость с MCP","Необходим доступ к файловой системе для сохранения доказательств и артефактов","Требуется специальная структура директорий для интеграции рабочего процесса"],"ar":["يتطلب توافق MCP","تحتاج الوصول إلى نظام الملفات لتحفظ الأدلة والفنون","مطلوبة هيكل دليل محدد للدمج تدفق العمل"]},"version":4},"contentHash":"6c6ca1e7a6fb6626aed5dc112b2204726f64a3ee16d94312391394a61d0883a4","qualityScore":60}');
