INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Heyvhuang/ship-faster/mcp-cloudflare', 'mcp-cloudflare', 'Heyvhuang', 'ship-faster', 'community', 'mcp-cloudflare Heyvhuang ship-faster community The mcp-cloudflare skill enables developers to interact with Cloudflare services via MCP, streamlining workflow integration and troubleshooting. It benefits developers working with Cloudflare Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit, and Container Sandbox. Cloudflare MCP技能提供了与Cloudflare服务的交互，包括Workers、KV、R2、D1、Hyperdrive、Observability、Builds、Audit和Container Sandbox Cloudflare MCPスキルは、Workers、KV、R2、D1、Hyperdrive、Observability、Builds、Audit、Container SandboxなどのCloudflareサービスとの相互作用を提供します Cloudflare MCP 스킬은 Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit, Container Sandbox 등의 Cloudflare 서비스와의 상호 작용을 제공합니다 MCP Cloudflare es una habilidad que permite a los desarrolladores interactuar con los servicios de Cloudflare, como Workers, KV y R2, para crear soluciones personalizadas MCP Cloudflare est une compétence qui permet aux développeurs d''interagir avec les services Cloudflare, tels que Workers, KV et R2, pour créer des solutions personnalisées MCP Cloudflare ist eine Fähigkeit, die es Entwicklern ermöglicht, mit Cloudflare-Diensten wie Workers, KV und R2 zu interagieren, um individuelle Lösungen zu erstellen O mcp-cloudflare é uma habilidade que permite interagir com serviços Cloudflare via MCP. Ele suporta Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit e Container Sandbox. Mcp-cloudflare - это навык, который позволяет взаимодействовать с сервисами Cloudflare через MCP. Он поддерживает Workers, KV, R2, D1, Hyperdrive, Observability, Builds, Audit и Container Sandbox. mcp-cloudflare هو مهارة تمكن من التفاعل مع خدمات Cloudflare عبر MCP. يدعم Workers، KV، R2، D1، Hyperdrive، Observability، Builds، Audit و Container Sandbox. how to use mcp-cloudflare mcp-cloudflare setup guide Cloudflare Workers integration mcp-cloudflare vs Cloudflare API mcp-cloudflare install what is mcp-cloudflare mcp-cloudflare alternative Cloudflare services integration mcp-cloudflare tutorial Cloudflare R2 storage Cloudflare MCP技能 AI工具 Cloudflare服务 Workers KV R2 D1 Hyperdrive Observability Builds Audit Container Sandbox Interacts with Cloudflare Workers for serverless computing Utilizes Cloudflare KV for secure key-value storage Supports Cloudflare R2 for object storage and retrieval Enables Observability for monitoring and analytics Facilitates Builds and Audit for streamlined development and security Integrates with Container Sandbox for secure testing and deployment mcp-cloudflare is a skill that allows interaction with Cloudflare services via MCP, facilitating file-based pipeline management and workflow integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lgbarn/shipyard/shipyard-testing', 'community', 'lgbarn', 'shipyard', 'lgbarn/shipyard', 'shipyard-testing', 0, 0, 60, '2026-03-08T01:57:15.403Z', '2026-03-08T02:06:49.710Z', '96b1b0046fb50d009bbb7d8bfdbf78609c2c0f3ae5868d52a8b523b84ba3952b', '{"id":"lgbarn/shipyard/shipyard-testing","name":"shipyard-testing","description":{"en":"shipyard-testing is a plugin for Claude Code that structures project lifecycles with discipline, parallel agents, and quality gates, benefiting developers and teams. It aids in writing effective tests, setting up test infrastructure, and debugging.","zh":"Shipyard-Testing是一个结构化项目生命周期的插件，支持从idea到生产的测试管理，包括平行代理和质量门控","ja":"Shipyard-Testingは、アイデアからプロダクションまでのプロジェクトライフサイクルを構造化するプラグインで、テストの自動化をサポートします","ko":"Shipyard-Testing은 프로젝트 생명주기를 구조화하는 플러그인으로, 아이디어에서 프로덕션까지의 테스트 관리를 지원합니다","es":"Shipyard-testing es un plugin de ciclo de vida de proyecto estructurado para Claude Code que ayuda a mejorar la calidad y eficiencia de las pruebas, desde la creación de tests unitarios hasta la integración con herramientas de testing.","fr":"Shipyard-testing est un plugin de cycle de vie de projet structuré pour Claude Code qui aide à améliorer la qualité et l''efficacité des tests, de la création de tests unitaires à l''intégration avec des outils de testing.","de":"Shipyard-testing ist ein Plugin für den strukturierten Projekt-Lebenszyklus von Claude Code, das dabei hilft, die Qualität und Effizienz von Tests zu verbessern, von der Erstellung von Einheitstests bis zur Integration mit Testtools.","pt":"O Shipyard-Testing é um plugin de ciclo de vida de projeto estruturado para Claude Code, que ajuda a manter a disciplina e a qualidade dos testes","ru":"Shipyard-Testing — это структурированный плагин жизненного цикла проекта для Claude Code, который помогает поддерживать дисциплину и качество тестирования","ar":"Shipyard-Testing هو مكون إضافي لم цикل حياة المشروع المنظم ل Claude Code، الذي يساعد في الحفاظ على الانضباط وجودة الاختبارات"},"seo":{"title":{"en":"shipyard-testing: Structured Project Lifecycle Setup Guid...","zh":"Shipyard-Testing 集成指南：从idea到生产的测试解决方案","ja":"Shipyard-Testing セットアップガイド：AIエージェントを使用したテスト自動化","ko":"Shipyard-Testing 설정 가이드: 아이디어에서 프로덕션까지의 테스트 플랫폼","es":"Guía de configuración de shipyard-testing para pruebas au...","fr":"Guide de mise en place de shipyard-testing pour les tests...","de":"Einrichtungsleitfaden für shipyard-testing zur Automatisi...","pt":"Guia de Configuração do Shipyard-Testing para Desenvolved...","ru":"Настройка Shipyard-Testing: Руководство для Разработчиков...","ar":"دليل إعداد Shipyard-Testing للبرمجة"},"description":{"en":"Unlock efficient testing with shipyard-testing. Discover how to streamline your project lifecycle from idea to production. Get started now!","zh":"使用Shipyard-Testing插件，从idea到生产，实现项目生命周期的结构化管理，包括平行代理和质量门控","ja":"Shipyard-Testingプラグインを使用して、アイデアからプロダクションまでのプロジェクトライフサイクルを構造化し、テストを自動化する","ko":"Shipyard-Testing 플러그인을 사용하여 프로젝트 생명주기를 구조화하고, 병렬 에이전트와 품질 게이트를 사용하여 테스트를 자동화합니다","es":"Aprende a utilizar shipyard-testing para mejorar la calidad y eficiencia de tus pruebas, desde la creación de tests unitarios hasta la integración con herram...","fr":"Découvrez comment utiliser shipyard-testing pour améliorer la qualité et l''efficacité de vos tests, de la création de tests unitaires à l''intégration avec de...","de":"Erfahren Sie, wie Sie shipyard-testing verwenden können, um die Qualität und Effizienz Ihrer Tests zu verbessern, von der Erstellung von Einheitstests bis zu...","pt":"Aprenda a configurar o Shipyard-Testing para melhorar a disciplina e a qualidade dos testes em seus projetos de desenvolvimento de software","ru":"Узнайте, как настроить Shipyard-Testing, чтобы повысить дисциплину и качество тестирования в ваших проектах разработки ПО с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Shipyard-Testing لتحسين الانضباط وجودة الاختبارات في مشاريع برمجة البرمجيات"},"definition":{"en":"shipyard-testing is a structured project lifecycle plugin for Claude Code, enabling disciplined development from idea to production with features like parallel agents and quality gates.","zh":"Shipyard-Testing是一种结构化项目生命周期的插件，用于管理从idea到生产的测试过程","ja":"Shipyard-Testingは、プロジェクトライフサイクルを構造化するプラグインで、テストの自動化をサポートする","ko":"Shipyard-Testing은 프로젝트 생명주기를 구조화하는 플러그인으로, 테스트 관리를 지원하는 도구입니다","es":"Shipyard-testing es un plugin que ayuda a los desarrolladores a crear y ejecutar pruebas automatizadas de manera eficiente","fr":"Shipyard-testing est un plugin qui aide les développeurs à créer et exécuter des tests automatisés de manière efficace","de":"Shipyard-testing ist ein Plugin, das Entwicklern hilft, automatisierte Tests effizient zu erstellen und auszuführen","pt":"O Shipyard-Testing é um plugin que ajuda a gerenciar o ciclo de vida de um projeto de software, desde a ideia até a produção","ru":"Shipyard-Testing — это плагин, который помогает управлять жизненным циклом проекта разработки ПО, от идеи до производства","ar":"Shipyard-Testing هو مكون إضافي يساعد في إدارة دورة حياة مشروع برمجة البرمجيات، من الفكرة إلى الإنتاج"},"features":{"en":["Writes effective tests for various file formats like *.test.*, *.spec.*, *_test.go, and test_*.py","Sets up test infrastructure and utilities for efficient testing","Debugs flaky, brittle, or slow tests for improved test reliability","Decides between unit, integration, and E2E tests for comprehensive coverage","Chooses when and how to use mocks, stubs, or fakes for effective test isolation"],"zh":["支持写入或修改测试文件（*.test.*，*.spec.*，*_test.go，test_*.py）","提供测试基础设施和测试工具的设置","支持调试不稳定、脆弱或慢速的测试","提供单元测试、集成测试和E2E测试的选择","支持mocks、stubs或fakes的使用"],"ja":["テストファイル（*.test.*，*.spec.*，*_test.go，test_*.py）の作成や修正をサポート","テストインフラストラクチャとテストユーティリティの設定を提供","不安定、脆弱、または遅いテストのデバッグをサポート","ユニットテスト、統合テスト、E2Eテストの選択を提供","モック、スタブ、またはフェイクの使用をサポート"],"ko":["테스트 파일（*.test.*，*.spec.*，*_test.go，test_*.py）的 작성 또는 수정을 지원","테스트 인프라스트럭처와 테스트 유틸리티의 설정을 제공","불안정한, 취약한 또는 느린 테스트의 디버깅을 지원","유닛 테스트, 통합 테스트, E2E 테스트의 선택을 제공","mocks, stubs 또는 fakes의 사용을 지원"],"es":["Creación de tests unitarios y de integración","Soporte para la creación de tests con mocks, stubs y fakes","Integración con herramientas de testing como JUnit y PyUnit","Soporte para la depuración de tests fallidos o lentos","Creación de tests E2E para garantizar la calidad del software"],"fr":["Création de tests unitaires et d''intégration","Support pour la création de tests avec des mocks, stubs et fakes","Intégration avec des outils de testing tels que JUnit et PyUnit","Support pour la débogage de tests défaillants ou lents","Création de tests E2E pour garantir la qualité du logiciel"],"de":["Erstellung von Einheitstests und IntegrationsTests","Unterstützung für die Erstellung von Tests mit Mocks, Stubs und Fakes","Integration mit Testtools wie JUnit und PyUnit","Unterstützung für die Fehlersuche bei fehlerhaften oder langsamen Tests","Erstellung von E2E-Tests zur Gewährleistung der Softwarequalität"],"pt":["Suporte a testes unitários, integração e E2E","Uso de mocks, stubs e fakes para testes","Depuração de testes instáveis, frágeis ou lentos","Configuração de infraestrutura de teste e utilitários","Escolha entre testes unitários, integração e E2E"],"ru":["Поддержка юнит-тестов, интеграционных и E2E-тестов","Использование моков, стабов и фейков для тестирования","Отладка нестабильных, хрупких или медленных тестов","Настройка инфраструктуры тестирования и утилит","Выбор между юнит-тестами, интеграционными и E2E-тестами"],"ar":["دعم الاختبارات الوحدوية والتكامل والانتهاء إلى النهاية","استخدام المزيفات والخدع للمحاكاة للاختبارات","تصحيح الاختبارات غير المستقرة أو الهشة أو البطيئة","تكوين بنية الاختبار والبرامج المساعدة","اختيار بين الاختبارات الوحدوية والتكامل والانتهاء إلى النهاية"]},"keywords":{"en":["how to use shipyard-testing","shipyard-testing vs claude code","shipyard-testing setup guide","what is shipyard-testing","shipyard-testing alternative","shipyard-testing install","structured project lifecycle","claude code plugin","effective testing strategies"],"zh":["Shipyard-Testing","AIエージェント","测试自动化","项目生命周期管理","平行代理","质量门控","测试文件","测试基础设施","单元测试","集成测试","E2E测试"],"ja":["Shipyard-Testing","AIエージェント","テスト自動化","プロジェクトライフサイクル管理","テストファイル","テストインフラストラクチャ","ユニットテスト","統合テスト","E2Eテスト","モック","スタブ","フェイク"],"ko":["Shipyard-Testing","AI 에이전트","테스트 자동화","프로젝트 생명주기 관리","테스트 파일","테스트 인프라스트럭처","유닛 테스트","통합 테스트","E2E 테스트","mocks","stubs","fakes"],"es":["pruebas automatizadas","testing de software","herramientas de testing","tests unitarios","tests de integración","mocks y stubs","depuración de tests","shipyard-testing","Claude Code"],"fr":["tests automatisés","testing de logiciel","outils de testing","tests unitaires","tests d''intégration","mocks et stubs","débogage de tests","shipyard-testing","Claude Code"],"de":["automatisierte Tests","Software-Testing","Testtools","Einheitstests","IntegrationsTests","Mocks und Stubs","Fehlersuche bei Tests","shipyard-testing","Claude Code"],"pt":["shipyard-testing","testes de software","desenvolvimento de software","ciclo de vida de projeto","disciplina de testes","qualidade de testes"," Claude Code","plugin de teste"],"ru":["shipyard-testing","тестирование ПО","разработка ПО","жизненный цикл проекта","дисциплина тестирования","качество тестирования","Claude Code","плагин тестирования","ИИ Агенты"],"ar":["shipyard-testing","اختبارات البرمجيات","برمجة البرمجيات","دورة حياة المشروع","انضباط الاختبارات","جودة الاختبارات","Claude Code","مكون إضافي للاختبار","أدوات الذكاء الاصطناعي"]}},"owner":"lgbarn","repo":"shipyard","repoPath":"lgbarn/shipyard","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.403Z","topics":[],"category":"community","skillMd":{"name":"shipyard-testing","description":"Use when writing tests, structuring test suites, choosing test boundaries, or debugging test quality issues like flakiness, over-mocking, or brittle tests. Also use when deciding between unit/integration/E2E tests, when tests break during refactoring (sign of testing implementation details), or when test setup exceeds 20 lines. Covers AAA structure, DAMP naming, mock boundaries, and the testing pyramid.","bodyPreview":"<!-- TOKEN BUDGET: 400 lines / ~1200 tokens -->\n\n# Writing Effective Tests\n\n<activation>\n\n## When This Skill Activates\n\n- Writing or modifying test files (`*.test.*`, `*.spec.*`, `*_test.go`, `test_*.py`)\n- Setting up test infrastructure or test utilities\n- Debugging flaky, brittle, or slow tests\n- Deciding between unit, integration, and E2E tests\n- Choosing when and how to use mocks, stubs, or fakes\n\n## Natural Language Triggers\n- \"add tests\", \"test coverage\", \"testing strategy\", \"write tests f","body":"<!-- TOKEN BUDGET: 400 lines / ~1200 tokens -->\n\n# Writing Effective Tests\n\n<activation>\n\n## When This Skill Activates\n\n- Writing or modifying test files (`*.test.*`, `*.spec.*`, `*_test.go`, `test_*.py`)\n- Setting up test infrastructure or test utilities\n- Debugging flaky, brittle, or slow tests\n- Deciding between unit, integration, and E2E tests\n- Choosing when and how to use mocks, stubs, or fakes\n\n## Natural Language Triggers\n- \"add tests\", \"test coverage\", \"testing strategy\", \"write tests for\", \"how should I test\"\n\n</activation>\n\n## Overview\n\nTest behaviors through public APIs. Verify state, not interactions.\n\n**Core principle:** If refactoring breaks your tests but not your users, your tests are wrong.\n\n**Relationship to TDD:** The `shipyard:shipyard-tdd` skill covers WHEN to write tests (test-first, red-green-refactor). This skill covers HOW to write tests that are effective, maintainable, and trustworthy.\n\n## The Iron Law\n\n```\nTEST BEHAVIORS, NOT IMPLEMENTATIONS\n```\n\nA test should break only when the system''s observable behavior changes -- never because of refactoring, renaming internals, or restructuring code.\n\n**No exceptions:**\n- Don''t test private methods\n- Don''t assert on internal state\n- Don''t verify method call sequences\n- Don''t couple tests to data structures users never see\n\n<instructions>\n\n## Test Structure (AAA)\n\nEvery test follows Arrange-Act-Assert:\n\n```\nArrange -- Set up preconditions and inputs\nAct     -- Execute the behavior under test\nAssert  -- Verify the expected outcome\n```\n\nSeparate the three sections with blank lines. One Act per test. One logical assertion per test.\n\n<examples>\n\n<example type=\"good\" title=\"Clear AAA structure, one behavior per test\">\n```python\ndef test_expired_subscription_denies_access():\n    # Arrange\n    user = create_user(subscription_end=yesterday())\n\n    # Act\n    result = check_access(user, resource=\"premium-content\")\n\n    # Assert\n    assert result.denied is True\n    assert result.reason == \"subscription expired\"\n```\nClear name, tests one behavior, obvious structure.\n</example>\n\n<example type=\"bad\" title=\"Multiple behaviors, internal state tested\">\n```python\ndef test_subscription():\n    user = create_user(subscription_end=yesterday())\n    assert check_access(user, \"premium-content\").denied\n    user.subscription_end = tomorrow()\n    assert check_access(user, \"premium-content\").allowed\n    assert user.access_log == [(\"denied\", \"premium-content\"), (\"allowed\", \"premium-content\")]\n```\nTwo behaviors in one test, tests internal log, vague name.\n</example>\n\n</examples>\n\n### Keep Tests DAMP, Not DRY\n\nPrefer **Descriptive And Meaningful Phrases** over eliminating duplication. Duplicating setup across tests is fine if it makes each test self-contained and readable. Extract shared setup into helpers only when it improves clarity, not to reduce line count.\n\n### No Logic in Tests\n\nTests are straight-line code. No loops, conditionals, ternaries, or string concatenation. If you need logic, the test is too complex -- split it or simplify the design.\n\n## What to Test\n\n### Test These\n\n- **Behaviors:** What the system does from a user''s perspective\n- **Edge cases:** Empty inputs, boundaries, overflow, zero, null\n- **Error paths:** Invalid input, missing dependencies, timeouts\n- **State transitions:** Before and after an operation\n\n### Skip These\n\n- Trivial getters/setters with no logic\n- Generated code (protobuf, ORM migrations)\n- Configuration files\n- Third-party library internals\n\n### Test Via Public APIs\n\nInvoke the system the same way its callers do. If the only way to test something is through a private method, the design needs to change -- extract it into a collaborator with its own public interface.\n\n## Naming Tests\n\nName tests after the behavior, not the method.\n\n| Good | Bad |\n|------|-----|\n| `rejects_empty_email_with_validation_error` | `test_validate` |\n| `returns_cached_result_when_within_ttl` | `test_cache` |\n| `retries_three_times_before_failing` | `test_retry_logic` |\n| `grants_access_when_subscription_active` | `test_check_access_method` |\n\nPatterns that work:\n- `[action]_[condition]_[expected_result]`\n- `should [expected behavior] when [condition]`\n- Plain descriptive sentence\n\nA test name containing \"and\" usually means two tests.\n\n## Choosing Test Level\n\n```dot\ndigraph test_level {\n    rankdir=TB;\n    start [label=\"What are you testing?\", shape=diamond];\n    pure [label=\"Pure logic?\\nNo I/O, no side effects\", shape=diamond];\n    boundary [label=\"System boundary?\\nDB, API, file, queue\", shape=diamond];\n    journey [label=\"Critical user journey?\\nLogin, checkout, signup\", shape=diamond];\n\n    unit [label=\"UNIT TEST\\nFast, isolated, many\", shape=box, style=filled, fillcolor=\"#ccffcc\"];\n    integration [label=\"INTEGRATION TEST\\nBoundary focused, fewer\", shape=box, style=filled, fillcolor=\"#ffffcc\"];\n    e2e [label=\"E2E TEST\\nFull stack, minimal\", shape=box, style=filled, fillcolor=\"#ffcccc\"];\n\n    start -> pure;\n    pure -> unit [label=\"yes\"];\n    pure -> boundary [label=\"no\"];\n    boundary -> integration [label=\"yes\"];\n    boundary -> journey [label=\"no\"];\n    journey -> e2e [label=\"yes\"];\n    journey -> unit [label=\"no\\n(rethink)\"];\n}\n```\n\n**The pyramid:** Many unit tests. Fewer integration tests. Minimal E2E tests.\n\n**Push tests down.** If a behavior can be tested at a lower level, test it there. Lower = faster, more stable, cheaper to maintain. Only go higher when the lower level can''t verify the behavior (serialization, wiring, full user flow).\n\n**Duplicate coverage?** If a unit test and integration test verify the same behavior, keep the unit test. Remove the integration test unless it adds confidence about wiring.\n\n## Test Isolation and Doubles\n\n### When to Use Test Doubles\n\n| Use doubles for | Use real objects for |\n|----------------|---------------------|\n| Network calls (HTTP, gRPC) | In-process collaborators |\n| Database queries (in unit tests) | Value objects and data structures |\n| Filesystem I/O | Pure functions |\n| Non-deterministic sources (time, random) | Deterministic transformations |\n| Expensive operations (ML inference, rendering) | Lightweight dependencies |\n\n### Types of Doubles\n\n- **Stub:** Returns canned responses. Use when you need a dependency to return specific data.\n- **Fake:** Working implementation with shortcuts (in-memory DB, local file store). Preferred over mocks for complex interactions.\n- **Mock:** Records calls and asserts on them. Use sparingly -- only when the interaction IS the behavior (e.g., \"sends an email\").\n\n### The Mocking Rule\n\n```\nVerify STATE over INTERACTIONS.\nMock only when the side effect IS the behavior under test.\n```\n\n<examples>\n\n<example type=\"good\" title=\"Testing resulting state\">\n```typescript\n// Testing that withdrawal updates balance (state)\ntest(''withdrawal reduces account balance'', () => {\n  const account = new Account(100);\n\n  account.withdraw(30);\n\n  expect(account.balance).toBe(70);\n});\n```\nTests resulting state -- survives internal refactoring.\n</example>\n\n<example type=\"bad\" title=\"Testing internal interaction\">\n```typescript\n// Testing that withdrawal calls the right methods (interaction)\ntest(''withdrawal calls debit'', () => {\n  const ledger = mock(Ledger);\n  const account = new Account(100, ledger);\n\n  account.withdraw(30);\n\n  expect(ledger.debit).toHaveBeenCalledWith(30);\n});\n```\nTests internal interaction -- breaks if refactored.\n</example>\n\n</examples>\n\n## Unchanging Tests\n\nA well-written test changes only when requirements change. It survives:\n- **Refactoring** -- internal restructuring, no behavior change\n- **Bug fixes** -- new tests added, existing tests unchanged\n- **New features** -- unrelated tests unaffected\n\nIf your tests break during refactoring, they''re testing implementation details. Fix the tests to test behavior instead.\n\n## Clear Failure Messages\n\nA failure message should let you diagnose the problem without reading the test code.\n\n<examples>\n\n<example type=\"good\" title=\"Descriptive failure message\">\n```\nFAIL: rejects_empty_email_with_validation_error\n  Expected: ValidationError(\"email is required\")\n  Actual:   None (no error raised)\n```\nShows expected vs actual with context.\n</example>\n\n<example type=\"bad\" title=\"Opaque failure message\">\n```\nFAIL: test_validate\n  AssertionError: False is not True\n```\nNo context, unclear what was tested.\n</example>\n\n</examples>\n\nUse assertion libraries that produce descriptive messages. Prefer `assertEqual(expected, actual)` over bare `assert`.\n\n</instructions>\n\n<rules>\n\n## Anti-Patterns\n\n| Anti-Pattern | Problem | Fix |\n|-------------|---------|-----|\n| Testing implementation | Breaks on refactor | Test observable behavior via public API |\n| Over-mocking | Tests verify mocks, not code | Use real objects; mock only at boundaries |\n| Flaky tests | Non-deterministic (time, order, network) | Control inputs; isolate state; use fakes |\n| Ice cream cone | Too many E2E, few unit tests | Push tests down the pyramid |\n| Logic in tests | Bugs in test code hide bugs in prod | Straight-line code only |\n| Shared mutable state | Tests depend on run order | Fresh state per test (setup/teardown) |\n| Test-only production code | Methods exist only for testing | Test via public API; redesign if needed |\n| Assertion-free tests | Test runs but verifies nothing | Every test must assert expected outcome |\n| Giant setup | 50 lines before the act | Simplify design; extract builder/factory |\n\n## Red Flags -- STOP and Rethink\n\n- Mocking more than 2 dependencies -- class has too many responsibilities\n- Test setup exceeds 20 lines -- design is too complex or test scope too broad\n- Test name contains \"and\" -- split into two tests\n- Tests break when you refactor -- testing implementation, not behavior\n- Tests pass but bugs ship -- testing the wrong things\n- Can''t explain what behavior a test verifies -- rewrite or delete it\n- All tests use mocks -- not testing real behavior\n- Test file is longer than production file -- over-testing or testing internals\n\n## Common Rationalizations\n\n| Excuse | Reality |\n|--------|---------|\n| \"Need mocks for everything\" | Design is too coupled. Inject dependencies, use fakes. |\n| \"100% coverage = quality\" | Coverage measures execution, not correctness. 80% covering behaviors > 100% covering lines. |\n| \"E2E tests cover everything\" | Slow, flaky, expensive. Unit tests catch most bugs faster. |\n| \"Test is too hard to write\" | Hard to test = hard to use. Fix the design. |\n| \"It''s just test code\" | Test code deserves production standards. Sloppy tests rot fast. |\n| \"One big test is easier\" | One big test = one useless failure message. Split by behavior. |\n| \"Helper makes it DRY\" | If the helper obscures what''s tested, inline it. DAMP > DRY. |\n\n</rules>\n\n## Quick Reference: FIRST Principles\n\n- **Fast** -- Tests run in seconds, not minutes. Slow tests get skipped.\n- **Independent** -- No test depends on another. Any order, any subset.\n- **Repeatable** -- Same result every run, any machine, any time.\n- **Self-checking** -- Pass/fail without human inspection.\n- **Timely** -- Written close to the code. Not \"later.\" Not \"before release.\"\n\n## Final Rule\n\n```\nTest what your users care about, through the interfaces they use.\nEverything else is an implementation detail.\n```\n"},"lastSynced":"2026-03-08T02:06:49.710Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents like Claude Code, needing structured project lifecycle management with test automation and quality gates.","zh":"适用于像 Claude Code 这样的开发代理，需要结构化的项目生命周期管理，具有测试自动化和质量门控。","ja":"Claude Code のような開発エージェントに適しています。構造化されたプロジェクトのライフサイクル管理とテスト自動化、品質ゲートが必要です。","ko":"클라우드 코드와 같은 개발 에이전트에 적합합니다. 구조화된 프로젝트 生命周期 관리와 테스트 자동화, 품질 게이트가 필요합니다.","es":"Ideal para Agentes de Desarrollo como Claude Code, que necesitan una gestión de ciclo de vida de proyecto estructurada con automatización de pruebas y puertas de calidad.","fr":"Idéal pour les agents de développement comme Claude Code, ayant besoin d''une gestion de cycle de vie de projet structurée avec une automatisation des tests et des portes de qualité.","de":"Ideal für Entwicklungssagenten wie Claude Code, die eine strukturierte Projekt-Lebenszyklusverwaltung mit Testautomatisierung und Qualitätsprüfungen benötigen.","pt":"Ideal para Agentes de Desenvolvimento como Claude Code, que necessitam de gerenciamento de ciclo de vida de projeto estruturado com automação de teste e portais de qualidade.","ru":"Идеально подходит для агентов разработки, таких как Claude Code, которые требуют структурированного управления жизненным циклом проекта с автоматизацией тестирования и контрольными воротами.","ar":"مثالي لعميل التطوير مثل Claude Code ، الذي يحتاج إلى إدارة دورة حياة المشروع المنظمة مع تلقيم الاختبار وأبواب الجودة."},"recommendation":{"en":"Empowers agents to write effective tests, set up test infrastructure, and debug flaky tests using discipline and parallel agents, supporting file formats like *.test.* and *_test.go, and utilizing quality gates for robust testing strategies.","zh":"赋予代理编写有效的测试、设置测试基础设施、调试易碎测试的能力，使用纪律和并行代理，支持类似 *.test.* 和 *_test.go 的文件格式，并利用质量门控进行强大的测试策略。","ja":"エージェントに効果的なテストを書き、テストインフラストラクチャを設定し、繊細なテストをデバッグする能力を与え、規律と並列エージェントを使用し、*.test.* や *_test.go などのファイル形式をサポートし、品質ゲートを使用して堅牢なテスト戦略を実現します。","ko":"에이전트에 효과적인 테스트를 작성하고 테스트 인프라를 설정하고 취약한 테스트를 디버깅할 수 있는 능력을 부여하며 규율과 병렬 에이전트를 사용하며 *.test.* 및 *_test.go와 같은 파일 형식을 지원하며 품질 게이트를 사용하여 강력한 테스트 전략을 수행합니다.","es":"Permite a los agentes escribir pruebas efectivas, configurar la infraestructura de prueba y depurar pruebas defectuosas utilizando disciplina y agentes paralelos, admitiendo formatos de archivo como *.test.* y *_test.go, y utilizando puertas de calidad para estrategias de pruebas robustas.","fr":"Permet aux agents d''écrire des tests efficaces, de configurer l''infrastructure de test et de déboguer des tests fragiles en utilisant la discipline et les agents parallèles, en prenant en charge des formats de fichiers tels que *.test.* et *_test.go, et en utilisant des portes de qualité pour des stratégies de test robustes.","de":"Ermöglicht es Agenten, effektive Tests zu schreiben, Testinfrastruktur einzurichten und fehlerhafte Tests zu debuggen, indem Disziplin und parallele Agenten verwendet werden, wobei Dateiformate wie *.test.* und *_test.go unterstützt werden und Qualitätsprüfungen für robuste Teststrategien eingesetzt werden.","pt":"Habilita os agentes a escrever testes eficazes, configurar a infraestrutura de teste e depurar testes frágeis usando disciplina e agentes paralelos, suportando formatos de arquivo como *.test.* e *_test.go, e utilizando portais de qualidade para estratégias de teste robustas.","ru":"Позволяет агентам писать эффективные тесты, настраивать инфраструктуру тестирования и отлаживать хрупкие тесты с помощью дисциплины и параллельных агентов, поддерживая форматы файлов, такие как *.test.* и *_test.go, и используя контрольные ворота для прочных стратегий тестирования.","ar":"يمنح الوكيل khảية كتابة اختبارات فعالة، وضبط بنية اختبار، وتصحيح اختبارات هشة باستخدام الانضباط والوكلاء المتوازي، ودعم صيغ الملفات مثل *.test.* و *_test.go ، واستخدام أبواب الجودة لاستراتيجيات اختبار قوية."},"useCases":{"en":["Writing unit, integration, and E2E tests","Debugging brittle or slow tests","Setting up test infrastructure with mocks, stubs, or fakes"],"zh":["编写单元测试、集成测试和端到端测试","调试脆弱或慢速的测试","使用模拟、存根或伪造设置测试基础设施"],"ja":["ユニットテスト、統合テスト、エンドツーエンドテストの記述","脆弱または遅いテストのデバッグ","モック、スタブ、またはフェイクを使用したテストインフラストラクチャの設定"],"ko":["유닛 테스트, 통합 테스트, 엔드투엔드 테스트 작성","취약하거나 느린 테스트 디버깅","모의, 스텁 또는 가짜를 사용한 테스트 인프라 설정"],"es":["Escribir pruebas unitarias, de integración y de extremo a extremo","Depurar pruebas frágiles o lentas","Configurar la infraestructura de prueba con mocks, stubs o fakes"],"fr":["Écrire des tests unitaires, d''intégration et de bout en bout","Déboguer des tests fragiles ou lents","Configurer l''infrastructure de test avec des mocks, des stubs ou des fakes"],"de":["Schreiben von Einheitstests, Integrations- und End-to-End-Tests","Debuggen von fehlerhaften oder langsamen Tests","Einrichten der Testinfrastruktur mit Mocks, Stubs oder Fakes"],"pt":["Escrita de testes unitários, de integração e de ponta a ponta","Depuração de testes frágeis ou lentos","Configuração da infraestrutura de teste com mocks, stubs ou fakes"],"ru":["Написание юнит-тестов, интеграционных и тестов от начала до конца","Отладка хрупких или медленных тестов","Настройка инфраструктуры тестирования с mocks, stubs или fakes"],"ar":["كتابة اختبارات الوحدة والتكامل واختبارات النهاية إلى النهاية","تصحيح اختبارات هشة أو بطيئة","ضبط بنية اختبار مع ميميكات، واستبدال أو مزييف"]},"limitations":{"en":["Requires Claude Code plugin integration","Supports specific file formats like *.test.* and *_test.go"],"zh":["需要 Claude Code 插件集成","支持特定的文件格式，如 *.test.* 和 *_test.go"],"ja":["Claude Code プラグイン統合が必要","特定のファイル形式（例: *.test.*、*_test.go）のみをサポート"],"ko":["클라우드 코드 플러그인 통합이 필요","특정 파일 형식만 지원합니다(예: *.test.*, *_test.go)"],"es":["Requiere integración del plugin Claude Code","Admite formatos de archivo específicos como *.test.* y *_test.go"],"fr":["Nécessite l''intégration du plugin Claude Code","Prend en charge des formats de fichiers spécifiques tels que *.test.* et *_test.go"],"de":["Benötigt die Integration des Claude Code-Plugins","Unterstützt bestimmte Dateiformate wie *.test.* und *_test.go"],"pt":["Requer integração do plugin Claude Code","Suporta formatos de arquivo específicos como *.test.* e *_test.go"],"ru":["Требует интеграции плагина Claude Code","Поддерживаетเฉพาะ форматы файлов, такие как *.test.* и *_test.go"],"ar":["يتطلب تكامل مكون إضافي Claude Code","يدعم صيغ الملفات المحددة مثل *.test.* و *_test.go"]},"version":4},"contentHash":"96b1b0046fb50d009bbb7d8bfdbf78609c2c0f3ae5868d52a8b523b84ba3952b","qualityScore":60}');
